inline int read(int f = 1, int x = 0, char ch = ' ')
{
    while(!isdigit(ch = getchar())) if(ch == '-') f = -1;
    while(isdigit(ch)) x = x*10+ch-'0', ch = getchar();
    return f*x;
}
const int N = 1e5+5;
struct Edge
{
    int next, to;
    Edge(int next = 0, int to = 0):next(next), to(to) {};
}edge[N<<1];
int head[N], tot;
void _add(int x, int y) { edge[++tot] = Edge(head[x], y), head[x] = tot; }
void add(int x, int y) { _add(x, y), _add(y, x); }
int n;
int t, dfn[N], d[N], son[N], size[N], fa[N], top[N];
int cov[N<<2], val[N<<2];
void pushc(int x, int f) { val[x] = f, cov[x] = 1; }
void pushdown(int x, int f) { if(cov[x]) pushc(x<<1, f>>1), pushc(x<<1|1, f-(f>>1)), cov[x] = 0; }
void pushup(int x) { val[x] = val[x<<1]+val[x<<1|1]; }
void cover(int x, int l, int r, int ql, int qr)
{
    if(ql <= l&&r <= qr) return pushc(x, r-l+1);
    int mid = (l+r)>>1; pushdown(x, r-l+1);
    if(ql <= mid) cover(x<<1, l, mid, ql, qr);
    if(qr > mid) cover(x<<1|1, mid+1, r, ql, qr);
    pushup(x);
}
int query(int x, int l, int r, int ql, int qr)
{
    if(ql <= l&&r <= qr) return val[x];
    int mid = (l+r)>>1, ret = 0; pushdown(x, r-l+1);
    if(ql <= mid) ret += query(x<<1, l, mid, ql, qr);
    if(qr > mid) ret += query(x<<1|1, mid+1, r, ql, qr);
    return ret;
}
void dfs(int x)
{
    d[x] = d[fa[x]]+1, size[x] = 1;
    for(int i = head[x]; i; i = edge[i].next)
    {
        int y = edge[i].to; if(y == fa[x]) continue;
        fa[y] = x, dfs(y), size[x] += size[y], son[x] = size[son[x]]>size[y]?son[x]:y;
    }
}
void dfs(int x, int topf)
{
    top[x] = topf, dfn[x] = ++t;
    if(son[x]) dfs(son[x], topf);
    for(int i = head[x]; i; i = edge[i].next)
    {
        int y = edge[i].to; if(y == fa[x]||y == son[x]) continue;
        dfs(y, y);
    }
}
int lca(int x, int y)
{
    for( ; top[x] != top[y]; x = fa[top[x]])
        if(d[top[x]] < d[top[y]]) swap(x, y);
    return d[x]<d[y]?x:y;
}
void cover(int x, int y)
{
    for( ; top[x] != top[y]; cover(1, 1, n, dfn[top[x]], dfn[x]), x = fa[top[x]])
        if(d[top[x]] < d[top[y]]) swap(x, y);
    if(dfn[x] > dfn[y]) swap(x, y);
    if(dfn[x] != dfn[y]) cover(1, 1, n, dfn[x]+1, dfn[y]);
}
int query(int x, int y)
{
    int ret = 0;
    for( ; top[x] != top[y]; ret += query(1, 1, n, dfn[top[x]], dfn[x]), x = fa[top[x]])
        if(d[top[x]] < d[top[y]]) swap(x, y);
    if(dfn[x] > dfn[y]) swap(x, y);
    if(dfn[x] != dfn[y]) ret += query(1, 1, n, dfn[x]+1, dfn[y]);
    return ret;
}
vector<int> f[N];
int a[N], b[N], h[N];
bool cmp(int x, int y) { return h[x] > h[y]; }
int main()
{
    n = read();
    for(int i = 1; i < n; ++i)
    {
        int x = read(), y = read();
        add(x, y);
    }
    dfs(1), dfs(1, 1);
    for(int i = 1; i < n; ++i)
    {   
        a[i] = read(), b[i] = read();
        f[d[a[i]]+d[b[i]]-2*d[lca(a[i], b[i])]].push_back(i);
    }
    for(int i = 1; i < n; ++i)
    {
        for(int k = 0; k < f[i].size(); ++k)
        {
            int x = a[f[i][k]], y = b[f[i][k]];
            h[f[i][k]] = query(x, y);
        }       
        sort(f[i].begin(), f[i].end(), cmp);
        for(int k = 0; k < f[i].size(); ++k)
        {
            int x = a[f[i][k]], y = b[f[i][k]];
            if(query(x, y) == i) return puts("NO"), 0;
            cover(x, y);
        }
    }

    puts("YES");
    return 0;
}

#include<bits/stdc++.h>
#define N 100005
#define oo (1<<30)
#define L(__) (__ << 1)
#define R(__) (L(__)|1)
using namespace std;
vector<int> G[N]; set<int> S[4*N];
int n,cnt,u[N],v[N],nu[N],d[N],sz[N],zl[N],MA[4*N],A[4*N],MB[4*N],B[4*N],T[4*N],f[N];
void update(int t)
{
	MA[t]=min(MA[L(t)],MA[R(t)]);
	if(MA[t]==MA[L(t)]) A[t]=A[L(t)];
	else A[t]=A[R(t)];
	if(MA[L(t)]==MA[R(t)]){
		if(MB[L(t)]>MB[R(t)]) MB[t]=MB[R(t)],B[t]=B[R(t)];
		else MB[t]=MB[L(t)],B[t]=B[L(t)];
	  }
	else{
		if(MA[L(t)]>MA[R(t)]){
			MB[t]=min(MA[L(t)],MB[R(t)]);
			if(MB[t]==MA[L(t)]) B[t]=A[L(t)];
			else B[t]=B[R(t)];
		  }
		else{
			MB[t]=min(MA[R(t)],MB[L(t)]);
			if(MB[t]==MA[R(t)]) B[t]=A[R(t)];
			else B[t]=B[L(t)];
		  }
	  }
}
void dfs(int t,int fa)
{
	int i; d[t]=d[fa]+1,f[t]=fa,sz[t]=1;
	for(i=0;i<G[t].size();i++)
		if(G[t][i]!=fa)
			dfs(G[t][i],t),sz[t]+=sz[G[t][i]];
}
void DFS(int t,int fa)
{
	int i,p=0; nu[t]=++cnt;
	zl[t]=zl[t] ? zl[t] : t;
	for(i=0;i<G[t].size();i++)
		if(G[t][i]!=fa&&sz[G[t][i]]>sz[p]) p=G[t][i];
	if(p) zl[p]=zl[t],DFS(p,t);
	for(i=0;i<G[t].size();i++)
		if(G[t][i]!=fa&&G[t][i]!=p) DFS(G[t][i],t);
}
void TA(int t,int d){ T[t]+=d,MA[t]+=d,MB[t]+=d; return ;}
void push(int t)
{
	if(T[t]==0) return ;
	TA(L(t),T[t]);
	TA(R(t),T[t]);
	T[t]=0;
}
void Ins(int t,int l,int r,int l1,int r1,int x)
{
	int mid=(l+r)>>1;
	if(l>r1 || r<l1) return ;
	if(l>=l1&&r<=r1){
		TA(t,1);
		S[t].insert(x);
		return ;
	  }
	push(t);
	Ins(L(t),l,mid,l1,r1,x);
	Ins(R(t),mid+1,r,l1,r1,x);
	update(t);
}
void Del(int t,int l,int r,int l1,int r1,int x)
{
	int mid=(l+r)>>1;
	if(l>r1 || r<l1) return ;
	if(l>=l1&&r<=r1){
		TA(t,-1);
		S[t].erase(x);
		return ;
	  }
	push(t);
	Del(L(t),l,mid,l1,r1,x);
	Del(R(t),mid+1,r,l1,r1,x);
	update(t);
}
void ins(int t)
{
	int x=u[t],y=v[t];
	while(zl[x]!=zl[y]){
		if(d[zl[x]]<d[zl[y]]) swap(x,y);
		Ins(1,1,n,nu[zl[x]],nu[x],t);
		x=f[zl[x]];
	  }
	if(d[x]<d[y]) swap(x,y);
	Ins(1,1,n,nu[y]+1,nu[x],t);
}
int find(int t,int l,int r,int x)
{
	int mid=(l+r)>>1;
	if(S[t].size()) return (*S[t].begin());
	if(l==r) return 0;
	if(x<=mid) return find(L(t),l,mid,x);
	else return find(R(t),mid+1,r,x);
}
int del()
{
	int t,x,y;
	if(MB[1]>1) return 0;
	t=find(1,1,n,B[1]),x=u[t],y=v[t];
	while(zl[x]!=zl[y]){
		if(d[zl[x]]<d[zl[y]]) swap(x,y);
		Del(1,1,n,nu[zl[x]],nu[x],t);
		x=f[zl[x]];
	  }
	if(d[x]<d[y]) swap(x,y);
	Del(1,1,n,nu[y]+1,nu[x],t);
	return 1;
}
void build(int t,int l,int r)
{
	int mid=(l+r)>>1;
	if(l==r){ A[t]=l,MB[t]=oo; return ;}
	build(L(t),l,mid),build(R(t),mid+1,r);
	update(t);
}
int main()
{
	int i,x,y;
	scanf("%d",&n);
	build(1,1,n);
	for(i=1;i<n;i++){
		scanf("%d %d",&x,&y);
		G[x].push_back(y);
		G[y].push_back(x);
	  }
	dfs(1,0);
	DFS(1,0);
	for(i=1;i<n;i++){
		scanf("%d %d",&u[i],&v[i]);
		ins(i);
	  }
	for(i=1;i<n;i++)
		if(!del()){ printf("NO"); return 0;}
	printf("YES");
	return 0;
}

