void solve (int n)
{
    vector<vvi> g(2, vvi(n));
    forn (it, 2)
    {
        forn (i, n - 1)
        {
            int u, v;
            cin >> u >> v;
            --u, --v;
            g[it][u].pb(v);
            g[it][v].pb(u);
        }
    }

    vvi cnt(2, vi(n));
    forn (it, 2) forn (j, n)
        cnt[it][j] = sz(g[it][j]);

    queue<int> q;
    vc used(n);

    auto add = [&] (int v) -> void
    {
        if (used[v])
            return;
        assert(cnt[0][v] >= 1 && cnt[1][v] >= 1);
        if (cnt[0][v] == 1 && cnt[1][v] == 1)
        {
            q.push(v);
            used[v] = 1;
        }
    };

    forn (i, n)
        add(i);

    int kill = 0;
    while (!q.empty())
    {
        kill++;
        if (kill == n - 1)
        {
            cout << "YES" << endl;
            return;
        }
        int cur = q.front();
        q.pop();
        forn (it, 2) for (int x : g[it][cur])
            cnt[it][x]--;

        forn (it, 2) for (int x : g[it][cur])
            add(x);
    }

    cout << "NO" << endl;
}

