int F()
{
	char ch;
	int x, a;
	while (ch = getchar(), (ch < '0' || ch > '9') && ch != '-');
	if (ch == '-') ch = getchar(), a = -1;
	else a = 1;
	x = ch - '0';
	while (ch = getchar(), ch >= '0' && ch <= '9')
		x = (x << 1) + (x << 3) + ch - '0';
	return a * x;
}

const int N = 1e5 + 10;

map<int, int> h[N];

set<int> edge[N];

queue<PII> q;

void link(int u, int v)
{
	if (u > v) swap(u, v);
	edge[u].insert(v);
	edge[v].insert(u);
	++h[u][v];
	if (h[u][v] == 2)
	{
		q.push(mp(u, v));
	}
	if (h[u][v] > 2)
	{
		puts("NO");
		exit(0);
	}
}

void cut(int u, int v)
{
	edge[u].erase(v);
	if (u > v) swap(u, v); 
	h[u].erase(v);
}

int fa[N], n;

int find(int x) { return x == fa[x] ? x : fa[x] = find(fa[x]); }

int main()
{
	gi(n);
	for (int i = 1; i <= n; ++i) fa[i] = i;
	for (int i = 1; i < n; ++i)
	{
		int u, v;
		gii(u, v);
		link(u, v);
	}
	for (int i = 1; i < n; ++i)
	{
		int u, v;
		gii(u, v);
		link(u, v);
	}
	for (int i = 1; i < n; ++i)
	{
		int u, v;
		do
		{
			if (q.empty())
			{
				puts("NO");
				return 0;
			}
			u = q.front().fi;
			v = q.front().se;
			u = find(u);
			v = find(v);
			q.pop();
		} while (u == v || h[u][v] != 2);
		if (SZ(edge[u]) > SZ(edge[v])) swap(u, v);
		fa[u] = v;
		cut(v, u);
		edge[u].erase(v); 
		for (auto x : edge[u])
		{
			x = find(x);
			if (x == v) continue;
			link(x, v);
			cut(x, u);
			edge[u].erase(x);
		}
	}
	puts("YES");
	return 0;
}

