struct UF{
	set<int> R[MX], B[MX];
	int t[MX], cnt[MX];
	int find(int x){ return t[x]? t[x] = find(t[x]) : x; }
	int merge(int a, int b){
		a = find(a), b = find(b);
		if( a == b ) return false;
		if( cnt[a] > cnt[b] ) swap(a, b);

		for(int c : R[a]){
			R[c].erase(a);
			R[c].insert(b);
		}
		for(int c : B[a]){
			B[c].erase(a);
			B[c].insert(b);
		}
		t[a] = b; cnt[b] += cnt[a];

		vector<int> L;
		for(int c : R[a] ) if( B[b].find(c) != B[b].end() ) L.push_back(c);
		for(int c : B[a] ) if( R[b].find(c) != R[b].end() ) L.push_back(c);
		for(int c : R[a] ) R[b].insert(c);
		for(int c : B[a] ) B[b].insert(c);

		for(int c : L) merge(b, c);
	}
}uf;

int main()
{
