struct Node{
	int l,r,mx,mn,head,bj;
}T[maxn<<2];

void build(int i,int l,int r){
	T[i].l=l;T[i].r=r;
	if(l==r)return;
	int M=l+r>>1;
	build(i<<1,l,M);build(i<<1|1,M+1,r);
}

void pushdown(int i){
	if(!T[i].bj)return;
	T[i<<1].mx+=T[i].bj;T[i<<1].mn+=T[i].bj;T[i<<1].bj+=T[i].bj;
	T[i<<1|1].mx+=T[i].bj;T[i<<1|1].mn+=T[i].bj;T[i<<1|1].bj+=T[i].bj;
	T[i].bj=0;
}

void add(int i,int l,int r,int id){
	if(l<=T[i].l&&T[i].r<=r){
		T[i].mn++;T[i].mx++;
		cnt++;val[cnt]=id;nxt[cnt]=T[i].head;T[i].head=cnt;
		T[i].bj++;
		return;
	}
	int M=T[i].l+T[i].r>>1;
	pushdown(i);
	if(l<=M)add(i<<1,l,r,id);if(r>M)add(i<<1|1,l,r,id);
	T[i].mn=min(T[i<<1].mn,T[i<<1|1].mn);
	T[i].mx=max(T[i<<1].mx,T[i<<1|1].mx);
}

void add(int u,int v,int id){
	while(an[u]!=an[v]){
		if(dep[an[u]]>dep[an[v]])swap(u,v);
		add(1,l[an[v]],l[v],id);
		v=fa[an[v]];
	}
	if(l[u]>l[v])swap(u,v);
	if(l[u]<l[v])add(1,l[u]+1,l[v],id);
}

void del2(int i,int l,int r){
	if(l<=T[i].l&&T[i].r<=r){
		T[i].bj--;
		T[i].mn--;T[i].mx--;
		return;
	}
	int M=T[i].l+T[i].r>>1;
	pushdown(i);
	if(l<=M)del2(i<<1,l,r);if(r>M)del2(i<<1|1,l,r);
	T[i].mn=min(T[i<<1].mn,T[i<<1|1].mn);
	T[i].mx=max(T[i<<1].mx,T[i<<1|1].mx);
}

int query(int i){
	while(Is[val[T[i].head]])T[i].head=nxt[T[i].head];
	if(T[i].head)return val[T[i].head];
	if(T[i].l==T[i].r)return -1;
	pushdown(i);
	//if(T[i].l==T[i].r)return;
	if(T[i<<1].mn<=1&&T[i<<1].mx>=1)return query(i<<1);else return query(i<<1|1);
}

