    //printf("merge %d to %d\n",v,u);
    num++;
    vector<ii> que;
    for (auto x: g[v]){
        if (x == u) continue;
        //printf("%d connected to %d\n",x,v);
        g[x].erase(v);
        if (g[x].count(u)){
            que.push_back({x,u});
        }
        g[u].insert(x);
        g[x].insert(u);
    }
    g[u].erase(v);
    p[v] = u;
    for (auto cur : que){
        merge(cur.first,cur.second);
    }
}
int main(){
    int n;
    scanf("%d",&n);
    iota(p,p+N,0);
    for (int i = 0; i < 2*n-2; i++){
        int a,b;
        scanf("%d%d",&a,&b);
        a = find(a); b = find(b);
        if (g[a].count(b)) merge(a,b);
        g[a].insert(b);
        g[b].insert(a);
    }
    int c = find(1);
    for (int i = 2; i <= n; i++){
        if (c != find(i)){
            printf("NO");
            return 0;
        }
    }
    //printf("num %d ",num);
    printf("%s",num==n-1 ? "YES":"NO");
}

