void solve()
{
	int m = 0;
	while(!que.empty())
	{
		int x = que.front().first, y = que.front().second;
		que.pop();
		if(edg_cnt[make_pair(x, y)] < 2) continue;
		// cerr << x << ' ' << y << endl;
