			edg_cnt[make_pair(y, z)]--;
			edg[z].erase(edg[z].find(y)), edg_cnt[make_pair(z, y)]--;
			if(z == x) continue;
			edg[x].insert(z), edg_cnt[make_pair(x, z)]++;
			edg[z].insert(x), edg_cnt[make_pair(z, x)]++;
			if(edg_cnt[make_pair(x, z)] == 2)
				que.push(make_pair(x, z));
