	int ted = 0;
	while(!deg.empty() && (*deg.begin()).first < -1)
	{
		pair<int, pair<int, int> > cur = *deg.begin();
		merge(cur.second.first, cur.second.second);
		ted++;
	}
	cout << ((ted == n - 1) ? "YES" : "NO");
}

