#include<cstdio>
#include<set>
#include<queue>
#include<map>
using namespace std;

typedef long long ll;
const int MAXN=100005;

int n;
int fa[MAXN];
set<int> s[MAXN];
queue<pair<int,int> > q;
map<ll,int> g;

int find(int u){return fa[u]==u?u:(fa[u]=find(fa[u]));}

 ll getID(int x,int y){
    if(x>y) swap(x,y);
    return 1ll*n*y+x;
}

void addEdge(int u,int v){
    s[u].insert(v);
    s[v].insert(u);
    ll eid=getID(u,v);
    int t=g[eid]+1;
    g[eid]++;
    if(t==2) q.push(make_pair(u,v));
}

void re(int u,int v){
    s[u].erase(v);
    s[v].erase(u);
    g.erase(getID(u,v));
}

bool solve(){
    for(int i=1;i<=n;i++) fa[i]=i;
    for(int i=1;i<n;i++){
        int u,v;
        if(q.empty()) return 0;
        u=q.front().first;
        v=q.front().second;
        q.pop();
        u=find(u); v=find(v);
        if(s[u].size()>s[v].size()) swap(u,v);
        fa[u]=v;
        re(u,v);
        for(set<int>::iterator i=s[u].begin(),j;i!=s[u].end();i=j){
            j=i;
            j++;
            int x=*i;
            x=find(x);
            re(u,x);
            addEdge(v,x);
        }
    }
    return 1;
}

int main(){
    scanf("%d",&n);
    int u,v;
    for(int i=1;i<=(n-1)<<1;i++){
        scanf("%d%d",&u,&v);
        addEdge(u,v);
    }
    puts(solve()?"YES":"NO");
}

