inline void Insert(int x,int y){
	E[++cnt].t=y; E[cnt].nx=G[x]; G[x]=cnt;
	E[++cnt].t=x; E[cnt].nx=G[y]; G[y]=cnt;
}

void dfs1(int x,int f){
	fa[x]=f; dpt[x]=dpt[f]+1; 
	s[x]=1;
	for(int i=G[x];i;i=E[i].nx)
		if(E[i].t!=f){
			dfs1(E[i].t,x);
			if(s[E[i].t]>s[son[x]]) son[x]=E[i].t;
			s[x]+=s[E[i].t];
		}
}

void dfs2(int x,int t){
	top[x]=t; p[x]=++g; q[g]=x;
	if(son[x]) dfs2(son[x],t);
	for(int i=G[x];i;i=E[i].nx)
		if(E[i].t!=fa[x]&&E[i].t!=son[x]) dfs2(E[i].t,E[i].t);
}

void Build(int g,int l,int r){
	T[g].l=l; T[g].r=r; T[g].x=0;
	if(l==r) return ;
	int mid=l+r>>1;
	Build(g<<1,l,mid); Build(g<<1|1,mid+1,r);
}

inline int dis(int x,int y){
	int ret=0,LCA,a=x,b=y;
	while(top[x]!=top[y])
		if(dpt[top[x]]>dpt[top[y]]) x=fa[top[x]];
		else y=fa[top[y]];
	if(dpt[x]<dpt[y]) LCA=x; else LCA=y;
	return dpt[a]+dpt[b]-2*dpt[LCA];
}

inline void Push(int g){ if(T[g].x) T[g<<1].x=T[g<<1|1].x=1; }
inline void Up(int g){ T[g].x=T[g<<1].x&T[g<<1|1].x; }

int query(int g,int l,int r){
	if(l>r) return 0;
	if(T[g].l==l&&T[g].r==r) return T[g].x;
	Push(g);
	int mid=T[g].l+T[g].r>>1;
	if(r<=mid) return query(g<<1,l,r);
	if(l>mid) return query(g<<1|1,l,r);
	return query(g<<1,l,mid)&query(g<<1|1,mid+1,r);
}

void cover(int g,int l,int r){
	if(l>r) return ;
	if(T[g].l==l&&T[g].r==r){
		T[g].x=1; return ;	
	}
	int mid=T[g].l+T[g].r>>1;
	if(r<=mid) cover(g<<1,l,r);
	else if(l>mid) cover(g<<1|1,l,r);
	else cover(g<<1,l,mid),cover(g<<1|1,mid+1,r);
	Up(g);
}

inline bool cover(int x,int y){
	while(top[x]!=top[y]){
		if(dpt[top[x]]<dpt[top[y]]) swap(x,y);
		if(query(1,p[top[x]],p[x]-1)) return false;
		cover(1,p[top[x]],p[x]-1);
		x=fa[top[x]];
	}
	if(dpt[x]<dpt[y]) swap(x,y);
	if(query(1,p[y],p[x]-1)) return false;
	cover(1,p[y],p[x]-1);
	return true;
}

