    if(a1==b1) return a1;
    for(int i=16; i>=0; i--){
        if(p[i][a1]!=p[i][b1]){
            a1=p[i][a1], b1=p[i][b1];
        }
    }
    return p[0][a1];
}
void add(int s, int t, int i){
	int p0=lca(s, t);
	while(s!=p0){
		v[s].insert(i);
		s=p[0][s];
