		if (set[u].count(v)){
			q.push({u, v});
		}
		else{
			set[u].insert(v);
			set[v].insert(u);
		}
	}
	while (!q.empty()){
		std::pair <int, int> p = q.front();
		q.pop();
		int u = find(p.first), v = find(p.second);
		if (sz[u] > sz[v]){
			std::swap(u, v);
		}
		unite(u, v);
		set[u].erase(v);
		set[v].erase(u);
		for (auto w : set[u]){
			set[w].erase(u);
			if (set[w].count(v)){
