    		if(u != anc[u]) seg::M(dfn[anc[u]] + 1, dfn[u], -1);
    		u = par[anc[u]];
    	}

    	if(dep[u] < dep[v]) swap(u, v);
    	if(u != v) seg::M(dfn[v] + 1, dfn[u], -1);
