void merge(int x,int y){
	x=getfather(x);y=getfather(y);
	if (x==y)return;
	tim++;
	s[x].erase(y);s[y].erase(x);
	if (s[x].size()<s[y].size())swap(x,y);
	int pk=k;
	fa[y]=x;
	for(set<int>::iterator h=s[y].begin();h!=s[y].end();h++){
		s[(*h)].erase(y);
		s[(*h)].insert(x);
		if (s[x].find((*h))!=s[x].end())key[++k]=edge(x,*h);
		s[x].insert(*h);
	}
	s[y].clear();
	int nk=k;
	fo(i,pk+1,nk)merge(key[i].x,key[i].y);
}

