signed main(){
  Int n;
  cin>>n;

  vector<set<Int> > G(n),H(n);
  for(Int i=1;i<n;i++){
    Int x,y;
    cin>>x>>y;
    x--;y--;
    G[x].emplace(y);
    G[y].emplace(x);
  }
  for(Int i=1;i<n;i++){
    Int x,y;
    cin>>x>>y;
    x--;y--;
    H[x].emplace(y);
    H[y].emplace(x);
  }

  UnionFind uf(n);
  using P = pair<Int, Int>;
  priority_queue<P,vector<P>,greater<P> > pq;

  for(Int i=0;i<n;i++) pq.emplace(H[i].size(),i);
  while(!pq.empty()){
    Int v=pq.top().second;pq.pop();
    if(v!=uf.find(v)) continue;
    //v=uf.find(v);
    for(auto z:H[v]){
      if(uf.same(z,v)||!G[v].count(z)) continue;
      Int u=uf.find(z);
      queue<Int> mg;
      mg.emplace(u);
      while(!mg.empty()){
	u=mg.front();mg.pop();
	u=uf.find(u);
	if(uf.same(u,v)) continue;

	if(H[v].size()<H[u].size()) swap(H[v],H[u]);
	if(G[v].size()<G[u].size()) swap(G[v],G[u]);
	for(auto x:G[u]){
	  if(H[u].count(x)||H[v].count(x)) mg.emplace(x);
	  G[v].emplace(x);
	}
	for(auto x:H[u]){
	  if(G[u].count(x)||G[v].count(x)) mg.emplace(x);
	  H[v].emplace(x);
	}
	H[u].clear();G[u].clear();

	uf.unite(u,v);        
	Int r=uf.find(v);
	if(r!=v){
	  swap(H[u],H[v]);
	  swap(G[u],G[v]);
	}
	v=r;
      }
      assert(v==uf.find(v));
      pq.emplace(H[v].size(),v);
      break;
    }
  }

  Int sum=0;
  for(Int i=0;i<n;i++)
    if(uf.find(i)==i) sum+=uf.r[i];
  assert(sum==n);
  sum=0;
  for(Int i=0;i<n;i++)
    sum+=G[i].size();
  assert(sum+1==n);
  sum=0;
  for(Int i=0;i<n;i++)
    sum+=H[i].size();
  assert(sum+1==n);

  cout<<(uf.r[uf.find(0)]==n?"YES":"NO")<<endl;
  return 0;
}

