struct segmenttree {
    vector<int> d;
    vector<pair<int, int> > a;
    int n;
    int sid;

    void init(int sz) {
        sid = cc++;
        n = 1;
        while (n < sz) n *= 2;
        d.assign(2 * n, 0);
        a.assign(2 * n, make_pair(0, 0));
        for (int i = n; i < 2 * n; i++) {
          a[i].second = i - n;
        }
        for (int i = n - 1; i > 0; i--) {
          a[i].second = a[2 * i].second;
        }
    }

    void relax(int v) {
      if (d[v] == 0) return;
      a[v].first += d[v];
      d[2 * v] += d[v];
      d[2 * v + 1] += d[v];
      d[v] = 0;
    }

    void add(int v, int l, int r, int left, int right, int val) {
      if (r <= left || right <= l) {
        return;
      }
      if (left <= l && r <= right) {
        d[v] += val;
        return;
      }
      relax(v);
      int m = (l + r) / 2;
      add(v * 2, l, m, left, right, val);
      add(v * 2 + 1, m, r, left, right, val);
      a[v] = std::min(a[v * 2], a[v * 2 + 1]);
    }

    void add(int l, int r, int val) {
      add(1, 0, n, l, r, val);
    }

    pair<int, int> getmin(int v, int l, int r, int left, int right) {
      if (r <= left || right <= l) {
        return {INF, -1};
      }
      if (left <= l && r <= right) {
        return {a[v].first + d[v], a[v].second};
      }
      relax(v);
      int m = (l + r) / 2;
      return std::min(getmin(v * 2, l, m, left, right), getmin(v * 2 + 1, m, r, left, right));
    }

    pair<int, int> getmin(int l, int r) {
      return getmin(1, 0, n, l, r);
    }

