void addcpath(segmenttree &tree, vector<int> &hpath, int dl, int dr, int value) {
  tree.add(dl, dr, value);
  if (value < 0) {
    while (true) {
      pair<int, int> e = tree.getmin(dl, dr);
      if (e.first == 1) {
        q[tail++] = hpath[e.second];
        tree.add(e.second, e.second + 1, N);
      } else break;
    }
  }
}

void addpath(int v, int p, int add) {
    while (true) {
        if (up[v] == up[p]) {
          addcpath(tree[up[v]], hpath[up[v]], depth[p] + 1, depth[v] + 1, add);
            // tree[up[v]].addpath(depth[p] + 1, depth[v] + 1, add);
            break;
        }
        addcpath(tree[up[v]], hpath[up[v]], 0, depth[v] + 1, add);
        // tree[up[v]].addpath(0, depth[v] + 1, add);
        v = parent[up[v]];
    }
}

int fx[N];

void mxor(int x, int y) {
  for (int i = x; i < N; i |= i + 1) {
    fx[i] ^= y;
  }
}

int gxor(int x) {
  int ret = 0;
  for (int i = x; i >= 0; i = (i & (i + 1)) - 1) {
    ret ^= fx[i];
  }
  return ret;
}

int gxor(int left, int right) {
  return gxor(right - 1) ^ gxor(left - 1);
}


