    for (int i = 0; i + 1 < n; i++) {
        int v, u;
        scanf("%d%d", &v, &u);
        --v;
        --u;
        edges[v].push_back(u);
        edges[u].push_back(v);
    }
    T = 0;
    dfs(0, -1);
    for (int v = 0; v < n; v++) pp[0][v] = parent[v] >= 0 ? parent[v] : v;
    for (int i = 1; i < K; i++) {
        for (int v = 0; v < n; v++) {
            pp[i][v] = pp[i - 1][pp[i - 1][v]];
        }
    }
    for (int i = 0; i + 1 < n; i++) {
      scanf("%d%d", qv + i, qu + i);
      --qv[i];
      --qu[i];
      mxor(en[qv[i]], i);
      mxor(en[qu[i]], i);
      int lc = glca(qv[i], qu[i]);
      addpath(qv[i], lc, 1);
