        tree[up[i]].add(depth[i], depth[i] + 1, N);
        q[tail++] = i;
      }
    }
    while (head < tail) {
      int v = q[head++];
      int pid = gxor(en[v], ex[v]);
      assert(!waspath[pid]);
      waspath[pid] = true;
      mxor(en[qv[pid]], pid);
