struct SegmentTree{
  int N;
  vector<pii> dat;
  vi sum;
  vi S;
  void init(int N_){
    N = 2;
    while(N<N_)N<<=1;
    dat.assign(2*N-1,INFPII);
    sum.assign(2*N-1,0);
    S.assign(2*N-1,0);
    REP(i,N_)dat[i+N-1]=pii(0,i);
    FORR(i,0,N-1)dat[i]=min(dat[2*i+1],dat[2*i+2]);
  }
  SegmentTree(){}
  SegmentTree(int N_){
    init(N_);
  }
  void add(int l,int r,int v,int a,int b,int k){
    // printf("%d %d %d\n",a,b,k);
    if(r<=a || b<=l){
      // nothing
    }else if(l<=a && b<=r){
      sum[k] += v;
      dat[k].first += v;
    }else{
      int m = (a+b)/2;
      add(l,r,v,a,m,2*k+1);
      add(l,r,v,m,b,2*k+2);
      dat[k] = min(dat[2*k+1],dat[2*k+2]);
      dat[k].first += sum[k];
    }
  }
  void add(int l,int r,int v){
    if(r<=l)return;
    add(l,r,v,0,N,0);
  }
  pii qmin(int l,int r,int a,int b,int k){
    if(r<=a || b<=l){
      return INFPII;
    }else if(l<=a && b<=r){
      return dat[k];
    }else{
      int m = (a+b)/2;
      pii ret = min(qmin(l,r,a,m,2*k+1),qmin(l,r,m,b,2*k+2));
      ret.first += sum[k];
      return ret;
    }
  }
  pii qmin(int l,int r){
    if(r<=l)return INFPII;
    return qmin(l,r,0,N,0);
  }
  void insert(int l,int r,int v,int a,int b,int k){
    if(r<=a || b<=l){
      // nothing
    }else if(l<=a && b<=r){
      S[k] += v;
    }else{
      int m = (a+b)/2;
      insert(l,r,v,a,m,2*k+1);
      insert(l,r,v,m,b,2*k+2);
    }
  }
  void insert(int l,int r,int v){
    if(r<=l)return;
    insert(l,r,v,0,N,0);
  }
  void erase(int l,int r,int v,int a,int b,int k){
    if(r<=a || b<=l){
      // nothing
    }else if(l<=a && b<=r){
      S[k] -= v;
    }else{
      int m = (a+b)/2;
      erase(l,r,v,a,m,2*k+1);
      erase(l,r,v,m,b,2*k+2);
    }
  }
  void erase(int l,int r,int v){
    if(r<=l)return;
    erase(l,r,v,0,N,0);
  }
  int getid(int x){
    x += N-1;
    if(S[x]!=0)return S[x];
    while(x>0){
      x = (x-1)/2;
      if(S[x]!=0)return S[x];
    }
    return -1;
  }
};

struct HeavyLightDecomposition{
  static const int root = 0;
  // tree representation
  int N;              // size
  vi parent;          // parent[p] := parent of node p
  vi depth;           // depth[p] := depth of node p
  vi subtreesize;     // subtreesize[p] := size of subtree rooted at node p

  // heavy light decomposition
  vector<vi> paths;   // paths[i] := heavy edge path (id=i)
  vector<SegmentTree> segs;
  vi belongs;         // belongs[p] := id of path that node p belongs to
  vi pathpos;         // pathpos[p] := index of node p in paths[belongs[p]] (paths[belongs[p]][pathpos[p]] == p) (for segment tree)
  vi heavyedge;       // heavyedge[p] := edge (p,heavyedge[p]) is heavy edge

  vi lightedge_qcnt;
  vi lightedge_set;

  // tree construct dfs
  int treedfs(int p,int d,int bef,vi g[]){
    parent[p] = bef;
    depth[p] = d;
    subtreesize[p] = 1;
    int maxchild = -1;
    REP(i,g[p].size()){
      int to = g[p][i];
      if(to==bef)continue;
      subtreesize[p] += treedfs(to,d+1,p,g);
      if(maxchild == -1 || subtreesize[maxchild] < subtreesize[to]){
        maxchild = to;
      }
    }
    if(maxchild != -1 && subtreesize[maxchild]*2 >= subtreesize[p]){
      heavyedge[p] = maxchild;
    }
    return subtreesize[p];
  }

  // heavy light decomposition dfs
  void decompositiondfs(int pathid,int head,int bef,vi g[]){
    paths.push_back(vi());
    int cur = head;
    while(true){
      belongs[cur] = pathid;
      pathpos[cur] = paths[pathid].size();
      paths[pathid].push_back(cur);
      int nxt = heavyedge[cur];
      REP(i,g[cur].size()){
        int to = g[cur][i];
        if(to==bef)continue;
        if(to==nxt)continue;
        decompositiondfs(paths.size(),to,cur,g);
      }
      if(nxt==-1)break;
      bef = cur;
      cur = nxt;
    }
  }

  HeavyLightDecomposition(int n,vi g[]){
    N = n;
    parent.assign(n,-1);
    depth.assign(n,-1);
    subtreesize.assign(n,-1);
    belongs.assign(n,-1);
    pathpos.assign(n,-1);
    heavyedge.assign(n,-1);

    treedfs(root,0,-1,g);
    decompositiondfs(0,root,-1,g);

    // init for query
    REP(i,paths.size()){
      segs.push_back(SegmentTree(paths[i].size()-1));
    }
    lightedge_qcnt.assign(paths.size(), 0);
    lightedge_set.assign(paths.size(), 0);
  }

  int lca(int a,int b){
    int ato = paths[belongs[a]][0];
    int bto = paths[belongs[b]][0];
    while(belongs[a]!=belongs[b]){
      if(depth[ato] > depth[bto]){
        a = ato;
        if(a!=root){
          a = parent[a];
          ato = paths[belongs[a]][0];
        }
      }else{
        b = bto;
        if(b!=root){
          b = parent[b];
          bto = paths[belongs[b]][0];
        }
      }
    }
    if(depth[a]<=depth[b]){
      return a;
    }else{
      return b;
    }
  }

  void addup(int a,int g,int id){
    while(belongs[a] != belongs[g]){
      int decompid = belongs[a];
      int pos = pathpos[a];
      segs[decompid].add(0,pos,1);
      // printf("[0,%d)\n",pos);
      segs[decompid].insert(0,pos,id);
      lightedge_qcnt[decompid] += 1;
      lightedge_set[decompid] += id;
      int p = paths[decompid][0];
      a = parent[p];
    }
    int decompid = belongs[a];
    int pos = pathpos[a];
    int gpos = pathpos[g];
    segs[decompid].add(gpos,pos,1);
    // printf("[%d,%d)\n",gpos,pos);
    segs[decompid].insert(gpos,pos,id);
  }
  void add(int a,int b,int id){
    int g = lca(a,b);
    addup(a,g,id);
    addup(b,g,id);
  }
  void eraseup(int a,int g,int id){
    while(belongs[a] != belongs[g]){
      int decompid = belongs[a];
      int pos = pathpos[a];
      segs[decompid].add(0,pos,-1);
      segs[decompid].erase(0,pos,id);
      lightedge_qcnt[decompid] -= 1;
      lightedge_set[decompid] -= id;
      int p = paths[decompid][0];
      a = parent[p];
    }
    int decompid = belongs[a];
    int pos = pathpos[a];
    int gpos = pathpos[g];
    segs[decompid].add(gpos,pos,-1);
    segs[decompid].erase(gpos,pos,id);
  }
  void erase(int a,int b,int id){
    int g = lca(a,b);
    eraseup(a,g,id);
    eraseup(b,g,id);
  }
  bool calc(vector<pii> &PS){
    assert(PS.size()==N-1);
    vi lcas(N-1);
    REP(i,N-1){
      lcas[i] = lca(PS[i].first, PS[i].second);
      addup(PS[i].first, lcas[i], i+125);
      addup(PS[i].second, lcas[i], i+125);
    }
    REP(_,N-1){
      // get 1-path
      bool done = false;
      // from lightedge
      REP(i,paths.size()){
        if(lightedge_qcnt[i] == 1){
          // do it
          int id = lightedge_set[i] - 125;
          eraseup(PS[id].first, lcas[id], id+125);
          eraseup(PS[id].second, lcas[id], id+125);
          // just do it
          done = true;
          break;
        }
      }
      if(!done){
        REP(i,paths.size()){
          pii qu = segs[i].qmin(0,segs[i].N);
          if(qu.first==1){
            // do it
            int p = qu.second;
            int id = segs[i].getid(p) - 125;
          eraseup(PS[id].first, lcas[id], id+125);
          eraseup(PS[id].second, lcas[id], id+125);
            segs[i].add(p,p+1,INF);
            // just do it
            done = true;
            break;
          }
        }
      }
      if(!done)return false;
    }
    return true;
  }
};

