        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (int i = 1; i <= n - 1; ++i) scanf("%d%d", &red[i][0], &red[i][1]);

    DFS(1);
    HLD(1);
    ST.Assign(1, 1, n, pos[1], INF);
    for (int i = 1; i <= n - 1; ++i) {
        UpdateRed(red[i][0], red[i][1], i);
    }

    for (int i = 1; i <= n - 1; ++i) {
        if (ST.S[1].Min != 1) {
            puts("NO");
            return 0;
        }
        int u = ST.MinElement(1, 1, n);
        int x = ST.Find(1, 1, n, u);
        UpdateRed(red[x][0], red[x][1], -x);
        ST.Assign(1, 1, n, u, INF);
    }
    puts("YES");
    return 0;
}

