		u = uf.root(u), v = uf.root(v);

		if((int)B[v].size()+(int)R[v].size() > (int)B[u].size()+(int)R[u].size()) swap(u, v);
		for(auto it = B[v].begin(); it != B[v].end(); it++){
			if(*it == 0) continue;
			if(R[u].count(*it)){
				auto tmp = it; tmp--;
				Q.push(P(u, *it));
				R[*it].erase(u);
				B[*it].erase(v);
				R[u].erase(*it);
