const int N=1000005;
typedef set<int>::iterator It;
set<int> S[N];
queue<pair<int,int> > q;
map<pair<int,int>,int> Map;
int FA[N],n;
int find(int u) { if (u!=FA[u]) FA[u]=find(FA[u]); return FA[u]; }
pair<int,int> work(int u,int v) { if (u>v) swap(u,v); return make_pair(u,v); }
void Add(int u,int v) {
	if (u>v) swap(u,v);
	S[u].insert(v),S[v].insert(u);
	Map[work(u,v)]++; int num=Map[work(u,v)];
	if (num==2) q.push(work(u,v));
}
void Del(int u,int v) {
	S[u].erase(v); S[v].erase(u);
	Map.erase(work(u,v));
}
bool Solve() {
	for (int i=1; i<=n; i++) FA[i]=i;
	for (int i=1; i<n; i++) {
		if (q.empty()) return false;
		int u=q.front().first,v=q.front().second;
		q.pop(); u=find(u),v=find(v);
		if (S[u].size()>S[v].size()) swap(u,v);
		FA[u]=v; Del(u,v);
		for (It i=S[u].begin(),j; i!=S[u].end(); i=j) {
			(j=i)++; int x=*i; x=find(x);
			Del(u,x); Add(v,x);
		}
	}
	return true;
}
