	int s,t;
};
queue<node> q;
int sum[maxn];
int f[maxn];
int fa(int x){
	if(f[x]==x) return x;
	return f[x]=fa(f[x]);
}
int zs,zt;
int stk[maxn],top;
void merge(int s,int t){
//	if(s==t) return ;
	int v;
	sum[t]+=sum[s];
	f[s]=t;

	it=sak1[s].begin();
	while(it!=sak1[s].end()){
		v=*it;
		if(fa(t)!=fa(v))
		{
			itt=sak2[t].lower_bound(v);
			if(itt!=sak2[t].end()&&*itt==v)
				q.push((node){t,v});
			itt=sak1[t].lower_bound(v);
			stk[++top]=v;
		}
		it++;
	}
	sak1[s].clear();

	it=sak2[s].begin();
	while(it!=sak2[s].end()){
		v=*it;
		if(fa(t)!=fa(v))
		{
			itt=sak1[t].lower_bound(v);
			if(itt!=sak1[t].end()&&*itt==v)
				q.push((node){t,v});
			sak2[t].insert(v);
		}
		it++;
	}
	sak2[s].clear();
	while(top){
		sak1[t].insert(stk[top]);
		top--;
	}
}
