		scanf("%d%d", &u, &v);
		blue[u].insert(v);
		blue[v].insert(u);
	}
}

int find(int u, int father[]) {
	if (father[u] == u) {
		return u;
	} else {
		return father[u] = find(father[u], father);
	}
}

void work() {
	static std::vector<std::pair<int, int>> records;

	for (int u = 1; u <= n; u++) {
		for (auto v : red[u]) {
			if (v > u && blue[u].find(v) != blue[u].end()) {
				records.push_back({u, v});
			}
		}
	}

	static int father[N];
	for (int i = 1; i <= n; i++) {
		father[i] = i;
	}
	for (int l = 0; l < (int)records.size(); l++) {
		int u = find(records[l].first, father), v = find(records[l].second, father);
		if (red[u].size() + blue[u].size() > red[v].size() + blue[v].size()) {
			std::swap(u, v);
		}
		red[u].erase(v);
		red[v].erase(u);
		blue[u].erase(v);
		blue[v].erase(u);
		for (auto t : red[u]) {
			if (blue[v].find(t) != blue[v].end()) {
				records.push_back({t, v});
			}
		}
		for (auto t : blue[u]) {
			if (red[v].find(t) != red[v].end()) {
				records.push_back({t, v});
			}
		}
		for (auto t : red[u]) {
			red[v].insert(t);
			red[t].erase(u);
			red[t].insert(v);
		}
		for (auto t : blue[u]) {
			blue[v].insert(t);
			blue[t].erase(u);
			blue[t].insert(v);
		}
		father[u] = v;
	}
	if (records.size() == n - 1) {
		std::cout << "YES" << std::endl;
	} else {
		std::cout << "NO" << std::endl;
	}
}

