queue < pair < int , int > > q;
void insert(int a , int b){
	++edges[a][b];
	++edges[b][a];
	if(edges[a][b] == 2){
		q.push({a , b});
	}
}
void merge(){
	int a = q.front().first;
	int b = q.front().second;
	q.pop();
	if(edges[a].size() > edges[b].size()){
		swap(a , b);
	}
	for(auto it : edges[a]){
		if(it.first == b){
			continue;
		}
		edges[it.first].erase(edges[it.first].find(a));
	}
	for(auto it : edges[a]){
		if(it.first == b){
			continue;
		}
		insert(b , it.first);
	}
	edges[a].clear();
}
