    ios::sync_with_stdio(false); cin.tie(0);
    struct E { int to; };
    int n;
    cin >> n;
    VV<E> g(n);
    for (int i = 0; i < n-1; i++) {
        int a, b;
        cin >> a >> b; a--; b--;
        g[a].push_back(E{b});
        g[b].push_back(E{a});
    }
    auto tr = new Node(n);
    auto hl = get_hl(g, 0);
    auto add = [&](int x, int y, int z) {
        int c = hl.lca(x, y), d = hl.par(c);
        hl.get_path(c, x, [&](int a, int b){
            tr->add(a, b+1, z);
        });
        hl.get_path(d, y, [&](int a, int b){
            tr->add(a, b+1, z);
        });
    };
    V<int> c(n), d(n);
    for (int i = 0; i < n-1; i++) {
        cin >> c[i] >> d[i]; c[i]--; d[i]--;
        add(c[i], d[i], TEN(6) + i);
    }

    int pc = 0;
    while (true) {
        P p = tr->get(0, n);
        if (p.first == 0) {
            tr->add(p.second, p.second + 1, TEN(18));
            continue;
        }
        if (p.first >= 2*TEN(6)) {
            cout << "NO" << endl;
            return 0;
        }
        int idx = p.first - TEN(6);
        add(c[idx], d[idx], -TEN(6) - idx);
        pc++;
        if (pc == n-1) break;
    }
    cout << "YES" << endl;
    return 0;
}

