int h[maxn];

void pre(int u, int prev, int ch = 0) {
    in[u] = timer++;
    h[u] = ch;
    p[u][0] = prev;
    for (int v: g[u]) {
        if (v == prev)
            continue;
        pre(v, u, ch + 1);
    }
    out[u] = timer;
}

bool isPrev(int u, int v) {
    return in[u] <= in[v] && out[v] <= out[u];
}

int lca(int u, int v) {
    for (int d = maxd - 1; d >= 0; --d)
        if (!isPrev(p[u][d], v))
            u = p[u][d];
    if (!isPrev(u, v))
        u = p[u][0];
    return u;
}

int fw[maxn];

void put(int pos, int delta) {
    for (int i = pos; i < maxn; i |= i + 1)
        fw[i] += delta;
}

int get(int r) {
    int res = 0;
    for (int i = r; i >= 0; i = (i & (i + 1)) - 1)
        res += fw[i];
    return res;
}

int rem(int id) {
    int u = qu[id];
    int v = qv[id];
    int w = qw[id];
    int res = get(in[v]);
    res += get(in[u]);
    res -= 2 * get(in[w]);
    return res;
}

struct DSU {
    vector<int> col;

    DSU() {
    }

    DSU(int n): col(n) {
        iota(all(col), 0);
    }

    int get(int u) {
        if (u == col[u])
            return u;
        return u = get(col[u]);
    }

    void join(int u, int v) {
        u = get(u);
        v = get(v);
        col[u] = v;
    }
} dsu;

