int singleEdge(int id) {
    int len = rem(id);
    assert(len == 1);
    int u = qu[id];
    int v = qv[id];
    int w = qw[id];
    while (h[u] > h[w]) {
        int e = dsu.get(u);
        if (h[e] <= h[w])
            break;
        return e;
    }
    while (h[v] > h[w]) {
        int e = dsu.get(v);
        if (h[e] <= h[w])
            break;
        return e;
    }
    assert(false);
}

void extractEdges(int id) {
    int len = rem(id);
    int u = qu[id];
    int v = qv[id];
    int w = qw[id];
    while (h[u] > h[w]) {
        int e = dsu.get(u);
        if (h[e] <= h[w])
            break;
        by[e].push_back(id);
        //cerr << "Edge " << e << '\n';
        u = p[e][0];
        --len;
    }
    while (h[v] > h[w]) {
        int e = dsu.get(v);
        if (h[e] <= h[w])
            break;
        by[e].push_back(id);
        //cerr << "Edge " << e << '\n';
        v = p[e][0];
        --len;
    }
    assert(len == 0);
}

