#define MAXN 100000
using namespace std;
typedef pair<int,int> PII;
queue<PII> que;
set<int> st[MAXN+5];
map<PII,int> mp;
int N,setfa[MAXN+5];
vector<int> vec;
PII Work(int x,int y)
{
	if(x>y)
		swap(x,y);
	return PII(x,y);
}
void AddEdge(int u,int v)
{
	st[u].insert(v);
	st[v].insert(u);
	mp[Work(u,v)]++;
	if(mp[Work(u,v)]==2)
		que.push(Work(u,v));
}
void Init()
{
	for(int i=0;i<=MAXN;i++)
		setfa[i]=i;
}
int Findfa(int x)
{
	if(x==setfa[x])
		return x;
	return setfa[x]=Findfa(setfa[x]);
}
void Union(int x,int y)
{
	int fx=Findfa(x),fy=Findfa(y);
	if(fx==fy)
		return;
	setfa[fx]=fy;
}
int main()
{
//	freopen("bluered.in","r",stdin);
//	freopen("bluered.out","w",stdout);
	Init();
	scanf("%d",&N);
	int u,v;
	for(int i=1;i<=2*N-2;i++)
	{
		scanf("%d %d",&u,&v);
		AddEdge(u,v);
	}
	set<int>::iterator it;
	for(int i=1;i<=N-1;i++)
	{
		int spu,spv;
		while(true)
		{
			if(que.empty()==true)
			{
				printf("NO\n");
				exit(0);
			}
			u=Findfa(que.front().first);
			v=Findfa(que.front().second);
			que.pop();
			if(Findfa(u)==Findfa(v))
				continue;
			spu=u,spv=v;
			break;
		}
		if(st[spu].size()>st[spv].size())
			swap(spu,spv);
		Union(spu,spv);
		mp.erase(Work(spu,spv));
		st[spv].erase(spu);
		vec.clear();
		for(it=st[spu].begin();it!=st[spu].end();it++)
			vec.push_back(*it);
		for(int i=0;i<vec.size();i++)
		{
			int poi=vec[i];
			poi=Findfa(poi);
			if(poi==spv)
				continue;
			mp.erase(Work(spu,poi));
			st[poi].erase(spu);
			st[spu].erase(poi);
			AddEdge(poi,spv);
		}
	}
	printf("YES\n");
	return 0;
}

