int find(int x) {
  if (dad[x] == x) return x;
  return dad[x] = find(dad[x]);
}

void add_edge(int x, int y, int t) {
  y  = find(y);
  if (x == y) return;

  e[x][t].insert(y);
  if (e[x][t^1].find(y) != e[x][t^1].end()) {
    q.push({x, y});
  }
}


void merge(int u, int v) {
  u = find(u);
  v = find(v);
  if (u == v) return;

  ++totm;

  if (sz[v] > sz[u]) swap(u, v);
  dad[v] = u;

  REP(t, 2)
    for (auto it = e[v][t].begin(); it != e[v][t].end(); ++it)
      add_edge(u, *it, t);
}

int main(void) {
  scanf("%d",&n);
  REP(i, n) dad[i] = i;
  REP(t, 2) {
    REP(i, n - 1) {
      int u, v;
      scanf("%d %d",&u,&v);
      --u;
      --v;
      add_edge(u, v, t);
      add_edge(v, u, t);
    }
  }

  while (!q.empty()) {
    pii x = q.front();
    q.pop();

    TRACE(x.u+1 _ x.v+1);

    merge(x.u, x.v);
  }

