#define Rep(i, n) for (int i = 1; i <= n; i ++)
#define RepG(i, x) for (int i = head[x]; i; i = edge[i].next)
#define RepG0(i, x) for (int i = head0[x]; i; i = edge0[i].next)
#define mp(a, b) make_pair(a, b)

using namespace std;

const int N = 200010;

struct Edge{int to, next;} edge[N * 2], edge0[N * 2];
int head[N], num, d[N], head0[N], num0;
map<int, int> m[N], m0[N];
void add_edge(int a, int b) { edge[++ num] = (Edge){b, head[a]}, head[a] = num, m[a][b] = 1; }
void add_edge0(int a, int b) { edge0[++ num0] = (Edge){a, head0[b]}, head0[b] = num0, m0[a][b] = 1;}

int f[N];
int f_f(int x) { return f[x] == x ? x : f[x] = f_f(f[x]);}

pair<int, int> q[N];

int main()
{
	int n, a, b;
	scanf("%d", &n);
	Rep(i, n - 1) { 
		scanf("%d%d", &a, &b); 
		add_edge(a, b); add_edge(b, a); 
		d[a] ++, d[b] ++;
	}
	Rep(i, n - 1) { 
		scanf("%d%d", &a, &b); 
		add_edge0(a, b); add_edge0(b, a); 
		d[a] ++, d[b] ++;
	}
	int he = 0, ta = 0, cnt = 0;
	Rep(i, n) f[i] = i;

	Rep(i, n) RepG(j, i)if (m0[edge[j].to][i])
		q[++ ta] = mp(i, edge[j].to);

	while (he != ta) {
		int fx = f_f(q[++ he].first), fy = f_f(q[he].second);
		if (fx == fy) continue;
		cnt ++;
		if (d[fx] < d[fy]) swap(fx, fy);
		RepG0(i, fy){
			int fv = f_f(edge0[i].to);
			if (fv == fx) continue;
			if (m[fx][fv]) q[++ ta] = mp(fx, fv);
			m0[fx][fv] = m0[fv][fx] = true;
		}
		RepG(i, fy){
			int fv = f_f(edge[i].to);
			if (fv == fx) continue;
			if (m0[fx][fv]) q[++ ta] = mp(fx, fv);
			m[fx][fv] = m[fv][fx] = true;
		}
		f[fy] = fx, d[fy] += d[fx];
	}

	if (cnt == n - 1) printf("YES\n");
	else printf("NO\n");

	return 0;
}

