		if (dep[fx] < dep[fy]) swap(x, y);
		seg_modify(RT, bg[fx], bg[x], tag, d); x = fa[fx];
	}
	if (dep[x] > dep[y]) swap(x, y);
	if (x != y) seg_modify(RT, bg[x] + 1, bg[y], tag, d);
}

