void push(int w,int z)
{
	t[w].z+=z,t[w].b+=z;
}

void pushdown(int w)
{
	int &z=t[w].b;
	if (z)
		push(w<<1,z),push(w<<1|1,z),z=0;
}

void update(int w)
{
	t[w].z=min(t[w<<1].z,t[w<<1|1].z);
}

void motree(int w,int L,int R)
{
	if (l<=L&&r>=R)
	{
		push(w,z);
		return;
	}
	pushdown(w);
	int mid=L+R>>1;
	if (l<=mid)
		motree(w<<1,L,mid);
	if (r>mid)
		motree(w<<1|1,mid+1,R);
	update(w);
}

int qtree(int w,int L,int R)
{
	if (l<=L&&r>=R) return t[w].z;
	pushdown(w);
	int mid=L+R>>1;
	return min(l<=mid?qtree(w<<1,L,mid):inf,r>mid?qtree(w<<1|1,mid+1,R):inf);
}

int getlca(int x,int y)
