		x=fa[top[x]];
	}
	if (x==y) return;
	if (h[x]>h[y]) swap(x,y);
	l=dfn[x]+1,y=dfn[y],motree(1,1,n);
}

bool qt(int x,int y)
{
	while (top[x]!=top[y])
	{
		if (h[top[x]]<h[top[y]])
			swap(x,y);
		l=dfn[top[x]],r=dfn[x];
		if (!qtree(1,1,n)) return 0;
		x=fa[top[x]];
	}
	if (x==y) return 1;
	if (h[x]>h[y]) swap(x,y);
	l=dfn[x]+1,y=dfn[y];
	if (qtree(1,1,n)) return 0;
	return 1;
}

