const int MAXN = (int) 1e5;

struct edge
{
	int u, v;

	edge() { }
	edge(int _u, int _v): u(_u), v(_v) { }
};

int n;

edge A[MAXN + 5], B[MAXN + 5];

inline void input()
{
	n = read<int>();
	for(int i = 1; i < n; ++i) A[i].u = read<int>(), A[i].v = read<int>();
	for(int i = 1; i < n; ++i) B[i].u = read<int>(), B[i].v = read<int>();
}

namespace SET
{
	int fa[MAXN + 5];

	inline void init(int N) { for(int i = 1; i <= N; ++i) fa[i] = i; }
	inline int get_fa(int u) { return u == fa[u] ? u : fa[u] = get_fa(fa[u]); }
	inline void set_fa(int u, int v) { fa[get_fa(u)] = get_fa(v); }
}

inline void solve()
{
	static queue<pii> q;
	static unordered_map<int, int> adj[MAXN + 5];

	auto add_edge = [&] (int u, int v)
	{
		++adj[u][v];
		++adj[v][u];
		if(adj[u][v] == 2) q.emplace(u, v);
	};

	auto erase_edge = [&] (int u, int v)
	{
		if(SZ(adj[u]) < SZ(adj[v])) swap(u, v);
		SET::set_fa(v, u);
		for(auto it : adj[v]) if(it.snd == 1)
			if(SET::get_fa(it.fst) != u) add_edge(u, SET::get_fa(it.fst));
		adj[v].clear();
	};

	for(int i = 1; i < n; ++i) add_edge(A[i].u, A[i].v);
	for(int i = 1; i < n; ++i) add_edge(B[i].u, B[i].v);

	SET::init(n);
	int cnt = 0;
	while(!q.empty())
	{
		auto it = q.front();
		++cnt, q.pop();
		it.fst = SET::get_fa(it.fst);
		it.snd = SET::get_fa(it.snd);
		erase_edge(it.fst, it.snd);
	}
	puts(cnt == n - 1 ? "YES" : "NO");
}

