		ad[u].erase(v);
		while(ad[v].size()) {
			int x = *ad[v].begin();
			ad[v].erase(x);
			ad[x].erase(v);
			if (x == u) continue;
			mp[make_pair(x, v)] = mp[make_pair(v, x)] = 0;
			add(x, u);
		}
	}
	if(q.size() == n - 1) return cout << "YES", 0;
	return cout << "NO", 0;
}

