		{
			int ans = 0;
			for(l += t - 1, r += t + 1; l ^ r ^ 1; l >>= 1, r >>= 1)
			{
				if(~l & 1)
					ans += no[l];
				if(r & 1)
					ans += no[r];
			}
			return ans;
		}
	}
