class UnionFindTree
{
private:
    const int n;
    int groupNum;       // グループの数
    vector<int> parent; // 親ノード
    vector<int> rank;   // 木の高さの上限
    vector<int> num;    // グループの要素数
    int find(int i){
        if(parent[i] == i)
            return i;
        else
            return parent[i] = find(parent[i]);
    }
public:
    UnionFindTree(int n) : n(n){ // コンストラクタ
        groupNum = n;
        parent.resize(n);
        for(int i=0; i<n; ++i)
            parent[i] = i;
        rank.assign(n, 0);
        num.assign(n, 1);
    }
    void unite(int a, int b){ // aとbのグループを併合
        if((a = find(a)) != (b = find(b))){
            if(rank[a] < rank[b]){
                parent[a] = b;
                num[b] += num[a];
            }
            else{
                parent[b] = a;
                if(rank[a] == rank[b])
                    ++ rank[a];
                num[a] += num[b];
            }
            -- groupNum;
        }
    }
    bool same(int a, int b){ // aとbのグループが同じかを調べる
        return find(a) == find(b);
    }
    int getNum(){ // グループの数を返す
        return groupNum;
    }
    int getNum(int a){ // aのグループの要素数を返す
        return num[find(a)];
    }
};

int main()
{
    int n;
    cin >> n;
    vector<set<pair<int, int> > > s(2);
    for(int i=0; i<2; ++i){
        for(int j=0; j<n-1; ++j){
            int a, b;
            cin >> a >> b;
            -- a;
            -- b;
            s[i].insert(make_pair(a, b));
            s[i].insert(make_pair(b, a));
        }
    }

    queue<pair<int, int> > q;
    for(const auto& p : s[0]){
        if(p.first < p.second && s[1].find(p) != s[1].end())
            q.push(p);
    }

    UnionFindTree uft(n);
    for(int t=0; t<n-1; ++t){
        if(q.empty()){
            cout << "NO" << endl;
            return 0;
        }

        int a, b;
        tie(a, b) = q.front();
        q.pop();
        if(uft.getNum(a) < uft.getNum(b))
            swap(a, b);

        for(int i=0; i<2; ++i){
            s[i].erase(make_pair(a, b));
            s[i].erase(make_pair(b, a));
            for(;;){
                auto it = s[i].lower_bound(make_pair(b, -1));
                if(it == s[i].end() || it->first != b)
                    break;

                int c = it->second;
                s[i].erase(make_pair(b, c));
                s[i].erase(make_pair(c, b));
                s[i].insert(make_pair(a, c));
                s[i].insert(make_pair(c, a));
                if(s[i^1].find(make_pair(a, c)) != s[i^1].end())
                    q.push(make_pair(a, c));
            }
        }
    }

    cout << "YES" << endl;
    return 0;
}

