	swap(H[v][i],H[v].back());
	H[v].pop_back();
	if(H[v].size()<H[u].size()) swap(H[v],H[u]);
	if(G[v].size()<G[u].size()) swap(G[v],G[u]);
	for(auto x:H[u])
	  if(!uf.same(v,x)&&!uf.same(u,x)) H[v].emplace_back(x);
	for(auto x:G[u])
	  if(!uf.same(v,x)&&!uf.same(u,x)) G[v].emplace(x);

	for(auto x:H[v])
	  if(!uf.same(v,x)&&!uf.same(u,x)) H[u].emplace_back(x);
	for(auto x:G[v])
	  if(!uf.same(v,x)&&!uf.same(u,x)) G[u].emplace(x);

	//H[u].clear();G[u].clear();

	uf.unite(u,v);
	Int r=uf.find(v);
	if(r!=v){
	  swap(H[r],H[v]);
	  swap(G[r],G[v]);
	}
	pq.emplace(H[u].size(),u);
	pq.emplace(H[v].size(),v);
	//pq.emplace(H[r].size(),r);
	break;
      }
    }
  }

  cout<<(uf.r[uf.find(0)]==n?"YES":"NO")<<endl;
  return 0;
}

