int fa[MAXN];
int Root(int x)
{return fa[x]==0?x:(fa[x]=Root(fa[x]));}

void Link(int u,int v)
{
    E[u].insert(v);
    E[v].insert(u);
    if(u>v)
        swap(u,v);
    cnt[u][v]++;
    if(cnt[u][v]>2)
    {
        puts("NO");
        exit(0);
    }
    if(cnt[u][v]==2)
        Q.emplace(u,v);
}
void Cut(int u,int v)
{
    E[u].erase(v);
    if(u>v)
        swap(u,v);
    cnt[u].erase(v);
}

int main()
{
