    for(int i=1;i<=2*N-2;i++)
    {
        int u,v;
        scanf("%d%d",&u,&v);
        Link(u,v);
    }
    for(int i=1;i<N;i++)
    {
        int u,v;
        do
        {
            if(Q.empty())
            {
                puts("NO");
                return 0;
            }
            u=Root(Q.front().first),v=Root(Q.front().second);
            Q.pop();
        }while(u==v);
        if(E[u].size()<E[v].size())
            swap(u,v);
        fa[v]=u;
        Cut(u,v);
        for(auto e:E[v])
        {
            int t=Root(e);
            if(t==u)
                continue;
            Link(t,u);
            Cut(t,v);
        }
    }
    puts("YES");

