int find(int x) {
  if (dad[x] == x) return x;
  return dad[x] = find(dad[x]);
}

void add_edge(int x, int y, int t) {
  if (x == find(y)) return;

  e[x][t].insert(y);
  if (e[x][t^1].count(y)) 
    q.push({x, y});
}

void change_edge(int x, int y1, int y2, int t) {
  if (x == find(y1)) return;

  e[x][t].insert(y2);

  if (e[x][t^1].count(y2))
    q.push({x, y2});
}

void merge(int u, int v) {
  u = find(u);
  v = find(v);
  if (u == v) return;

  ++totm;

  if (sz[v] > sz[u]) swap(u, v);
  dad[v] = u;
  sz[u] += sz[v];

  REP(t, 2)
    for (auto it = e[v][t].begin(); it != e[v][t].end(); ++it)
      change_edge(*it, v, u, t);

  REP(t, 2)
    for (auto it = e[v][t].begin(); it != e[v][t].end(); ++it)
      add_edge(u, *it, t);
}

int main(void) {
