  REP(t, 2) {
    REP(i, n - 1) {
      int u, v;
      scanf("%d %d",&u,&v);
      --u;
      --v;
      add_edge(u, v, t);
      add_edge(v, u, t);
    }
  }

  while (!q.empty()) {
    pii x = q.front();
    q.pop();

    TRACE(x.u+1 _ x.v+1);

    merge(x.u, x.v);
  }

  printf(totm == n - 1 ? "YES\n" : "NO\n");

  return 0;
}

