        int a,b; cin >> a >> b;
        a = findset(a), b = findset(b);
        assert(a != b);
        if (a > b) swap(a,b);
        if (f.count({a,b})) {
            merge(a,b);
        } else {
            c[a].insert(b);
            c[b].insert(a);
            f.insert({a,b});
        }
    }

    //cout<<SZ(q)<<endl;

    while (!q.empty()){
        ii a = q.front(); q.pop();
        a.fi = findset(a.fi), a.sc = findset(a.sc);
        if (a.fi > a.sc) swap(a.fi,a.sc);
        merge(a.fi,a.sc);
    }

    cout << (merged == N-1 ? "YES" : "NO");
}

