        f[i] = i, sz[i] = 1;

    while(!q.empty())
    {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();

        int fx = F(x), fy = F(y);
        if(fx == fy)    continue;
        if(sz[fx] > sz[fy]) swap(x, y), swap(fx, fy);

        f[fx] = fy;
        sz[fy] += sz[fx];

        for(auto nxt: edg[fx])
        {
