int main(){
	int a;scanf("%d",&a);
	for(int i=0;i<a-1;i++){
		int p,q;scanf("%d%d",&p,&q);
		p--;q--;
		A[p].insert(q);
		A[q].insert(p);
	}
	for(int i=0;i<a-1;i++){
		int p,q;scanf("%d%d",&p,&q);
		p--;q--;
		B[p].insert(q);
		B[q].insert(p);
	}
	init_UF(110000);
	queue<pair<int,int> >Q;
	int cnt=0;
	for(int i=0;i<a;i++){
		for(set<int>::iterator it=A[i].begin();it!=A[i].end();it++){
			if(i>(*it))continue;
			if(B[i].count(*it)){
				Q.push(make_pair(i,*it));
			}
		}
	}
	while(Q.size()){
		pair<int,int>at=Q.front();
		Q.pop();
		if(FIND(at.first)==FIND(at.second))continue;
		cnt++;
		int L=FIND(at.first);
		int R=FIND(at.second);
		if(A[L].size()+B[L].size()<A[R].size()+B[R].size()){
			swap(L,R);
		}
		UNION(L,R);
		for(set<int>::iterator it=A[R].begin();it!=A[R].end();it++){
			if((*it)==L)continue;
			if(B[L].count(*it)||B[R].count(*it)){
				Q.push(make_pair(L,*it));	
			}
		}

		for(set<int>::iterator it=B[R].begin();it!=B[R].end();it++){
			if((*it)==L)continue;
			if(A[L].count(*it)||A[R].count(*it)){
				Q.push(make_pair(L,*it));	
			}
		}
		for(set<int>::iterator it=A[R].begin();it!=A[R].end();it++){
			if((*it)==L)continue;
			A[L].insert(*it);
		}

		for(set<int>::iterator it=B[R].begin();it!=B[R].end();it++){
			if((*it)==L)continue;
			B[L].insert(*it);
		}

	}
	if(cnt==a-1)printf("YES\n");
	else printf("NO\n");

}

