pair<int, int> getMin(int u, int v) {
    pair<int, int> res = {INF, -1};
    path(u, v, [&](int l, int r) {
        res = min(res, tree.get(1, 0, n - 1, l, r));
    });
    return res;
}

void add(int u, int v, int x) {
    path(u, v, [&](int l, int r) {
        tree.add(1, 0, n - 1, l, r, x);
    });
}

void xr(int u, int v, int x) {
    path(u, v, [&](int l, int r) {
        tree.upd(1, 0, n - 1, l, r, x);
    });
}

int get2(int v) {
    return tree.get2(1, 0, n - 1, pos[v]);
}

