            xr(u[i], v[i], i);
        }
        tree.add(1, 0, n - 1, pos[0], pos[0], INF);

        int cnt = 0;
        while (cnt < n - 1) {
            auto o = tree.get(1, 0, n - 1, 0, n - 1);
            if (o.first != 1) break;
            int cur = vert[o.second];
            int id = tree.get2(1, 0, n - 1, pos[cur]);
            add(v[id], u[id], -1);
            xr(v[id], u[id], id);
            add(cur, par[cur], INF);
            cnt++;
        }
        string ans = cnt == n - 1 ? "YES" : "NO";
        cout << ans << endl;
    }


#ifdef HOME
    cerr << "time: " << clock() * 1.0 / CLOCKS_PER_SEC << endl;
#endif
    return 0;
}

