    if(b == 0)  return a;
    return gcd(b, a%b);
}


const int N = 100002;
int n, deg1[N], deg2[N];
vector<int> adj1[N], adj2[N];
ii tree[4*N];
bool done[N];


void build(int node, int s, int e){
	if(s > e)	return;
	if(s == e){
		tree[node] = ii(0, s);
		return;
	}
	int mid = (s+e)/2;
	build(LEFT(node), s, mid);
	build(RIGHT(node), mid+1, e);
	tree[node] = max(tree[LEFT(node)], tree[RIGHT(node)]);
}

void update(int node, int s, int e, int pos, int val){
	if(s > e || pos < s || pos > e)	return;
	if(s == e){
		tree[node].ff += val;
		return;
	}
	int mid = (s+e)/2;
	update(LEFT(node), s, mid, pos, val);
	update(RIGHT(node), mid+1, e, pos, val);
	tree[node] = max(tree[LEFT(node)], tree[RIGHT(node)]);
}

ii query(int node, int s, int e, int lo, int hi){
	if(s > e || s > hi || lo > e)	return ii(-MOD, 0);
	if(s >= lo && e <= hi)	return tree[node];
	int mid = (s+e)/2;
	ii a = query(LEFT(node), s, mid, lo, hi);
	ii b = query(RIGHT(node), mid+1, e, lo, hi);
	return max(a, b);
}



