    for(int i=1;i<=n;i++){
    	if(deg1[i] == 1)	update(1, 1, n, i, 1);
    	if(deg2[i] == 1)	update(1, 1, n, i, 1);
    }

    while(1){

    	ii nxt = query(1, 1, n, 1, n);
// cout<<nxt.ff<<" "<<nxt.ss<<endl;
    	if(nxt.ff != 2)	break;

    	done[nxt.ss] = true;

