segmenttree tree[N];
vector<int> hpath[N];
vector<int> edges[N];
int pp[K][N];
int T;
int en[N], ex[N], depth[N], up[N], heavy[N], sz[N], parent[N];

void godown(int root) {
    int d = 0;
    for (int v = root; v >= 0; v = heavy[v]) {
        depth[v] = d++;
        up[v] = root;
        hpath[root].push_back(v);
    }
    tree[root].init(d);
}

void dfs(int v, int p) {
    sz[v] = 1;
    en[v] = T++;
    heavy[v] = -1;
    parent[v] = p;
    for (int to : edges[v]) {
        if (to == p) continue;
        dfs(to, v);
        sz[v] += sz[to];
        if (heavy[v] < 0 || sz[heavy[v]] < sz[to]) heavy[v] = to;
    }
    for (int to : edges[v]) {
        if (to == p || to == heavy[v])
            continue;
        godown(to);
    }
    ex[v] = T;
    if (p < 0) godown(v);
}

int anc(int v, int u) {
    return en[v] <= en[u] && ex[u] <= ex[v];
}

int glca(int v, int u) {
    if (anc(v, u)) return v;
    for (int i = K - 1; i >= 0; i--)
        if (!anc(pp[i][v], u)) v = pp[i][v];
    return parent[v];
}

