    for (int i = 1; i < K; i++) {
        for (int v = 0; v < n; v++) {
            pp[i][v] = pp[i - 1][pp[i - 1][v]];
        }
    }
    for (int i = 0; i + 1 < n; i++) {
      scanf("%d%d", qv + i, qu + i);
      --qv[i];
      --qu[i];
      mxor(en[qv[i]], i);
      mxor(en[qu[i]], i);
      int lc = glca(qv[i], qu[i]);
      addpath(qv[i], lc, 1);
      addpath(qu[i], lc, 1);
    }
    for (int i = 1; i < n; i++) {
      // printf("%d\n", tree[up[i]].getmin(depth[i], depth[i] + 1).first);
      if (tree[up[i]].getmin(depth[i], depth[i] + 1).first == 1) {
        tree[up[i]].add(depth[i], depth[i] + 1, N);
        q[tail++] = i;
      }
    }
    while (head < tail) {
      int v = q[head++];
      int pid = gxor(en[v], ex[v]);
      assert(!waspath[pid]);
      waspath[pid] = true;
      mxor(en[qv[pid]], pid);
      mxor(en[qu[pid]], pid);
      int lc = glca(qv[pid], qu[pid]);
      addpath(qv[pid], lc, -1);
      addpath(qu[pid], lc, -1);
    }
    puts(head == n - 1 ? "YES" : "NO");
}

