const int UF_MAX = 100010;

class UF{
	int x[UF_MAX];
	int co;

public:

	UF(){
		fill(x,x+UF_MAX,-1);
		co = 0;
	}

	int boss(int a){
		int s = a;
		while(x[s] > -1) s = x[s];
		if(s != a) x[a] = s;
		return s;
	}

	void uni(int a , int b){
		int s = boss(a);
		int t = boss(b);
		if(s != t){
			++co;
			if(x[s] < x[t]){
				x[s] += x[t];
				x[t] = s;
			} else {
				x[t] += x[s];
				x[s] = t;
			}
		}
	}

	bool find(int a , int b){
		return boss(a) == boss(b);
	}

	int count(){
		return co;
	}

	int member(int a){
		return -x[boss(a)];
	}
} uf;

