	vector<int> a(N - 1), b(N - 1), c(N - 1), d(N - 1);
	rep(i, N - 1) scanf("%d%d", &a[i], &b[i]), a[i]--, b[i]--;
	rep(i, N - 1) scanf("%d%d", &c[i], &d[i]), c[i]--, d[i]--;
	vector<set<int> > st;
	rep(i, N - 1) {
		st[a[i]].insert(i);
		st[b[i]].insert(i);
		st[c[i]].insert(~i);
		st[d[i]].insert(~i);
	}
	map<i_i, int> mp;
	rep(i, N - 1) {
		mp[f(a[i], b[i])]++;
		mp[f(c[i], d[i])]++;
	}
	vector<bool> add(N - 1);
	queue<i_i> q;
	for (auto z: mp)
		if (z.second >= 2)
			q.push(z.first);
	union_find uf(N);
	while (q.size()) {
		i_i z = q.front(); q.pop();
		int u = z.first, v = z.second;
		u = uf.find(u), v = uf.find(v);
		if (uf.same(u, v)) continue;
		uf.unite(u, v);
		int w = uf.find(u);
		if (u == w) swap(u, v);
		for (int i: st[u]) {
			st[v].insert(i);
			if (i >= 0) {
				mp[f(a[i], b[i])]--;
				if (a[i] == u) a[i] = w;
				if (b[i] == u) a[i] = w;
				mp[f(a[i], b[i])]++;
				if (mp[f(a[i], b[i])] == 2) q.push(f(a[i], b[i]));
			}
			else {
				i = ~i;
				mp[f(c[i], d[i])]--;
				if (c[i] == u) c[i] = w;
				if (d[i] == u) d[i] = w;
				mp[f(c[i], d[i])]++;
				if (mp[f(c[i], d[i])] == 2) q.push(f(c[i], d[i]));
			}
		}
	}
	cout << (uf.size(0) == N ? "YES" : "NO") << endl;
}

