	for(it=xjt2.begin();it!=xjt2.end();it++)if((*it)!=y){del(x,*it,1);del(*it,x,1);}
	for(it=xjt.begin();it!=xjt.end();it++)if((*it)!=y){upd(make_pair(*it,y));upd(make_pair(y,*it));}
	for(it=xjt2.begin();it!=xjt2.end();it++)if((*it)!=y){upd(make_pair(*it,y));upd(make_pair(y,*it));}
