#include <bits/stdc++.h>
using namespace std;
const int N = 100005;
int n, a[N], b[N];
vector<int> g[N]; 
int tot, dfn[N], fa[N], dep[N], sz[N], son[N], top[N];
void pre(int u) {
  sz[u] = 1;
  for (auto v : g[u]) {
    if (v ^ fa[u]) {
      dep[v] = dep[u] + 1;
      fa[v] = u;
      pre(v);
      sz[u] += sz[v];
      if (sz[son[u]] < sz[v]) {
        son[u] = v;
      }
    }
  }
}
void dfs(int u) {
  if (son[u]) {
    top[son[u]] = top[u];
    dfn[son[u]] = ++tot;
    dfs(son[u]);
  }
  for (auto v : g[u]) {
    if ((v ^ fa[u]) && (v ^ son[u])) {
      top[v] = v;
      dfn[v] = ++tot;
      dfs(v);
    }
  }
}
struct data {
  int val, cnt;
  inline void operator += (const data &rhs) {
    val ^= rhs.val;
    cnt += rhs.cnt;
  }
  inline data operator + (const data &rhs) {
    if (cnt < rhs.cnt) {
      return *this;
    } else {
      return rhs;
    }
  }
}; 
struct node {
  data info, tag;
} t[N << 2];
inline void pushup(int p) {
  t[p].info = t[p << 1].info + t[p << 1 | 1].info;
}
inline void tag(int p, data add) {
  t[p].info += add;
  t[p].tag += add;
}
inline void pushdown(int p) {
  if (t[p].tag.cnt) {
    tag(p << 1, t[p].tag);
    tag(p << 1 | 1, t[p].tag);
    t[p].tag = (data) {0, 0};
  }
}
void modify(int p, int l, int r) {
  if (l == r) {
    t[p].info.cnt = 1e9;
    return;
  }
  pushdown(p);
  int mid = l + r >> 1;
  if (t[p << 1].info.cnt == 1) {
    modify(p << 1, l, mid);
  } else {
    modify(p << 1 | 1, mid + 1, r);
  }
  pushup(p);
}
void modify(int p, int l, int r, int L, int R, data add) {
  if (l >= L && r <= R) {
    tag(p, add);
    return;
  }
  pushdown(p);
  int mid = l + r >> 1;
  if (mid >= L) {
    modify(p << 1, l, mid, L, R, add);
  } 
  if (mid < R) {
    modify(p << 1 | 1, mid + 1, r, L, R, add);
  }
  pushup(p);
}
inline void modify(int u, int v, data add) {
  while (top[u] != top[v]) {
    if (dep[u] < dep[v]) {
      swap(u, v);
    }
    if (u ^ top[u]) {
      modify(1, 1, tot, dfn[top[u]] + 1, dfn[u], add);
    }
    u = fa[top[u]];
  }
  if (u ^ v) {
    if (dep[u] < dep[v]) {
      swap(u, v);
    }
    modify(1, 1, tot, dfn[v] + 1, dfn[u], add);
  }
}
int main() {
  scanf("%d", &n);
  for (int i = 1; i < n; ++i) {
    int u, v;
    scanf("%d%d", &u, &v);
    g[u].push_back(v);
    g[v].push_back(u);
  }
  pre(1);
  top[1] = 1;
  dfs(1);
  for (int i = 1; i < n; ++i) {
    scanf("%d%d", &a[i], &b[i]);
    modify(a[i], b[i], (data) {i, 1});
  }
  for (int i = 1; i < n; ++i) {
    int cnt = t[1].info.cnt;
    int idx = t[1].info.val;
    if (cnt ^ 1) {
      puts("NO");
      return 0;
    }
    modify(1, 1, tot);
    modify(a[idx], b[idx], (data) {idx, -1});
  }
  puts("YES");
  return 0;
}

