	if (x == num[x]) return x;
	else return num[x] = F(num[x]);
}
int main() {
	int n; scanf("%d", &n);
	for (int i = 1; i <= n; i++)
		num[i] = i;
	for (int i = 1; i <= 2 * n - 2; i++) {
