		scanf("%d%d", &x, &y);
		a[x].insert(y);
		a[y].insert(x);
	}
	static int qx[MAXM], qy[MAXM];
	int l = 1, r = 0, ans = 0;
	for (int i = 1; i <= n; i++) {
		multiset <int> :: iterator j, k;
		for (j = a[i].begin(); j != a[i].end(); k = j, j++)
			if (j != a[i].begin() && *j == *k) {
				r++;
				qx[r] = i;
				qy[r] = *j;
			}
	}
	while (l <= r) {
		int tx = F(qx[l]);
		int ty = F(qy[l]);
		l++;
		if (tx == ty) continue;
		ans++;
