const int INF = 1.01e9;

int n;
vector<int> e[MAXN];
int par[MAXN];
int heavy[MAXN];
int h[MAXN];
int root[MAXN];
int treePos[MAXN];

int dfs1(int v) {
	int sz = 1;
	int mx = 0;
	for (int to : e[v]) if (to != par[v]) {
		par[to] = v;
		h[to] = h[v] + 1;
		int subtr = dfs1(to);
		if (subtr > mx) heavy[v] = to, mx = subtr;
		sz += subtr;
	}
	return sz;
}

pair<int, int> tmn[MAXN * 2];
int pmn[MAXN * 2];
int txr[MAXN * 2];
int pxr[MAXN * 2];

void build(int v, int tl, int tr) {
	pmn[v] = txr[v] = pxr[v] = 0;
	if (tl == tr) {
		tmn[v] = make_pair(tl == 0 ? INF : 0, tl);
		return;
	}
	int tm = (tl + tr) >> 1;
	build(v * 2, tl, tm);
	build(v * 2 + 1, tm + 1, tr);
	tmn[v] = min(tmn[v * 2], tmn[v * 2 + 1]);
}

void push(int v, int tl, int tr) {
	if (pmn[v] != 0) {
		tmn[v].first += pmn[v];
		if (tl != tr) {
			pmn[v * 2] += pmn[v];
			pmn[v * 2 + 1] += pmn[v];
		}
		pmn[v] = 0;
	}
	if (pxr[v] != 0) {
		txr[v] ^= pxr[v];
		if (tl != tr) {
			pxr[v * 2] ^= pxr[v];
			pxr[v * 2 + 1] ^= pxr[v];
		}
		pxr[v] = 0;
	}
}

void updAdd(int v, int tl, int tr, int l, int r, int x) {
	push(v, tl, tr);
	if (l > r) return;
	if (l == tl && r == tr) {
		pmn[v] += x;
		push(v, tl, tr);
		return;
	}
	int tm = (tl + tr) >> 1;
	updAdd(v * 2, tl, tm, l, min(r, tm), x);
	updAdd(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, x);
	tmn[v] = min(tmn[v * 2], tmn[v * 2 + 1]);
}

void updXor(int v, int tl, int tr, int l, int r, int x) {
	push(v, tl, tr);
	if (l > r) return;
	if (l == tl && r == tr) {
		pxr[v] ^= x;
		push(v, tl, tr);
		return;
	}
	int tm = (tl + tr) >> 1;
	updXor(v * 2, tl, tm, l, min(r, tm), x);
	updXor(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, x);
	txr[v] = txr[v * 2] ^ txr[v * 2 + 1];
}

