void work() {
	int u, v;
	pair<int, int> o;
	while(!que.empty()) {
		o = que.front(), que.pop();
		u = UFS :: find(o.first), v = UFS :: find(o.second);
		if(u != v) {
			--totBlock;
			if(size[u] > size[v]) swap(u, v);
			// merge
			UFS :: fa[u] = v;
			for(set<int> :: iterator it = g[u].begin(); it != g[u].end(); ++it) {
				int to = UFS :: find(*it);
				if(to == v) continue;
