					g[to].erase(u), --size[to];
					//g[v].erase(to), --size[v];
					que.push(make_pair(u, to));
				} else {
					g[to].erase(u), g[to].insert(v);
					g[v].insert(to), ++size[v];
				}
			}
		}
	}
}

