void insertedge(int u,int v)
{
	if(u==v) return;
	if(u>v) swap(u,v);
	ae[u].insert(v); ae[v].insert(u);
	g[mkpr(u,v)]++;
	if(g[mkpr(u,v)]==2) {que.push(mkpr(u,v));}
}

void deleteedge(int u,int v)
{
	ae[v].erase(ae[v].find(u));
	if(u>v) swap(u,v);
	g[mkpr(u,v)]--;
}

