        fo(i, 1, N+1) par[i] = i;
        fo(x, 0, 2) fo(i, 1, N) {
                int a, b; scanf("%d %d", &a, &b);
                if (a > b) swap(a, b);

                l[x][i] = MP(a, b);
                add(x, i);

                c[a].v[x].PB(i);
                c[b].v[x].PB(i);
        }

        int num=0;
        while (q.size()) {
                int xa, xb; tie(xa,xb) = q.front(); q.pop();
                int a = g(l[0][xa].first), b = g(l[0][xa].second);

                num++;

                //printf("onq %d %d (edge id)\n", xa, xb);

                assert(a == g(l[1][xb].first));
                assert(b == g(l[1][xb].second));
                //printf("corresponds to merge %d %d\n", a, b);

                if (a != b) merge(a, b);

