namespace Main {

	struct Solution: Data {
		set<int> ra[N], rb[N], rc[N], rd[N];

		set<pii> e, f;
		set<pii> q;

		void adde (int i) {
			ra[a[i]].insert(i);
			rb[b[i]].insert(i);
			int x = a[i], y = b[i];
			if (x > y) {
				swap(x, y);
			}
			pii key = mp(x, y);
			if (f.count(key)) {
				q.insert(key);
			}
			e.insert(key);
		}

		void addf (int i) {
			rc[c[i]].insert(i);
			rd[d[i]].insert(i);
			int x = c[i], y = d[i];
			if (x > y) {
				swap(x, y);
			}
			pii key = mp(x, y);
			if (e.count(key)) {
				q.insert(key);
			}
			f.insert(key);
		}

		void dele (int i) {
			ra[a[i]].erase(i);
			rb[b[i]].erase(i);
			int x = a[i], y = b[i];
			if (x > y) {
				swap(x, y);
			}
			pii key = mp(x, y);
			if (f.count(key)) {
				q.erase(key);
			}
			e.erase(key);
		}

		void delf (int i) {
			rc[c[i]].erase(i);
			rd[d[i]].erase(i);
			int x = c[i], y = d[i];
			if (x > y) {
				swap(x, y);
			}
			pii key = mp(x, y);
			if (e.count(key)) {
				q.erase(key);
			}
			f.erase(key);
		}

		int cnt (int i) {
			return sz(ra[i]) + sz(rb[i]) + sz(rc[i]) + sz(rd[i]);
		}

		void solve () {
			forn (i, n - 1) {
				adde(i);
				addf(i);
			}
			forn (i, n - 1) {
				if (sz(q) == 0) {
					ans = 0;
					return;
				}
				int x = q.begin()->fs;
				int y = q.begin()->sc;
				q.erase(q.begin());
				if (cnt(x) > cnt(y)) {
					swap(x, y);
				}
				set<int> ea = ra[x];
				set<int> eb = rb[x];
				set<int> fc = rc[x];
				set<int> fd = rd[x];
				for (int e : ea) {
					dele(e);
					assert(a[e] == x);
					a[e] = y;
					if (a[e] != b[e]) {
						adde(e);
					}
				}
				for (int e : eb) {
					dele(e);
					assert(b[e] == x);
					b[e] = y;
					if (a[e] != b[e]) {
						adde(e);
					}
				}
				for (int f : fc) {
					delf(f);
					assert(c[f] == x);
					c[f] = y;
					if (c[f] != d[f]) {
						addf(f);
					}
				}
				for (int f : fd) {
					delf(f);
					assert(d[f] == x);
					d[f] = y;
					if (c[f] != d[f]) {
						addf(f);
					}
				}
			}
			ans = 1;
		}

		void clear () {
			*this = Solution();
		}
	};
