	void init(int n){
		siz = 1;
		while(siz < n)siz <<= 1;
		rep(i,siz*2-1){
			s.push_back(nullsi);
			t.push_back(P(0,0));
			u.push_back(0);
		}
		rep(i,siz){
			t[i+siz-1] = P(0,i);
		}
		rrep(i,siz-1){
			t[i] = min( t[2*i+1] , t[2*i+2] );
		}
	}
	void add(int a,int b,int x,int k,int l,int r){
		//fprintf(stderr,"seg:add(%d,%d,%d,%d,%d,%d)\n",a,b,x,k,l,r);
		if(b <= l || r <= a)return;
		if(a <= l && r <= b){
			//if(x != -1){
