{
	if(fa[x] == x) return x;
	return fa[x] = findr(fa[x]);
}
int main()
{
	ios::sync_with_stdio(false);
	fin >> n;
	for(int i = 1; i <= n; i++) fa[i] = i;
	for(int i = 1; i < n; i++) {
		int u,v; fin >> u >> v;
		add(u,v); add(v,u); M[Hash(u,v)]++;
		sz[u]++; sz[v]++;
	}
	for(int i = 1; i < n; i++) {
		int u,v; fin >> u >> v;
		add(u,v); add(v,u);
