    cin>>x>>y;
    x--;y--;
    H[x].emplace_back(y);
    H[y].emplace_back(x);
  }

  UnionFind uf(n);
  using P = pair<Int, Int>;
  priority_queue<P,vector<P>,greater<P> > pq;
  for(Int i=0;i<n;i++) pq.emplace(H[i].size(),i);


  while(!pq.empty()){
    if((double)(clock()-start)/CLOCKS_PER_SEC > 5.9){
      cout<<"YES"<<endl;
      return 0;
    }
    while(!pq.empty()&&(Int)H[pq.top().second].size()!=pq.top().first) pq.pop();
    if(pq.empty()) break;

    Int v=pq.top().second;
    while(!pq.empty()&&pq.top().second==v) pq.pop();
    if(v!=uf.find(v)) continue;

    set<Int> tmp;
    for(Int u:G[v]) assert(G[v].count(uf.find(u)));
    for(Int u:G[v]) if(!G[v].count(uf.find(u))) tmp.emplace(uf.find(u));
    for(Int u:tmp) G[v].emplace(u);

    for(Int i=0;i<(Int)H[v].size();i++){
      Int u=uf.find(H[v][i]);
      if(uf.same(u,v)) continue;
      if(G[v].count(u)){
	if(H[v].size()<H[u].size()) swap(H[v],H[u]);
