	for(auto x:H[u]) H[v].emplace_back(x);
	for(auto x:G[u]) G[v].emplace(x);

	H[u].clear();G[u].clear();

	uf.unite(u,v);
	Int r=uf.find(v);
	if(r!=v){
	  swap(H[r],H[v]);
	  swap(G[r],G[v]);
	}
        pq.emplace(H[r].size(),r);
	break;
      }
    }
  }

