#include <bits/stdc++.h>
using namespace std;
#define sz(x) ((int) (x).size())
#define forn(i,n) for (int i = 0; i < int(n); ++i)
#define all(x) (x).begin(), (x).end()
typedef long long ll;
typedef long long i64;
typedef long double ld;
const int inf = int(1e9) + int(1e5);
const ll infl = ll(2e18) + ll(1e10);

const int maxn = 100100;
const int maxd = 17;

const int buben = 100;

vector<int> g[maxn];
int in[maxn];
int out[maxn];
int timer;

int qu[maxn];
int qv[maxn];
int qw[maxn];
int p[maxn][maxd];
int h[maxn];

void pre(int u, int prev, int ch = 0) {
    in[u] = timer++;
    h[u] = ch;
    p[u][0] = prev;
    for (int v: g[u]) {
        if (v == prev)
            continue;
        pre(v, u, ch + 1);
    }
    out[u] = timer;
}

bool isPrev(int u, int v) {
    return in[u] <= in[v] && out[v] <= out[u];
}

int lca(int u, int v) {
    for (int d = maxd - 1; d >= 0; --d)
        if (!isPrev(p[u][d], v))
            u = p[u][d];
    if (!isPrev(u, v))
        u = p[u][0];
    return u;
}

int fw[maxn];

void put(int pos, int delta) {
    for (int i = pos; i < maxn; i |= i + 1)
        fw[i] += delta;
}

int get(int r) {
    int res = 0;
    for (int i = r; i >= 0; i = (i & (i + 1)) - 1)
        res += fw[i];
    return res;
}

int rem(int id) {
    int u = qu[id];
    int v = qv[id];
    int w = qw[id];
    int res = get(in[v]);
    res += get(in[u]);
    res -= 2 * get(in[w]);
    return res;
}

struct DSU {
    vector<int> col;

    DSU() {
    }

    DSU(int n): col(n) {
        iota(all(col), 0);
    }

    int get(int u) {
        if (u == col[u])
            return u;
        return u = get(col[u]);
    }

    void join(int u, int v) {
        u = get(u);
        v = get(v);
        col[u] = v;
    }
} dsu;

vector<int> by[maxn];
vector<int> upd[5 * maxn];
vector<int> q;

int singleEdge(int id) {
    int len = rem(id);
    assert(len == 1);
    int u = qu[id];
    int v = qv[id];
    int w = qw[id];
    while (h[u] > h[w]) {
        int e = dsu.get(u);
        if (h[e] <= h[w])
            break;
        return e;
    }
    while (h[v] > h[w]) {
        int e = dsu.get(v);
        if (h[e] <= h[w])
            break;
        return e;
    }
    assert(false);
}

void extractEdges(int id) {
    int len = rem(id);
    int u = qu[id];
    int v = qv[id];
    int w = qw[id];
    while (h[u] > h[w]) {
        int e = dsu.get(u);
        if (h[e] <= h[w])
            break;
        by[e].push_back(id);
        //cerr << "Edge " << e << '\n';
        u = p[e][0];
        --len;
    }
    while (h[v] > h[w]) {
        int e = dsu.get(v);
        if (h[e] <= h[w])
            break;
        by[e].push_back(id);
        //cerr << "Edge " << e << '\n';
        v = p[e][0];
        --len;
    }
    assert(len == 0);
}

bool used[maxn];

int main() {
    #ifdef LOCAL
    assert(freopen("e.in", "r", stdin));
    #else
    #endif
    int n;
    cin >> n;

    dsu = DSU(n);

    forn (i, n - 1) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    const int root = 0;
    pre(root, root);
    forn (d, maxd - 1)
        forn (u, n)
            p[u][d + 1] = p[p[u][d]][d];
    forn (i, n) {
        if (i == root)
            continue;
        put(in[i], 1);
        put(out[i], -1);
    }

    forn (i, n - 1) {
        //cerr << "Que " << i << '\n';
        int u, v;
        cin >> u >> v;
        --u, --v;
        qu[i] = u;
        qv[i] = v;
        qw[i] = lca(u, v);
        int len = rem(i);
        if (len == 1) {
            q.push_back(i);
        }
        if (len <= buben) {
            extractEdges(i);
        } else {
            upd[i + len - 2].push_back(i);
        }
    }
    forn (ii, sz(q)) {
        int id = q[ii];
        used[id] = true;
        //cerr << "que " << id << '\n';
        int len = rem(id);
        if (len != 1) {
            cout << "NO\n";
            return 0;
        }
        int e = singleEdge(id);
        //cerr << "edge " << e << '\n';
        put(in[e], -1);
        put(out[e], 1);
        if (p[e][0] != root)
            dsu.join(e, p[e][0]);
        for (int id: by[e]) {
            if (used[id])
                continue;
            int r = rem(id);
            if (r == 0) {
                cout << "NO\n";
                return 0;
            }
            if (r == 1) {
                //cerr << "trig " << id << '\n';
                q.push_back(id);
            }
        }
        for (int id: upd[ii]) {
            int len = rem(id);
            if (len <= buben) {
                extractEdges(id);
            } else {
                upd[ii + len - 2].push_back(id);
            }
        }
    }
    if (sz(q) != n - 1) {
        cout << "NO\n";
        return 0;
    }
    cout << "YES\n";
}

