class unionfind {
	vector<int> par;
	vector<int> sz;
public:
	vector<vector<int>> rev;
	unionfind(int n) {
		par = vector<int>(n);
		rev = vector<vector<int>>(n, vector<int>());
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rev[i].push_back(i);
		}
		sz = vector<int>(n, 1);
	}
	int find(int x) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x]);
	}
	int si(int x) { return sz[find(x)]; }
	bool same(int x, int y) { return find(x) == find(y); }
	int unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return -1;
		if (sz[x] < sz[y]) {
			par[x] = y;
			sz[y] += sz[x];
			while (!rev[x].empty()) {
				rev[y].push_back(rev[x].back());
				rev[x].pop_back();
			}
			return x;
		}
		else {
			par[y] = x;
			sz[x] += sz[y];
			while (!rev[y].empty()) {
				rev[x].push_back(rev[y].back());
				rev[y].pop_back();
			}
			return y;
		}
	}
};

