	int v;
	vet *next;
} vets[maxn<<1];
vet *root[maxn];
int tot;
inline void add(int u, int v)
{
	tot++;
	vets[tot].v = v; vets[tot].next = root[u];
	root[u] = vets+tot;
}
unordered_map<ull, int> M;
inline ull Hash(int u, int v)
{
	if(u > v) swap(u,v);
	return u*n+v;
}
struct node {
	int u, v;
};
node stk[maxn]; int top;
int fa[maxn],sz[maxn];
int findr(int x)
{
	if(fa[x] == x) return x;
	return fa[x] = findr(fa[x]);
}
int main()
{
	ios::sync_with_stdio(false);
	n = getint();
	for(int i = 1; i <= n; i++) fa[i] = i;
	for(int i = 1; i < n; i++) {
		int u,v; u = getint(); v = getint();
		add(u,v); add(v,u); M[Hash(u,v)]++;
		sz[u]++; sz[v]++;
	}
	for(int i = 1; i < n; i++) {
		int u,v; u = getint(); v = getint();
		add(u,v); add(v,u);
		if(++M[Hash(u,v)] > 1) {
			stk[++top] = (node){u, v};
		}
		sz[u]++; sz[v]++;
	}
	bool flag = true;
	for(int i = 1; i < n; i++) {
		int u,v;
		while(true) {
			if(top == 0) {
				flag = false; break;
			}
			u = stk[top].u; v = stk[top].v; top--;
//			printf("u:%d v:%d top-1:%d\n",u,v,top);
			if(findr(u) == u && findr(v) == v) {
				break;
			}
		}
		if(sz[u] > sz[v]) swap(u, v);
		sz[v] += sz[u]; fa[u] = v;
		for(vet *i = root[u]; i; i = i->next) {
			M[Hash(u, findr(i->v))]--;
			if(fa[i->v] != v) {
				if(++M[Hash(v, fa[i->v])] > 1) {
					stk[++top] = (node){v, fa[i->v]};
				}
			}
		}
	}
	if(flag) {
		fout << "YES";
	} else {
		fout << "NO";
	}
	return 0;
}

