template<class E, class Handler>		//for lazy segtree
struct HLdecomp{
	using val_t = typename Handler::val_t;
	using opr_t = typename Handler::opr_t;
	using segtree = segtree_lazy<Handler>;

	static const bool OnEdge = 1;

	vector<vector<E>> G;
	using P = pair<int,int>;
	vector<P> id;				//id[v] = P(chain_id,pos_on_chain)	posはtop to bottom
	vector<int> sz;				//sz[v] = subtree_size
	vector<int> dep;			//dep[v] = depth
	vector<int> par;			//par[v] = parent
	vector<int> top;			//id[v].fs の一番上

	int C;	//num of chains
	vector<vector<int>> chains;	//chains[c][i] = v <=> id[v] = P(c,i)
	vector<segtree> segs;


	HLdecomp(const vector<vector<E>>& G, int r = 0):G(G){
		int N = G.size();
		C = 1;
		chains.pb({0});
		id.assign(N,P(0,0));
		sz.assign(N,0);
		dep.assign(N,0);
		par.assign(N,0);
		top.assign(N,0);

		dfs_base(r);
		dfs_decomp(r);


		rep(c,C) segs.pb(segtree(chains[c].size()));
	}
	void dfs_base(int v,int p=-1){	//calc sz,dep
		sz[v] = 1;
		par[v] = p;
		if(p==-1) dep[v] = 0;
		else dep[v] = dep[p] + 1;
		for(const auto& e: G[v]){
			int u = e.to;
			if(u==p) continue;
			dfs_base(u,v);
			sz[v] += sz[u];
		}
	}
	void dfs_decomp(int v,int p=-1){
		int heavy = -1;
		for(const auto& e: G[v]){
			int u = e.to;
			if(u == p) continue;
			if(heavy == -1 || sz[heavy]<sz[u]) heavy = u;
		}
		for(const auto& e: G[v]){
			int u = e.to;
			if(u == p) continue;
			if(u == heavy){
				id[u] = P(id[v].fs,id[v].sc+1);
				top[u] = top[v];
			}else{
				id[u] = P(C,0);
				top[u] = u;
				C++;
				chains.pb({});
			}
			chains[id[u].fs].pb(u);
			dfs_decomp(u,v);
		}
	}
	int lca(int a,int b){
		while(id[a].fs != id[b].fs){
			if(id[a].fs < id[b].fs) b = par[top[b]];
			else a = par[top[a]];
		}
		return dep[a]<dep[b] ? a : b;
	}
	int up(int v,int d){	//vから上にd上がった点
		if(dep[v]<d) return -1;
		while(true){
			int d1 = dep[v] - dep[top[v]];
			if(d1<=d){
				d -= d1;
				v = top[v];
			}else{
				int c = id[v].fs;
				return chains[c][d1-d];
			}
			if(d==0) return v;
			v = par[v];
			d--;
		}
		assert(0);
		return -1;
	}
	val_t query(int u,int v){	//[u,w) + [w,v]			edge ver なら [u,w) + (w,v]
		int w = lca(u,v);
		val_t up,down;

		{
			for(;id[u].fs!=id[w].fs; u = par[top[u]]){
				//chains[c][l,r]
				int c = id[u].fs;
				int l = id[top[u]].sc;
				int r = id[u].sc;
				val_t x = segs[c].query(l,r+1);
				up = x + up;
			}
			int c = id[u].fs;
			int l = id[w].sc+1;
			int r = id[u].sc;
			val_t x = segs[c].query(l,r+1);
			up = x + up;
		}
		{
			u = v;
			for(;id[u].fs!=id[w].fs; u = par[top[u]]){
				int c = id[u].fs;
				int l = id[top[u]].sc;
				int r = id[u].sc;
				val_t x = segs[c].query(l,r+1);
				down = x + down;
			}
			int c = id[u].fs;
			int l = id[w].sc + OnEdge;
			int r = id[u].sc;
			val_t x = segs[c].query(l,r+1);
			down = x + down;
		}

		// ! reverse up !
		return up + down;
	}
	void update(int u,int v,const opr_t &x){	//[u,w) + [w,v]
		int w = lca(u,v);

		{
			for(;id[u].fs!=id[w].fs; u = par[top[u]]){
				//chains[c][l,r]
				int c = id[u].fs;
				int l = id[top[u]].sc;
				int r = id[u].sc;
				auto v = segs[c].query(0,chains[c].size());
				st.erase(P(v.x,v.id));
				segs[c].update(l,r+1,x);
				v = segs[c].query(0,chains[c].size());
				st.insert(P(v.x,v.id));
			}
			int c = id[u].fs;
			int l = id[w].sc+1;
			int r = id[u].sc;
			auto v = segs[c].query(0,chains[c].size());
			st.erase(P(v.x,v.id));
			segs[c].update(l,r+1,x);
			v = segs[c].query(0,chains[c].size());
			st.insert(P(v.x,v.id));
		}
		{
			u = v;
			for(;id[u].fs!=id[w].fs; u = par[top[u]]){
				int c = id[u].fs;
				int l = id[top[u]].sc;
				int r = id[u].sc;
				auto v = segs[c].query(0,chains[c].size());
				st.erase(P(v.x,v.id));
				segs[c].update(l,r+1,x);
				v = segs[c].query(0,chains[c].size());
				st.insert(P(v.x,v.id));
			}
			int c = id[u].fs;
			int l = id[w].sc + OnEdge;
			int r = id[u].sc;
			auto v = segs[c].query(0,chains[c].size());
			st.erase(P(v.x,v.id));
			segs[c].update(l,r+1,x);
			v = segs[c].query(0,chains[c].size());
			st.insert(P(v.x,v.id));
		}
	}
};

using ll = long long;
struct handler{
	struct val_t{
		ll x,y;
		int id;
		val_t(){*this = e();}
		val_t(ll x,ll y,int id):x(x),y(y),id(id){}

		const static val_t e(){
			return val_t(1e9,0,-1);
		}
		val_t operator+(const val_t &r) const {
			if(x<=r.x) return *this;
			else return r;
		}
		friend ostream& operator<<(ostream& o,const val_t& d){return o<<"("<<d.x<<" "<<d.y<<" "<<d.id<<")";}
	};

	struct opr_t{
		ll x,y;
		int id;
		opr_t(){*this = e();}
		opr_t(ll x,ll y):x(x),y(y),id(-1){}
		opr_t(ll x,ll y,int id):x(x),y(y),id(id){}

		const static opr_t e(){
			return opr_t(0,0,-1);
		}
	};

	static void setg2fg(const opr_t &f, opr_t &g){	//g -> fg		f after g
		g.x += f.x;
		g.y += f.y;
		if(f.id!=-1) g.id = f.id;
	}
	static val_t act(const opr_t &f, const val_t &v,int k,int l,int r){	//assign f.x -> sum = 
		return val_t(v.x+f.x,v.y+f.y,(f.id==-1?v.id:f.id));
	}
};

