void dfs(int x){
	size[x]=1,deep[x]=deep[fa[x]]+1;
	for(int i=head[x];i;i=nex[i])
		if(!size[v[i]]){
			fa[v[i]]=x,dfs(v[i]);
			size[x]+=size[v[i]];
			if(size[v[i]]>size[son[x]])	son[x]=v[i];
		}
}
void dfs(int x,int t){
	top[x]=t,id[x]=++now;
	if(!son[x])	return ;
	dfs(son[x],t);
	for(int i=head[x];i;i=nex[i])
		if(!id[v[i]])	dfs(v[i],v[i]);
}
queue<int>que;
void pushdown(int x){
	a[x<<1|1]+=lazy[x],lazy[x<<1|1]+=lazy[x];
	a[x<<1]+=lazy[x],lazy[x<<1]+=lazy[x];
	lazy[x]=0;
}
int cnt[N<<2];
void check(int l,int r,int rt){
	if(a[rt]>1)	return ;
	for(int i=head[rt];i;i=nex[i])
		if(!vis[v[i]])	que.push(v[i]),vis[v[i]]=1;
	head[rt]=0;
	if(l==r){
		a[rt]=inf;
		return ;
	}
	if(lazy[rt])	pushdown(rt);
	int mid=(l+r)>>1;
	check(l,mid,rt<<1);
	check(++mid,r,rt<<1|1);
	a[rt]=min(a[rt<<1],a[rt<<1|1]);
}
void added(int l,int r,int x,int y,int z,int rt){
	if(x<=l&&y>=r){
		++a[rt],++lazy[rt];
		addedges(rt,z);
		return ;
	}
	int mid=(l+r)>>1;
	if(lazy[rt])	pushdown(rt);
	if(x<=mid)	added(l,mid,x,y,z,rt<<1);
	if(y>mid)	added(++mid,r,x,y,z,rt<<1|1);
	a[rt]=min(a[rt<<1],a[rt<<1|1]);
}
void get(int l,int r,int x,int y,int rt){
	if(x<=l&&y>=r){
		--a[rt],--lazy[rt];
		return ;
	}
	int mid=(l+r)>>1;
	if(lazy[rt])	pushdown(rt);
	if(x<=mid)	get(l,mid,x,y,rt<<1);
	if(y>mid)	get(++mid,r,x,y,rt<<1|1);
	a[rt]=min(a[rt<<1],a[rt<<1|1]);
}
void change(int x,int y){
	while(top[x]!=top[y]){
		if(deep[top[x]]<deep[top[y]])	swap(x,y);
		get(1,n,id[top[x]],id[x],1);
		x=fa[top[x]];
	}
	if(x==y)	return ;
	if(deep[x]>deep[y])	swap(x,y);
	get(1,n,id[x]+1,id[y],1);
}
void lca(int x,int y,int k){
	while(top[x]!=top[y]){
		if(deep[top[x]]<deep[top[y]])	swap(x,y);
		added(1,n,id[top[x]],id[x],k,1);
		x=fa[top[x]];
	}
	if(x==y)	return ;
	if(deep[x]>deep[y])	swap(x,y);
	added(1,n,id[x]+1,id[y],k,1);
}
void build(int l,int r,int rt){
	a[rt]=inf;
	if(l==r) return ;
	build(l,(l+r)>>1,rt<<1);
}
