  while(!q.empty()){
    Int v=q.front();q.pop();
    if(uf.find(v)!=v) continue;
    queue<Int> mg;
    for(auto z:H[v]){
      if(uf.same(z,v)) continue;
      int u=uf.find(z);
      if(G[v].count(z)||G[v].count(u)) mg.emplace(u);
    }
    while(!mg.empty()){
      Int u=mg.front();mg.pop();
      u=uf.find(u);
      if(uf.same(u,v)) continue;

      if(H[v].size()<H[u].size()) swap(H[v],H[u]);
      if(G[v].size()<G[u].size()) swap(G[v],G[u]);
      for(auto x:G[u]){
	int w=uf.find(x);
	if(H[u].count(x)||H[v].count(x)) mg.emplace(x);
	if(H[u].count(w)||H[v].count(w)) mg.emplace(w);
