    // solve
    constexpr int root = 0;
    lowest_common_ancestor_t lca(root, g);
    heavy_light_decomposition_t hl(root, g);
    heavy_light_decomposition_node_adapter<lazy_propagation_segment_tree<min_count_t, plus_endomorphism_t> > segtree(hl, lca, (min_count_t::type) { 0, 1 });
    repeat (i, n-1) {
        segtree.path_apply(c[i], d[i], 1);
    }
    vector<int> length(n-1);
    repeat (i, n-1) length[i] = path_length(lca, c[i], d[i]);
    vector<int> length_order(n-1);
    whole(iota, length_order, 0);
    whole(sort, length_order, [&](int i, int j) { return length[i] > length[j]; }); // reversed
    bool result = true;
    for (int i : length_order) {
        auto path = segtree.path_concat(c[i], d[i]);
        if (not (path.min == 1 and (path.count == 1 or (path.count == 2 and length[i] == 1)))) {
            result = false;
            break;
        }
        segtree.path_apply(c[i], d[i], -1);
    }
    printf("%s\n", result ? "YES" : "NO");
    return 0;
}

