using namespace std;
const int N = 100005;
int n, a[N], b[N];
vector<int> g[N]; 
int tot = -1, dfn[N], fa[N], dep[N], sz[N], son[N], top[N];
void pre(int u) {
  sz[u] = 1;
  for (auto v : g[u]) {
    if (v ^ fa[u]) {
      dep[v] = dep[u] + 1;
      fa[v] = u;
      pre(v);
      sz[u] += sz[v];
      if (sz[son[u]] < sz[v]) {
        son[u] = v;
      }
    }
  }
}
void dfs(int u) {
  dfn[u] = ++tot;
  if (son[u]) {
    top[son[u]] = top[u];
    dfs(son[u]);
  }
  for (auto v : g[u]) {
    if ((v ^ fa[u]) && (v ^ son[u])) {
      top[v] = v;
      dfs(v);
    }
  }
}
struct Data {
  int val, cnt, pos;
  inline void operator += (const Data &rhs) {
    val ^= rhs.val;
    cnt += rhs.cnt;
  }
  inline Data operator + (const Data &rhs) {
    if (cnt < rhs.cnt) {
      return *this;
    } else {
      return rhs;
    }
  }
}; 
struct node {
  Data info, tag;
} t[N << 2];
void build(int p, int l, int r) {
  t[p].info.pos = l;
  if (l ^ r) {
    int mid = l + r >> 1;
    build(p << 1, l, mid);
    build(p << 1 | 1, mid + 1, r);
  }
}
inline void pushup(int p) {
  t[p].info = t[p << 1].info + t[p << 1 | 1].info;
}
inline void tag(int p, Data add) {
  t[p].info += add;
  t[p].tag += add;
}
inline void pushdown(int p) {
  if (t[p].tag.cnt || t[p].tag.val) {
    tag(p << 1, t[p].tag);
    tag(p << 1 | 1, t[p].tag);
    t[p].tag = (Data) {0, 0};
  }
}
void modify(int p, int l, int r, int L, int R, Data add) {
  if (l >= L && r <= R) {
    tag(p, add);
    return;
  }
  pushdown(p);
  int mid = l + r >> 1;
  if (mid >= L) {
    modify(p << 1, l, mid, L, R, add);
  } 
  if (mid < R) {
    modify(p << 1 | 1, mid + 1, r, L, R, add);
  }
  pushup(p);
}
inline void modify(int u, int v, Data add) {
  while (top[u] != top[v]) {
    if (dep[top[u]] < dep[top[v]]) {
      swap(u, v);
    }
    modify(1, 1, tot, dfn[top[u]], dfn[u], add);
    u = fa[top[u]];
  }
  if (u ^ v) {
    if (dep[u] > dep[v]) {
      swap(u, v);
    }
    modify(1, 1, tot, dfn[u] + 1, dfn[v], add);
  }
}
int main() {
  scanf("%d", &n);
  for (int i = 1; i < n; ++i) {
    int u, v;
    scanf("%d%d", &u, &v);
    g[u].push_back(v);
    g[v].push_back(u);
  }
  pre(1);
  top[1] = 1;
  dfs(1);
  build(1, 1, tot);
  for (int i = 1; i < n; ++i) {
    scanf("%d%d", &a[i], &b[i]);
    modify(a[i], b[i], (Data) {i, 1});
  }
  for (int i = 1; i < n; ++i) {
    int cnt = t[1].info.cnt;
    int idx = t[1].info.val;
    int pos = t[1].info.pos;
    if (cnt ^ 1) {
      puts("NO");
      return 0;
    }
    modify(1, 1, tot, pos, pos, (Data) {0, 1e9});
    modify(a[idx], b[idx], (Data) {idx, -1});
  }
  puts("YES");
  return 0;
}

