const int N = 1e5 + 100;

int d1[N], d2[N], cut1[N], cut2[N];
vector<int> G[N], H[N];

int main(){
	ios::sync_with_stdio(0);
	cout.tie(0); cin.tie(0);

	int n; cin >> n;
	for (int i = 0; i < n - 1; i++){
		int u, v; cin >> u >> v; u--; v--;
		G[u].push_back(v); G[v].push_back(u);
		d1[u]++; d1[v]++;
	}

	for (int i = 0; i < n - 1; i++){
		int u, v; cin >> u >> v; u--; v--;
		H[u].push_back(v); H[v].push_back(u);
		d2[u]++; d2[v]++;
	}

	set<int> lG, lH, lB;
	for (int i = 0; i < n; i++) if (d1[i] == 1) lG.insert(i), cut1[i] = true;
	for (int i = 0; i < n; i++) if (d2[i] == 1){
		lH.insert(i);
		cut2[i] = true;
		if (lG.count(i)); lB.insert(i);
	}

	int x = 0;
	while (lB.size()){
		int u = *lB.begin();
		lB.erase(u); lG.erase(u); lH.erase(u);

		for (int v : G[u]) if (!cut1[v] && --d1[v] == 1){
			lG.insert(v);
			cut1[v] = true;
			if (lH.count(v)) lB.insert(v);
		}

		for (int v : H[u]) if (!cut2[v] && --d2[v] == 1){
			lH.insert(v);
			cut2[v] = true;
			if (lG.count(v)) lB.insert(u);
		}

		x++;
	}

	if (x == n) cout << "YES\n";
	else cout << "NO\n";

}

