int main()
{
    int n,m=0;scanf("%d",&n);
    for (int i=1;i<n;i++)
    {
        int x,y;scanf("%d%d",&x,&y);
        if (x>y) swap(x,y);a[make_pair(x,y)]++;
        q.push(make_pair(x,y));deg[x]++;deg[y]++;
        b[++m]=y;if (!head[x]) head[x]=m; else next0[tail[x]]=m;tail[x]=m;
        b[++m]=x;if (!head[y]) head[y]=m; else next0[tail[y]]=m;tail[y]=m;
    }
    for (int i=1;i<n;i++)
    {
        int x,y;scanf("%d%d",&x,&y);
        if (x>y) swap(x,y);a[make_pair(x,y)]++;
        q.push(make_pair(x,y));deg[x]++;deg[y]++;
        b[++m]=y;if (!head[x]) head[x]=m; else next0[tail[x]]=m;tail[x]=m;
        b[++m]=x;if (!head[y]) head[y]=m; else next0[tail[y]]=m;tail[y]=m;
    }
    for (int i=1;i<=n;i++) fa[i]=i;
    for (int i=1;i<n;i++)
    {
        while (!q.empty())
        {
            pii t=q.front();
            int x=t.first,y=t.second;
            if (x>y) swap(x,y);
            if (a[make_pair(x,y)]!=2||find(x)==find(y)) {q.pop();continue;}
            if (deg[x]>deg[y]) swap(x,y);
            int p=head[x];
            while (p)
            {
                int u=find(b[p]),v=x;
                if (u>v) swap(u,v);
                a[make_pair(u,v)]--;
                u=find(b[p]);v=y;
                if (u>v) swap(u,v);
                a[make_pair(u,v)]++;
                q.push(make_pair(u,v));
                p=next0[p];
            }
            deg[y]+=deg[x];fa[x]=y;
            next0[tail[y]]=head[x];tail[y]=tail[x];
            break;
        }
        if (q.empty()) {puts("NO");return 0;}
    }
    puts("YES");
    return 0;
}

