    		if(e[x].count(*it)){
    			e[*it].erase(x);
    			e[*it].erase(y);
    			e[x].erase(*it);
    			calc(x,*it);
    		}else{
    			e[x].insert(*it);
    			e[*it].erase(y);
    			e[*it].insert(x);
    		}
    	}
    	e[y].clear();
    }
    puts("YES");
    return 0;
}

#include <bits/stdc++.h>
#define ls  (n<<1)
#define rs  (ls|1)
using namespace std;

const int N=100010;
struct edge{int s,t,n;}e[2*N],E[N];
int n,h[N],f[N],g[N],siz[N],hs[N],dfn[N],dep[N],t1[4*N],t2[4*N],tag[4*N];
set <int> S[4*N];

void dfs(int x,int fa)
{
	f[x]=fa,siz[x]=1;
	for (int i=h[x],y; y=e[i].t,i; i=e[i].n)
		if (y!=fa)
			{
				dfs(y,x),siz[x]+=siz[y];
				if (siz[y]>siz[hs[x]])  hs[x]=y;
			}
}

void dfs2(int x,int gf)
{
	g[x]=gf,dfn[x]=++dfn[0],dep[x]=dep[f[gf]]+1;
	if (hs[x])  dfs2(hs[x],gf);
	for (int i=h[x],y; y=e[i].t,i; i=e[i].n)
		if ((y!=f[x])&&(y!=hs[x]))  dfs2(y,y);
}

void merge(int n)
{
	if (t1[ls]<t1[rs])  t1[n]=t1[ls],t2[n]=min(t2[ls],t1[rs]);
	else  if (t1[ls]>t1[rs])  t1[n]=t1[rs],t2[n]=min(t2[rs],t1[ls]);
	else  t1[n]=t1[ls],t2[n]=min(t2[ls],t2[rs]);
	t1[n]+=tag[n],t2[n]+=tag[n];
}

void modify(int n,int l,int r,int L,int R,int k)
{
	if ((L<=l)&&(r<=R))
		{
			if (k>0)  S[n].insert(k),t1[n]++,t2[n]++,tag[n]++;
			else  S[n].erase(-k),t1[n]--,t2[n]--,tag[n]--;
		}else
		{
			int mid=(l+r)>>1;
			if (L<=mid)  modify(ls,l,mid,L,R,k);
			if (mid<R)  modify(rs,mid+1,r,L,R,k);
			merge(n);
		}
}

int find(int n,int l,int r)
{
	if (S[n].size())  return *S[n].begin();
	int mid=(l+r)>>1;
	return (t1[ls]==1)||(t2[ls]==1)?find(ls,l,mid):find(rs,mid+1,r);
}

void modify(int x,int y,int k)
{
	while (g[x]!=g[y])
		{
			if (dep[x]<dep[y])  swap(x,y);
			modify(1,1,n,dfn[g[x]],dfn[x],k),x=f[g[x]];
		}
	if (dfn[x]>dfn[y])  swap(x,y);
	if (x!=y)  modify(1,1,n,dfn[x]+1,dfn[y],k);
}

void work()
{
	scanf("%d",&n);
	for (int i=1,u,v,tot=0; i<n; i++)
		{
			scanf("%d %d",&u,&v);
			e[++tot]=(edge){u,v,h[u]},h[u]=tot;
			e[++tot]=(edge){v,u,h[v]},h[v]=tot;
		}
	for (int i=1; i<n; i++)  scanf("%d %d",&E[i].s,&E[i].t);
	dfs(1,0),dfs2(1,1),memset(t2,127,sizeof(t2));
	for (int i=1; i<n; i++)  modify(E[i].s,E[i].t,i);
	for (int i=1,j; i<n; i++)
		if (t2[1]==1)  j=find(1,1,n),modify(E[j].s,E[j].t,-i);
		else  puts("NO"),exit(0);
	puts("YES");
}

int main()
{
	work();
	return 0;
}

