{
	if(t[L].ms<t[R].ms)t[k].ms=t[L].ms,t[k].md=t[L].md,t[k].mp=t[L].mp;
	else t[k].ms=t[R].ms,t[k].md=t[R].md,t[k].mp=t[R].mp;
