	int mid=l+r>>1;down(k);
	if(qr<=mid)modify(L,l,mid,ql,qr,s,d);
	else if(ql>mid)modify(R,mid+1,r,ql,qr,s,d);
	else modify(L,l,mid,ql,mid,s,d),modify(R,mid+1,r,mid+1,qr,s,d);
