#define rep(i,a,b) for(int i=a;i<=b;i++)
#define per(i,a,b) for(int i=a;i>=b;i--)
using namespace std;
const int N=1e5+5;
map<int,int>mp[N];
set<int>e[N];
queue<pair<int,int> >que;
int fa[N],n;
int getfather(int &p){
	return p=fa[p]==p?p:getfather(fa[p]);
}
int main(){
	scanf("%d",&n);
	rep(i,1,2*(n-1)){
		int u,v;
		scanf("%d%d",&u,&v);
		mp[u][v]++;mp[v][u]++;
		e[u].insert(v);e[v].insert(u);
		if(mp[u][v]==2) que.push(make_pair(u,v));
	}
	rep(i,1,n) fa[i]=i;
	while(!que.empty()){
		int u=que.front().first,v=que.front().second;
		getfather(u);getfather(v);
		que.pop(); e[u].erase(v); e[v].erase(u);
		mp[u][v]--;mp[v][u]--;
		if(e[u].size()<e[v].size()) swap(u,v);
		for(set<int>::iterator it=e[v].begin();it!=e[v].end();it++){
			int t=*it;
			e[t].erase(v);e[t].insert(u);e[u].insert(t);
			mp[v][t]=mp[t][v]=0;
			mp[u][t]++;mp[t][u]++;
			if(mp[u][t]==2) que.push(make_pair(u,t));
		}
		fa[v]=u;e[v].clear();
	}
	int res=0;
	rep(i,1,n) res+=fa[i]==i;
	puts(res==1?"YES":"NO");
	return 0;
}

#include<bits/stdc++.h>
#define inf 1000000000
#define N 100009
#define M 300009
#define E 4000009
using namespace std;

int n,tot,dfsclk,e[N][2],fst[M],pnt[E],nxt[E];
int fa[N],sz[N],d[N],anc[N],pos[N],son[N],id[N],tg[M];
bool vis[N];
struct node{ int x,y; }mn[N];
bool operator <(node u,node v){ return u.x<v.x; }
void add(int x,int y){
	pnt[++tot]=y; nxt[tot]=fst[x]; fst[x]=tot;
}
void dfs(int x){
	int i,y; sz[x]=1;
	for (i=fst[x]; i; i=nxt[i]){
		y=pnt[i];
		if (y!=fa[x]){
			fa[y]=x; d[y]=d[x]+1;
			dfs(y); sz[x]+=sz[y];
			if (sz[y]>sz[son[x]]) son[x]=y;
		}
	}
}
void dvd(int x,int tp){
	int i,y; anc[x]=tp; pos[x]=++dfsclk;
	if (son[x]) dvd(son[x],tp);
	for (i=fst[x]; i; i=nxt[i]){
		y=pnt[i];
		if (y!=fa[x] && y!=son[x]) dvd(y,y); 
	}
}
int lca(int x,int y){
	for (; anc[x]!=anc[y]; x=fa[anc[x]])
		if (d[anc[x]]<d[anc[y]]) swap(x,y);
	return d[x]<d[y]?x:y;
}
void maintain(int k){	
	mn[k]=min(mn[k<<1],mn[k<<1|1]); mn[k].x+=tg[k];
}
void ins(int k,int l,int r,int x,int y,int z,int v){
	if (x<=l && r<=y){
		tg[k]+=v; mn[k].x+=v; if (v>0) add(k,z);
		return;
	}
	int mid=l+r>>1;
	if (x<=mid) ins(k<<1,l,mid,x,y,z,v);
	if (y>mid) ins(k<<1|1,mid+1,r,x,y,z,v);
	maintain(k);
}
void build(int k,int l,int r){
	mn[k].x=0; mn[k].y=l; 
	if (l==r){ id[l]=k; return; }
	int mid=l+r>>1;
	build(k<<1,l,mid); build(k<<1|1,mid+1,r);
}
void ins(int i,int x,int y,int v){
	for (; anc[x]!=anc[y]; x=fa[anc[x]])
		ins(1,1,n,pos[anc[x]],pos[x],i,v);
	if (d[y]<d[x]) ins(1,1,n,pos[y]+1,pos[x],i,v);
}
void ins(int i,int v){
	int x=e[i][0],y=e[i][1],z=lca(x,y);
	ins(i,x,z,v); ins(i,y,z,v);
}
void mdy(int x,int y){
	int i=id[x]; mn[i].x=y;
	for (i>>=1; i; i>>=1) maintain(i);
}
int main(){
	scanf("%d",&n);
	int i,j,k,x,y;
	for (i=1; i<n; i++){
		scanf("%d%d",&x,&y);
		add(x,y); add(y,x);
	}
	d[1]=1; dfs(1); dvd(1,1);
	tot=0; memset(fst,0,sizeof(fst));
	build(1,1,n);
	for (i=1; i<n; i++){
		scanf("%d%d",&e[i][0],&e[i][1]);
		ins(i,1);
	}
	int res=n;
	while (res>1 && mn[1].x<2){
		if (!mn[1].x)
			mdy(mn[1].y,inf);
		else{
			for (i=id[mn[1].y]; i; i>>=1){
				for (j=fst[i]; j; j=nxt[j]){
					k=pnt[j];
					if (vis[k]) fst[i]=nxt[j]; else break;
				}
