signed main(){
  Int n;
  cin>>n;

  vector<set<Int> > G(n),H(n);
  for(Int i=1;i<n;i++){
    Int x,y;
    cin>>x>>y;
    x--;y--;
    G[x].emplace(y);
    G[y].emplace(x);
  }
  for(Int i=1;i<n;i++){
    Int x,y;
    cin>>x>>y;
    x--;y--;
    H[x].emplace(y);
    H[y].emplace(x);
  }

  UnionFind uf(n);
  for(Int i=0;i<n;i++){
    Int v=i;
    if(v!=uf.find(v)) continue;
    queue<Int> mg;
    for(auto z:H[v]){
      if(uf.same(z,v)||!G[v].count(z)) continue;
      mg.emplace(uf.find(z));
    }
    while(!mg.empty()){
      Int u=mg.front();mg.pop();
      u=uf.find(u);
      if(uf.same(u,v)) continue;

      if(H[v].size()<H[u].size()) swap(H[v],H[u]);
      if(G[v].size()<G[u].size()) swap(G[v],G[u]);
      for(auto x:G[u]){
	int w=uf.find(x);
	if(H[u].count(x)||H[v].count(x)) mg.emplace(x);
	if(H[u].count(w)||H[v].count(w)) mg.emplace(w);
	G[v].emplace(x);
	G[v].emplace(w);
      }
      for(auto x:H[u]){
	int w=uf.find(x);
	if(G[u].count(x)||G[v].count(x)) mg.emplace(x);
	if(G[u].count(w)||G[v].count(w)) mg.emplace(w);
	H[v].emplace(x);
	H[v].emplace(w);
      }
      H[u].clear();G[u].clear();

      uf.unite(u,v);        
      Int r=uf.find(v);
      if(r!=v){
	swap(H[u],H[v]);
	swap(G[u],G[v]);
      }
      v=r;
    }
  }

  for(int v=0;v<n;v++){
    for(int u:G[v]) if(!uf.same(u,v)) assert(!H[v].count(u));
    for(int u:H[v]) if(!uf.same(u,v)) assert(!G[v].count(u));
  }
  cout<<(uf.r[uf.find(0)]==n?"YES":"NO")<<endl;
  return 0;
}

