struct Edge {
  int t,next;
  Edge() {}
  Edge(int a,int b):t(a),next(b) {}
};

Edge e[400005],e2[400005];
int head[200005],head2[200005];

int dep[200005],fa[200005][20];

void dfs(int x) {
  for(int i=head[x];i;i=e[i].next)
    if (e[i].t!=fa[x][0]) {
        int u=e[i].t;
        fa[u][0]=x;dep[u]=dep[x]+1;
        for(int j=1;j<20;j++) fa[u][j]=fa[fa[u][j-1]][j-1];
        dfs(u);
    }
}

int lca(int x,int y) {
  if (dep[x]<dep[y]) swap(x,y);
  int d=dep[x]-dep[y];
  for(int i=0;i<20;i++)
    if (d&(1<<i)) x=fa[x][i];
  if (x==y) return x;
  for(int i=19;i>=0;i--)
    if (fa[x][i]!=fa[y][i]) {
        x=fa[x][i];
        y=fa[y][i];
    }
  return fa[x][0];
}

int dis(int x,int y) {
  return dep[x]+dep[y]-2*dep[lca(x,y)];
}

int d[200005];
queue <int> q;

int bfs(int s) {
  memset(d,255,sizeof(d));
  d[s]=0;q.push(s);
  int ans=0;
  while (!q.empty()) {
    int x=q.front();q.pop();
    ans=max(ans,2*dep[x]);
    if (d[x]<dep[x]) {
        for(int i=head2[x];i;i=e2[i].next) {
            int u=e2[i].t,len=dis(x,u);
            if (len>2) return -1;
            else if (d[u]==-1) {
                d[u]=d[x]+1;
                q.push(u);
              }
          }
      }
  }
  return ans;
}

