const int MAXN = 1e5 + 7;
set<int> G[MAXN]; 
set<int> T[MAXN];

int main() {
    //ifstream cin("E.in");

    int n; cin >> n;

    for(int i = 0; i < n - 1; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        G[a].insert(b);
        G[b].insert(a);
    }

    for(int i = 0; i < n - 1; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        T[a].insert(b);
        T[b].insert(a);
    }

    queue<pair<int, int>> Q;
    set<pair<int, int>> seen;

    for(int i = 0; i < n; ++i)
        for(auto node : G[i])
            if(T[i].find(node) != T[i].end()) {
                auto edge = make_pair(min(node, i), max(node, i));
                if(seen.find(edge) == seen.end()) {
                    Q.push(edge);
                    seen.insert(edge);
                }
            }

    int many = 0;

    while(not Q.empty()) {
        auto edge = Q.front();
        Q.pop();

        int a = edge.first, b = edge.second;

        if(T[a].empty() or T[b].empty())
            continue;

        many++;
        vector<pair<int, int>> check;

        for(auto node : T[a]) {
            if(node != b) {
                T[b].insert(node);
                T[node].insert(b);
                T[node].erase(a);
                check.push_back(make_pair(min(b, node), max(b, node)));
            }
        }

        for(auto node : G[a]) {
            if(node != b) {
                G[b].insert(node);
                G[node].insert(b);
                G[node].erase(a);
                check.push_back(make_pair(min(b, node), max(b, node)));
            }
        }

        T[b].erase(a);
        G[b].erase(a);

        T[a].clear();
        G[a].clear();

        for(auto temp : check) {
            int x = temp.first;
            int y = temp.second;
            if(G[x].find(y) != G[x].end() and T[x].find(y) != T[x].end()) {
                if(seen.find(temp) == seen.end()) {
                    Q.push(temp);
                    seen.insert(temp);
                }
            }
        }
    }

    if(many == n - 1) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }    
}

