typedef long long ll;
const int maxn=200010;
int n,pre[maxn],fa[maxn],ch[maxn][2],sum[maxn],val[maxn],mx[maxn],flip[maxn];
#define lc ch[x][0]
#define rc ch[x][1]
void maintain(int x) {
	sum[x]=sum[lc]+sum[rc]+val[x];
	mx[x]=x;
	if(val[mx[lc]]>val[mx[x]]) mx[x]=mx[lc];
	if(val[mx[rc]]>val[mx[x]]) mx[x]=mx[rc];
}
void rotate(int x) {
	int y=pre[x],z=pre[y],d=ch[y][0]==x;
	ch[y][d^1]=ch[x][d];pre[ch[x][d]]=y;
	ch[z][ch[z][1]==y]=x;pre[x]=z;
	ch[x][d]=y;pre[y]=x;maintain(y);
}
void pushdown(int x) {
	if(flip[x]) {
		flip[lc]^=1;flip[rc]^=1;
		swap(lc,rc);flip[x]=0;
	}
}
int sta[maxn],top;
void splay(int x) {
	for(int i=x;i;i=pre[i]) sta[++top]=i;
	fa[x]=fa[sta[top]];
	while(top) pushdown(sta[top--]);
	while(pre[x]) {
		int y=pre[x],z=pre[y];
		if(z) {
			if(ch[y][0]==x^ch[z][0]==y) rotate(x);
			else rotate(y);
		}
		rotate(x);
	}
	maintain(x);
}
void access(int x) {
	for(int y=0;x;x=fa[x]) {
		splay(x);fa[ch[x][1]]=x;pre[ch[x][1]]=0;
		ch[x][1]=y;pre[y]=x;maintain(y=x);
	}
}
void makeroot(int x) {access(x);splay(x);flip[x]^=1;}
void link(int x,int y) {makeroot(x);fa[x]=y;}
int query(int x,int y,int tp) {
	makeroot(y);access(x);splay(x);
	if(!tp) return sum[x];
	return sum[x]==1?mx[x]:0;
}
struct Edge {
	int u,v,w;
	bool operator < (const Edge& ths) const {return w<ths.w;}
}E[maxn];
