	sort(E+1,E+n);
	rep(i,1,n-1) {
		int u=E[i].u,v=E[i].v,t;
		if(t=query(u,v,1)) {
			splay(t);val[t]=0;maintain(t);
			continue;
		}
		puts("NO");return 0;
	}
	puts("YES");
	return 0;
}

