void change(int k,int l,int r,int x,int y,int s)
{
	if (x<=l&&r<=y) return Add(k,s);
	pushdown(k);
	int mid=(l+r)>>1;
	if (x<=mid) change(lson,x,y,s);
	if (y>mid) change(rson,x,y,s);
	pushup(k);
}
