		L.emplace(a, b);
		uf.B[a].insert(b);
		uf.B[b].insert(a);
	}
	for(int i = 1; i < N; i++){
		scanf("%d%d", &a, &b);
		if( a > b ) swap(a, b);
		if( L.find(pii(a, b)) != L.end() ) M.insert(pii(a, b));
		uf.R[a].insert(b);
		uf.R[b].insert(a);
	}

	for(pii c : M) uf.merge(c.first, c.second);
	for(int i = 1; i <= N; i++){
		if( uf.find(i) != uf.find(1) ) return !printf("NO\n");
	}
	printf("YES\n");
}

