set<int>f[1000005];
int main(void)
{
	int i,j,k,x,y,n,found=0;
	scanf("%d",&n);
	for(i=1;i<=2*n-2;++i)
	{
		scanf("%d%d",&x,&y);
		++Hash[1LL*x*n+y];
		++Hash[1LL*y*n+x];
		f[x].insert(y);
		f[y].insert(x);
		if(Hash[x*n+y]==2)a.push_back(x),b.push_back(y);
	}
	for(i=0;i<a.size();++i)
	{
		if(Hash[1LL*a[i]*n+b[i]]==2)
		{
			++found;
			if(f[a[i]].size()<f[b[i]].size())swap(a[i],b[i]);
			while(f[b[i]].size())
			{
				j=*f[b[i]].begin();
				Hash[1LL*a[i]*n+j]+=Hash[1LL*b[i]*n+j];
				Hash[1LL*j*n+a[i]]+=Hash[1LL*b[i]*n+j];
				Hash[1LL*b[i]*n+j]=Hash[1LL*j*n+b[i]]=0;
				f[a[i]].insert(j);
				f[j].erase(b[i]);
				f[j].insert(a[i]);
				if(Hash[1LL*a[i]*n+j]==2)a.push_back(a[i]),b.push_back(j);
				f[b[i]].erase(j);
			}
		}
	}
	if(found==n-1)printf("YES\n");
	else printf("NO\n");
	return 0;
}

