inline ll fid(ll x){return fa[x]==x?x:fa[x]=fid(fa[x]);}
inline ll Ha(ll x,ll y){return ((x-1)*n+y)%P;}
int main(){
	read(n);
	for (ll i=1,x,y;i<=2*n-2;++i){
		read(x),read(y);
		++vis[Ha(x,y)],++vis[Ha(y,x)];
