	if(l[u]>l[v])swap(u,v);
	if(l[u]<l[v])add(1,l[u]+1,l[v],id);
}

void del2(int i,int l,int r){
	if(l<=T[i].l&&T[i].r<=r){
		T[i].bj--;
		T[i].mn--;T[i].mx--;
		return;
	}
	int M=T[i].l+T[i].r>>1;
	pushdown(i);
	if(l<=M)del2(i<<1,l,r);if(r>M)del2(i<<1|1,l,r);
	T[i].mn=min(T[i<<1].mn,T[i<<1|1].mn);
	T[i].mx=max(T[i<<1].mx,T[i<<1|1].mx);
}

int query(int i){
	while(Is[val[T[i].head]])T[i].head=nxt[T[i].head];
	if(T[i].head)return val[T[i].head];
	if(T[i].l==T[i].r)return -1;
	pushdown(i);
	//if(T[i].l==T[i].r)return;
	if(T[i<<1].mn<=1&&T[i<<1].mx>=1)return query(i<<1);else return query(i<<1|1);
}

