bool solve(const vector<vector<pair<int, int> > >& v)
{
    int n = v[0].size() + 1;
    vector<set<pair<int, int> > > s(2);
    vector<int> cnt(n, 0);
    for(int i=0; i<2; ++i){
        for(int j=0; j<n-1; ++j){
            int a = v[i][j].first;
            int b = v[i][j].second;
            s[i].insert(make_pair(a, b));
            s[i].insert(make_pair(b, a));
            ++ cnt[a];
            ++ cnt[b];
        }
    }

    queue<pair<int, int> > q;
    for(const auto& p : s[0]){
        if(p.first < p.second && s[1].find(p) != s[1].end())
            q.push(p);
    }

    for(int t=0; t<n-1; ++t){
        int a, b;
        for(;;){
            if(q.empty())
                return false;
            tie(a, b) = q.front();
            q.pop();
            if(cnt[a] != -1 && cnt[b] != -1)
                break;
        }

        if(cnt[a] < cnt[b])
            swap(a, b);
        cnt[a] += cnt[b] - 4;
        cnt[b] = -1;

        for(int i=0; i<2; ++i){
            s[i].erase(make_pair(a, b));
            s[i].erase(make_pair(b, a));
            for(;;){
                auto it = s[i].lower_bound(make_pair(b, -1));
                if(it == s[i].end() || it->first != b)
                    break;

                int c = it->second;
                s[i].erase(make_pair(b, c));
                s[i].erase(make_pair(c, b));
                s[i].insert(make_pair(a, c));
                s[i].insert(make_pair(c, a));
                if(s[i^1].find(make_pair(a, c)) != s[i^1].end())
                    q.push(make_pair(a, c));
            }
        }
    }

    return true;
}

int main()
{
    int n;
    cin >> n;

    vector<vector<pair<int, int> > > v(2, vector<pair<int, int> >(n-1));
    for(int i=0; i<2; ++i){
        for(int j=0; j<n-1; ++j){
            cin >> v[i][j].first >> v[i][j].second;
            -- v[i][j].first;
            -- v[i][j].second;
        }
    }

    if(solve(v))
        cout << "YES" << endl;
    else
        cout << "NO" << endl;

    return 0;
}

