			exit(0);
		}
		par[v].erase(tmp);
		if(par[v].size()==1) leaves.pb(v);
		v=T.st[0][v].p;
	}
	if(tim()>585000)
	{
		cout<<"YES\n";
		exit(0);
	}
}

