		arr[p].l=l;
		arr[p].r=r;
		if(l<r){
			int M=((l+r)>>1);
			init((p<<1),l,M);
			init(((p<<1)|1),M+1,r);
		}
	}
	void insert(int p,int d,pii v){
		arr[p].vs.insert(v);
		if(arr[p].l<arr[p].r){
			int M=((arr[p].l+arr[p].r)>>1);
			if(d<=M) insert((p<<1),d,v);
			else 	 insert(((p<<1)|1),d,v);
		}
	}
	void erase(int p,int d,pii v){
		arr[p].vs.erase(arr[p].vs.find(v));
		if(arr[p].l<arr[p].r){
			int M=((arr[p].l+arr[p].r)>>1);
			if(d<=M) erase((p<<1),d,v);
			else 	 erase(((p<<1)|1),d,v);
		}
	}
	pii query(int p,int L,int R){
		if(arr[p].l>=L && arr[p].r<=R){
			if(arr[p].vs.empty()) return mpr(-1,-1);
			if(arr[p].vs.begin()->first<L) return *arr[p].vs.begin();
			if(arr[p].vs.rbegin()->first>R) return *arr[p].vs.rbegin();
			return mpr(-1,-1);
		}
		int M=((arr[p].l+arr[p].r)>>1);
		pii ret=mpr(-1,-1);
		if(L<=M) ret=query((p<<1),L,R);
		if(R>M) UMAX(ret,query(((p<<1)|1),L,R));
		return ret;
	}
}segt_edge;
