struct HLdecomp {
	static const int MD=20;
	int N,NE;
	vector<vector<int>> E,Cs; // edge, list of BIT
	vector<int> D,S,B,C,Ci; // depth, size, base of BIT, child of BIT(val,id)
	vector<vector<int>> P;
	void init(int N) { this->N=N, NE=0, E.clear(),E.resize(N); Cs.clear(),Cs.resize(N);
		D=S=B=C=Ci=vector<int>(N,0); int i; P.clear(); FOR(i,MD+1) P.push_back(vector<int>(N,0));}
	void add_edge(int a,int b){ E[a].push_back(b),E[b].push_back(a); NE++;} // undir
	void dfs(int cur,int pre) { // get depth, parent, size, largest subtree
		int i;
		P[0][cur]=pre;S[cur]=1;C[cur]=Ci[cur]=-1;B[cur]=cur;
		D[cur]=(pre==-1)?0:(D[pre]+1);
		FOR(i,E[cur].size()) if(E[cur][i]!=pre) {
			int r=E[cur][i]; dfs(r,cur); S[cur]+=S[r];
			if(C[cur]==-1 || S[r]>S[C[cur]]) C[cur]=r,Ci[cur]=i;
		}
	}
	void dfs2(int cur,int pre) { // set base and list
		if(pre!=-1 && C[pre]==cur) B[cur]=B[pre];
		Cs[B[cur]].push_back(cur);
		FORR(r,E[cur]) if(r!=pre) dfs2(r,cur);
	}
	pair<int,int> lca(int a,int b) {
		int ret=0,i,aa=a,bb=b;
		if(D[aa]>D[bb]) swap(aa,bb);
		for(i=19;i>=0;i--) if(D[bb]-D[aa]>=1<<i) bb=P[i][bb];
		for(i=19;i>=0;i--) if(P[i][aa]!=P[i][bb]) aa=P[i][aa], bb=P[i][bb];
		return make_pair((aa==bb)?aa:P[0][aa], D[a]+D[b]-2*D[(aa==bb)?aa:P[0][aa]]);
	}
	void decomp(int root=0){
		assert(NE==N-1);
		dfs(root,root); dfs2(root,root);
		int i,x; FOR(i,MD) FOR(x,N) P[i+1][x]=P[i][P[i][x]];
	}
};

static ll const def=1<<20;
template<class V> class SegTree_3 {
public:
	int NV;
	vector<V> val, mi;
	void init(int n) {
		NV=1;
		while(NV<=n) NV*=2;
		int i;
		val.resize(NV*2,0); mi.resize(NV*2,0);
	};

	V getval(int x,int y,int l=0,int r=-1,int k=1) {
		if(r==-1) r=NV;
		if(r<=x || y<=l) return def;
		if(x<=l && r<=y) return mi[k];
		return val[k]+min(getval(x,y,l,(l+r)/2,k*2),getval(x,y,(l+r)/2,r,k*2+1));
	}

	void update(int x,int y, V v,int l=0,int r=-1,int k=1) {
		if(r==-1) r=NV;
		if(l>=r) return;
		if(x<=l && r<=y) {
			val[k]+=v;
			mi[k]+=v;
		}
		else if(l < y && x < r) {
			update(x,y,v,l,(l+r)/2,k*2);
			update(x,y,v,(l+r)/2,r,k*2+1);
			mi[k]=val[k]+min(mi[k*2],mi[k*2+1]);
		}
	}
};

HLdecomp hl;
SegTree_3<int> st[201010];
void add(int f,int t,int v) {
	while(hl.B[f]!=hl.B[t]) {
		st[hl.B[f]].update(0,1+hl.D[f]-hl.D[hl.B[f]],v);
		f=hl.P[0][hl.B[f]];
	}
	st[hl.B[f]].update(hl.D[t]-hl.D[hl.B[f]],1+hl.D[f]-hl.D[hl.B[f]],v);
}
int get(int f,int t) {
	int ret = 1<<22;
	while(hl.B[f]!=hl.B[t]) {
		ret=min(ret,st[hl.B[f]].getval(0,1+hl.D[f]-hl.D[hl.B[f]]));
		f=hl.P[0][hl.B[f]];
	}
	return min(ret,st[hl.B[f]].getval(hl.D[t]-hl.D[hl.B[f]],1+hl.D[f]-hl.D[hl.B[f]]));
}

int N;
vector<int> E[101010];
int A[101010],B[101010],C[101010];

vector<int> Ds[101010];
vector<pair<int,int>> LD[101010];


void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;

	hl.init(N);
	FOR(i,N-1) {
		cin>>x>>y;
		E[x-1].push_back(y-1);
		E[y-1].push_back(x-1);
		hl.add_edge(x-1,y-1);
	}
	hl.decomp();

	FOR(i,N) if(hl.B[i]==i) st[i].init(hl.Cs[i].size()+2);
	FOR(i,N) Ds[hl.D[i]].push_back(i);

	FOR(i,N-1) {
		cin>>A[i]>>B[i];
		A[i]--;
		B[i]--;
		C[i] = hl.lca(A[i],B[i]).first;
		add(A[i],C[i],1);
		add(B[i],C[i],1);
		add(C[i],C[i],-1);
		LD[hl.D[C[i]]].push_back({max(hl.D[A[i]],hl.D[B[i]]),i});
	}

	FOR(i,N) {
		FORR(x,Ds[i]) {
			sort(ALL(LD[x]));
			reverse(ALL(LD[x]));
			FORR(e,LD[x]) {
				i=e.second;
				add(A[i],C[i],-1);
				add(B[i],C[i],-1);
				add(C[i],C[i],1);
				x = min(get(A[i],C[i]),get(B[i],C[i]));
				//_P("%d[%d] : %d %d %d %d\n",i,max(hl.D[A[i]],hl.D[B[i]]),A[i],B[i],get(A[i],C[i]),get(B[i],C[i]));
				if(x>0) return _P("NO\n");

			}
		}
	}



	return _P("YES\n");



}


