const int MAXN = 1e5 + 1;
typedef pair<int,int> pii;
set<int> B[MAXN] , R[MAXN];
map<pii,int> Bm , Rm;
int n , f[MAXN] , he , ta;
pii que[MAXN << 4];
int find( const int & x ) { return x == f[x] ? x : f[x] = find( f[x] ); }
pii get( int u , int v ) { if( u > v ) swap( u , v ); return make_pair( u , v ); }
int main( void ) {
  scanf("%d",&n) , he = 1 , ta = 0;
  for( int i = 1 ; i <= n ; ++i ) f[i] = i;
  for( int i = 1 , u , v ; i < n ; ++i ) {
    scanf( "%d%d" , &u , &v );
    B[u].insert( v ) , B[v].insert( u );
    Bm[get( u , v )] = 1;
  }
  for( int i = 1 , u , v ; i < n ; ++i ) {
    scanf( "%d%d" , &u , &v );
    R[u].insert( v ) , R[v].insert( u );
    Rm[get( u , v )] = 1;
    if( Bm[get( u , v )] ) que[++ta] = pii( u , v );
  }
  int u , v , cnt = 0;
  while( he <= ta ) {
    u = que[he].first , v = que[he].second; ++he;
    if( ( u = find( u ) ) == ( v = find( v ) ) ) continue;
    ++cnt;
    if( B[u].size() + R[u].size() < B[v].size() + R[v].size() ) swap( u , v );
    B[u].erase( v ) , B[v].erase( u );
    for( int pt : B[v] ) {
      B[u].insert( pt );
      Bm[get( v , pt )] = 0 , Bm[get( u , pt )] = 1;
      if( Rm[get( u , pt )] ) que[++ta] = pii( u , pt );
      B[u].insert( pt ) , B[pt].insert( u ) , B[pt].erase( v );
    }
    R[u].erase( v ) , R[v].erase( u );
    for( int pt : R[v] ) {
      R[u].insert( pt );
      Rm[get( v , pt )] = 0 , Rm[get( u , pt )] = 1;
      if( Bm[get( u , pt )] ) que[++ta] = pii( u , pt );
      R[u].insert( pt ) , R[pt].insert( u ) , R[pt].erase( v );
    }
    f[v] = u;
  }
  puts( cnt == n - 1 ? "YES" : "NO" );
  return 0;
}

