using namespace std;

typedef pair<int,int> pr;

set <int> e1[100005],e2[100005];
int size[100005];
queue <pr> q;

int fa[100005];

void init(int n) {
  for(int i=1;i<=n;i++) fa[i]=i;
}

int find_father(int x) {
  return (fa[x]==x)?x:fa[x]=find_father(fa[x]);
}

bool merge(int x,int y) {
  x=find_father(x);y=find_father(y);
  if (x==y) return 0;
  if (size[x]<size[y]) swap(x,y);
  size[x]+=size[y];fa[y]=x;
  int p=0;
  for(set<int>::iterator it=e1[y].begin();it!=e1[y].end();it++,p=find_father(*it))
    if (p!=x&&e2[x].count(p)) q.push(pr(x,p));
  for(set<int>::iterator it=e2[y].begin();it!=e2[y].end();it++,p=find_father(*it))
    if (p!=x&&e1[x].count(p)) q.push(pr(x,p));
  for(set<int>::iterator it=e1[y].begin();it!=e1[y].end();it++,p=find_father(*it))
    if (p!=x) e1[x].insert(p);
  for(set<int>::iterator it=e2[y].begin();it!=e2[y].end();it++,p=find_father(*it))
    if (p!=x) e2[x].insert(p);
  return 1;
}

int main() {
  int n;
  scanf("%d",&n);
  init(n);
  for(int i=1;i<n;i++) {
    int x,y;
    scanf("%d%d",&x,&y);
    e1[x].insert(y);
    e1[y].insert(x);
  }
  for(int i=1;i<n;i++) {
    int x,y;
    scanf("%d%d",&x,&y);
    e2[x].insert(y);
    e2[y].insert(x);
    if (e1[x].count(y)) q.push(pr(x,y));
  }
  int cnt=0;
  while (!q.empty()) {
    pr x=q.front();q.pop();
    cnt+=merge(x.FR,x.SE);
  }
  printf("%s\n",(cnt==n-1)?"YES":"NO");
  return 0;
}

