#define x first
#define y second

namespace jm
{
	typedef std::pair<int,int> pii;
	const int N=101000;
	std::queue<pii> Q;
	std::set<int> G0[N],G1[N];
	int n;
	void initialize()
	{
		scanf("%d",&n);
		for(int i=1,u,v;i<n;i++)
		{
			scanf("%d%d",&u,&v);
			G0[u].insert(v);
			G0[v].insert(u);
		}

		for(int i=1,u,v;i<n;i++)
		{
			scanf("%d%d",&u,&v);
			G1[u].insert(v);
			G1[v].insert(u);

			if(G0[u].find(v)!=G0[u].end())
				Q.push(pii(u,v));
		}
	}

	bool done[N];

	void combine(int u,int v)
	{
		int v0=v,v1=v;
		if(G0[u].size()>G0[v].size())std::swap(G0[u],G0[v]),v0=u;
		if(G1[u].size()>G1[v].size())std::swap(G1[u],G1[v]),v1=u;

		for(auto x:G0[v])
		{
			G0[u].insert(x);
			G0[x].insert(u);

			G0[x].erase(v0);

			if(G1[u].find(x)!=G1[u].end())
				Q.push(pii(u,x));
		}
		G0[v].clear();

		for(auto x:G1[v])
		{
			G1[u].insert(x);
			G1[x].insert(u);

			G1[x].erase(v1);

			if(G0[u].find(x)!=G0[u].end())
				Q.push(pii(u,x));
		}
		G1[v].clear();

		done[v]=1;
	}

	void solve()
	{
		initialize();
		while(!Q.empty())
		{
			pii A=Q.front();Q.pop();
			int x=A.x,y=A.y;
			if(x==y || done[x] || done[y])continue;
//			printf("%d -- %d\n",x,y);
			combine(x,y),n--;
		}
		printf("%s\n",n>1?"NO":"YES");
	}
}

int main()
{
	jm::solve();
	return 0;
}

