using namespace std;

const int M = 110001;
queue<int> q;
map<pair<int,int>,int> mp;
int ft[M],s[M],S[M],m,n,d[M];
vector<int> v[M],V[M];
int ff(int x)
{
	if(ft[x]==x) return x;
	return ft[x]=ff(ft[x]);
}

struct vv
{
	int x,y;
} a[M],b[M];

int main()
{
	int T;
//	scanf("%d",&T);
//	for(;T;T--)
	{
	memset(s,0,sizeof(s));
	memset(S,0,sizeof(S));
	for(int i=1;i<=n;i++) V[i].clear(), v[i].clear();
	memset(d,0,sizeof(d));
	scanf("%d",&n);
	m=n;
	for(int i=1;i<=n;i++) ft[i]=i;
	for(int i=1;i<n;i++)
	{
		scanf("%d%d",&a[i].x,&a[i].y);
		mp[Mp(a[i].x,a[i].y)]=1;mp[Mp(a[i].y,a[i].x)]=1;
	}
	for(int i=1;i<n;i++)
	{
		scanf("%d%d",&b[i].x,&b[i].y);
		if(mp.find(Mp(b[i].x,b[i].y))!=mp.end() || mp.find(Mp(b[i].y,b[i].x))!=mp.end()) ft[ff(b[i].x)]=ff(b[i].y);
	}
	for(int i=1;i<n;i++)
	{
		if(ff(a[i].x)==ff(a[i].y)) continue;
		v[ft[a[i].x]].push_back(ft[a[i].y]);
		v[ft[a[i].y]].push_back(ft[a[i].x]);
		s[ft[a[i].x]]+=1, s[ft[a[i].y]]+=1;
	}
	for(int i=1;i<n;i++)
	{
		if(ff(b[i].x)==ff(b[i].y)) continue;
		V[ft[b[i].x]].push_back(ft[b[i].y]);
		V[ft[b[i].y]].push_back(ft[b[i].x]);
		S[ft[b[i].x]]+=1, S[ft[b[i].y]]+=1;
	}
	for(int i=1;i<=n;i++) if(S[i]<=1 && s[i]<=1 && ft[i]==i) q.push(i), m-=1, d[i]=1;
	for(int i=1;i<=n;i++) if(ft[i]!=i) d[i]=1, m-=1;
	while(q.size())
	{
		int x=q.front(); q.pop(); int k=0;
		for(int i=0;i<v[x].size();i++)
		{
			if(s[v[x][i]]<=1) continue;
			s[v[x][i]]-=1; k+=1;
			if(s[v[x][i]]<=1 && S[v[x][i]]<=1 && !d[v[x][i]]) q.push(v[x][i]), m-=1,d[v[x][i]]=1; 
		}
		if(k>1) return 1/0; k=0;
		for(int i=0;i<V[x].size();i++)
		{
			if(s[v[x][i]]<=1) continue;
			S[V[x][i]]-=1; k+=1;
			if(S[V[x][i]]<=1 && s[V[x][i]]<=1 && !d[V[x][i]]) q.push(V[x][i]), m-=1, d[V[x][i]]=1;
		}
		if(k>1) return 1/0;
	}
	for(int i=1;i<=n;i++)
	{
		if(S[i]<=1 && s[i]<=1 && !d[i]) return 1/0;
	}
	if(m) printf("NO\n");
	else printf("YES\n");
	}
}

