using namespace std;
using pii = pair<int, int>;

typedef long long llint;

const int MAXN = 100010;

int n, sz[MAXN], dad[MAXN], totm;
multiset<int> e[MAXN][2];
queue<pii> q;

int find(int x) {
  if (dad[x] == x) return x;
  return dad[x] = find(dad[x]);
}

void add_edge(int x, int y, int t) {
  //y  = find(y);
  if (x == find(y)) return;

  e[x][t].insert(y);
  if (e[x][t^1].count(y) == 1) {
    q.push({x, y});
  }
}

void merge(int u, int v) {
  u = find(u);
  v = find(v);
  if (u == v) return;

  ++totm;

  if (sz[v] > sz[u]) swap(u, v);
  dad[v] = u;
  sz[u] += sz[v];

  REP(t, 2)
    for (auto it = e[v][t].begin(); it != e[v][t].end(); ++it)
      add_edge(u, *it, t);
}

int main(void) {
  scanf("%d",&n);
  REP(i, n) { dad[i] = i; sz[i] = 1; }
  REP(t, 2) {
    REP(i, n - 1) {
      int u, v;
      scanf("%d %d",&u,&v);
      --u;
      --v;
      add_edge(u, v, t);
      add_edge(v, u, t);
    }
  }

  while (!q.empty()) {
    pii x = q.front();
    q.pop();

    TRACE(x.u+1 _ x.v+1);

    merge(x.u, x.v);
  }

  printf(totm == n - 1 ? "YES\n" : "NO\n");

  return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define MAXN	100005
int num[MAXN];
multiset <int> a[MAXN];
queue <int> qx, qy;
int F(int x) {
	if (x == num[x]) return x;
	else return num[x] = F(num[x]);
}
int main() {
	int n; scanf("%d", &n);
	for (int i = 1; i <= n; i++)
		num[i] = i;
	for (int i = 1; i <= 2 * n - 2; i++) {
		int x, y;
		scanf("%d%d", &x, &y);
		a[x].insert(y);
		a[y].insert(x);
	}
	int ans = 0;
	for (int i = 1; i <= n; i++) {
		multiset <int> :: iterator j, k;
		for (j = a[i].begin(); j != a[i].end(); k = j, j++)
			if (j != a[i].begin() && *j == *k) {
				qx.push(i);
				qy.push(*j);
			}
	}
	while (!qx.empty()) {
		int tx = F(qx.front());
		int ty = F(qy.front());
		qx.pop(), qy.pop();
		if (tx == ty) continue;
		ans++;
		if (a[tx].size() > a[ty].size()) swap(tx, ty);
		num[tx] = ty;
		multiset <int> :: iterator j;
		int value;
		for (j = a[tx].begin(), value = *j; j != a[tx].end(); j++, value = *j) {
			if (value == ty) continue;
			a[value].erase(a[value].find(tx));
			a[value].insert(ty);
			if (a[value].count(ty) >= 2) {
				qx.push(value);
				qy.push(ty);
			}
		}
		a[ty].erase(tx);
		a[tx].clear();
	}
	if (ans == n - 1) cout << "YES" << endl;
	else cout << "NO" << endl;
	return 0;
}

