const int maxv = 1e5+5;
int uf[maxv];
set<int> G[maxv];
map<PII,int> E;

int find(const int x)
{
    if (x != uf[x])
        uf[x] = find(uf[x]);    /* pass compression */
    return uf[x];
}

void unin(const int x, const int y)
{
    const int a = find(x), b = find(y);
    uf[b] = a;
}

PII makee(const int u, const int v)
{ return u > v ? PII(v,u) : PII(u,v); }

PII connect(const int u, const int v)
{ G[u].insert(v); G[v].insert(u); return makee(u,v); }

void disconnect(const int u, const int v)
{ G[u].erase(v); G[v].erase(u); }

int main()
{
    int N;
    while (cin >> N) {
        FOR(i,1,N+1)
            uf[i] = i;
        E.clear();
        FOR(_,0,2*(N-1)) {
            int u,v; cin >> u >> v;
            const PII e = connect(u,v);
            E[e]++;
        }
        queue<PII> Q;
        FOR_ALL(e,E) if (e->second >= 2)
            Q.push(e->first);
        while (Q.size()) {
            const PII e = Q.front(); Q.pop();
            const int x = find(e.first);
            const int y = find(e.second);
            unin(x,y);
            const int u = find(x);
            const int v = u == x ? y : x;
            const set<int> gv = G[v];
            FOR_ALL(i,gv) {
                const int w = find(*i);
                if (w != u) {
                    const PII ee = connect(u,w);
                    E[ee]++;
                    if (E[ee] >= 2) {
                        Q.push(ee);
                    }
                }
                disconnect(v,w);
            }
        }
        set<int> S;
        FOR(i,1,N+1)
            S.insert(find(i));
        const string ans = S.size() == 1 ? "YES" : "NO";
        cout << ans << endl;
    }
    return 0;
}

