			int noww = getfa(*it);
			if(noww != fax)
			{
//			cout << "it = " << (*it) << endl;
				if(!mp[fay].count(noww))
				{
					mp[fay].insert(noww);
					mp[noww].insert(fay);
				}
				if(!vis[fay].count(noww) && mp[fay].count(noww) && mp2[fay].count(noww))
				{
					vis[fay].insert(noww);
					vis[noww].insert(fay);
					q.push(make_pair(fay, noww));
