        cin >> u >> v;
        add(u, v, 1);
        e.push_back({u, v});
    }

    sort(e.begin(), e.end(), cmp);

    for(int i = 0; i < n - 1; i++)
    {
        int u = e[i].first, v = e[i].second;
        pair<int, int> mx = query(u, v).mx;

        //cout << u << " -> " << v << " : " << vert[mx.second] << endl;

        if(mx.first != 1)
        {
            cout << "NO" << endl;
