int main(){
	int N;
	scanf("%d",&N);
	REP(i,N-1){
		int a,b;
		scanf("%d %d",&a,&b);
		a--;
		b--;
		G[a].insert(P(b,false));
		G[b].insert(P(a,false));
	}
	REP(i,N-1){
		int a,b;
		scanf("%d %d",&a,&b);
		a--;
		b--;
		G[a].insert(P(b,true));
		G[b].insert(P(a,true));
	}
	int c=0;
	REP(i,N){
		int v=i,v2;
		while(1){
			v2=-1;
			if (used[v]) break;
			for(auto ite=G[v].begin();ite!=G[v].end();){
				auto ite2=ite;
				ite2++;
				if (ite2==G[v].end()) break;
				if (ite->first==ite2->first){
					v2=ite->first;
					if (G[v].size()<G[v2].size()){
						swap(v,v2);
					}
					break;
				}
				ite++;
				if (ite->second){
					ite++;
				}
			}
