int d[100000];
void dfs0(int x){
	used[x]=1;
	for(auto y:g[x]){
		if(!used[y]){
			d[y]=d[x]+1;
			p[0][y]=x;
			dfs0(y);
		}
	}
}
int lca(int a, int b){
  if(d[a]>d[b]) swap(a, b);
    int a1=a, b1=b;
    int dd=d[b]-d[a], i=0;
    while(dd>0){
        if(dd%2==1){
            b1=p[i][b1];
        }
        dd/=2;
        i++;
    }
    if(a1==b1) return a1;
    for(int i=16; i>=0; i--){
        if(p[i][a1]!=p[i][b1]){
            a1=p[i][a1], b1=p[i][b1];
        }
    }
    return p[0][a1];
}
void add(int s, int t, int i){
	int p0=lca(s, t);
	while(s!=p0){
		v[s].insert(i);
		s=p[0][s];
	}
	while(t!=p0){
		v[t].insert(i);
		t=p[0][t];
	}
}
void sub(int s, int t, int i){
	int p0=lca(s, t);
	while(s!=p0){
		v[s].erase(i);
		s=p[0][s];
	}
	while(t!=p0){
		v[t].erase(i);
		t=p[0][t];
	}
}
