{
	int n;
	cin>>n;
	assert(n<=5000);
	for(int i=0; i<n-1; i++){
		int a, b; cin>>a>>b; a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	dfs0(0);
	for(int i=1; i<17; i++){
        for(int x=0; x<n; x++){
            p[i][x]=p[i-1][p[i-1][x]];
        }
    }
	int c[100000], e[100000];
	for(int i=0; i<n-1; i++){
		cin>>c[i]>>e[i]; c[i]--; e[i]--;
		add(c[i], e[i], i);
	}
	for(int i=0; i<n-1; i++){
		int i1=-1;
		for(int j=1; j<n; j++){
			if(v[j].size()==1){
				i1=(*v[j].begin());
				break;
			}
		}
		if(i1==-1){
			cout<<"NO"<<endl;
			return 0;
		}
		sub(c[i1], e[i1], i1);
	}
	cout<<"YES"<<endl;
	return 0;
}

