struct SegTree {
    static const int maxn = 100100;

    struct node {
        int l, r;
        int val, lazy;
        VI path;

        int get_val () {
            return val + lazy;
        }
    };

    node no[maxn * 4];

    void push_up (int ind) {
        no[ind].val = min (no[lson].get_val (), no[rson].get_val ());
    }

    void push_down (int ind) {
        no[lson].val += no[ind].lazy;
        no[rson].val += no[ind].lazy;
        no[ind].lazy = 0;
    }

    void build (int l, int r, int ind) {
        no[ind].l = l;
        no[ind].r = r;
        no[ind].lazy = no[ind].val = 0;
        if (l == r) {

        } else {
            int mid = (l + r) / 2;
            build (l, mid, lson);
            build (mid + 1, r, rson);
            push_up (ind);
        }
    }

    void update (int l, int r, int ind, int val, int id) {
        if (l > no[ind].r || r < no[ind].l)return;
        if (l <= no[ind].l && no[ind].r <= r) {
            no[ind].lazy += val;
            if (id)no[ind].path.PB (id);
        } else {
            push_down (ind);
            update (l, r, lson, val, id);
            update (l, r, rson, val, id);
            push_up (ind);
        }
    }

    void clean (int ind) {
        if (no[ind].get_val ())return;
        if (no[ind].l == no[ind].r) {
            no[ind].val = 1e9;
        } else {
            push_down (ind);
            clean (lson);
            clean (rson);
            push_up (ind);
            if (no[ind].get_val () == 0)no[ind].val = 1e9;
        }
    }

    int gao (int ind) {
        if (no[ind].get_val () != 1)return -1;
        while (sz(no[ind].path) and vis[no[ind].path.back ()]) {
            no[ind].path.pop_back ();
        }
        if (sz(no[ind].path)) {
            int id = no[ind].path.back();
            return id;
        } else {
            push_down (ind);
            int id = gao (lson);
            if (id != -1)return id;
            else id = gao (rson);
            push_up (ind);
            return id;
        }
    }

};
namespace HLD {
    SegTree tree;

    //0不能被使用
    struct Edge {
        int to, len;

        Edge (int to, int len = 1) : to (to), len (len) {}
    };

    const int root = 1;
    const int maxn = 200010;
    vector<Edge> adj[maxn];
    int dfnToID[maxn], dfn[maxn], head[maxn], fa[maxn], size[maxn], heavy[maxn], r[maxn], cnt = 1;
    ll dep[maxn];

    void addEdge (int u, int v, int len = 1) {
        adj[u].emplace_back (v, len);
        adj[v].emplace_back (u, len);
    }

    void firstDfs (int cur, int _fa) {
        size[cur] = 1;
        fa[cur] = _fa;
        for (auto e:adj[cur]) {
            if (e.to != _fa) {
                dep[e.to] = dep[cur] + e.len;
                firstDfs (e.to, cur);
                size[cur] += size[e.to];
            }
        }
        int heavyChild = 0;
        for (auto e:adj[cur]) {
            if (e.to != _fa) {
                if (size[e.to] > size[heavyChild]) {
                    heavyChild = e.to;
                }
            }
        }
        heavy[cur] = heavyChild;
    }


    void secondDfs (int cur, int _fa) {
        if (cur != heavy[_fa]) {
            head[cur] = cur;
        } else {
            head[cur] = head[_fa];
        }
        dfn[cur] = cnt++;
        r[cur] = dfn[cur];
        dfnToID[dfn[cur]] = cur;
        if (!heavy[cur])return;
        secondDfs (heavy[cur], cur);
        r[cur] = r[heavy[cur]];
        for (auto e:adj[cur]) {
            if (e.to == _fa || e.to == heavy[cur])continue;
            secondDfs (e.to, cur);
            r[cur] = r[e.to];
        }
    }

    void init () {
        cin>>n;
        REP(i, 1, n) {
            int a, b;
            cin>>a>>b;
            addEdge (a, b);
        }
        dep[1] = 0;
        firstDfs (root, 0);
        secondDfs (root, 0);
        tree.build (2, n, 1);
    }


    int kthFather (int k, int cur) {
        while (k) {
            if (head[cur] == cur) {
                k--;
                cur = fa[head[cur]];
            } else {
                if (dep[cur] - dep[head[cur]] <= k) {
                    k -= dep[cur] - dep[head[cur]];
                    cur = head[cur];
                } else {
                    return dfnToID[dfn[cur] - k];
                }
            }
        }
        return cur;
    }

    int LCA (int u, int v) {
        while (head[u] != head[v]) {
            if (dep[head[u]] > dep[head[v]])swap (u, v);
            v = fa[head[v]];
        }
        if (dep[u] < dep[v])return u;
        return v;
    }

    int dis (int u, int v) {
        return dep[u] + dep[v] - 2 * dep[LCA (u, v)];
    }


    bool inSubtree (int root, int node) {
        return dfn[root] <= dfn[node] and dfn[node] <= r[root];
    }

    void addPath (int u, int v, int delta, int id) {
        while (head[u] != head[v]) {
            if (dep[head[u]] > dep[head[v]])swap (u, v);
            tree.update (dfn[head[v]], dfn[v], 1, delta, id);
            v = fa[head[v]];
        }
        if (dep[v] > dep[u])swap (u, v);
        tree.update (dfn[v] + 1, dfn[u], 1, delta, id);
    }


    void solve () {
        REP(i, 1, n) {
            cin>>u[i]>>v[i];
            addPath (u[i], v[i], 1, i);
        }

        REP(i, 1, n) {
            int res = tree.gao (1);
            dbg(res);
            if (res == -1) {
                cout<<"NO";
                return;
            } else {
                vis[res] = 1;
                addPath (u[res], v[res], -1, 0);
                tree.clean (1);
            }
        }
        cout<<"YES"<<endl;
    }
}

