pii swp(pii x){ if (x.first < x.second) return x; else return pii(x.second, x.first); }

void insG(int G, int u, int v){
	pii e = swp(pii(u, v));

	c[u].insert(pip(G, e));
	c[v].insert(pip(G, e));

	if (eG[1 - G].count(e)) eB.insert(e);
	eG[G].insert(e);
}

void ersG(int G, int u, int v){
	pii e = swp(pii(u, v));

	c[u].erase(pip(G, e));
	c[v].erase(pip(G, e));

	eB.erase(e);
	eG[G].erase(e);
}

int findpar(int u){ return (p[u] == u ? u : p[u] = findpar(p[u])); }

void mrg(int u, int v){
	u = findpar(u), v = findpar(v);
	if (c[v].size() > c[u].size()) swap(u, v);
	p[v] = u;

	while(c[v].size()){
		pip e = *c[v].begin();
		ersG(e.first, e.second.first, e.second.second);
		if (e.second.first == v) e.second.first = u;
		if (e.second.second == v) e.second.second = u;
		insG(e.first, e.second.first, e.second.second);
	}
}

