template<int NV> struct UF {
    int par[NV], cnt[NV];
    UF() { rep(i, 0, NV) par[i] = i, cnt[i] = 1; }
    int operator[](int x) { return par[x] == x ? x : par[x] = operator[](par[x]); }
    void operator()(int x, int y) { // xをyにくっつける
        x = operator[](x); y = operator[](y);
        if (x != y) par[x] = y, cnt[y] += cnt[x];
    }
};
int N;
