set<int> E[101010];
UF<101010> uf;
void merge(int a, int b) {
    //printf("[%d %d]\n", a, b);
    a = uf[a], b = uf[b];
    if (a == b) return;
    if (E[a].size() > E[b].size()) swap(a, b);

    set<pair<int, int>> next;

    for (int to : E[a]) if (to != b) {
        E[to].erase(a);
        if (E[to].count(b)) next.insert({ b, to });
        E[to].insert(b);
        E[b].insert(to);
    }
    E[b].erase(a);
    E[a].clear();

    uf(a, b);

    for (auto p : next) merge(p.first, p.second);
}
