inline void pu(int x)
{
	f[x].mi=min(f[x<<1].mi,f[x<<1|1].mi)+f[x].sz;
}

inline void modify(int x,int l,int r,int p)
{
	if(l==r){f[x].mi=19260817;}
	else
	{
		int t=(l+r)>>1;
		if(p<=t)modify(x<<1,l,t,p);
		else modify(x<<1|1,t+1,r,p);
		pu(x);
	}
}

inline void insert(int x,int l,int r,int ql,int qr,int v)
{
	if(l>=ql&&r<=qr){f[x].f.insert(v);f[x].sz++;f[x].mi++;return;}
	int t=(l+r)>>1;
	if(ql<=t)insert(x<<1,l,t,ql,qr,v);
	if(qr>t)insert(x<<1|1,t+1,r,ql,qr,v);
	pu(x);
}

inline void erase(int x,int l,int r,int ql,int qr,int v)
{
	if(l>=ql&&r<=qr){f[x].f.erase(v);f[x].sz--;f[x].mi--;return;}
	int t=(l+r)>>1;
	if(ql<=t)erase(x<<1,l,t,ql,qr,v);
	if(qr>t)erase(x<<1|1,t+1,r,ql,qr,v);
	pu(x);
}

inline pii query(int x,int l,int r)
{
	if(l==r)return mp(l,f[x].f.size()?*f[x].f.begin():0);
	int t=(l+r)>>1;
	pii v;
	if(f[x<<1].mi<f[x<<1|1].mi)v=query(x<<1,l,t);
	else v=query(x<<1|1,t+1,r);
	if(f[x].f.size())v.yy=*f[x].f.begin();
	return v;
}

