void dfs(int v, int p, int dep1, int dep2) {
	tin[v] = timer++;
	d1[v] = dep1;
	d2[v] = dep2;
	par[v][0] = p;
	FOR(i, 1, N) {
		par[v][i] = par[par[v][i - 1]][i - 1];
	}
	FOR(i, 0, g[v].size()) {
		int to = g[v][i];
		if (to != p) {
			int ndep1 = dep1 + 1;
			int ndep2 = dep2 + (c.find(mp(v,to))!= c.end());
			dfs(to, v, ndep1, ndep2);
		}
	}
	tout[v] = timer++;
}

inline bool isPar(int v1, int v2) {
	return ((tin[v1] <= tin[v2]) && (tout[v1] >= tout[v2]));
}

inline int lca(int v1, int v2) {
	if (isPar(v1, v2)) {
		return v1;
	}
	if (isPar(v2, v1)) {
		return v2;
	}
	int res = v1;
	for (int i = N - 1; i >= 0; --i) {
		if (!isPar(par[res][i], v2)) {
			res = par[res][i];
		}
	}
	return par[res][0];
}

bool ok = true;

int dfs2(int v, int p) {
	int res = -1;
	FOR(i, 0, t[v].size()) {
		if ((res == -1) || (isPar(t[v][i], res))) {
			res = t[v][i];
		}
	}
	FOR(i, 0, g[v].size()) {
		int to = g[v][i];
		if (to == p) {
			continue;
		}
		int val = dfs2(to, v);
		if ((val == -1) || (isPar(v, val))) {
			ok = false;
		}
		if ((res == -1) || (isPar(val, res))) {
			res = val;
		}
	}
	return res;
}

