inline int getf(int x) {
  return fa[x] ? fa[x] = getf(fa[x]) : x;
}

inline void Merge(int x, int y) {
  x = getf(x); y = getf(y);
  if (x == y) { puts("NO"); exit(0); }
  if (e[x].size() > e[y].size()) swap(x, y);
  fa[x] = y;
  int t;
  for (auto i : e[x]) {
    t = i.first;
    if (e[y].count(t) && e[y][t] != i.second) {
      a[++ top] = y; b[top] = t;
      e[y].erase(t);
      e[t].erase(y);
    }
    else {
      e[y][t] = i.second;
      e[t].erase(x);
      e[t][y] = i.second;
    }
  }
}

