		}
}
int LCA(int x,int y){
	int a=top[x],b=top[y];
	while (a!=b){
		if (dep[a]>dep[b]) swap(a,b),swap(x,y);
		y=fa[b],b=top[y];
	}
	return dep[x]<dep[y]?x:y;
}

int xo[N*4],plu[N*4];
pii mn[N*4];

void Plus(int x,int v){
	plu[x]+=v;
	mn[x].fi+=v;
}
void Down(int x){
	if (plu[x]){
		Plus(Lsn,plu[x]);
		Plus(Rsn,plu[x]);
		plu[x]=0;
	}
}
void Build(int x,int L,int R){
	if (L==R){
		mn[x]=mp(Sum[pt[L]],L);
		return;
	}
	Build(Lsn,L,Mid);
	Build(Rsn,Mid+1,R);
	mn[x]=min(mn[Lsn],mn[Rsn]);
}
void Change(int x,int L,int R,int Qx){
	if (L==R){
		mn[x]=mp(oo,0);
		return;
	}
	Down(x);
	Qx<=Mid?Change(Lsn,L,Mid,Qx):Change(Rsn,Mid+1,R,Qx);
	mn[x]=min(mn[Lsn],mn[Rsn]);
}
void Query(int x,int L,int R,int Qx){
	num^=xo[x];
	if (L==R) return;
	Qx<=Mid?Query(Lsn,L,Mid,Qx):Query(Rsn,Mid+1,R,Qx);
}
void Modify(int x,int L,int R){
	if (Ql<=L&&R<=Qr){
		Plus(x,-1);
		xo[x]^=num;
		return;
	}
	Down(x);
	if (Ql<=Mid) Modify(Lsn,L,Mid);
	if (Qr>Mid) Modify(Rsn,Mid+1,R);
	mn[x]=min(mn[Lsn],mn[Rsn]);
}
void gao(int x,int y){
	int a=top[x],b=top[y];
	while (a!=b){
		if (dep[a]>dep[b]) swap(a,b),swap(x,y);
		Ql=id[b],Qr=id[y];
		Modify(1,1,n);
		y=fa[b],b=top[y];
	}
	Ql=id[x],Qr=id[y];
	if (Ql>Qr) swap(Ql,Qr);
	if (++Ql<=Qr) Modify(1,1,n);
}

