const int Max_N(100050);

struct edge
{
	edge(const int &_u = 0, const int &_v = 0) : u(_u), v(_v) {}
	int u, v;
};

inline bool operator<(const edge &a, const edge &b)
{
	return a.u == b.u ? a.v < b.v : a.u < b.u;
}

int N, Father[Max_N];
map<int, int> To[Max_N];
map<edge, int> C;
set<edge> S;

int Get_Father(const int &x)
{
	return Father[x] == x ? x : Father[x] = Get_Father(Father[x]);
}

inline void insert(int u, int v)
{
	if (u == v)
		return;
	++To[u][v];
	++To[v][u];
	if (u > v)
		swap(u, v);
	if ((++C[edge(u, v)]) == 2)
		S.insert(edge(u, v));
}

inline void erase(int u, int v)
{
	if (u == v)
		return;
	if ((--To[u][v]) == 0)
		To[u].erase(v);
	if ((--To[v][u]) == 0)
		To[v].erase(u);
	if (u > v)
		swap(u, v);
	if ((--C[edge(u, v)]) == 1)
		S.erase(edge(u, v));
}

void init()
{
	Get_Val(N);
	for (int i = 1;i <= N;++i)
		Father[i] = i;
	for (int i = 1, u, v;i != N;++i)
		Get_Val(u), Get_Val(v), insert(u, v);
	for (int i = 1, u, v;i != N;++i)
		Get_Val(u), Get_Val(v), insert(u, v);
}

void work()
{
	for (int CNT = 1, u, v, p, t;CNT <= N - 1;++CNT)
	{
		if (S.empty())
		{
			printf("NO");
			return;
		}
		u = S.begin() -> u, v = S.begin() -> v;
		if (To[u].size() < To[v].size())
			swap(u, v);
		while (To[v].size())
		{
			p = To[v].begin() -> first;
			t = To[v].begin() -> second;
			for (int i = 1;i <= t;++i)
			{
				erase(v, p);
				insert(u, p);
			}
		}
	}
	printf("YES");
}

int main()
{
	init();
	work();
	return 0;
}

