#define mid ((lb+rb)>>1)
inline void _update(int rt,int lb,int rb,int l,int r,int x){
	if (lb>r||rb<l) return;
	if (lb>=l&&rb<=r) return (void)(sum[rt]++,tag[rt]++,seg[rt].push_back(x));
	pushdown(rt);
	_update(rt<<1,lb,mid,l,r,x),_update(rt<<1|1,mid+1,rb,l,r,x);
	pushup(rt);
}
inline void _clr(int rt,int lb,int rb,int l,int r){
	if (lb>r||rb<l) return;
	if (lb>=l&&rb<=r) return (void)(sum[rt]--,tag[rt]--);
	pushdown(rt);
	_clr(rt<<1,lb,mid,l,r),_clr(rt<<1|1,mid+1,rb,l,r);
	pushup(rt);
}
inline void del(int rt,int lb,int rb,int pos){
	if (lb==rb) return (void)(sum[rt]=0x3f3f3f3f);
	pushdown(rt);
	(mid>=pos?del(rt<<1,lb,mid,pos):del(rt<<1|1,mid+1,rb,pos));
	pushup(rt);
}
