struct UnionFind {
   vector<int> node;
   UnionFind(int n) : node(n,-1) {}
   bool unionSet(int x, int y) {
      x = root(x); 
      y = root(y);
      if (x != y) {
         if (node[y] < node[x]) swap(x, y);
         node[x] += node[y]; 
         node[y] = x;
      }
      return x != y;
   }
   bool findSet(int x, int y) {
      return root(x) == root(y);
   }
   int root(int x) {
      return node[x] < 0 ? x : node[x] = root(node[x]);
   }
   int size(int x) {
      return -node[root(x)];
   }
};

int main() {

	int N;
	cin >> N;

	set<int> G[100010];
	queue< pair<int,int> > que;
	UnionFind inst(100010);

	REP(i,N-1) {
		int a,b; cin >> a >> b;
		G[a].insert(b);
		G[b].insert(a);
	}

	REP(i,N-1) {
		int a,b; cin >> a >> b;
		if(G[a].find(b) != G[a].end()) que.push(make_pair(a,b));
		G[a].insert(b);
		G[b].insert(a);
	}

	int r = 0;
	while(que.size() != 0) {
		int a = que.front().first;
		int b = que.front().second;
		que.pop();
		if(inst.findSet(a,b)) continue;
		inst.unionSet(a,b);
		if(G[a].size() < G[b].size()) swap(a,b);
		for(auto x:G[b]) {
			if(G[x].find(a) != G[x].end()) {
				que.push(make_pair(x,a));
			} else {

				G[x].erase(b);
			}
			G[x].insert(a);
			G[a].insert(x);
		}
		G[a].insert(b);
		G[b].clear();
		r = a;
	}

	//for(int i=1; i<=N; i++) cout << G[i].size() << endl;
	if(G[r].size() == N) cout << "YES" << endl;
	else cout << "NO" << endl;

	return 0;
}

