void updr (int i, int x, int y) {
        mr.erase(mr.find(ar[i]));
        //printf("update %d %d, as %d changes to %d\n", ar[i].first, ar[i].second, x, y);
        if (ar[i].first == x) {
                ar[i].first = y;
        } else {
                assert(ar[i].second == x);
                ar[i].second = y;
        }
        fix(ar[i]);

        insert(mr, mb, ar[i]);
}

void updb (int i, int x, int y) {
        mb.erase(mb.find(ab[i]));
        if (ab[i].first == x) {
                ab[i].first = y;
        } else {
                assert(ab[i].second == x);
                ab[i].second = y;
        }
        fix(ab[i]);

        insert(mb, mr, ab[i]);
}

void merge (int a, int b) {
        //printf("merge %d %d\n", a, b);
        //for (int i : c[b].r) printf("%d has reds %d\n", b, i);
        //for (int i : c[b].b) printf("%d has blue %d\n", b, i);

        //merging based on r + b size
        int sza = (int) c[a].r.size() + (int) c[a].b.size();
        int szb = (int) c[b].r.size() + (int) c[b].b.size();
        if (sza > szb) swap(a, b);

        //merge nodes (commutative, so can swap)
        if (c[a].nodes.size() > c[b].nodes.size()) {
                swap(c[a].nodes, c[b].nodes);
        }
        for (int i : c[b].nodes) {
                c[a].nodes.PB(i);
                mycomp[i] = a;
        }
        c[b].nodes.clear();

        //merge reds
        for (int i : c[b].r) if (mycomp[ar[i].first] != mycomp[ar[i].second]) {
                //printf("red merge from comp %d to comp %d - %d %d\n", b, a, ar[i].first, ar[i].second);
                updr(i, b, a);
                c[a].r.PB(i);
        }
        c[b].r.clear();

        //merge blues
        for (int i : c[b].b) if (mycomp[ab[i].first] != mycomp[ab[i].second]) {
                //printf("blue merge from comp %d to comp %d - %d %d\n", b, a, ab[i].first, ab[i].second);
                updb(i, b, a);
                c[a].b.PB(i);
        }
        c[b].b.clear();
}

