using namespace std;
#define MAXN	100005
int num[MAXN];
multiset <int> a[MAXN];
int F(int x) {
	if (x == num[x]) return x;
	else return num[x] = F(num[x]);
}
int main() {
	int n; scanf("%d", &n);
	for (int i = 1; i <= n; i++)
		num[i] = i;
	for (int i = 1; i <= 2 * n - 2; i++) {
		int x, y;
		scanf("%d%d", &x, &y);
		a[x].insert(y);
		a[y].insert(x);
	}
	static int qx[MAXN], qy[MAXN];
	int l = 1, r = 0, ans = 0;
	for (int i = 1; i <= n; i++) {
		multiset <int> :: iterator j, k;
		for (j = a[i].begin(); j != a[i].end(); k = j, j++)
			if (j != a[i].begin() && *j == *k) {
				r++;
				qx[r] = i;
				qy[r] = *j;
			}
	}
	while (l <= r) {
		int tx = F(qx[l]);
		int ty = F(qy[l]);
		l++;
		if (tx == ty) continue;
		ans++;
		if (a[tx].size() > a[ty].size()) swap(tx, ty);
		num[tx] = ty;
		multiset <int> :: iterator j;
		int value;
		for (j = a[tx].begin(), value = *j; j != a[tx].end(); j++, value = *j) {
			if (value == ty) continue;
			a[value].erase(a[value].find(tx));
			a[value].insert(ty);
			if (a[value].count(ty) >= 2) {
				r++;
				qx[r] = value;
				qy[r] = ty;
			}
		}
		a[tx].clear();
	}
	if (ans == n - 1) cout << "YES" << endl;
	else cout << "NO" << endl;
	return 0;
}

