			possible[pose++] = i;
		} else if (ps[d][0] == c) {
			a[i] = ps[d].id(0);
			possible[pose++] = i;
		} else {
			for (int j = LG - 1; j >= 0; j--) {
				if (h[c] >= h[d] + (1 << j)) {
					advance(i, c, j);
				}
				if (h[d] >= h[c] + (1 << j)) {
					advance(i, d, j);
				}
			}
			if (c != d) {
				for (int j = LG - 1; j >= 0; j--) {
					if (ps[d][j] >= ps[c][j]) {
						advance(i, d, j);
						advance(i, c, j);
