struct Edge{int to, next;} edge[N * 42], edge0[N * 42];
int head[N], num, d[N], head0[N], num0;
map<int, bool> m[N], m0[N];
void add_edge(int a, int b) { edge[++ num] = (Edge){b, head[a]}, head[a] = num, m[a][b] = true; }
void add_edge0(int a, int b) { edge0[++ num0] = (Edge){a, head0[b]}, head0[b] = num0, m0[a][b] = true;}

int f[N];
int f_f(int x) { return f[x] == x ? x : f[x] = f_f(f[x]);}

pair<int, int> q[N];

int main()
{
	int n, a, b;
	scanf("%d", &n);
	Rep(i, n - 1) { 
		scanf("%d%d", &a, &b); 
		add_edge(a, b); add_edge(b, a); 
		d[a] ++, d[b] ++;
	}
	Rep(i, n - 1) { 
		scanf("%d%d", &a, &b); 
		add_edge0(a, b); add_edge0(b, a); 
		d[a] ++, d[b] ++;
	}
	int he = 0, ta = 0, cnt = 0;
	Rep(i, n) f[i] = i;

	Rep(i, n) RepG(j, i)if (m0[edge[j].to][i])
		q[++ ta] = mp(i, edge[j].to);

	while (he != ta) {
		int fx = f_f(q[++ he].first), fy = f_f(q[he].second);
		if (fx == fy) continue;
		cnt ++;
		if (d[fx] < d[fy]) swap(fx, fy);
		RepG0(i, fy){
			int fv = f_f(edge0[i].to);
			if (fv == fx || fv == fy) continue;
			if (m[fx][fv]) q[++ ta] = mp(fx, fv);
			add_edge0(fx, fv); add_edge0(fv, fx);
		}
		RepG(i, fy){
			int fv = f_f(edge[i].to);
			if (fv == fx || fv == fy) continue;
			if (m0[fx][fv]) q[++ ta] = mp(fx, fv);
			add_edge(fx, fv); add_edge(fv, fx);
		}
		f[fy] = fx, d[fx] += d[fy];
	}

	if (cnt == n - 1) printf("YES\n");
	else printf("NO\n");

	return 0;
}

