int n,fa[N],cnt;
queue<pi> q;
set<int> G1[N],G2[N];
int find_father(int x){
	if(fa[x]==x)
        return x;
	return fa[x]=find_father(fa[x]);
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
        fa[i]=i;
	for(int i=1;i<n;i++){
		int u,v;
		scanf("%d%d",&u,&v);
		G1[u].insert(v);
		G1[v].insert(u);
	}
	for(int i=1;i<n;i++){
		int u,v;
		scanf("%d%d",&u,&v);
		G2[u].insert(v);
		G2[v].insert(u);
		if(G1[u].find(v)!=G1[u].end())
            q.push(pi(u,v));
	}
	while(!q.empty()){
		int u=q.front().first,v=q.front().second;
		q.pop();
		u=find_father(u),v=find_father(v);
		if(u==v)
            continue;
		if(G1[u].size()+G2[u].size()>G1[v].size()+G2[v].size())
            swap(u,v);
		fa[u]=v;
		G1[u].erase(v);
		G1[v].erase(u);
		G2[u].erase(v);
		G2[v].erase(u);
		for(sit it=G1[u].begin();it!=G1[u].end();it++){
			int x=*it;
			G1[x].erase(u);
			G1[x].insert(v);
			G1[v].insert(x);
			if(G2[x].find(v)!=G2[x].end())
                q.push(pi(x,v));
		}
		for(sit it=G2[u].begin();it!=G2[u].end();it++){
			int x=*it;
			G2[x].erase(u);
			G2[x].insert(v);
			G2[v].insert(x);
			if(G1[x].find(v)!=G1[x].end())
                q.push(pi(x,v));
		}
	}
	int cnt=0;
	for(int i=1;i<=n;i++)
		if(find_father(i)==i)
            cnt++;
	puts(cnt==1?"YES":"NO");
}

