const int N = 1 << 17, INF = 0x3f3f3f3f;

int n, c[N], d[N];
std::vector<int> adj[N];

int fa[N], dep[N], size[N], son[N], top[N], left[N], right[N], val[N];

void dfs(int a) {
  size[a] = 1;
  for (auto b : adj[a]) {
    if (b == fa[a]) continue;
    fa[b] = a;
    dep[b] = dep[a] + 1;
    dfs(b);
    size[a] += size[b];
    if (size[b] > size[son[a]]) son[a] = b;
  }
}

void split(int a, int t) {
  static int tot = 0;
  left[a] = ++tot;
  val[tot] = a;
  top[a] = t;
  if (son[a]) split(son[a], t);
  for (auto b : adj[a]) if (b != fa[a] && b != son[a]) split(b, b);
  right[a] = tot;
}

class {
  std::pair<int, int> min[N << 1];
  int tag[N << 1];
  void update(int id) {
    min[id] = std::min(min[id << 1], min[id << 1 | 1]);
    min[id].first += tag[id];
  }
 public:
  void init() {
    for (int i = 0; i < N; ++i) min[N + i] = {INF, INF};
    for (int i = 2; i <= n; ++i) min[N + i] = {0, val[i]};
    for (int i = N - 1; i > 0; --i) update(i);
  }
  void add(int l, int r, int v) {
    int p = l, q = r;
    for (l = l + N - 1, r = r + N + 1; l ^ r ^ 1; l >>= 1, r >>= 1) {
      if (!(l & 1)) tag[l + 1] += v, min[l + 1].first += v;
      if (r & 1) tag[r - 1] += v, min[r - 1].first += v;
    }
    for (p += N; p >>= 1;) update(p);
    for (q += N; q >>= 1;) update(q);
  }
  inline std::pair<int, int> query() const { return min[1]; }
} seg;

bool flag[N];

void add(int x, int y, int z) {
  for (; top[x] != top[y]; x = fa[top[x]]) {
    if (dep[top[x]] < dep[top[y]]) std::swap(x, y);
    seg.add(left[top[x]], left[x], z);
  }
  if (x == y) return;
  if (dep[x] > dep[y]) std::swap(x, y);
  seg.add(left[son[x]], left[y], z);
}

std::deque<std::pair<int, int>> pool[2 * N];

inline int pos(int l, int r) { return (l + r) | (l != r); }

void build(int l, int r) {
  int id = pos(l, r);
  if (l == r) {
    std::sort(pool[id].begin(), pool[id].end());
    return;
  }
  int mid = (l + r) >> 1, lch = pos(l, mid), rch = pos(mid + 1, r);
  build(l, mid);
  build(mid + 1, r);
  std::merge(pool[lch].begin(), pool[lch].end(), pool[rch].begin(), pool[rch].end(), std::back_inserter(pool[id]));
}

int query(int l, int r, int p, int q, int u, int v) {
  int id = pos(l, r);
  if (p <= l && r <= q) {
    while (!pool[id].empty() && flag[pool[id].front().second]) pool[id].pop_front();
    while (!pool[id].empty() && flag[pool[id].back().second]) pool[id].pop_back();
    if (!pool[id].empty() && pool[id].front().first <= u) {
      int res = pool[id].front().second;
      pool[id].pop_front();
      return res;
    }
    if (!pool[id].empty() && pool[id].back().first >= v) {
      int res = pool[id].back().second;
      pool[id].pop_back();
      return res;
    }
    return 0;
  }
  int mid = (l + r) >> 1, res = 0;
  if (p <= mid) res = query(l, mid, p, q, u, v);
  if (!res && q > mid) res = query(mid + 1, r, p, q, u, v);
  return res;
}

int main() {
  scanf("%d", &n);
  for (int i = n - 1; i--;) {
    int a, b;
    scanf("%d%d", &a, &b);
    adj[a].push_back(b);
    adj[b].push_back(a);
  }
  dep[1] = 1;
  dfs(1);
  split(1, 1);
  seg.init();
  for (int i = 1; i < n; ++i) scanf("%d%d", &c[i], &d[i]), add(c[i], d[i], 1);
  for (int i = 1; i < n; ++i) {
    int x = left[c[i]], y = left[d[i]];
    pool[pos(x, x)].emplace_back(y, i);
    pool[pos(y, y)].emplace_back(x, i);
  }
  build(1, n);
  for (int i = n - 1; i--;) {
    int x, y;
    std::tie(x, y) = seg.query();
    if (x != 1) return puts("NO"), 0;
    seg.add(left[y], left[y], INF);
    int z = query(1, n, left[y], right[y], left[fa[y]], right[fa[y]]);
    add(c[z], d[z], -1);
    flag[z] = true;
  }
  puts("YES");
  return 0;
}

