        int a = edge.first, b = edge.second;

        if(T[a].size() + G[a].size() > T[b].size() + G[b].size())
            swap(a, b);

        vector<pair<int, int>> check;

        for(auto node : T[a]) {
            if(node != b) {
                T[b].insert(node);
                T[node].insert(b);
                T[node].erase(a);
                check.push_back(make_pair(min(b, node), max(b, node)));
            }
        }

        for(auto node : G[a]) {
            if(node != b) {
                G[b].insert(node);
                G[node].insert(b);
                G[node].erase(a);
                check.push_back(make_pair(min(b, node), max(b, node)));
            }
        }

        T[b].erase(a);
        G[b].erase(a);

        T[a].clear();
        G[a].clear();

        for(auto temp : check) {
            int x = temp.first;
            int y = temp.second;
            if(G[x].find(y) != G[x].end() and T[x].find(y) != T[x].end()) {
                if(seen.find(temp) == seen.end()) {
                    Q.push(temp);
                    seen.insert(temp);
                }
            }
        }
    }

    if(many == n - 1) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }    
}

