class Dsu {
  public:
    void Join(int a, int b) {
        if (!zero_based) {
            a--;
            b--;
        }
        a = WhichGroup_(a);
        b = WhichGroup_(b);
        if (a == b) {
            // Already in the same group
            return;
        }
        if (sizes[a] > sizes[b]) {
            // After this we can assume sizes[a] <= sizes[b]
            swap(a, b);
        }
        // Joining a in b
        sizes[b] += sizes[a];
        ancestor[a] = b;
        groups_number--;
    }

    bool SameGroup(int a, int b) const {
        if (!zero_based) {
            a--;
            b--;
        }
        return WhichGroup_(a) == WhichGroup_(b);
    }

    // The function WhichGroup most likely should not be among the public API.
    // It is not really meaningful and is implementation-dependent.
    // At the same time, if someone wants to modify the algorithm, it might be
    // handy.
    int WhichGroup(int a) const {
        if (!zero_based) a--;
        return WhichGroup_(a) + (!zero_based);
    }

    int GroupSize(int a) const {
        if (!zero_based) a--;
        return sizes[WhichGroup_(a)];
    }

    int GroupsNumber() const {
        return groups_number;
    }

    Dsu(int set_size, bool zero_based = true) :
        ancestor(set_size),
        sizes(set_size),
        zero_based(zero_based),
        groups_number(set_size) {
        for (int i = 0; i < set_size; i++) {
            ancestor[i] = i;
            sizes[i] = 1;
        }
    }
  private:
    mutable vector<int> ancestor; // This is not always the root of the respective tree.
    vector<int> sizes; // This is correct only for indexes that are roots.
    bool zero_based;
    int groups_number;

    int WhichGroup_(int a) const {
        if (ancestor[a] != a) {
            ancestor[a] = WhichGroup_(ancestor[a]);
        }
        return ancestor[a];
    }
};

