			return nxt[o];
		}
		int mid=(l+r)/2;
		int ans=nxt[o];
		if (mn[o]==mn[o*2]+tag[o])
			ans^=pop(o*2,l,mid);
		else ans^=pop(o*2+1,mid+1,r);
		pu(o);
