namespace seg
{
	int tag[N << 2];
	pii num[N << 2];

	int L(int i){ return i << 1; }
	int R(int i){ return (i << 1) | 1; }

	void pull(int i)
	{
		num[i] = min(num[L(i)], num[R(i)]);
		return;
	}

	void push(int i)
	{
		if(tag[i])
		{
			int l = L(i), r = R(i);
			tag[l] += tag[i], tag[r] += tag[i];
			num[l].X += tag[i], num[r].X += tag[i];
			tag[i] = 0;
		}
		return;
	}

	void M(int a, int b, int x, int l = 1, int r = n, int k = 1)
	{
		if(a == l && b == r)
		{
			num[k].X += x;
			tag[k] += x;
			return;
		}

		int mid = l + r >> 1; push(k);
		if(a > mid) M(a, b, x, mid + 1, r, R(k));
		else if(b <= mid) M(a, b, x, l, mid, L(k));
		else M(a, mid, x, l, mid, L(k)), M(mid + 1, b, x, mid + 1, r, R(k));
		return pull(k);
	}

	pii Q()
	{
		return num[1];
	}

	void B(int *a, int l = 1, int r = n, int k = 1)
	{
		tag[k] = 0;
		if(l == r)
		{
			num[k] = {a[l], l};
			return;
		}

		int mid = l + r >> 1;
		B(a, l, mid, L(k)); B(a, mid + 1, r, R(k));
		return pull(k);
	}

	void out(int l = 1, int r = n, int k = 1, int tab = 1)
	{
		if(l == r)
		{
			rep(i, tab) putchar('\t'); printf("[%d, %d]:\t{%d, %d} %d\n", l, r, num[k].X, num[k].Y, tag[k]);
			return;
		}
		int mid = l + r >> 1;
		out(l, mid, L(k), tab + 1);
		rep(i, tab) putchar('\t'); printf("[%d, %d]:\t{%d, %d} %d\n", l, r, num[k].X, num[k].Y, tag[k]);
		out(mid + 1, r, R(k), tab + 1);
		return;
	}
