		while (1){
			if (q.empty()){puts("NO"); return 0;}
			int x=q.front().first,y=q.front().second; q.pop();
			if (!mp[x][y]) continue;
			if (s[x].size()<s[y].size()) swap(x,y);
			for (int i:s[y]){
				mp[y][i]=mp[i][y]=0;
				s[i].erase(s[i].find(y));
				ins(i,x);
			}
			break;
		}
	}
	puts("YES");

	return 0;
}

