struct Node{
	int l,r,mn,pos,bj;
}T[maxn<<2];

void pushdown(int i){
	int x=T[i].bj;T[i].bj=0;
	T[i<<1].mn+=x;T[i<<1].bj+=x;
	T[i<<1|1].mn+=x;T[i<<1|1].bj+=x;
}

void pushup(int i){
	if(T[i<<1].mn<T[i<<1|1].mn)T[i].mn=T[i<<1].mn,T[i].pos=T[i<<1].pos;else T[i].mn=T[i<<1|1].mn,T[i].pos=T[i<<1|1].pos;
}

void build(int i,int l,int r){
	T[i].l=l;T[i].r=r;
	if(T[i].l==T[i].r){
		T[i].pos=l;
		return;
	}
	int M=l+r>>1;
	build(i<<1,l,M);build(i<<1|1,M+1,r);
	pushup(i);
}

void add(int i,int l,int r,int val){
	if(l<=T[i].l&&T[i].r<=r){
		T[i].mn+=val;T[i].bj+=val;
		return;
	}
	pushdown(i);
	int M=T[i].l+T[i].r>>1;
	if(l<=M)add(i<<1,l,r,val);if(r>M)add(i<<1|1,l,r,val);
	pushup(i);
}

void add2(int u,int v,int id,int val){
	while(an[u]!=an[v]){
		if(dep[an[u]]>dep[an[v]])swap(u,v);
		add(1,l[an[v]],l[v],val);
		add(l[an[v]],id);add(l[v]+1,id);
		v=fa[an[v]];
	}
	if(l[u]>l[v])swap(u,v);
	if(l[u]<l[v]){
		add(1,l[u]+1,l[v],val);
		add(l[u]+1,id);add(l[v]+1,id);
	}
}

