#define PB push_back
#define MP make_pair
#define sz(v) (in((v).size()))
#define forn(i,n) for(in i=0;i<(n);++i)
#define forv(i,v) forn(i,sz(v))
#define fors(i,s) for(auto i=(s).begin();i!=(s).end();++i)
#define all(v) (v).begin(),(v).end()
using namespace std;
typedef int in;
typedef vector<in> VI;
typedef vector<VI> VVI;
in n;
vector<set<in> > bleg,rdeg;
set<pair<in,in> > totegbl,totegrd;
queue<pair<in,in> > gdeg;
void adbl(in a, in b){
  assert(a!=b);
  if(a>b)
    swap(a,b);
  bleg[a].insert(b);
  bleg[b].insert(a);
  totegbl.insert(MP(a,b));
  if(totegrd.count(MP(a,b))){
    gdeg.push(MP(a,b));
  }
}
void adrd(in a, in b){
  assert(a!=b);
  if(a>b)
    swap(a,b);
  rdeg[a].insert(b);
  rdeg[b].insert(a);
  totegrd.insert(MP(a,b));
  if(totegbl.count(MP(a,b))){
    gdeg.push(MP(a,b));
  }
}
void erasebl(in a, in b){
  assert(a!=b);
  if(a>b)
    swap(a,b);
  bleg[a].erase(b);
  bleg[b].erase(a);
  totegbl.erase(MP(a,b));
}
void eraserd(in a, in b){
  assert(a!=b);
  if(a>b)
    swap(a,b);
  rdeg[a].erase(b);
  rdeg[b].erase(a);
  totegrd.erase(MP(a,b));
}
int main(){
  ios::sync_with_stdio(0);
  cin.tie(0);
  cin>>n;
  bleg.resize(n);
  rdeg.resize(n);
  in ta,tb;
  forn(z,n-1){
    cin>>ta>>tb;
    adbl(ta-1,tb-1);
  }
  forn(z,n-1){
    cin>>ta>>tb;
    adrd(ta-1,tb-1);
  }
  in gfd=0;
  pair<in,in> eg;
  in a,b;
  VI te;
  while(!gdeg.empty()){
    eg=gdeg.front();
    gdeg.pop();
    if(!totegrd.count(eg) || !totegbl.count(eg))
      continue;
    ++gfd;
    tie(a,b)=eg;
    if(sz(bleg[a])+sz(rdeg[a])<sz(bleg[b])+sz(rdeg[b]))
      swap(a,b);
    erasebl(a,b);
    eraserd(a,b);
    te.clear();
    fors(i,bleg[b]){
      te.PB(*i);
    }
    forv(i,te){
      erasebl(b,te[i]);
      adbl(a,te[i]);
    }
    te.clear();
    fors(i,rdeg[b]){
      te.PB(*i);
    }
    forv(i,te){
      eraserd(b,te[i]);
      adrd(a,te[i]);
    }
  }
  if(gfd==n-1)
    cout<<"YES"<<endl;
  else
    cout<<"NO"<<endl;
  return 0;
}

