void solve()
{
	int m = 0;
	while(!que.empty())
	{
		int x = que.front().first, y = que.front().second;
		que.pop();
		if(edg_cnt[make_pair(x, y)] < 2) continue;
		// cerr << x << ' ' << y << endl;
		m++;
		if(edg[x].size() < edg[y].size())
			swap(x, y);
		for(int i = 0; i < edg[y].size(); i++)
		{
			int z = edg[y][i];
			if(z == x) continue;
			edg[x].push_back(z);
			edg_cnt[make_pair(x, z)]++, edg_cnt[make_pair(y, z)]--;
			edg_cnt[make_pair(z, x)]++, edg_cnt[make_pair(z, y)]--;
			if(edg_cnt[make_pair(x, z)] == 2)
				que.push(make_pair(x, z));
		}
		edg[y].clear();
	}
	if(m == n - 1)
		yes();
	else
		no();
}

