namespace seg
{
	int tag[N << 2];
	pii num[N << 2];

	int L(int i){ return i << 1; }
	int R(int i){ return (i << 1) | 1; }

	void out(int l = 1, int r = n, int k = 1, int tab = 1)
	{
		if(l == r)
		{
			rep(i, tab) putchar('\t'); printf("[%d, %d]:\t{%d, %d} %d\n", l, r, num[k].X, num[k].Y, tag[k]);
		}
		else
		{
			int mid = l + r >> 1;
			out(l, mid, L(k), tab + 1);
			rep(i, tab) putchar('\t'); printf("[%d, %d]:\t{%d, %d} %d\n", l, r, num[k].X, num[k].Y, tag[k]);
			out(mid + 1, r, R(k), tab + 1);
		}
		return;
	}

	void pull(int i)
	{
		int l = L(i), r = R(i);
		if(!num[l].X) num[i] = num[r];
		else if(!num[r].X) num[i] = num[l];
		else num[i] = min(num[l], num[r]);
		return;
	}

	void push(int i)
	{
		if(tag[i])
		{
			int l = L(i), r = R(i);
			tag[l] += tag[i]; tag[r] += tag[i];
			num[l].X += tag[i]; num[r].X += tag[i];
			tag[i] = 0;
		}
		return;
	}

	void M(int a, int b, int x, int l = 1, int r = n, int k = 1)
	{
		if(a == l && b == r)
		{
			num[k].X += x;
			tag[k] += x;

			if(l < r)
			{
				push(k);
				pull(k);
			}
			return;
		}

		int mid = l + r >> 1; push(k);
		if(a > mid) M(a, b, x, mid + 1, r, R(k));
		else if(b <= mid) M(a, b, x, l, mid, L(k));
		else M(a, mid, x, l, mid, L(k)), M(mid + 1, b, x, mid + 1, r, R(k));
		return pull(k);
	}

	void B(int l = 1, int r = n, int k = 1)
	{
		if(l == r)
		{
			num[k] = {0, l};
			return;
		}

		int mid = l + r >> 1;
		B(l, mid, L(k));
		B(mid + 1, r, R(k));
		return pull(k);
	}

	pii Q()
	{
		return num[1];
	}
}

