		printf("M(%d, %d, -1)\n", dfn[anc[u]], dfn[u]);
#endif
		seg::M(dfn[anc[u]], dfn[u], -1);
		u = par[anc[u]];
	}

	if(dep[u] < dep[v]) swap(u, v);
	if(u != v)
	{
#ifdef DEBUG
		printf("M(%d, %d, -1)\n", dfn[v] + 1, dfn[u]);
