int find(int x)
{
	if (x == fa[x])
		return x;
	return fa[x] = find(fa[x]);
}

inline void addEdge(int u, int v)
{
	Adj[u].insert(v), Adj[v].insert(u);
	if (u > v)
		swap(u, v);
	if (++edgeCnt[make_pair(u, v)] == 2)
		dualEdges.emplace(u, v);
}

