			if (dualEdges.empty())
			{
				puts("NO");
				return 0;
			}
			tie(x, y) = dualEdges.front();
			dualEdges.pop();
			x = find(x), y = find(y);
		} while (x == y);

		if (Adj[x].size() > Adj[y].size())
			swap(x, y);
		fa[x] = y, Adj[x].erase(y), Adj[y].erase(x);
