int MINV[N<<2],lazy[N<<2],pos[N<<2];
set<int> S[N<<2];
#define L o<<1
#define R o<<1|1
void Down(int o,int v) {
  MINV[o]+=v; lazy[o]+=v;
}
void Pushup(int o) {
  MINV[o]=min(MINV[L],MINV[R]);
  if(MINV[L]<MINV[R]) pos[o]=pos[L];
  else pos[o]=pos[R];
}
void Pushdown(int o) {
  if(lazy[o]) {
    Down(L,lazy[o]); Down(R,lazy[o]);
    lazy[o]=0;
  }
}
void Build(int l,int r,int o) {
  pos[o]=l;
  if(l==r) {
    if(l==1) MINV[o]=2e9;
    return;
  }
  int mid=l+r>>1;
  Build(l,mid,L); Build(mid+1,r,R);
}
void Modify(int l,int r,int o,int ql,int qr,int v,int id) {
  if(ql<=l&&r<=qr) {
    if(v>0) S[o].insert(id);
    else S[o].erase(S[o].find(id));
    return Down(o,v);
  }
  Pushdown(o);
  int mid=l+r>>1;
  if(ql<=mid) Modify(l,mid,L,ql,qr,v,id);
  if(qr>mid) Modify(mid+1,r,R,ql,qr,v,id);
  Pushup(o);
}
int Get(int l,int r,int o,int pos) {
  if(S[o].size()) return *S[o].begin();
  Pushdown(o);
  int mid=l+r>>1,t;
  if(pos<=mid) t=Get(l,mid,L,pos);
  else t=Get(mid+1,r,R,pos);
  Pushup(o);
  return t;
}
void Inf(int l,int r,int o,int pos) {
  if(l==r) {
    MINV[o]=2e9;
    return;
  }
  Pushdown(o);
  int mid=l+r>>1;
  if(pos<=mid) Inf(l,mid,L,pos);
  else Inf(mid+1,r,R,pos);
  Pushup(o);
}
void Change(int u,int v,int val,int id) {
  while(top[u]!=top[v]) {
    if(dep[top[u]]<dep[top[v]]) swap(u,v);
    Modify(1,n,1,dfn[top[u]],dfn[u],val,id);
    u=fa[top[u]];
  }
  if(u==v) return;
  if(dep[u]>dep[v]) swap(u,v);
  Modify(1,n,1,dfn[u]+1,dfn[v],val,id);
}
