void dfs1(int num,int fath)
{	fa[num]=fath;dep[num]=dep[fath]+1;
	int x,maxx=0;now++;size[num]=1;
	id[num]=now;ip[now]=num;
	for(int i=head[num];i;i=a[i].next)
	{	x=a[i].to;
		if(x!=fath)
		{	dfs1(x,num);
			if(size[x]>maxx)
			{	maxx=size[x];son[num]=x;}
			size[num]+=size[x];
		}
	}
}
void dfs2(int num,int tt)
{	top[num]=tt;
	if(son[num]) dfs2(son[num],tt);
	else return;
	int x;
	for(int i=head[num];i;i=a[i].next)
	{	x=a[i].to;
		if(x!=fa[num]&&x!=son[num])
		dfs2(x,x);
	}
}
void build(int l,int r)
{	now++;
	if(l==r) return;
	int x=now,mid=(l+r)>>1;
	build(l,mid);
	f[x].rc=now+1;
	build(mid+1,r);
}
void down(int num)
{	int x=num+1,y=f[num].rc,xx=f[num].lazy1,yy=f[num].lazy2;
	if(!xx&&!yy) return;
	f[x].minn+=xx;f[y].minn+=xx;
	f[x].lazy1+=xx;f[y].lazy1+=xx;
	f[x].vi^=yy;f[y].vi^=yy;
	f[x].lazy2^=yy;f[y].lazy2^=yy;
	f[num].lazy1=f[num].lazy2=0;
}
void update(int num)
{	int x=num+1,y=f[num].rc;
	if(f[x].minn<=f[y].minn)
	{	f[num].minn=f[x].minn;
		f[num].vi=f[x].vi;
	}
	else
	{	f[num].minn=f[y].minn;
		f[num].vi=f[y].vi;
	}
}
void modify(int num,int l,int r,int ll,int rr,int vi1,int vi2)
{	int mid=(l+r)>>1;
	if(l>=ll&&r<=rr)
	{	f[num].minn+=vi1;f[num].vi^=vi2;
		if(f[num].minn==0)
		{	if(l==r)
			{	f[num].minn=N;return;}
			down(num);modify(num+1,l,mid,ll,rr,vi1,vi2);
			modify(f[num].rc,mid+1,r,ll,rr,vi1,vi2);
			update(num);
		}
		else
		{ f[num].lazy1+=vi1;f[num].lazy2^=vi2;}
		return;
	}
	down(num);
	if(rr<=mid) modify(num+1,l,mid,ll,rr,vi1,vi2);
	else if(ll>mid) modify(f[num].rc,mid+1,r,ll,rr,vi1,vi2);
	else { modify(num+1,l,mid,ll,rr,vi1,vi2);modify(f[num].rc,mid+1,r,ll,rr,vi1,vi2);}
	update(num);
}
void add(int x,int y,int vi,int vi2)
{//	printf("add %d %d %d %d\n",x,y,vi,vi2);
	while(top[x]!=top[y])
	{	if(dep[top[x]]<dep[top[y]]) swap(x,y);
//		printf("1modify %d %d %d %d\n",id[top[x]],id[x],vi,vi2);
		modify(1,2,n,id[top[x]],id[x],vi,vi2);
		x=fa[top[x]];
	}
	if(x!=y)
	{	if(dep[x]<dep[y]) swap(x,y);
//		printf("modify %d %d %d %d\n",id[son[y]],id[x],vi,vi2);
		modify(1,2,n,id[son[y]],id[x],vi,vi2);
	}
}
