vector < int > G[MAXN];

inline void dfs(int x)
{
	size[ x ] = 1;
	for( auto y : G[ x ] ) if( y ^ fa[ x ] )
	{
		fa[ y ] = x;
		dep[ y ] = dep[ x ] + 1;
		dfs( y );
		size[ x ] += size[ y ];
	}
}

inline void dfs2(int x, int c)
{
	dfn[ x ] = ++tim; bl[ x ] = c;
	int k = 0;
	for( auto y : G[ x ] ) if( y ^ fa[ x ] ) if( size[ y ] > size[ k ] ) k = y;
	if( !k ) return ;
	dfs2( k, c );
	for( auto y : G[ x ] ) if( y ^ fa[ x ] ) if( y ^ k ) dfs2( y, y );
}

inline void pushup(int x) { mn[ x ] = min( mn[ x << 1 ], mn[ x << 1 | 1 ] ); mn[ x ].xx += S[ x ].size(); }

inline void build(int x, int l, int r)
{
	mn[ x ].yy = l;
	if( l == r ) return ;
	int mid = l + r >> 1;
	build( x << 1, l, mid ); build( x << 1 | 1, mid + 1, r );
}

inline void insert(int x, int l, int r, int ql, int qr, pa v)
{
	if( l == ql && r == qr ) { S[ x ].insert( v ); mn[ x ].xx++; return ; }
	int mid = l + r >> 1;
	if( qr <= mid ) insert( x << 1, l, mid, ql, qr, v );
	else if( ql > mid ) insert( x << 1 | 1, mid + 1, r, ql, qr, v );
	else insert( x << 1, l, mid, ql, mid, v ), insert( x << 1 | 1, mid + 1, r, mid + 1, qr, v );
	pushup( x );
}

inline void add(int x, int y)
{
	int tx = x, ty = y;
	while( bl[ tx ] ^ bl[ ty ] )
	{
		if( dep[ bl[ tx ] ] < dep[ bl[ ty ] ] ) swap( tx, ty );
		insert( 1, 2, n, dfn[ bl[ tx ] ], dfn[ tx ], mp( x, y ) );
		tx = fa[ bl[ tx ] ];
	}
	if( dfn[ tx ] > dfn[ ty ] ) swap( tx, ty );
	if( tx ^ ty ) insert( 1, 2, n, dfn[ tx ] + 1, dfn[ ty ], mp( x, y ) );
}

inline void erase(int x, int l, int r, int ql, int qr, pa v)
{
	if( l == ql && r == qr ) { S[ x ].erase( v ); mn[ x ].xx--; return ; }
	int mid = l + r >> 1;
	if( qr <= mid ) erase( x << 1, l, mid, ql, qr, v );
	else if( ql > mid ) erase( x << 1 | 1, mid + 1, r, ql, qr, v );
	else erase( x << 1, l, mid, ql, mid, v ), erase( x << 1 | 1, mid + 1, r, mid + 1, qr, v );
	pushup( x );
}

inline void del(int x, int y)
{
	int tx = x, ty = y;
	while( bl[ tx ] ^ bl[ ty ] )
	{
		if( dep[ bl[ tx ] ] < dep[ bl[ ty ] ] ) swap( tx, ty );
		erase( 1, 2, n, dfn[ bl[ tx ] ], dfn[ tx ], mp( x, y ) );
		tx = fa[ bl[ tx ] ];
	}
	if( dfn[ tx ] > dfn[ ty ] ) swap( tx, ty );
	if( tx ^ ty ) erase( 1, 2, n, dfn[ tx ] + 1, dfn[ ty ], mp( x, y ) );
}

inline void GG()
{
	puts( "NO" );
	exit( 0 );
}

inline pa query(int x, int l, int r, int p)
{
	if( S[ x ].size() ) return *S[ x ].begin();
	int mid = l + r >> 1;
	if( p <= mid ) return query( x << 1, l, mid, p );
	return query( x << 1 | 1, mid + 1, r, p );
}

inline void modify(int x, int l, int r, int p)
{
	if( l == r ) { mn[ x ].xx = INF; return ; }
	int mid = l + r >> 1;
	if( p <= mid ) modify( x << 1, l, mid, p );
	else modify( x << 1 | 1, mid + 1, r, p );
	pushup( x );
}

