	st2.erase({u, v});
}

inline int root (int v) { return par[v]; }

inline void merge (int u, int v)
{
	if ((u = root(u)) == (v = root(v))) return;

	if (_sz(vec[u]) < _sz(vec[v])) swap(u, v);

	for (int x : vec[v])
	{
		for (int y : g[x])
		{
			int z = root(y);

