			int value = *j;
			if (value == ty) continue;
			a[value].erase(a[value].find(tx));
			a[value].insert(ty);
			if (a[value].count(ty) >= 2) {
				qx.push(value);
				qy.push(ty);
			}
		}
		a[ty].erase(tx);
		a[tx].clear();
	}
	if (ans == n - 1) cout << "YES" << endl;
	else cout << "NO" << endl;
	return 0;
}

