	int u, v;
	lp ( i, 0, 2 * n - 2 ){
		scanf ( "%d%d", &u, &v );
		e[u].insert ( v ), e[v].insert ( u );
	}
}

void work ()
{
	// main work

	int l = 0, r = 0;

	lpi ( i, 1, n ){
		for ( auto x : e[i] ){
			if ( i < x && ( l == r || ( q[r-1] != MP ( i, x ) ) ) && e[i].count ( x ) == 2 ) q[r++] = MP ( i, x );
		}
	}

	lpi ( i, 1, n ) deg[i] = 1;

	int nu, nv;
	while ( l < r ){
		nu = q[l].first, nv = q[l].second, ++l;
//		cerr << nu << " " << nv << endl;

		if ( deg[nu] < deg[nv] ) swap ( nu, nv );

		for ( auto x : e[nv] ){
			if ( x ^ nu ){
				if ( e[nu].find ( x ) != e[nu].end () ) q[r++] = MP ( qmin ( nu, x ), qmax ( nu, x ) );
				e[nu].insert ( x );
				e[x].insert ( nu );
				e[x].erase ( nv );
			}
		}

		deg[nu] += deg[nv];
	}

	printf ( ( r == n - 1 ) ? "YES\n" : "NO\n" );
}

