int main()
{
    int N; cin >> N;

    auto queue = std::queue<pair<int, int>>();
    auto degrees = vector<int>(N);
    auto adjacency_list = vector<multiset<int>>(N);

    for (auto i = 0; i < 2*(N-1); i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;

        degrees[a]++;
        degrees[b]++;
        adjacency_list[a].insert(b);
        adjacency_list[b].insert(a);

        if (adjacency_list[a].count(b) == 2)
        {
            queue.push({a, b});
            adjacency_list[a].erase(b);
            adjacency_list[b].erase(a);
        }
    }

    auto representatives = vector<int>(N);
    iota(begin(representatives), end(representatives), 0);

    const function<int(int)> find = [&](const int i)
    {
        if (representatives[i] != i)
            representatives[i] = find(representatives[i]);
        return representatives[i];
    };

    auto size = N;
    while (!queue.empty())
    {
        int a, b; tie(a, b) = queue.front(); queue.pop();
        a = find(a); b = find(b);

        if (degrees[a] > degrees[b]) swap(a, b);

        degrees[b] += degrees[a];
        representatives[a] = b;

        for (const auto v : adjacency_list[a])
        {
            adjacency_list[v].erase(a);

            if (adjacency_list[b].count(v))
            {
                adjacency_list[b].erase(v);
                adjacency_list[v].erase(b);
                queue.push({b, v});
            }
            else
            {
                adjacency_list[b].insert(v);
                adjacency_list[v].insert(b);
            }
        }

        size--;
    }

    cout << (size == 1 ? "YES" : "NO") << endl;
}

