void insert(int x, int y) {
  if (x > y) swap(x, y);
  kotori res = {x, y};
  if (++ ct[res] == 2) {
    que.push(res);
  }
  mp.insert(res);
}

void erase(int x, int y) {
  if (x > y) swap(x, y);
  mp.erase({x, y});
}

int main(int argc, char const *argv[]) {
