      erase(x, to);
      insert(to, y);
      es[to].erase(x);
      es[to].insert(y);
      es[y].insert(to);
    }

  }

  int ans = 0;
  for (int i = 1; i <= n; ++ i) {
    ans += fa[i] == i;
  }

