set<int> mp2[maxn];
set<int> vis[maxn];

int main()
{
	scanf("%d", &n);
	for(int i = 1, f, t; i < n; ++i)
	{
		scanf("%d%d", &f, &t);
		mp[f].insert(t);
		mp[t].insert(f);
	}
	queue<pii> q;
	while(!q.empty())
		q.pop();
	for(int i = 1; i <= n; ++i)
	{
		fa[i] = i;
		siz[i] = 1;
	}
	for(int i = 1, f, t; i < n; ++i)
	{
		scanf("%d%d", &f, &t);
		mp2[f].insert(t);
		mp2[t].insert(f);
		if(mp[f].count(t))
		{
			vis[f].insert(t);
			q.push(make_pair(f, t));
		}
