		if(getfa(now.first) == getfa(now.second))
			continue;
		int fax = getfa(now.first);
		int fay = getfa(now.second);
		if(siz[fax] > siz[fay])
		{
			swap(fax, fay);
			swap(now.first, now.second);
		}
		siz[fay] += siz[fax];
		fa[fax] = fay;
		for(set<int>::iterator it = mp2[fax].begin(); it != mp2[fax].end(); ++it)
		{
			int noww = getfa(*it);
			if(noww != fax)
			{
				if(!mp2[fay].count(noww))
				{
					mp2[fay].insert(noww);
					mp2[*it].insert(fay);
				}
				if(!vis[fay].count(noww) && mp[fay].count(noww) && mp2[fay].count(noww))
				{
					vis[fay].insert(noww);
					vis[noww].insert(fay);
					q.push(make_pair(fay, noww));
				}
			}
		}
		for(set<int>::iterator it = mp[fax].begin(); it != mp[fax].end(); ++it)
		{
			int noww = getfa(*it);
			if(noww != fax)
			{
//			cout << "it = " << (*it) << endl;
				if(!mp[fay].count(noww))
				{
					mp[fay].insert(noww);
					mp[noww].insert(fay);
				}
				if(!vis[fay].count(noww) && mp[fay].count(noww) && mp2[fay].count(noww))
				{
					vis[fay].insert(noww);
					vis[*it].insert(fay);
					q.push(make_pair(fay, noww));
				}
			}
		}
	}
//	for(int i = 1; i <= n; ++i)
//		cout << fa[i] << ' ';
//	cout << endl;
	int now = fa[1];
	for(int i = 1; i <= n; ++i)
	{
		if(fa[i] != now)
		{
			puts("NO");
			return 0;
		}
	}
	puts("YES");
	return 0;
}

