const int maxn = 110000;
int par[maxn];
vector<pii> reles[maxn];
pii e[2][maxn];
set<pii> se[2];

int root(int x) {
    if (x == par[x]) return x;
    return par[x] = root(par[x]);
}

pii normp(int x, int y) {
    if (x > y) swap(x, y);
    return {x, y};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);
    cout << fixed;
#ifdef LOCAL_DEFINE
    freopen("input.txt", "rt", stdin);
