        int x, y;
        cin >> x >> y;
        --x; --y;
        pii p = normp(x, y);
        e[k][i] = p;
        se[k].insert(p);
        reles[x].pb({i, k});
        reles[y].pb({i, k});
    }

    vector<pii> q;
    for (auto w: se[0]) {
        if (se[1].count(w)) q.pb(w);
    }

    forn(cur, q.size()) {
        pii p = q[cur];
        int x = root(p.fi), y = root(p.se);
        if (x == y) continue;
        if (reles[x].size() > reles[y].size()) swap(x, y);
        par[x] = y;
        for (auto w: reles[x]) {
            int id = w.fi, k = w.se;
            se[k].erase(e[k][id]);
            e[k][id].fi = root(e[k][id].fi);
            e[k][id].se = root(e[k][id].se);
            e[k][id] = normp(e[k][id].fi, e[k][id].se);
            se[k].insert(e[k][id]);
            if (se[k ^ 1].count(e[k][id])) q.pb(e[k][id]);
            reles[y].pb(w);
        }
        reles[x].clear();
    }

    bool ok = true;
    forn(i, n) ok &= root(i) == root(0);
