typedef long long int64;
typedef pair<int, int> ii;
const int INF = 1 << 30;
const int MOD = 1e9 + 7;

const int N = 1e5 + 10;
vector<int> a[N];
int deg[N];
bool flag[N];

int main() {
  int n;
  scanf("%d", &n);
  map<ii, int> cnt;
  set<ii> A;
  for (int i = 0; i < 2 * (n - 1); ++i) {
    int x, y;
    scanf("%d%d", &x, &y);
    if (x > y) swap(x, y);
    --x; --y;
    deg[x]++;
    deg[y]++;
    if (++cnt[{x, y}] == 2) {
      A.insert({x, y});
    }
    a[x].push_back(y);
    a[y].push_back(x);
  }
  int k;
  for (k = 1; k < n; ++k) {
    int x, y;
    bool found = false;
    while (!A.empty()) {
      ii cur = *A.begin();
      A.erase(cur);
      x = cur.first, y = cur.second;
      if (!flag[x] && !flag[y]) {
        found = true;
        break;
      }
    }
    if (!found) break;
    if (deg[x] < deg[y]) swap(x, y);
    deg[x] += deg[y] - 2;
    flag[y] = true;
    for (auto& v : a[y]) {
      if (v == x || flag[v]) continue;
      a[x].push_back(v);
      int s = min(x, v), t = max(x, v);
      if (++cnt[{s, t}] == 2) {
        A.insert({s, t});
      }
    }
  }
  puts(k == n ? "YES" : "NO");
  return 0;
}

