multiset<int> edge[Nmax];
bool active[Nmax];

int main()
{
    //freopen("input", "r", stdin);
    cin.sync_with_stdio(false);

    cin >> n;
    for(i=1; i<=2*(n-1); ++i)
    {
        cin >> x >> y;
        edge[x].insert(y);
        edge[y].insert(x);

        if(edge[x].count(y) == 2)
        {
            q.push({x,y});
            edge[x].erase(y);
            edge[y].erase(x);
        }
    }

    for(i=1; i<=n; ++i) iset[i] = 1, active[i] = 1;

    while(!q.empty())
    {
        x = q.front().first;
        y = q.front().second;
        q.pop();
        if(!active[x] || !active[y]) continue;

        ++cnt;
        if(edge[x].size() > edge[y].size()) swap(x, y);
