map<pi,int>ap;
int fa[100010];
inline int findfa(int x)
{
	if(fa[x]!=x)fa[x]=findfa(fa[x]);
	return fa[x];
}
inline pi make(int x,int y){if(x>y)swap(x,y);return mp(x,y);}
inline void ins(int x,int y)
{
	p[x].insert(y);p[y].insert(x);
	pi uf=make(x,y);ap[uf]++;
	if(ap[uf]==2)q.push(uf);
}
inline void del(int x,int y){ap.erase(mp(x,y)),p[y].erase(x);}
