void solve(){
	int n, a, b;
	scanf("%d", &n);
	REP(i, 0, 2 * (n - 1)) {
		scanf("%d%d", &a, &b);
		g[a][b]++;
		g[b][a]++;
	}
	REPN(i, 1, n) {
		FA(it, g[i]) {
			if (it->_1 > i && it->_2 > 1) {
				st.insert(mp(i, it->_1));

				//printf("+ %d %d\n", i, it->_1);
			}
		}
		sz[i] = 1;
	}
	int cnt = 0;
	while(!st.empty()) {
		a = st.begin()->_1;
		b = st.begin()->_2;
		st.erase(st.begin());

		//printf("- %d %d\n", a, b);

		cnt++;
		if (sz[a] < sz[b]) {
			swap(a, b);
		}

		sz[a] += sz[b];

		g[b].erase(a);
		g[a].erase(b);

		FA(it, g[b]) {
			int to = it->_1;
			int d = it->_2;

			g[to].erase(b);

			int mn = min(b, to);
			int mx = b + to - mn;
			if (st.find(mp(mn, mx)) != st.end()) {
				st.erase(mp(mn, mx));
			}

			mn = min(a, to);
			mx = a + to - mn;

			if (g[a].find(to) == g[a].end() && d > 1 || g[a][to] == 1) {
				st.insert(mp(mn, mx));

				//printf("+ %d %d\n", mn, mx);
			}

			g[a][to] += d;
			g[to][a] += d;
		}

		g[b].clear();
	}
	if (cnt == n - 1) {
		printf("YES\n");
	} else {
		printf("NO\n");
	}
}   

