void merge(){
	int a = - 1 , b = -1;
	while(!q.empty()){
		a = comp[q.front().first];
		b = comp[q.front().second];
		q.pop();
		if(a != b){
			continue;
		}
	}
	if(a == -1){
		printf("NO\n");
		exit(0);
	}
	if(edges[a].size() > edges[b].size()){
		swap(a , b);
	}
	for(auto it : edges[a]){
		edges[it.first].erase(edges[it.first].find(a));
	}
	comp[a] = b;
	for(auto it : edges[a]){
		if(it.first == b){
			continue;
		}
		if(it.first == a){
			continue;
		}
		while(it.second--){
			insert(b , comp[it.first]);
		}
	}
	edges[a].clear();
}
