void pushup(int x){
     if(w[lc].z<w[rc].z) w[x]=w[lc];
     else w[x]=w[rc];
}
void build(int l,int r,int x){
     if(l==r){w[x].i=l,w[x].z=vis[l]?inf:0; return;}
     int mid=l+r>>1;
     build(l,mid,lc),build(mid+1,r,rc);
     pushup(x);
}
void update(int l,int r,int p,int q,int x,int y){
    if(p<=l&&r<=q){++lazy[x],++w[x].z,v[x]^=y; return;}
    pushdown(x);
    int mid=l+r>>1;
    if(p<=mid) update(l,mid,p,q,lc,y);
    if(q>mid) update(mid+1,r,p,q,rc,y);
    pushup(x);
}
void update2(int l,int r,int p,int x){
    if(l==r){w[x].z=inf; return;}
    pushdown(x);
    int mid=l+r>>1;
    if(p<=mid) update2(l,mid,p,lc);
    else update2(mid+1,r,p,rc);
    pushup(x);
}
void update3(int l,int r,int p,int q,int x,int y){
    if(p<=l&&r<=q){--lazy[x],--w[x].z,v[x]^=y; return;}
    pushdown(x);
    int mid=l+r>>1;
    if(p<=mid) update3(l,mid,p,q,lc,y);
    if(q>mid) update3(mid+1,r,p,q,rc,y);
    pushup(x);
}
int query(int l,int r,int p,int x){
    if(l==r) return v[x];
    int mid=l+r>>1;
    pushdown(x);
    if(p<=mid) return query(l,mid,p,lc);
    return query(mid+1,r,p,rc); 
}
