#include <bits/stdc++.h>

const int MAXN = 200010;
typedef std::pair<int, int> pi;
std::set<int> qry[MAXN], out[MAXN];
std::set<pi> S;
int n;
void chk(int x, int y) {
	if (x > y) std::swap(x, y); if (x == y) return ;
	if (out[x].count(y)) S.emplace(x, y);
}
void chk2(int x, int y) {
	if (x > y) std::swap(x, y); if (x == y) return ;
	if (qry[x].count(y)) S.emplace(x, y);
}
void del(int x, int y) {
	if (x > y) std::swap(x, y); if (x == y) return ;
	S.erase(pi(x, y));
}
int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	std::cin >> n;
	for (int i = 1, t1, t2; i < n; ++i)
		std::cin >> t1 >> t2, out[t1].insert(t2), out[t2].insert(t1);
	for (int i = 1, t1, t2; i < n; ++i) {
		std::cin >> t1 >> t2;
		qry[t1].insert(t2), qry[t2].insert(t1);
		chk(t1, t2);
	}
	int cnt = 0;
	while (!S.empty()) {
		pi t = *S.begin(); S.erase(S.begin()); ++cnt;
		int x = t.first, y = t.second;
		if (out[x].size() + qry[x].size() > out[y].size() + qry[y].size())
			std::swap(x, y);
		for (auto u : out[x]) {
			out[u].erase(x), del(u, x);
			if (u != y) out[u].insert(y), out[y].insert(u);
		}
		for (auto u : qry[x]) {
			qry[u].erase(x), del(u, x);
			if (u != y) qry[u].insert(y), qry[y].insert(u);
		}
		for (auto u : out[x]) chk2(u, y);
		for (auto u : qry[x]) chk(u, y);
		out[x].clear(), qry[x].clear();
	}
	std::cout << (cnt == n - 1 ? "YES" : "NO") << std::endl;
	return 0;
}

