		for (int v : adj[a])
		{
			adj[b].insert(v);
			adj[v].insert(b);
			if (b < v)
			{
				edgeCount[ii(b, v)]++;
				if (edgeCount[ii(b, v)] == 2) bfs.emplace(b, v);
