    return p[a] = get(p[a]);
}

int fnd(int tl, int tr, int x) {
    int l = tl - 1;
    int r = tr;
    while (r - l > 1) {
        int mid = (l + r) >> 1;
        if (vv[mid].second >= x)
            r = mid;
        else
            l = mid;
    }
    return r;
}

