using namespace std;

const int N = 200010;

struct Edge{int to, next;} edge[N * 42], edge0[N * 42];
int head[N], num, d[N], head0[N], num0;
map<int, bool> m[N], m0[N];
void add_edge(int a, int b) { edge[++ num] = (Edge){b, head[a]}, head[a] = num, m[a][b] = true; }
void add_edge0(int a, int b) { edge0[++ num0] = (Edge){a, head0[b]}, head0[b] = num0, m0[a][b] = true;}

int f[N];
int f_f(int x) { return f[x] == x ? x : f[x] = f_f(f[x]);}

