	Rep(i, n - 1) { 
		scanf("%d%d", &a, &b); 
		add_edge(a, b); add_edge(b, a); 
		d[a] ++, d[b] ++;
	}
	Rep(i, n - 1) { 
		scanf("%d%d", &a, &b); 
		add_edge0(a, b); add_edge0(b, a); 
		d[a] ++, d[b] ++;
	}
	int he = 0, ta = 0, cnt = 0;
	Rep(i, n) f[i] = i;

	Rep(i, n) RepG(j, i)if (m0[edge[j].to][i])
		q[++ ta] = mp(i, edge[j].to);

	while (he != ta) {
		int fx = f_f(q[++ he].first), fy = f_f(q[he].second);
