int up[LOG][MAXN];
vector<int> gg;
vector<pair<int, int> > vv;
pair<int, int> rmq[MAXN * 4];
int dd[MAXN * 4];
int h[MAXN];
int mn[MAXN];
int mx[MAXN];

int is_p(int a, int b) {
    return tin[a] <= tin[b] && tin[b] < tout[a];
}

int lca(int a, int b) {
    if (is_p(a, b))
        return a;
    for (int i = LOG - 1; i >= 0; --i) {
        if (!is_p(up[i][a], b))
            a = up[i][a];
    }
    return up[0][a];
}

void build(int v, int tl, int tr) {
    if (tl + 1 == tr) {
        int a = gg[vv[tl].first];
        int b = gg[vv[tl].second];
        int x = lca(a, b);
        rmq[v] = make_pair(h[a] + h[b] - 2 * h[x], tl);
        return;
    }
    int m = (tl + tr) >> 1;
    build(v * 2 + 1, tl, m);
    build(v * 2 + 2, m, tr);
    rmq[v] = min(rmq[v * 2 + 1], rmq[v * 2 + 2]);
}

void del(int v, int tl, int tr, int l, int r, int x) {
    if (r <= tl || tr <= l)
        return;
    if (l <= tl && tr <= r) {
        dd[v] += x;
        rmq[v].first += x;
        return;
    }
    int m = (tl + tr) >> 1;
    del(v * 2 + 1, tl, m, l, r, x);
    del(v * 2 + 2, m, tr, l, r, x);
    rmq[v] = min(rmq[v * 2 + 1], rmq[v * 2 + 2]);
    rmq[v].first += dd[v];
}

int tm;
vector<int> eds[MAXN];

void dfs1(int v) {
    was[v] = 1;
    tin[v] = tm++;
    gg.push_back(v);
    for (int u: eds[v]) {
        if (!was[u]) {
            pp[u] = v;
            h[u] = h[v] + 1;
            dfs1(u);
        }
    }
    tout[v] = tm;
}

int n;

bool cmp2(pair<int, int> a, pair<int, int> b) {
    return a.second < b.second;
}

int get(int a) {
    if (a == p[a])
        return a;
    return p[a] = get(p[a]);
}

int fnd(int tl, int tr, int x) {
    int l = tl - 1;
    int r = tr;
    while (r - l > 1) {
        int mid = (l + r) >> 1;
        if (vv[mid].second >= x)
            r = mid;
        else
            l = mid;
    }
    return r;
}

void upgrade(int v, int tl, int tr, int l, int r, int l1, int r1, int l2, int r2) {
    if (r <= tl || tr <= l)
        return;
    if (tl + 1 == tr) {
        if (vv[tl].first >= l1 && vv[tl].first < r1 && vv[tl].second >= l2 && vv[tl].second < r2) {
            --dd[v];
            --rmq[v].first;
        }
        return;
    }
    int m = (tl + tr) >> 1;
    upgrade(v * 2 + 1, tl, m, l, r, l1, r1, l2, r2);
    upgrade(v * 2 + 2, m, tr, l, r, l1, r1, l2, r2);
    rmq[v] = min(rmq[v * 2 + 1], rmq[v * 2 + 2]);
    rmq[v].first += dd[v];
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
