struct xd{int z,i;}w[N<<2];
void dfs(int x,int fa){
     f[x]=fa,d[x]=d[fa]+1,siz[x]=1; int maxt=0,maxa=-1;
     for(int i=head[x];i;i=e[i].nxt)
         if(e[i].to!=fa){
            dfs(e[i].to,x),siz[x]+=siz[e[i].to];
            if(maxa<siz[e[i].to]) maxt=e[i].to,maxa=siz[maxt];
         } 
     son[x]=maxt;
