void pushdown(int x){
     if(lazy[x]!=0) lazy[lc]+=lazy[x],lazy[rc]+=lazy[x],w[lc].z+=lazy[x],w[rc].z+=lazy[x],lazy[x]=0;
     if(v[x]!=0) v[lc]^=v[x],v[rc]^=v[x],v[x]=0;
}
void pushup(int x){
     if(w[lc].z<w[rc].z) w[x]=w[lc];
     else w[x]=w[rc];
}
void build(int l,int r,int x){
     if(l==r){w[x].i=l,w[x].z=vis[l]?inf:0; return;}
     int mid=l+r>>1;
     build(l,mid,lc),build(mid+1,r,rc);
     pushup(x);
}
void update(int l,int r,int p,int q,int x,int y){
    if(p<=l&&r<=q){++lazy[x],++w[x].z,v[x]^=y; return;}
    pushdown(x);
    int mid=l+r>>1;
    if(p<=mid) update(l,mid,p,q,lc,y);
    if(q>mid) update(mid+1,r,p,q,rc,y);
    pushup(x);
}
void update2(int l,int r,int p,int x){
    if(l==r){w[x].z=inf; return;}
    pushdown(x);
    int mid=l+r>>1;
    if(p<=mid) update2(l,mid,p,lc);
    else update2(mid+1,r,p,rc);
    pushup(x);
}
void update3(int l,int r,int p,int q,int x,int y){
    //cout<<" "<<l<<" "<<r<<" "<<x<<" "<<p<<" "<<q<<" "<<y<<endl; 
    if(p<=l&&r<=q){--lazy[x],--w[x].z,v[x]^=y; return;}
    pushdown(x);
    int mid=l+r>>1;
    if(p<=mid) update3(l,mid,p,q,lc,y);
    if(q>mid) update3(mid+1,r,p,q,rc,y);
    pushup(x);
}
int query(int l,int r,int p,int x){
    if(l==r) return v[x];
    int mid=l+r>>1;
    pushdown(x);
    if(p<=mid) return query(l,mid,p,lc);
    return query(mid+1,r,p,rc); 
}
void lj_update(int x,int y,int z){
    while(top[x]!=top[y]){
         if(d[top[x]]<d[top[y]]) swap(x,y);
         update(1,n,num[top[x]],num[x],1,z);
         x=f[top[x]];
    }
    if(d[x]>d[y]) swap(x,y);
    update(1,n,num[x],num[y],1,z);
}
void lj_update3(int x,int y,int z){
    while(top[x]!=top[y]){
         if(d[top[x]]<d[top[y]]) swap(x,y);
         update3(1,n,num[top[x]],num[x],1,z);
         //cout<<"x:"<<x<<" topx:"<<top[x]<<endl;
         x=f[top[x]];
    }
    if(d[x]>d[y]) swap(x,y);
    update3(1,n,num[x],num[y],1,z);
    //cout<<" "<<num[x]<<" "<<num[y]<<" "<<z<<endl;
}
void output(int l,int r,int x){
    if(l==r) return;
    int mid=l+r>>1;
