const int MN = 100111;

vector<int> ke[MN];
int h[MN], n;
int father[20][MN];

void myDfs(int u, int fu) {
    for(int v : ke[u]) {
        if (v == fu) continue;

        h[v] = h[u] + 1;
        father[0][v] = u;
        myDfs(v, u);
    }
}

void initLCA() {
    FOR(t,1,19) {
        FOR(i,1,n) {
            father[t][i] = father[t-1][father[t-1][i]];
        }
    }
}

int lca(int u, int v) {
    if (u == v) return u;

    if (h[u] < h[v]) swap(u, v);
    if (h[u] > h[v]) {
        FORD(t,19,0) {
            int x = father[t][u];
            if (h[x] >= h[v]) u = x;
        }
    }

    if (u == v) return u;

    FORD(t,19,0) if (father[t][u] != father[t][v]) {
        u = father[t][u];
        v = father[t][v];
    }
    assert(father[0][u] == father[0][v]);
    return father[0][u];
}

struct Query {
    int x, y;
    int len;
    int minVal;

    void read() {
        cin >> x >> y;
        int l = lca(x, y);

        len = h[x] + h[y] - 2 * h[l];
    }
} q[MN];

bool operator < (const Query& a, const Query& b) {
    return a.minVal < b.minVal;
}

int sz[MN], dep[MN], fa[MN];
int dfn[MN], top[MN];
int id;

void dfs1(int u, int f = 0) {
    sz[u] = 1; fa[u] = f;
    for (auto &v: ke[u]) if (v != f) {
        dep[v] = dep[u] + 1;
        dfs1(v, u); sz[u] += sz[v];
    }
}

void dfs2(int u, int chain, int f = 0) {
    int son(-1); dfn[u] = ++id; top[u] = chain;
    for (auto &v: ke[u]) if (v != f) {
        if (son == -1 || sz[son] < sz[v]) son = v;
    }
    if (~son) dfs2(son, chain, u);
    for (auto &v: ke[u]) if (v != f && v != son) {
        dfs2(v, v, u);
    }
}

struct Node {
    int nn;
    int lazy;
} it[MN * 10];

void down(int i) {
    if (it[i].lazy) {
        int t = it[i].lazy;

        it[i<<1].lazy += t;
        it[i<<1].nn += t;

        it[i<<1|1].lazy += t;
        it[i<<1|1].nn += t;

        it[i].lazy = 0;
    }
}
void up(int i) {
    it[i].nn = min(it[i<<1].nn, it[i<<1|1].nn);
}

void add(int i, int l, int r, int u, int v, int k) {
    if (v < l || r < u) return ;
    if (u <= l && r <= v) {
        it[i].nn += k;
        it[i].lazy += k;
        return ;
    }
    down(i);
    int mid = (l + r) >> 1;
    add(i<<1, l, mid, u, v, k);
    add(i<<1|1, mid+1, r, u, v, k);
    up(i);
}

const int INF = 1000111000111000LL;
int getMin(int i, int l, int r, int u, int v) {
    if (v < l || r < u) return INF;
    if (u <= l && r <= v) return it[i].nn;

    down(i);
    int mid = (l + r) >> 1;
    int res = min(getMin(i<<1, l, mid, u, v), getMin(i<<1|1, mid+1, r, u, v));
    up(i);

    return res;
}

void update(int u, int v, int val) {
    int fu = top[u], fv = top[v];
    while (fu != fv) {
        if (dep[fu] < dep[fv]) swap(u, v), swap(fu, fv);
        add(1, 1, n, dfn[fu], dfn[u], val);
        u = fa[fu], fu = top[u];
    }
    if (dep[u] > dep[v]) swap(u, v);
    add(1, 1, n, dfn[u], dfn[v], val);
}

int getMin(int u, int v) {
    int res = INF;
    int fu = top[u], fv = top[v];
    while (fu != fv) {
        if (dep[fu] < dep[fv]) swap(u, v), swap(fu, fv);
        res = min(res, getMin(1, 1, n, dfn[fu], dfn[u]));
        u = fa[fu], fu = top[u];
    }
    if (dep[u] > dep[v]) swap(u, v);
    res = min(res, getMin(1, 1, n, dfn[u], dfn[v]));
    return res;
}

int32_t main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout << (fixed) << setprecision(9) << boolalpha;
    while (cin >> n) {
        FOR(i,1,n) ke[i].clear();
        FOR(i,2,n) {
            int u, v; cin >> u >> v;
            ke[u].push_back(v);
            ke[v].push_back(u);
        }

        h[1] = 1;
        myDfs(1, -1);
        initLCA();

        FOR(i,1,n-1) q[i].read();

        // heavy light
        id = 0;
        dfs1(1);
        id = 0;
        dfs2(1, 1);

        memset(it, 0, sizeof it);

        FOR(i,1,n-1) {
            int x = q[i].x;
            int y = q[i].y;
            update(x, y, +1);
        }

        FOR(i,1,n-1) {
            int x = q[i].x;
            int y = q[i].y;
            q[i].minVal = getMin(x, y);
        }

        sort(q+1, q+n);

        try {
            FOR(i,1,n-1) {
                int x = q[i].x;
                int y = q[i].y;
                update(x, y, -1);

                int t = getMin(x, y);
                if (t) throw 1;
            }
            cout << "YES" << endl;
        } catch (...) {
            cout << "NO" << endl;
        }
    }
    return 0;
}

