		{
			int x=*it;
			G2[x].erase(u); G2[x].insert(v);
			G2[v].insert(x);
			if(G1[x].find(v)!=G1[x].end()) q.push(PII(x,v));
		}
	}
	int cnt=0;
	for(int i=1;i<=n;i++)
