int lca(int x, int y){
    if(dep[x] < dep[y])swap(x, y);
    for(int i = 29;i >= 0;i--)
        if(dep[parent[i][x]] >= dep[y])
            x = parent[i][x];

    if(x == y)return x;
    for(int i = 29;i >= 0;i--){
        if(parent[i][x] != parent[i][y]){
            x = parent[i][x];
            y = parent[i][y];
        }
    }
    return parent[0][x];
}

