int main()
{
    int N; cin >> N;

    auto adjacency_list = vector<map<int, int>>(N);
    auto queue = std::queue<pair<int, int>>();
    for (auto i = 0; i < 2*(N-1); i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;

        adjacency_list[a][b]++;
        adjacency_list[b][a]++;

        if (adjacency_list[a][b] == 2)
            queue.push({a, b});
    }

    auto representatives = vector<int>(N);
    iota(begin(representatives), end(representatives), 0);

    const function<int(int)> find = [&](const int i)
    {
        if (representatives[i] != i)
            representatives[i] = find(representatives[i]);
        return representatives[i];
    };

    auto size = N;
    while (!queue.empty())
    {
        int a, b; tie(a, b) = queue.front(); queue.pop();
        a = find(a); b = find(b);

        if (adjacency_list[a].size() > adjacency_list[b].size())
            swap(a, b);

        representatives[a] = b;

        adjacency_list[a].erase(b);
        adjacency_list[b].erase(a);

        for (const auto i : adjacency_list[a])
        {
            const auto v = i.first, x = i.second;
            adjacency_list[v].erase(a);
            adjacency_list[v][b] += x;
            adjacency_list[b][v] += x;
            if (x != 2 && adjacency_list[b][v] == 2)
                queue.push({b, v});
        }

        size--;
    }

    cout << (size == 1 ? "YES" : "NO") << endl;
}

