using namespace std;
struct edge{
	int f,t;
	edge(int f1,int t1){
		if(f1>t1) swap(f1,t1);
		f=f1;t=t1;
	}
	bool operator <(const edge &b)const{
		if(f!=b.f) return f<b.f;
		return t<b.t;
	}
};
int bcj[N];
int ff(int x) {return bcj[x]==x? x:bcj[x]=ff(bcj[x]);}
void connect(int fr,int to){
	if(ff(fr)==ff(to)) return ;
	bcj[ff(fr)]=ff(to);
}
vector<int> g1[N],g2[N];
queue<edge> q;
set<edge> st,st2;

int n;
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++) bcj[i]=i;
	for(int i=1,f,t;i<n;i++){
		scanf("%d%d",&f,&t);
		st.insert(edge(f,t));
		g1[f].push_back(t),g1[t].push_back(f);
	}
	int cnt=0;
	for(int i=1,f,t;i<n;i++){
		scanf("%d%d",&f,&t);
		edge e(f,t);
		if(st.find(e)!=st.end()) q.push(e);
		else g2[f].push_back(t),g2[t].push_back(f),st2.insert(e);
	}
	while(!q.empty()){
		edge e=q.front();q.pop();
		if(ff(e.f)==ff(e.t)) continue;
		cnt++;
		int f=ff(e.f),t=ff(e.t);
		if(g1[f].size()>g1[t].size()) swap(f,t);
		connect(f,t);
		for(int i=0;i<g1[f].size();i++){
			if(ff(g1[f][i])!=t){
				edge e(ff(g1[f][i]),t);
				if(st2.find(e)!=st2.end()) q.push(e);
				else g1[t].push_back(ff(g1[f][i])),st.insert(e);
			}
		}
		g1[f].clear();

		for(int i=0;i<g2[f].size();i++){
			if(ff(g2[f][i])!=t){
				edge e(ff(g2[f][i]),t);
				if(st.find(e)!=st.end()) q.push(e);
				else st2.insert(e),g2[t].push_back(ff(g2[f][i]));
			}
		}
		g2[f].clear();
	}

	if(cnt==n-1) puts("YES");
	else puts("NO");
	return 0;
}

