inline void pushup(int rt){
	sum[rt]=min(sum[rt<<1],sum[rt<<1|1]);
}
int tag[606060];
inline void pushdown(int rt){
	if (tag[rt]){
		sum[rt<<1]+=tag[rt],sum[rt<<1|1]+=tag[rt];
		tag[rt<<1]+=tag[rt],tag[rt<<1|1]+=tag[rt];
		tag[rt]=0;
	}
}
bool die[202020];
#define mid ((lb+rb)>>1)
inline void _update(int rt,int lb,int rb,int l,int r,int x){
	if (lb>r||rb<l) return;
	if (lb>=l&&rb<=r) return (void)(sum[rt]++,tag[rt]++,seg[rt].push_back(x));
	pushdown(rt);
	_update(rt<<1,lb,mid,l,r,x),_update(rt<<1|1,mid+1,rb,l,r,x);
	pushup(rt);
}
inline void _clr(int rt,int lb,int rb,int l,int r){
	if (lb>r||rb<l) return;
	if (lb>=l&&rb<=r) return (void)(sum[rt]--,tag[rt]--);
	pushdown(rt);
	_clr(rt<<1,lb,mid,l,r),_clr(rt<<1|1,mid+1,rb,l,r);
	pushup(rt);
}
inline void del(int rt,int lb,int rb,int pos){
	if (lb==rb) return (void)(sum[rt]=0x3f3f3f3f);
	pushdown(rt);
	(mid>=pos?del(rt<<1,lb,mid,pos):del(rt<<1|1,mid+1,rb,pos));
	pushup(rt);
}
inline void update(int x,int y,int id){
	while (top[x]!=top[y]){
		if (dep[top[x]]<dep[top[y]]) swap(x,y);
		_update(1,1,n,tpos[top[x]],tpos[x],id);
		x=fa[top[x]];
	}
	if (dep[x]<dep[y]) swap(x,y);
	if (tpos[y]+1<=tpos[x]) _update(1,1,n,tpos[y]+1,tpos[x],id);
}
inline void clr(int x,int y){
	while (top[x]!=top[y]){
		if (dep[top[x]]<dep[top[y]]) swap(x,y);
		_clr(1,1,n,tpos[top[x]],tpos[x]);
		x=fa[top[x]];
	}
	if (dep[x]<dep[y]) swap(x,y);
	if (tpos[y]+1<=tpos[x]) _clr(1,1,n,tpos[y]+1,tpos[x]);
}
