		exit(0);
	}
	if(edges[a].size() > edges[b].size()){
		swap(a , b);
	}
	for(auto it : edges[a]){
		edges[it.first].erase(edges[it.first].find(a));
	}
	comp[a] = b;
	for(auto it : edges[a]){
		if(it.first == b){
