using ii = pair<int,int>;
map<ii, int> c_edges;
set<ii> d_edges[3];
void upd_edge(int u, int v, int d){
	if(u == v) return;
	if(u > v) swap(u, v);
	ii e = {u, v};
	int cur_c = c_edges[e];
	if(cur_c >= 0 && d_edges[cur_c].count(e)) d_edges[cur_c].erase(e);
	cur_c += d;
	c_edges[e] = cur_c;
	if(cur_c < 0 || cur_c > 2) return;
	d_edges[cur_c].insert(e);
}
int join(int u, int v){
	u = find(u);
	v = find(v);
	if(u == v) return false;
	if(to[u].size() < to[v].size()) swap(u, v);
	to[u].erase(v);
	to[v].erase(u);
	for(int s : to[v]){
		upd_edge(v, s, -1);
		to[u].insert(s);
		upd_edge(u, s, 1);
	}
	to[v].clear();
	uf[v] = u;
	return true;
}
