int was[MAXN];
int tin[MAXN];
int tout[MAXN];
int p[MAXN];
int pp[MAXN];
int up[LOG][MAXN];
vector<int> gg;
vector<pair<int, int> > vv;
pair<int, int> rmq[MAXN * 4];
int dd[MAXN * 4];
int h[MAXN];
int mn[MAXN];
int mx[MAXN];

int is_p(int a, int b) {
    return tin[a] <= tin[b] && tin[b] < tout[a];
}

int lca(int a, int b) {
    if (is_p(a, b))
        return a;
    for (int i = LOG - 1; i >= 0; --i) {
        if (!is_p(up[i][a], b))
            a = up[i][a];
    }
    return up[0][a];
}

void build(int v, int tl, int tr) {
    if (tl + 1 == tr) {
        int a = gg[vv[tl].first];
        int b = gg[vv[tl].second];
        int x = lca(a, b);
        rmq[v] = make_pair(h[a] + h[b] - 2 * h[x], tl);
        return;
    }
    int m = (tl + tr) >> 1;
    build(v * 2 + 1, tl, m);
    build(v * 2 + 2, m, tr);
    rmq[v] = min(rmq[v * 2 + 1], rmq[v * 2 + 2]);
}

void del(int v, int tl, int tr, int l, int r, int x) {
    if (r <= tl || tr <= l)
        return;
    if (l <= tl && tr <= r) {
        dd[v] += x;
        rmq[v].first += x;
        return;
    }
    int m = (tl + tr) >> 1;
    del(v * 2 + 1, tl, m, l, r, x);
    del(v * 2 + 2, m, tr, l, r, x);
    rmq[v] = min(rmq[v * 2 + 1], rmq[v * 2 + 2]);
    rmq[v].first += dd[v];
}

int tm;
vector<int> eds[MAXN];

void dfs1(int v) {
    was[v] = 1;
    tin[v] = tm++;
    gg.push_back(v);
    for (int u: eds[v]) {
        if (!was[u]) {
            pp[u] = v;
            h[u] = h[v] + 1;
            dfs1(u);
        }
    }
    tout[v] = tm;
}

int n;

bool cmp2(pair<int, int> a, pair<int, int> b) {
    return a.second < b.second;
}

int get(int a) {
    if (a == p[a])
        return a;
    return p[a] = get(p[a]);
}

int fnd(int tl, int tr, int x) {
    int l = tl - 1;
    int r = tr;
    while (r - l > 1) {
        int mid = (l + r) >> 1;
        if (vv[mid].second >= x)
            r = mid;
        else
            l = mid;
    }
    return r;
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        scanf("%d%d", &a, &b);
        --a, --b;
        eds[a].push_back(b);
        eds[b].push_back(a);
    }
    for (int i = 0; i < n; ++i)
        p[i] = i;
    dfs1(0);
    for (int i = 0; i < n; ++i)
        up[0][i] = pp[i];
    for (int i = 1; i < LOG; ++i) {
        for (int j = 0; j < n; ++j)
            up[i][j] = up[i - 1][up[i - 1][j]];
    }
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        scanf("%d%d", &a, &b);
        --a, --b;
        if (tin[a] > tin[b])
            swap(a, b);
        vv.push_back(make_pair(tin[a], tin[b]));
    }
    sort(vv.begin(), vv.end());
    for (int i = 0; i < vv.size(); i += SQ) {
        int r = min((int)vv.size(), i + SQ);
        mn[i / SQ] = vv[i].first;
        mx[i / SQ] = vv[r - 1].first;
        sort(vv.begin() + i, vv.begin() + r, cmp2);
    }
    build(0, 0, vv.size());
    for (int i = 0; i < n - 1; ++i) {
        if (rmq[0].first != 1) {
            cout << "NO\n";
            return 0;
        }
        int x = rmq[0].second;
        int a = gg[vv[x].first];
        int b = gg[vv[x].second];
        int l = lca(a, b);
        int x1 = get(a);
        int x2 = get(b);
        if (h[x1] <= h[l] && h[x2] <= h[l]) {
            cout << "NO\n";
            return 0;
        }
        if (h[x1] < h[x2])
            swap(x1, x2);
        p[x1] = pp[x1];
        a = tin[x1];
        b = tout[x1];
        for (int k = 0; k * SQ < vv.size(); ++k) {
            if (mn[k] >= b || mx[k] < a)
                continue;
            int l = k * SQ;
            int r = min((k + 1) * SQ, (int)vv.size());
            if (a <= mn[k] && mx[k] < b) {
                int xx = fnd(l, r, b);
                if (xx != r)
                    del(0, 0, vv.size(), xx, r, -1);
            }
            else {
                for (int i = l; i < r; ++i)
                    if (a <= vv[i].first && vv[i].first < b && vv[i].second >= b)
                        del(0, 0, vv.size(), i, i + 1, -1);
            }
        }
        for (int k = 0; k * SQ < vv.size(); ++k) {
            if (mn[k] >= a)
                continue;
            int l = k * SQ;
            int r = min((k + 1) * SQ, (int)vv.size());
            if (mx[k] < a) {
                int xl = fnd(l, r, a);
                int xr = fnd(l, r, b);
                if (xl != xr)
                    del(0, 0, vv.size(), xl, xr, -1);
            }
            else {
                for (int i = l; i < r; ++i)
                    if (a <= vv[i].second && vv[i].second < b && vv[i].first < a)
                        del(0, 0, vv.size(), i, i + 1, -1);
            }
        }
        del(0, 0, vv.size(), x, x + 1, MAXN * 5);
    }
    cout << "YES\n";
    return 0;
}

