int find(int x) {return x==f[x]? x:f[x]=find(f[x]);}

set<int> G[maxn],H[maxn];
set<int>::iterator it;

struct Node{
	int x,y;
	Node(){}
	Node(int x,int y):x(x),y(y){}
}zz[maxn];
int s=1,t=0;

void get_inz(int x,int y) {
	if(x>y) swap(x,y);
	G[x].erase(y); G[y].erase(x);
	H[x].erase(y); H[y].erase(x);
	zz[++t]=Node(x,y);
}

bool solve() {
	int x,y,z;
	while(s<=t) {
		x=zz[s].x; y=zz[s].y; s++; x=find(x); y=find(y);
		if(G[x].size()+H[x].size()<G[y].size()+H[y].size()) swap(x,y);
		for(it=G[y].begin();it!=G[y].end();++it) {
			z=*it; G[z].erase(y); G[z].insert(x);
			G[x].insert(z);
			if(H[x].find(z)!=H[x].end()) get_inz(x,z);
		}
		for(it=H[y].begin();it!=H[y].end();++it) {
			z=*it; H[z].erase(y); H[z].insert(x);
			H[x].insert(z);
			if(G[x].find(z)!=G[x].end()) get_inz(x,z);
		}
		f[y]=x;
	}
	return t==n-1;
}

