		H[x].insert(y); H[y].insert(x);
		if(G[x].find(y)!=G[x].end()) get_inz(x,y);
	}
	if(solve()) printf("YES\n");
	else printf("NO\n");
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int MAXN = 1.1e5;
int N;
set<int> adj[MAXN];

int par[MAXN];
int getpar(int a) {
	return par[a] == -1 ? a : (par[a] = getpar(par[a]));
}

int main() {
	ios::sync_with_stdio(0), cin.tie(0);
	cin >> N;
	for (int i = 0; i < N-1; i++) {
		int a, b; cin >> a >> b;
		adj[a].insert(b);
		adj[b].insert(a);
	}
	vector<pair<int, int>> todos;
	for (int i = 0; i < N-1; i++) {
		int a, b; cin >> a >> b;
		if (adj[a].count(b)) {
			todos.emplace_back(a, b);
		} else {
			adj[a].insert(b);
			adj[b].insert(a);
		}
	}

	for (int i = 1; i <= N; i++) par[i] = -1;
	int numEdges = 0;
	while (!todos.empty()) {
		int a, b; tie(a, b) = todos.back();
		todos.pop_back();
		a = getpar(a);
		b = getpar(b);
		if (a == b) continue;
		numEdges++;

		if (adj[a].size() > adj[b].size()) {
			swap(a, b);
		}
		adj[a].erase(b);
		adj[b].erase(a);
		par[a] = b;
		for (int c : adj[a]) {
			adj[c].erase(a);
			if (adj[b].count(c)) {
				todos.emplace_back(b, c);
			} else {
				adj[b].insert(c);
				adj[c].insert(b);
			}
		}
		set<int>().swap(adj[a]);
	}
	cout << (numEdges == N-1 ? "YES" : "NO") << '\n';

	return 0;
}

