template <class T>
IL void print(T x)
{
    if(x < 0)
    {
        putchar('-');
        x = -x;
    }
    if(x > 9)
        print(x / 10);
    putchar(x % 10 + '0');
}
IL int getfa(int u)
{
	return fa[u] == u ? u : (fa[u] = getfa(fa[u]));
}
IL ll getid(int x, int y)
{
	if(x > y) swap(x, y);
	return 1ll * n * y + x;
}
IL void ae(int u, int v)
{
	s[u].insert(v);
	s[v].insert(u);
	ll eid = getid(u, v);
	int t = ++g[eid];
	if(t == 2)
		q.push(mp(u, v));
}
IL void re(int u, int v)
{
	s[u].erase(v);
	s[v].erase(u);
	g.erase(getid(u, v));
}
IL bool solve()
{
	for(int i = 1; i <= n; ++i) fa[i] = i;
	for(int i = 1; i < n; ++i)
	{
		int u, v;
		if(q.empty())
			return false;
		u = q.front().first;
		v = q.front().second;
		q.pop();
		u = getfa(u);
		v = getfa(v);
		if(s[u].size() > s[v].size())
			swap(u, v);
		fa[u] = v;
		re(u, v);
		for(set<int> :: iterator i = s[u].begin(), j; i != s[u].end(); i = j)
		{
			j = i; ++j; 
			int x = *i;
			x = getfa(x);
			re(u, x);
			ae(v, x);
		}
	}
	return true;
}
