static const int MAXN = 1e5 + 5;

static int n, fa[MAXN];
set<int> s1[MAXN];
set<int> s2[MAXN];
queue< pair< int , int > > q;

int get_fa(int x) {
        return (fa[x] == x) ? x : (fa[x] = get_fa(fa[x]));
}

int main() {
        // boost;
