        read(n);
        for (int i = 1; i <= n; ++i ) {
                fa[i] = i;
        }
        for (int i = 1; i < n; ++i ) {
                int x, y;
                read(x), read(y);
                s1[x].insert(y);
                s1[y].insert(x);
        }
        for (int i = 1; i < n; ++i ) {
                int x, y;
                read(x), read(y);
                s2[x].insert(y);
                s2[y].insert(x);
                if (s1[x].find(y) != s1[x].end())
                        q.push(make_pair(x, y));
        }
        while (!q.empty()) {
                int x = q.front().first;
                int y = q.front().second;
                q.pop();
                int tx = get_fa(x);
                int ty = get_fa(y);
                if (tx == ty) continue;
                if (s1[tx].size() + s2[tx].size() > s1[ty].size() + s2[ty].size()) 
                        swap(tx, ty);
                fa[tx] = ty;
                s1[tx].erase(ty);
                s1[ty].erase(tx);
                s2[tx].erase(ty);
                s2[ty].erase(tx);
                for (set<int> :: iterator it = s1[tx].begin(); it != s1[tx].end(); ++it ) {
                        int now = *it;
                        s1[now].erase(tx);
                        s1[now].insert(ty);
                        s1[ty].insert(now);
                        if (s2[now].find(ty) != s2[now].end())
                                q.push(make_pair(now, ty));
                }
                for (set<int> :: iterator it = s2[tx].begin(); it != s2[tx].end(); ++it ) {
                        int now = *it;
                        s2[now].erase(tx);
                        s2[now].insert(ty);
                        s2[ty].insert(now);
                        if (s1[now].find(ty) != s1[now].end())
                                q.push(make_pair(now, ty));
                }
        }
        int ans = 0;
        for (int i = 1; i <= n; ++i )
                if (get_fa(i) == i) ans ++;
        (ans == 1) ? puts("YES") : puts("NO");
        return 0;
}
