		else (r?r:(r=new node(mid, hi)))->init(loc);
	}
	void del(int rlo, int rhi, int v)
	{
		if (lo == rlo && hi == rhi)
		{
			all.erase(v);
			va--;
		} else
		{
			int mid = (lo+hi) / 2;
			if (rhi <= mid) l->del(rlo, rhi, v);
			else if (rlo >= mid) r->del(rlo, rhi, v);
			else
			{
				l->del(rlo, mid, v);
				r->del(mid, rhi, v);
			}
			va = min(l?l->va:INF, r?r->va:INF)+all.size();
		}
	}
	void destroy(int loc)
	{
		if (lo+1 == hi)
		{
			va = INF;
			return;
		}
		int mid = (lo+hi) / 2;
		if (loc < mid) l->destroy(loc);
		else r->destroy(loc);
		va = min(l?l->va:INF, r?r->va:INF);
	}
};

