			nxt[tot]=nxt[o];
			lst[nxt[o]]=tot;
			nxt[o]=tot;
			lst[tot]=o;
			return;
		}
		int mid=(l+r)/2;
		if (ul<=mid)
			add(o*2,l,mid);
		if (ur>mid)
			add(o*2+1,mid+1,r);
		pu(o);
