			if (Queue.empty()) go_fail();
			x = Queue.front().first;
			y = Queue.front().second;
			Queue.pop();
			if (x != y) break;
		}
		if (edges[x].size() > edges[y].size()) swap(x, y);
		bel[x] = y;
		cnt.erase(get_id(x, y));
		edges[y].erase(x);
		for (auto v : edges[x]) {
			v = find(v);
			if (v == y) continue;
			cnt.erase(get_id(x, v));
			link_edges(v, y);
			edges[v].erase(x);
			edges[x].erase(v);
		}
	}
	puts("YES");
}

