using namespace std;
const int N = 1e5 + 5;
int n;
int a[N] , b[N];
int c[N] , d[N];
map < int , int > edges[N];
queue < pair < int , int > > q;
int comp[N];
void insert(int a , int b){
	a = comp[a];
	b = comp[b];
	if(a != b){
		++edges[a][b];
		++edges[b][a];
		if(edges[a][b] >= 2){
			q.push({a , b});
		}
	}
}
void merge(){
	int a = - 1 , b = -1;
	while(!q.empty()){
		a = comp[q.front().first];
		b = comp[q.front().second];
		q.pop();
		if(a != b){
			continue;
		}
	}
	if(a == b){
		printf("NO\n");
		exit(0);
	}
	if(edges[a].size() > edges[b].size()){
		swap(a , b);
	}
	for(auto it : edges[a]){
		edges[it.first].erase(edges[it.first].find(a));
	}
	comp[a] = b;
	for(auto it : edges[a]){
		if(it.first == b){
			continue;
		}
		if(it.first == a){
			continue;
		}
		while(it.second--){
			insert(b , comp[it.first]);
		}
	}
	edges[a].clear();
}
int main(){
	scanf("%d" , &n);
	for(int i = 1 ; i < n ; ++i){
		scanf("%d %d" , a + i , b + i);
	}
	for(int i = 1 ; i < n ; ++i){
		scanf("%d %d" , c + i , d + i);
	}
	for(int i = 1 ; i <= n ; ++i){
		comp[i] = i;
	}
	for(int i = 1 ; i < n ; ++i){
		insert(a[i] , b[i]);
		insert(c[i] , d[i]);
	}
	for(int i = 1 ; i < n ; ++i){
		merge();
	}
	printf("YES\n");
}

