{
	clock_t en=clock();
	return (en-st);
}

void addpath(int u, int v)
{
	ii tmp = mp(min(u,v),max(u,v));
	int lc=T.lca(u,v);
	while(u!=lc)
	{
		par[u].insert(tmp);
		u=T.st[0][u].p;
	}
	while(v!=lc)
	{
		par[v].insert(tmp);
		v=T.st[0][v].p;
	}
