	}

	void solve()
	{
		initialize();
//		printf("?\n");
		while(!Q.empty())
		{
			pii A=Q.front();Q.pop();
			int x=A.x,y=A.y;
			if(x==y || done[x] || done[y])continue;

//			printf("%d -- %d\n",x,y);

			combine(x,y),n--;
//			if(n%100==0)printf("%d\n",n);
		}
		printf("%s\n",n>1?"NO":"YES");
	}
}

