map<int,int>mp[maxn];
set<edge>q;
set<edge>::iterator it;
set<int>S[maxn];
set<int>::iterator it2;

int num[maxn];

int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++) num[i]=1,S[i].insert(0);
	for(int i=1;i<=2*(n-1);i++)
	{
		int x,y; scanf("%d%d",&x,&y);
		const edge now=edge(x,y);
		mp[x][y]++; mp[y][x]++;
		if(mp[x][y]==2) q.insert(now);
		S[x].insert(y); S[y].insert(x);
	}
	const edge Mn=edge(0,0); q.insert(Mn);
	for(int i=1;i<n;i++) 
	{
		it=q.upper_bound(Mn); if(it==q.end()) return puts("NO"),0;

		int x=(*it).x,y=(*it).y;
		if(num[x]<num[y]) swap(x,y); 
		num[x]+=num[y];

		for(it2=S[y].upper_bound(0);it2!=S[y].end();it2++)
		{
			int k=(*it2); if(k==x) continue;
			if(mp[y][k]==2)
			{
				const edge er=y<k?edge(y,k):edge(k,y);
