#include <bits/stdc++.h>

#define F first
#define S second
#define _sz(x) (int)x.size()
#define pb push_back

#define error(x) cout << #x << " = " << x << endl

using namespace std ;
using ll = long long ;
using ld = long double ;
using pii = pair <int , int> ;

const int N = 1e5 + 20;
int n;
vector <int> g[N], h[N];
set <pii> st1, st2;

int par[N];
vector <int> vec[N];

int cnt;
set <pii> que;

inline void add1 (int u, int v)
{
	if (u > v) swap(u, v);
	st1.insert({u, v});

	if (st2.count({u, v})) que.insert({u, v});
}

inline void rmv1 (int u, int v)
{
	if (u > v) swap(u, v);
	st1.erase({u, v});

	if (st2.count({u, v})) que.erase({u, v});
}

inline void add2 (int u, int v)
{
	if (u > v) swap(u, v);
	st2.insert({u, v});

	if (st1.count({u, v})) que.insert({u, v});
}

inline void rmv2 (int u, int v)
{
	if (u > v) swap(u, v);
	st2.erase({u, v});

	if (st1.count({u, v})) que.erase({u, v});
}

inline int root (int v) { return par[v]; }

inline void merge (int u, int v)
{
	if ((u = root(u)) == (v = root(v))) return;

	if (_sz(vec[u]) < _sz(vec[v])) swap(u, v);

	for (int x : vec[v])
	{
		for (int y : g[x])
		{
			int z = root(y);

			if (z != v) rmv1(v, z);
			if (z != v && z != u) add1(u, z);
		}

		for (int y : h[x])
		{
			int z = root(y);

			if (z != v) rmv2(v, z);
			if (z != v && z != u) add2(u, z);
		}

		par[x] = u;
		vec[u].pb(x);
	}

	vec[v].clear();
}

int main()
{
	ios::sync_with_stdio(false), cin.tie(0), cout.tie(0);

	cin >> n;

	for (int i = 0; i < n; i++)
	{
		par[i] = i;
		vec[i].pb(i);
	}

	for (int i = 0, u, v; i < n - 1; i++)
	{
		cin >> u >> v;
		u--, v--;
		g[u].pb(v);
		g[v].pb(u);

		add1(u, v);
	}

	for (int i = 0, u, v; i < n - 1; i++)
	{
		cin >> u >> v;
		u--, v--;
		h[u].pb(v);
		h[v].pb(u);

		add2(u, v);
	}

	while (_sz(que))
	{
		int u = que.begin() -> F, v = que.begin() -> S;
		que.erase(que.begin());

		merge(u, v);

		cnt++;
	}

	assert(cnt <= n - 1);

	cout << (cnt == n - 1 ? "YES" : "NO") << '\n';
}

