using namespace std;
int N;
vector <int> G[100005], G2[100005];
map <int, int> M[100005];
bool Use[100005], InQ[100005];
multiset <int> S[100005];
queue <pair <int, int> > Q;
int TT[100005];
int Father(int x)
{
    int init = x;
    while(TT[x] != x)
    {
        x = TT[x];
    }
    while(init != x)
    {
        int next = TT[init];
        TT[init] = x;
        init = next;
    }
    return x;
}

void Unite(int x, int y)
{
        TT[y] = x;
}
void Read()
{
    cin >> N;
    for(int i = 1; i < N; i++)
    {
        int x, y;
        cin >> x >> y;
        TT[i] = i;
        G[x].push_back(y);
        G[y].push_back(x);
        M[x][y]++;
        M[y][x]++;
        S[x].insert(y);
        S[y].insert(x);
    }
    TT[N] = N;
    for(int i = 1; i < N; i++)
    {
        int x, y;
        cin >> x >> y;
        S[x].insert(y);
        S[y].insert(x);
        M[x][y]++;
        M[y][x]++;
        if(M[x][y] == 2)
            Q.push(make_pair(x, y));
    }
}

void Solve()
{
    int cnt = 0;
    while(!Q.empty() && cnt < N - 1)
    {

        pair <int, int> p = Q.front();
        Q.pop();
        int x = p.first, y = p.second;
        x = Father(x);
        y = Father(y);
        if(x == y)
        {
            continue;
        }
        ++cnt;
        M[x][y] -= 2;
        M[y][x] -= 2;
        if(M[x][y] >= 2)
            Q.push(make_pair(x, y));
        if(S[x].size() < S[y].size())
            swap(x, y);
        for(auto it = S[y].begin(); it != S[y].end(); it = next(it))
        {
            S[x].insert(*it);
            int neighb = *it;
            auto it2 = S[neighb].find(y);
            if(it2 != S[neighb].end())
                S[neighb].erase(it2);
            S[neighb].insert(x);
            M[y].erase(neighb);
            M[neighb].erase(y);
            M[x][neighb]++;
            M[neighb][x]++;
            if(M[x][neighb] == 2)
                Q.push(make_pair(x, neighb));
        }
        S[y].clear();
        Unite(x, y);
    }
    if(cnt == N - 1)
        cout << "YES\n";
    else
        cout << "NO\n";
}
int main()
{
    Read();
    Solve();
    return 0;
}

