		if (out[x].size() + qry[x].size() > out[y].size() + qry[y].size())
			std::swap(x, y);
		for (auto u : out[x]) {
			out[u].erase(x);
			del(u, x);
			out[u].insert(y), out[y].insert(u);
			chk(u, y);
		}
		for (auto u : qry[x]) {
			qry[u].erase(x);
			del(u, x);
			qry[u].insert(y), qry[y].insert(u);
			chk(u, y);
		}
	}
	std::cout << (cnt == n - 1 ? "YES" : "NO") << std::endl;
	return 0;
}

