const int N=1e5+10;
int n,p,TIME;
int head[N],dep[N],num[N],son[N],dfn[N],low[N],nw[N],top[N],fa[N];
struct Data {
  int u,v,lca;
  Data () {}
  Data (int u,int v,int lca) :u(u),v(v),lca(lca) {}
}E[N];
struct Edge {
  int to,last;
  Edge () {}
  Edge (int a,int b) :to(a),last(b) {}
}edge[N<<1];
void ADD(int a,int b) {
  edge[++p]=Edge(b,head[a]); head[a]=p;
  edge[++p]=Edge(a,head[b]); head[b]=p;
}
void DFS(int u,int f) {
  num[u]=1; fa[u]=f;
  for(int i=head[u];i;i=edge[i].last) {
    int v=edge[i].to;
    if(v!=f) {
      dep[v]=dep[u]+1; DFS(v,u);
      num[u]+=num[v];
      if(num[v]>num[son[u]]) son[u]=v;
    }
  }
}
void SFD(int u,int topv) {
  nw[dfn[u]=++TIME]=u; top[u]=topv;
  if(son[u]) SFD(son[u],topv);
  for(int i=head[u];i;i=edge[i].last) {
    int v=edge[i].to;
    if(!dfn[v]) SFD(v,v);
  }
  low[u]=TIME;
}
int MINV[N<<2],lazy[N<<2];
#define L o<<1
#define R o<<1|1
void Down(int o,int v) {
  MINV[o]+=v; lazy[o]+=v;
}
void Pushup(int o) {
  MINV[o]=min(MINV[L],MINV[R]);
}
void Pushdown(int o) {
  if(lazy[o]) {
    Down(L,lazy[o]); Down(R,lazy[o]);
    lazy[o]=0;
  }
}
void Modify(int l,int r,int o,int ql,int qr,int v) {
  if(ql<=l&&r<=qr) return Down(o,v);
  Pushdown(o);
  int mid=l+r>>1;
  if(ql<=mid) Modify(l,mid,L,ql,qr,v);
  if(qr>mid) Modify(mid+1,r,R,ql,qr,v);
  Pushup(o);
}
int Query(int l,int r,int o,int ql,int qr) {
  if(ql<=l&&r<=qr) return MINV[o];
  Pushdown(o);
  int mid=l+r>>1,t=2e9;
  if(ql<=mid) t=Query(l,mid,L,ql,qr);
  if(qr>mid) t=min(t,Query(mid+1,r,R,ql,qr));
  Pushup(o);
  return t;
}
void Change(int u,int v,int val) {
  while(top[u]!=top[v]) {
    if(dep[top[u]]<dep[top[v]]) swap(u,v);
    Modify(1,n,1,dfn[top[u]],dfn[u],val);
    u=fa[top[u]];
  }
  if(u==v) return;
  if(dep[u]>dep[v]) swap(u,v);
  Modify(1,n,1,dfn[u]+1,dfn[v],val);
}
int Ask(int u,int v) {
  int res=2e9;
  while(top[u]!=top[v]) {
    if(dep[top[u]]<dep[top[v]]) swap(u,v);
    res=min(res,Query(1,n,1,dfn[top[u]],dfn[u]));
    u=fa[top[u]];
  }
  if(u==v) return res;
  if(dep[u]>dep[v]) swap(u,v);
  return min(res,Query(1,n,1,dfn[u]+1,dfn[v]));
}
int LCA(int u,int v) {
  while(top[u]!=top[v]) {
    if(dep[top[u]]<dep[top[v]]) swap(u,v);
    u=fa[top[u]];
  }
  return dfn[u]<dfn[v]?u:v;
}
bool Type(Data A) {
  return dfn[A.u]<=dfn[A.v]&&dfn[A.v]<=low[A.u];
}
bool cmp(int e1,int e2) {
  Data A=E[e1],B=E[e2];
  int a=Type(A),b=Type(B);
  if(a&&b) {
    return dfn[A.u]<=dfn[B.u]&&dfn[B.u]<=low[A.u]&&dfn[B.v]<=dfn[A.v]&&dfn[A.v]<=low[B.v];
  }
  if(!a&&b) {
    return dfn[A.lca]<=dfn[B.u]&&dfn[B.u]<=low[A.lca]&&((dfn[B.v]<=dfn[A.u]&&dfn[A.u]<=low[B.v])||(dfn[B.v]<=dfn[A.v]&&dfn[A.v]<=low[B.v]));
  }
  if(a&&!b) {
    return false;
  }
  if(!a&&!b) {
    return A.lca==B.lca&&dfn[B.u]<=dfn[A.u]&&dfn[A.u]<=low[B.u]&&dfn[B.v]<=dfn[A.v]&&dfn[A.v]<=low[B.v];
  } 
}
int vis[N];
vector<int> G[N];
void Solve(int u,int f) {
  sort(G[u].begin(),G[u].end(),cmp);
  for(int i=head[u];i;i=edge[i].last) {
    int v=edge[i].to;
    if(v!=f) Solve(v,u);
  }
  for(auto i: G[u]) {
    if(vis[i]==2) continue;
    int t=Ask(E[i].u,E[i].v);
    //printf("%d %d :%d\n",E[i].u,E[i].v,t);
    if(t!=1) {
      if(vis[i]) puts("NO"),exit(0);
      else vis[i]=1;
    }
    if(t==1) Change(E[i].u,E[i].v,-1),vis[i]=2;
  }
}
