const int N=1e5+50;

int n,mcnt,del[N];
multiset<int> adj[N]; 
struct P { int x,y; } ; 

queue<P> q;
map<P,int> e;
P makePair(int x,int y){ return x>y?(P){y,x}:(P){x,y}; }
bool operator<(const P &a,const P &b){ return a.x==b.x?a.y<b.y:a.x<b.x; } 

void merge(int x,int y){
	for(int d:adj[y]){
		if(d!=x){
			adj[x].insert(d); 
			if(++e[makePair(x,d)]==2){
				q.push(makePair(x,d)); 
			}
		}
		if(e.count(makePair(y,d)))e.erase(e.find(makePair(y,d))); 
	}
	del[y]=true;
	adj[x].erase(y); 
}

