        pii x = q.front(); q.pop();
        if(g[x] < 2) continue;
        ++ tot;
        g[x] -= 2;

        int u = x.fst, v = x.snd;
        if(s[u].size() > s[v].size()) swap(u, v);

        s[u].erase(v);
