int N;
set<int> E[101010][2];
set<pair<int,int>> S;

void add_edge(int a,int b) {
	if(E[a][0].count(b)) {
		E[a][0].erase(b);
		E[b][0].erase(a);
		S.insert({min(a,b),max(a,b)});
		E[a][1].erase(b);
		E[b][1].erase(a);
	}
	else {
		E[a][0].insert(b);
		E[b][0].insert(a);
	}
}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;

	int id=-1;
	FOR(i,2*(N-1)) {
		cin>>x>>y;
		add_edge(x-1,y-1);
	}

	FOR(i,N-1) {
		if(S.empty()) return _P("NO\n");
		x = S.begin()->first;
		y = S.begin()->second;
		S.erase(S.begin());

		if(E[x][0].size()+E[x][1].size()<E[y][0].size()+E[y][1].size()) {
			swap(x,y);
		}
		// merge y->x
		FORR(e,E[y][0]) {
			E[e][0].erase(y);
			add_edge(x,e);
		}
		FORR(e,E[y][1]) {
			E[e][1].erase(y);
			E[e][1].insert(x);
			E[x][1].insert(e);
			S.erase({min(e,y),max(e,y)});
			S.insert({min(x,e),max(x,e)});
		}

	}
	return _P("YES\n");
}


