void link(int u, int v)
{
	if (u > v) swap(u, v);
	edge[u].insert(v);
	edge[v].insert(u);
	++h[u][v];
	if (h[u][v] == 2)
	{
		q.push(mp(u, v));
	}
	if (h[u][v] > 2)
	{
		puts("NO");
		exit(0);
	}
}

void cut(int u, int v)
{
	if (u > v) swap(u, v); 
	edge[u].erase(v);
	edge[v].erase(u);
	h[u].erase(v);
}

