int n;
bool vis[N + 5];

queue<pii> q;
map<pii, int> g;
multiset<int> s[N + 5];

bool solve() {
    int tot = 0;
    while(!q.empty()) {
        pii x = q.front(); q.pop();
        if(g[x] < 2) continue;

        ++ tot;
        g[x] -= 2;


        int u = x.fst, v = x.snd;
        if(s[u].size() > s[v].size()) swap(u, v);

        assert(!vis[u] && !vis[v]);

        s[u].erase(v);
        s[v].erase(u);

        for(const auto& y : s[u]) {
            (y < u ? -- g[pii(y, u)] : -- g[pii(u, y)]);

            s[y].erase(u);
            s[v].insert(y);

            if(y < v) {
                if(++ g[pii(y, v)] == 2) q.push(pii(y, v));
            }else {
                if(++ g[pii(v, y)] == 2) q.push(pii(v, y));
            }
        }
    }

    return tot == n-1;
}

