                        int now = *it;
                        s2[now].erase(tx);
                        s2[now].erase(ty);
                        s2[ty].erase(now);
                        if (s1[now].find(ty) != s1[now].end())
                                q.push(make_pair(now, ty));
                }
        }
        int ans = 0;
        for (int i = 1; i <= n; ++i )
                if (get_fa(i) == i) ans ++;
        (ans == 1) ? puts("YES") : puts("NO");
        return 0;
}
