char buffer[Size],*head,*tail;
inline char Getchar() {
    if(head==tail) {
        int l=fread(buffer,1,Size,stdin);
        tail=(head=buffer)+l;
    }
    if(head==tail) return -1;
    return *head++;
}
inline int read() {
    int x=0,f=1;char c=Getchar();
    for(;!isdigit(c);c=Getchar()) if(c=='-') f=-1;
    for(;isdigit(c);c=Getchar()) x=x*10+c-'0';
    return x*f;
}
typedef long long ll;
const int maxn=100010;
#define mp make_pair
queue<pair<int,int> >Q;
set<int> adj[maxn];
int n,pa[maxn];
int findset(int x) {return x==pa[x]?x:pa[x]=findset(pa[x]);}
int solve(int u,int v) {
	u=findset(u);v=findset(v);
	if(u==v) return 0;
	if(adj[u].size()>adj[v].size()) swap(u,v);
	pa[u]=v;
	for(set<int>::iterator it=adj[u].begin();it!=adj[u].end();it++) {
		int t=findset(*it);
		if(t==v) continue;
		if(adj[v].count(t)) Q.push(mp(v,t));
		else adj[v].insert(t),adj[t].insert(v);
	}
	adj[v].erase(u);
	return 1;
}
int main() {
	n=read();
	rep(i,1,n) pa[i]=i;
	rep(i,1,2*n-2) {
		int u=read(),v=read();
		if(adj[u].count(v)) Q.push(mp(u,v));
		else adj[u].insert(v);adj[v].insert(u);
	}
	int ans=0;
	while(Q.size()) {
		pair<int,int> tmp=Q.front();Q.pop();
		ans+=solve(tmp.first,tmp.second);
	}
	puts(ans==n-1?"YES":"NO");
	return 0;
}

