using namespace std;

const int MAXN = 100001;
const int LG = 20;


struct prefsum {
	int p[LG];
	int start;

	int id(int x) {
		return start + x;
	}

	int& operator[] (int index) {
		return p[index];
	}

};

const int MAXM = MAXN * LG + MAXN;
vector <int> e[MAXN];
vector <int> partof[MAXM];
vector <int> sumof[MAXM];
int a[MAXM];
prefsum ps[MAXN];
int h[MAXN];

int n;
int possible[MAXN], pose = 0;

int merge(int v1, int v2) {
	if ((v1 == 0) || (v2 == 0)) return 0;
	if ((v1 == -1) && (v2 == -1)) return -1;
	if ((v1 != -1) && (v2 != -1)) return 0;
	return v1 + v2 + 1;
}

void upd(int x) {
	a[x] = -1;
	for (int u : sumof[x]) {
		a[x] = merge(a[x], a[u]);
	}
}

void go(int x) {
	if (x < n) {
		if (a[x] != -1) possible[pose++] = x;
	}
	for (int u : partof[x]) {
		upd(u);
		if (a[u] != 0) go(u);
	}
}

int curt;

void adedge(int fr, int t) {
	sumof[fr].push_back(t);
	partof[t].push_back(fr);
}

void dfs(int v, int p) {
	h[v] = h[p] + 1;
	ps[v].start = curt;
	ps[v][0] = p;
	a[curt] = curt;
	for (int i = 1; i < LG; i++) {
		ps[v][i] = ps[ps[v][i - 1]][i - 1];	
		adedge(ps[v].id(i), ps[v].id(i - 1));
		adedge(ps[v].id(i), ps[ps[v][i - 1]].id(i - 1));
	}
	curt += LG;
	for (int u : e[v]) {
		if (u != p)
			dfs(u, v);
	}
}

void advance(int ci, int& x, int j) {
	adedge(ci, ps[x].id(j));
	x = ps[x][j];
}

int main() {
	//freopen("input.txt", "r", stdin); freopen("output.txt", "w", stdout);
	ios_base::sync_with_stdio(0); cout.setf(ios::fixed); cout.precision(20);
	cin >> n;
	memset(a, 0, sizeof(a));
	for (int i = 1; i < n; i++) {
		int a, b;
		cin >> a >> b;
		e[a].push_back(b);
		e[b].push_back(a);
	}
	curt = n;
	dfs(1, 1);
	for (int i = 1; i < n; i++) {
		int c, d;
		cin >> c >> d;
		if (ps[c][0] == d) {
			a[i] = ps[c].id(0);
			possible[pose++] = i;
		} else if (ps[d][0] == c) {
			a[i] = ps[d].id(0);
			possible[pose++] = i;
		} else {
			for (int j = LG - 1; j >= 0; j--) {
				if (h[c] >= h[d] + (1 << j)) {
					advance(i, c, j);
				}
				if (h[d] >= h[c] + (1 << j)) {
					advance(i, d, j);
				}
			}
			if (c != d) {
				for (int j = LG - 1; j >= 0; j--) {
					if (ps[d][j] >= ps[c][j]) {
						advance(i, d, j);
						advance(i, c, j);
					}
				}
				advance(i, c, 0);
				advance(i, d, 0);
			}
		}
	}
	for (int posb = 0; posb < pose; posb++) {
		int v = possible[posb];
		a[a[v]] = -1;
		go(a[v]);
	}
	assert(pose <= n - 1);
	if (pose == n - 1) cout << "YES" << endl;
	else cout << "NO" << endl;
	return 0;
}

