typedef pair<int, int> pii;
const int N = 1e5 + 100;

int n;
struct data {
	int par[N];
	bool dead[N];
	queue<pii> q;
	vector<int> nei[N], comp[N];
	map<pii, vector<pii>> edges;
	data() {
		for (int i = 0; i < N; i++)
			comp[par[i] = i].push_back(i);
	}
	pii f(pii p, pii q) {
		for (pii x: {p, q})
			if (edges[x].size())
				return edges[x].back();
		return pii(-1, -1);
	}
	void normalize(pii p) {
		int U = p.first, V = p.second;
		if (dead[U] || dead[V])
			edges[p].clear();
		while (edges[p].size()) {
			pii e = edges[p].back();
			int u = par[e.first], v = par[e.second];
			if ((U == u && V == v) || (U == v && V == u))
				break;
			edges[p].pop_back();
		}
	}
	void read() {
		for (int i = 0; i < n - 1; i++) {
			int u, v;
			cin >> u >> v;
			nei[--u].push_back(--v);
			nei[v].push_back(u);
			edges[pii(u, v)].push_back(pii(u, v));
			q.push(pii(u, v));
		}
	}
	void merge(int u, int v) {
		//cerr << u + 1 << " *** " << v + 1 << '\n';
		if (u == v)
			return;
		if (comp[u].size() > comp[v].size())
			swap(u, v);
		while (comp[u].size()) {
			int me = comp[u].back();
			comp[u].pop_back();
			comp[par[me] = v].push_back(me);

			for (int she: nei[u]) {
				int a = u, b = par[she];
				if (a != b) {
					pii A = pii(v, b);
					q.push(pii(v, b));
					for (pii B: {pii(u, b), pii(b, u)}) {
						while (edges[B].size()) {
							edges[A].push_back(edges[B].back());
							edges[B].pop_back();
						}
					}
				}
			}
		}
		dead[u] = true;
	}
} blue, red;

void input() {
	cin >> n;
	blue.read();
	red.read();
}

bool can(pii p) {
	pii q = pii(p.second, p.first);
	blue.normalize(p);
	blue.normalize(q);
	red.normalize(p);
	red.normalize(q);
	pii A = blue.f(p, q), B = red.f(p, q);
	if (min(A.first, B.first) == -1)
		return false;
	//cerr << A.first + 1 << ' ' << A.second + 1 << " ... " << B.first + 1 << ' ' << B.second + 1 << '\n';
	int u = blue.par[A.first], v = blue.par[A.second];
	blue.merge(u, v);
	red.merge(u, v);
	return true;
}

bool ok() {
	int want = n - 1;
	while (want) {
		pii p;
		if (blue.q.size()) {
			p = blue.q.front();
			blue.q.pop();
		}
		else if (red.q.size()) {
			p = red.q.front();
			red.q.pop();
		}
		else
			return false;
		if (can(p))
			want--;
	}
	return true;
}

