	for(int i = 1 ; i <= 2 * N - 2 ; ++i) add(i);

	while(!q.empty()){int x = q.front().first , y = q.front().second; q.pop(); merge(x , y);}
	cout << (ext.empty() ? "YES" : "NO");
	return 0;
}

