#define fir first
#define sec second
#define N 100010
using namespace std;
typedef pair<int,int> pii;
map<lint,int> f;
set<int> g[N];
queue<pii> q;
int main()
{
	int n;scanf("%d",&n);
	for(int i=1;i<=2*n-2;i++)
	{
		int x,y;scanf("%d%d",&x,&y);
		f[P(x,y)]++,f[P(y,x)]++;
		g[x].insert(y),g[y].insert(x);
		if(f[P(x,y)]==2) q.push(mp(x,y));
	}
	int ans=0;
	for(int x,y;!q.empty();ans++,q.pop())
	{
		x=q.front().fir,y=q.front().sec;
		if(f[P(x,y)]>2) continue;
		if(g[x].size()<g[y].size()) swap(x,y);
		while(!g[y].empty())
		{
			int t=*g[y].begin();
			f[P(x,t)]+=f[P(y,t)],f[P(y,t)]=0;
			f[P(t,x)]+=f[P(t,y)],f[P(t,y)]=0;
			g[x].insert(t),g[t].insert(x);
			g[y].erase(t),g[t].erase(y);
			if(f[P(x,t)]==2) q.push(mp(x,t));
		}
	}
