void add (int i, int x) {
        assert(!m[i].count(l[i][x]));
        m[i][l[i][x]] = x;

        //printf("add edge %d %d (%d %d)\n", i, x, l[i][x].first, l[i][x].second);

        if (!done[i][x]) {
                auto o = m[i^1].find(l[i][x]);
                if (o != m[i^1].end()) {
                        //printf("found overlap between %d and %d\n", x, o->second);
                        done[i][x] = true;
                        done[i^1][o->second] = true;
                        assert(l[i][x] == l[i^1][o->second]);
                        if (i == 0) q.push(MP(x, o->second));
                        else q.push(MP(o->second, x));
                }
        }
}

void fix (int i, int x) {
        auto it = m[i].find(l[i][x]);
        assert(it->second == x);
        m[i].erase(it);

        l[i][x].first = g(l[i][x].first);
        l[i][x].second = g(l[i][x].second);
        if (l[i][x].first > l[i][x].second) {
                swap(l[i][x].first, l[i][x].second);
        }

        if (l[i][x].first != l[i][x].second) add(i, x);
}

void merge (int i, int j) {
        assert(i == g(i));
        assert(j == g(j));

        //printf("merge %d %d\n", i, j);

        if (c[i].bsz() < c[j].bsz()) swap(i, j);

        //union find merge
        par[j] = i;

        fo(p, 0, 2) {
                for (int x : c[j].v[p]) if (g(l[p][x].first) != g(l[p][x].second)) {
                        fix(p, x);
                        c[i].v[p].PB(x);
                }
                c[j].v[p].clear();
        }
}

