}
void update(int k, int l, int r, int L, int R, int opt, int x_id){
    if(L <= l && r <= R){
        minn[k] += opt; tag[k] += opt;
        sum_xor[k] ^= x_id;
        return; 
    }
    int mid = l + r >> 1;
    if(tag[k] != 0) pushdown(k, r - l + 1);
    if(L <= mid) update(k << 1, l, mid, L, R, opt, x_id);
    if(R > mid) update(k << 1 | 1, mid + 1, r, L, R, opt, x_id);
    minn[k] = min(minn[k << 1], minn[k << 1 | 1]);
    if(minn[k] == minn[k << 1]) minn_id[k] = minn_id[k << 1];
    else minn_id[k] = minn_id[k << 1 | 1]; 
