typedef pair<int, int> pii;

const int MAXN = 1e5+5;

int n;
set<int> a[MAXN][2];
map<pii, int> m;
set<pii> s;

void rem(int u, int v, int x) {
    if (u > v)
        swap(u, v);
    m[pii(u, v)]--;
    if (m[pii(u, v)] < 2)
        s.erase(pii(u, v));
    a[u][x].erase(v);
    a[v][x].erase(u);
}

void add(int u, int v, int x) {
    if (u > v)
        swap(u, v);
    m[pii(u, v)]++;
    if (m[pii(u, v)] >= 2)
        s.insert(pii(u, v));
    a[u][x].insert(v);
    a[v][x].insert(u);
}

void merge(int u, int v) {
    rem(u, v, 0);
    rem(u, v, 1);

    if (a[u][0].size()+a[u][1].size() > a[v][0].size()+a[v][1].size())
        swap(u, v);
    set<int> s0 = a[u][0];
    set<int> s1 = a[u][1];

    for (int w : s0) {
        rem(u, w, 0);
        add(v, w, 0);
    }

    for (int w : s1) {
        rem(u, w, 1);
        add(v, w, 1);
    }
}

