    cin >> n;
    for (int i = 0; i < n-1; ++i) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        add(u, v, 0);
    }

    for (int i = 0; i < n-1; ++i) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        add(u, v, 1);
    }

    for (int i = 0; i < n-1; ++i) {
        if (s.empty()) {
            cout << "NO\n";
            return 0;
        }

        pii t = (*s.begin());
        merge(t.first, t.second);
    }

    cout << "YES\n";
}

