void add(int u,int v){
	s[u].insert(v),s[v].insert(u);
	if(u>v) swap(u,v);
	M[make_pair(u,v)]++;
	if(M[make_pair(u,v)]==2) que.push(make_pair(u,v));
	return; 
}
void del(int u,int v){
	s[u].erase(v),s[v].erase(u);
	if(u>v) swap(u,v);
	M.erase(make_pair(u,v));
}
