vector<int> nullvi;

struct UF{
	vector<int> par,r;
	void init(int n){
		rep(i,n+1){
			par.pb(i);
			r.pb(0);
		}
	}
	int find(int x){
		if(par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	bool same(int x,int y){
		return find(x) == find(y);
	}
	void unit(int x,int y){
		if(same(x,y))return;
		x = find(x);
		y = find(y);
		if(r[x] < r[y]){
			par[x] = y;
		}
		else {
			par[y] = x;
			if(r[x] == r[y]){
				r[x] ++;
			}
		}
	}
};

struct HL{
	int V;
	vector<vector<int>> G;
	int x,y;
	vector<int> d[2];
	int D;
	vector<int> id;
	vector<P> loc;
	UF uf;
	vector<HL*> ch;
	vector<vector<int>> ch_ids;
	vector<int> par,root;
	void init(int _V){
		V = _V;
		rep(i,V+1){
			G.push_back(nullvi);
			d[0].push_back(-1);
			d[1].push_back(-1);
			loc.push_back(P(-1,-1));
		}
		//G = vector<vector<int>>(V+1);
	}
	void add_edge(int a,int b){
		G[a].pb(b); G[b].pb(a);
	}
	void dfs(int v,int p,int t){
		d[t][v] = d[t][p]+1;
		for(int u: G[v]){
			if(u == p)continue;
			dfs(u,v,t);
		}
	}
	void dia(){
		x = 1;
		d[0][0] = -1;
		dfs(x,0,0);
		rep1(i,V)if(d[0][i]>d[0][x])x=i;
		d[1][0] = -1;
		dfs(x,0,0);
		y = 1;
		rep1(i,V)if(d[0][i]>d[0][y])y=i;
		dfs(y,0,1);
	}
	void run_HL(){
		/*cerr << "==========" << endl;
		cerr << V << endl;
		rep1(i,V){
			for(int j: G[i]){
				cerr << i << " " << j << endl;
			}
		}*/
		dia();
		D = d[0][y];
		rep(i,D+1){
			id.push_back(-1);
		}
		rep1(i,V){
			if(d[0][i]+d[1][i] == D){
				id[d[0][i]] = i;
				loc[i] = P(-1,d[0][i]);
			}
			else loc[i] = P(-2,0);
		}
		uf.init(V);
		rep1(i,V){
			if(loc[i].fr != -2)continue;
			for(int j: G[i]){
				if(loc[j].fr == -2)uf.unit(i,j);
			}
		}
		rep1(i,V){
			if(loc[i].fr == -1)continue;
			if(loc[uf.find(i)].fr == -2){
				loc[uf.find(i)].fr = ch_ids.size();
				ch.push_back(new HL);
				ch_ids.push_back(nullvi);
				par.push_back(0);
				root.push_back(0);
				ch_ids[loc[uf.find(i)].fr].push_back(uf.find(i));
				loc[uf.find(i)].sc = 1;
			}
			if(uf.find(i) != i){
				loc[i].fr = loc[uf.find(i)].fr;
				ch_ids[loc[i].fr].push_back(i);
				loc[i].sc = ch_ids[uf.find(i)].size();
			}
		}
		rep(i,ch_ids.size()){
			ch[i]->init(ch_ids[i].size());
			int _v = ch_ids[i][0];
			par[i] = id[d[0][_v]-(d[0][_v]+d[1][_v]-D)/2];
			for(int v: ch_ids[i]){
				for(int u: G[v]){
					if(u == par[i])root[i] = v;
					else if(loc[v].sc < loc[u].sc)ch[i]->add_edge(loc[v].sc,loc[u].sc);
				}
			}
			ch[i]->run_HL();
		}
		//run_adhoc();
	}
	//void run_adhoc(){

	void out(){
		cerr << "diameter:";
		for(int v: id)cerr << v << " ";
		cerr << endl;
		rep1(i,V){
			cerr << i << ":" << loc[i].fr << " " << loc[i].sc << endl;
		}
		rep(i,ch.size()){
			cerr << "=========ch[" << i << "]==========" << endl;
			cerr << "par=" << par[i] << ",root=" << root[i] << endl;
			ch[i]->out();
		}
	}
};

