		int &x=red[i].x=read(),&y=red[i].y=read();
		lct::red_cover(x,y,i);
	}
	m=n-1;
	sta.push(1);
	while (!sta.empty()) {
		int x=sta.top();
		sta.pop();
		m-=lct::cancel(x);
	}
	puts(m?"NO":"YES");
	return 0;
}

