int ask(int x){return fa[x]==x?x:fa[x]=ask(fa[x]);}
void unite(int u,int v){
//	cout<<u<<" "<<v<<endl;
	int p=ask(u),q=ask(v);
	if(G[p].size()>G[q].size())swap(p,q),swap(u,v);
	if(p==q)return;
	fa[p]=q,yes++;
	for(iter i=G[p].begin();i!=G[p].end();i++){
		int t=*i;
		if(t==v)continue;
//		cout<<t<<" "<<q<<" "<<p<<endl;
		a[p][t]--,a[t][p]--;
		a[q][t]++,a[t][q]++;
		G[t].erase(G[t].find(p));
		G[t].insert(q),G[q].insert(t);
		if(a[q][t]>=2)Q.push(mkp(q,t));
	}
	G[p].clear();
}
