const int INF = 1000000;

struct node
{
	node *l, *r;
	int lo, hi, va;
	set<int> all;
	node(int L, int H) : l(NULL), r(NULL), lo(L), hi(H), va(0) { }
	void add(int rlo, int rhi, int v)
	{
		if (lo == rlo && hi == rhi)
		{
			va++;
			all.insert(v);
		} else
		{
			int mid = (lo+hi) / 2;
			if (rhi <= mid) l->add(rlo, rhi, v);
			else if (rlo >= mid) r->add(rlo, rhi, v);
			else
			{
				l->add(rlo, mid, v);
				r->add(mid, rhi, v);
			}
			va = min(l?l->va:INF, r?r->va:INF)+all.size();
		}
	}
	void init(int loc)
	{
		if (lo+1 == hi) return;
		int mid = (lo+hi) / 2;
		if (loc < mid) (l?l:(l=new node(lo, mid)))->init(loc);
		else (r?r:(r=new node(mid, hi)))->init(loc);
	}
	void del(int rlo, int rhi, int v)
	{
		if (lo == rlo && hi == rhi)
		{
			all.erase(v);
			va--;
		} else
		{
			int mid = (lo+hi) / 2;
			if (rhi <= mid) l->del(rlo, rhi, v);
			else if (rlo >= mid) r->del(rlo, rhi, v);
			else
			{
				l->del(rlo, mid, v);
				r->del(mid, rhi, v);
			}
			va = min(l?l->va:INF, r?r->va:INF)+all.size();
		}
	}
	void destroy(int loc)
	{
		if (lo+1 == hi)
		{
			va = INF;
			return;
		}
		int mid = (lo+hi) / 2;
		if (loc < mid) l->destroy(loc);
		else r->destroy(loc);
		va = min(l?l->va:INF, r?r->va:INF);
	}
};

