int dfs1(int at)
{
	sz[at] = 1;
	for (int u: ch[at]) if (u != par[0][at])
	{
		par[0][u] = at;
		dep[u] = dep[at] + 1;
		sz[at] += dfs1(u);
	}
	return sz[at];
}

void dfs2(int at, int _h)
{
	head[at] = _h;
	if (at == _h) tr[at] = new node(0, 131072);
	if (at) tr[_h]->init(dep[at]-dep[_h]);
	int hi = -1;
	for (int u: ch[at]) if (u != par[0][at])
		hi = max(hi, sz[u]);
	for (int u: ch[at]) if (u != par[0][at])
	{
		if (sz[u] == hi)
		{
			hi = -1;
			dfs2(u, _h);
		} else
			dfs2(u, u);
	}
}

int lca(int a, int b)
{
	if (dep[a] > dep[b]) swap(a, b);
	for (int i = 19;i >= 0;i--) if (dep[b]-(1<<i) >= dep[a])
		b = par[i][b];
	if (a == b) return a;
	for (int i = 19;i >= 0;i--) if (par[i][a] != par[i][b])
		a = par[i][a], b = par[i][b];
	return par[0][a];
}

void add(int a, int b, int v)
{
	if (a == b) return;
	if (head[a] == head[b])
	{
		tr[head[a]]->add(dep[a]-dep[head[a]]+1, dep[b]-dep[head[b]]+1, v);
	} else
	{
		tr[head[b]]->add(0, dep[b]-dep[head[b]]+1, v);
		add(a, par[0][head[b]], v);
	}
}

void destroy_requirement(int a, int b, int v)
{
	if (a == b) return;
	if (head[a] == head[b])
	{
		tr[head[a]]->del(dep[a]-dep[head[a]]+1, dep[b]-dep[head[b]]+1, v);
	} else
	{
		tr[head[b]]->del(0, dep[b]-dep[head[b]]+1, v);
		destroy_requirement(a, par[0][head[b]], v);
	}
}

void destroy_requirement(int e_id)
{
	int g = lca(A[e_id], B[e_id]);
	destroy_requirement(g, A[e_id], e_id);
	destroy_requirement(g, B[e_id], e_id);
}

void foo(int h)
{
	int who = -1;
	node *at = tr[h];
	while (at->lo+1 < at->hi)
	{
		if (at->all.size()) who = *at->all.begin();
		if (at->r == NULL) at = at->l;
		else if (at->l == NULL) at = at->r;
		else if (at->l->va < at->r->va) at = at->l;
		else at = at->r;
	}
	if (at->all.size()) who = *at->all.begin();
	destroy_requirement(who);
	tr[h]->destroy(at->lo);
}

