const int MAXN = 110000;
const int LOG = 19;
const int SQ = 300;

int was[MAXN];
int tin[MAXN];
int tout[MAXN];
int p[MAXN];
int pp[MAXN];
int up[LOG][MAXN];
vector<int> gg;
vector<pair<int, int> > vv;
pair<int, int> rmq[MAXN * 4];
int dd[MAXN * 4];
int h[MAXN];
int mn[MAXN];
int mx[MAXN];

int is_p(int a, int b) {
    return tin[a] <= tin[b] && tin[b] < tout[a];
}

int lca(int a, int b) {
    if (is_p(a, b))
        return a;
    for (int i = LOG - 1; i >= 0; --i) {
        if (!is_p(up[i][a], b))
            a = up[i][a];
    }
    return up[0][a];
}

void build() {
    int sh = vv.size() - 1;
    for (int i = 0; i < vv.size(); ++i) {
        int a = gg[vv[i].first];
        int b = gg[vv[i].second];
        int x = lca(a, b);
        rmq[i + sh] = make_pair(h[a] + h[b] - 2 * h[x], i);
    }
    for (int i = sh - 1; i >= 0; --i)
        rmq[i] = min(rmq[i * 2 + 1], rmq[i * 2 + 2]);
}

void del(int l, int r, int x) {
    l += vv.size() - 1;
    r += vv.size() - 1;
    int xl = l;
    int xr = r;
    while (l < r) {
        if (!(l & 1))
            rmq[l].first += x, dd[l] += x, ++l;
        l = (l - 1) >> 1;
        if (!(r & 1))
            --r, rmq[r].first += x, dd[r] += x;
        r = (r - 1) >> 1;
    }
    l = (xl - 1) / 2;
    while (l >= 0) {
        rmq[l] = min(rmq[l * 2 + 1], rmq[l * 2 + 2]);
        rmq[l].first += dd[l];
        l = (l - 1) >> 1;
    }
    l = (xr - 1 - 1) / 2;
    while (l >= 0) {
        rmq[l] = min(rmq[l * 2 + 1], rmq[l * 2 + 2]);
        rmq[l].first += dd[l];
        l = (l - 1) >> 1;
    }
}

int tm;
vector<int> eds[MAXN];

void dfs1(int v) {
    was[v] = 1;
    tin[v] = tm++;
    gg.push_back(v);
    for (int u: eds[v]) {
        if (!was[u]) {
            pp[u] = v;
            h[u] = h[v] + 1;
            dfs1(u);
        }
    }
    tout[v] = tm;
}

int n;

bool cmp2(pair<int, int> a, pair<int, int> b) {
    return a.second < b.second;
}

int get(int a) {
    if (a == p[a])
        return a;
    return p[a] = get(p[a]);
}

int fnd(int tl, int tr, int x) {
    int l = tl - 1;
    int r = tr;
    while (r - l > 1) {
        int mid = (l + r) >> 1;
        if (vv[mid].second >= x)
            r = mid;
        else
            l = mid;
    }
    return r;
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        scanf("%d%d", &a, &b);
        --a, --b;
        eds[a].push_back(b);
        eds[b].push_back(a);
    }
    for (int i = 0; i < n; ++i)
        p[i] = i;
    dfs1(0);
    for (int i = 0; i < n; ++i)
        up[0][i] = pp[i];
    for (int i = 1; i < LOG; ++i) {
        for (int j = 0; j < n; ++j)
            up[i][j] = up[i - 1][up[i - 1][j]];
    }
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        scanf("%d%d", &a, &b);
        --a, --b;
        if (tin[a] > tin[b])
            swap(a, b);
        vv.push_back(make_pair(tin[a], tin[b]));
    }
    sort(vv.begin(), vv.end());
    for (int i = 0; i < vv.size(); i += SQ) {
        int r = min((int)vv.size(), i + SQ);
        mn[i / SQ] = vv[i].first;
        mx[i / SQ] = vv[r - 1].first;
        sort(vv.begin() + i, vv.begin() + r, cmp2);
    }
    build();
    for (int i = 0; i < n - 1; ++i) {
        if (rmq[0].first != 1) {
            cout << "NO\n";
            return 0;
        }
        int x = rmq[0].second;
        int a = gg[vv[x].first];
        int b = gg[vv[x].second];
        int l = lca(a, b);
        int x1 = get(a);
        int x2 = get(b);
        if (h[x1] <= h[l] && h[x2] <= h[l]) {
            cout << "NO\n";
            return 0;
        }
        if (h[x1] < h[x2])
            swap(x1, x2);
        p[x1] = pp[x1];
        a = tin[x1];
        b = tout[x1];
        for (int k = 0; k * SQ < vv.size(); ++k) {
            if (mn[k] >= b || mx[k] < a)
                continue;
            int l = k * SQ;
            int r = min((k + 1) * SQ, (int)vv.size());
            if (a <= mn[k] && mx[k] < b) {
                int xx = fnd(l, r, b);
                if (xx != r)
                    del(xx, r, -1);
            }
            else {
                for (int i = l; i < r; ++i)
                    if (a <= vv[i].first && vv[i].first < b && vv[i].second >= b)
                        del(i, i + 1, -1);
            }
        }
        for (int k = 0; k * SQ < vv.size(); ++k) {
            if (mn[k] >= a)
                continue;
            int l = k * SQ;
            int r = min((k + 1) * SQ, (int)vv.size());
            if (mx[k] < a) {
                int xl = fnd(l, r, a);
                int xr = fnd(l, r, b);
                if (xl != xr)
                    del(xl, xr, -1);
            }
            else {
                for (int i = l; i < r; ++i)
                    if (a <= vv[i].second && vv[i].second < b && vv[i].first < a)
                        del(i, i + 1, -1);
            }
        }
        del(x, x + 1, MAXN * 5);
    }
    cout << "YES\n";
    return 0;
}

