// EOT

const int MAXN = 1e5 + 5;

int N;
vector<int> G0[MAXN], G1[MAXN];
std::set<Pii> E0, E1;
std::queue<Pii> q;

void input()
{
    read(N);
    for (int i = 1; i < N; ++i) {
        int u, v;
        read(u); read(v);
        if (u > v) std::swap(u, v);
        G0[u].push_back(v);
        G0[v].push_back(u);
        E0.insert(MP(u, v));
    }
    for (int i = 1; i < N; ++i) {
        int u, v;
        read(u); read(v);
        if (u > v) std::swap(u, v);
        G1[u].push_back(v);
        G1[v].push_back(u);
        E1.insert(MP(u, v));
    }
}

int fa[MAXN];

int getFather(int u)
{
    return fa[u] == u ? u : fa[u] = getFather(fa[u]);
}

void solve()
{
    for (std::set<Pii>::iterator it = E1.begin(); it != E1.end(); ++it) {
        if (E0.find(*it) != E0.end())
            q.push(*it);
    }

    int tot = 0;
    for (int i = 1; i <= N; ++i) {
        fa[i] = i;
    }
    while (!q.empty()) {
        Pii e = q.front(); q.pop();
        if (getFather(e.x) != e.x || getFather(e.y) != e.y)
            continue;
        assert(E0.find(e) != E0.end());
        assert(E1.find(e) != E1.end());
        ++tot;
        E0.erase(e);
        E1.erase(e);
        if (SZ(G0[e.x]) + SZ(G1[e.x]) > SZ(G0[e.y]) + SZ(G1[e.y]))
            std::swap(e.x, e.y);
        for (int i = 0; i < SZ(G0[e.x]); ++i) {
            int v = getFather(G0[e.x][i]);
            Pii e0(e.x, v), e1(e.y, v);
            if (e0.x > e0.y) std::swap(e0.x, e0.y);
            if (e1.x > e1.y) std::swap(e1.x, e1.y);
            if (E0.find(e0) != E0.end()) {
                E0.erase(e0);
                E0.insert(e1);
                G0[e.y].push_back(v);
                if (E1.find(e1) != E1.end())
                    q.push(e1);
            }
        }
        for (int i = 0; i < SZ(G1[e.x]); ++i) {
            int v = getFather(G1[e.x][i]);
            Pii e0(e.x, v), e1(e.y, v);
            if (e0.x > e0.y) std::swap(e0.x, e0.y);
            if (e1.x > e1.y) std::swap(e1.x, e1.y);
            if (E1.find(e0) != E1.end()) {
                E1.erase(e0);
                E1.insert(e1);
                G1[e.y].push_back(v);
                if (E0.find(e1) != E0.end())
                    q.push(e1);
            }
        }
        fa[e.x] = e.y;
    }

    puts(tot == N - 1 ? "YES" : "NO");
}

int main()
{
#ifdef __DEBUG
    freopen("E.in", "r", stdin);
    freopen("E.out", "w", stdout);
#endif

    input();
    solve();

    return 0;
}

// 无由持一碗，寄与爱茶人。
//     -- 白居易《山泉煎茶有怀》

#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int maxn = 1e5 + 50;

int n;
vector<int> t[maxn];
int h[maxn], st[maxn], ft[maxn], sz[maxn], Time, up[maxn], par[maxn];
int seg[4 * maxn], lazy[4 * maxn];
vector<int> vec[4 * maxn];
bool visited[maxn];

void shift(int, int, int);

int get(int id, int L, int R, int idx){
	while (!vec[id].empty()){
		int u = vec[id].back();
		vec[id].pop_back();
		if (visited[u])
			continue;
		return u;
	}
	shift(id, L, R);
	int mid = (L + R) >> 1;
	if (idx < mid)
		return get(2 * id + 0, L, mid, idx);
	return get(2 * id + 1, mid, R, idx);
}

pair<int,int> get(int id, int L, int R){
	if (L + 1 == R)
		return {seg[id], L};
	shift(id, L, R);
	int mid = (L + R) >> 1;
	if (seg[2 * id + 0] == seg[id])
		return get(2 * id + 0, L, mid);
	return get(2 * id + 1, mid, R);
}

void add(int id, int L, int R, int l, int r, int val, int invec){
	if (r <= L or R <= l)
		return;
	if (l <= L and R <= r){
		seg[id] += val;
		lazy[id] += val;
		if (invec != -1)
			vec[id].push_back(invec);
		return;
	}
	shift(id, L, R);
	int mid = (L + R) >> 1;
	add(2 * id + 0, L, mid, l, r, val, invec);
	add(2 * id + 1, mid, R, l, r, val, invec);
	seg[id] = min(seg[2 * id + 0], seg[2 * id + 1]);
}

void shift(int id, int L, int R){
	if (lazy[id] == 0)
		return;
	int mid = (L + R) >> 1;
	add(2 * id + 0, L, mid, L, mid, lazy[id], -1);
	add(2 * id + 1, mid, R, mid, R, lazy[id], -1);
	lazy[id] = 0;
}

void add(int v, int u, int x){
	int val = 1;
	if (x == -1)
		val = -1;
	while (up[v] != up[u]){
		if (h[up[v]] < h[up[u]])
			swap(v, u);
		add(1, 1, n, st[up[v]], st[v] + 1, val, x);
		v = par[up[v]];
	}
	if (h[v] < h[u])
		swap(v, u);
	if (h[v] != h[u])
		add(1, 1, n, st[u] + 1, st[v] + 1, val, x);
}

bool cmp(int v, int u){ return sz[v] > sz[u]; }
void dfs(int v){
	sort(t[v].begin(), t[v].end(), cmp);
	if (par[v] != -1)
		t[v].erase(t[v].begin());
	st[v] = Time ++;
	bool flag = 0;
	for (auto u : t[v]){
		if (flag == 0)
			up[u] = up[v];
		else
			up[u] = u;
		dfs(u);
		flag |= 1;
	}
	ft[v] = Time;
}

void dfs_sz(int v, int p = -1){
	sz[v] = 1;
	par[v] = p;
	for (auto u : t[v]){
		if (u != p){
			h[u] = h[v] + 1;
			dfs_sz(u, v);
			sz[v] += sz[u];
		}
	}
}

