};

node T[1<<18];

void update(int s, int d, int c, int ww = -1, int rt = 1, int l = 2, int r = N) {
	//if(l == 2 && r == N) printf("%d, %d, %d, %d\n", s, d, c, ww);
	if(s <= l && r <= d) {
		if(c == 1) T[rt].sc.insert(ww), T[rt].v++;
		else T[rt].sc.erase(ww), T[rt].v--;
		return;
	}
	int m = (l + r) >> 1;
	if(s <= m) {
		update(s, d, c, ww, rt<<1, l, m);
	}
	if(m < d) {
		update(s, d, c, ww, rt<<1|1, m+1, r);
	}
	T[rt].v = sz(T[rt].sc) + min(T[rt<<1].v, T[rt<<1|1].v);
}

void update_node(int x, int y, int c, int ww = -1) {
	if(x == y) return;
	if(head[x] == head[y]) {
		if(dep[x] > dep[y]) swap(x, y);
		update(SN[x] + 1, SN[y], c, ww);
		return;
	}
	if(dep[head[x]] < dep[head[y]]) swap(x, y);
	update(SN[head[x]], SN[x], c, ww);
	update_node(par[head[x]], y, c, ww);
}

int Find(int rt, int l, int r) {
	if(sz(T[rt].sc) == 1) {
		return *T[rt].sc.begin();
	}
	int m = (l + r) >> 1, res = -1;
	if(T[rt<<1].v < T[rt<<1|1].v) res = Find(rt<<1, l, m);
	else res = Find(rt<<1|1, m+1, r);
	return res;
}

void Fix(int rt, int l, int r) {
	if(sz(T[rt].sc)) return;
	if(l == r) {
		T[rt].v = 1e9;
		return;
	}
	int m = (l + r) >> 1;
	if(T[rt<<1].v < T[rt<<1|1].v) Fix(rt<<1, l, m);
	else Fix(rt<<1|1, m+1, r);
	T[rt].v = sz(T[rt].sc) + min(T[rt<<1].v, T[rt<<1|1].v);
}

void solve(){
	scanf("%d", &N);
	rep(i, N-1){
		int x, y; scanf("%d%d", &x, &y);
		E[x].pb(y);
		E[y].pb(x);
	}
	pre(1, -1);
	dfs(1, -1, 1);
	rep(i, N-1) {
		int x, y; scanf("%d%d", &x, &y);
		P[i] = pii(x, y);
		update_node(x, y, 1, i);
	}
	rep(i, N-1) {
		if(T[1].v != 1) {
			puts("NO");
			return;
		}
		int f = Find(1, 2, N);
		int x = P[f].Fi, y = P[f].Se;
		update_node(x, y, -1, f);
		Fix(1, 2, N);
	}
	puts("YES");
}

