void build(int p, int L, int R) {
    if (L == R) {
        st[p].se = L;
        return;
    }
    build(p << 1, L, L + R >> 1);
    build(p << 1 | 1, (L + R >> 1) + 1, R);
    st[p] = minx(st[p << 1], st[p << 1 | 1]);
}
void pushdown(int p, int L, int R) {
    if (lz[p]) {
        ss[p] += lz[p];
        st[p].fi = ss[p];
        if (L < R) {
            lz[p << 1] += lz[p];
            lz[p << 1 | 1] += lz[p];
        }
        lz[p] = 0;
    }
}
void upd(int p, int l, int r, int L, int R, int val) {
    pushdown(p, L, R);
    if (l > R || r < L) return;
    if (l <= L && r >= R) {
        lz[p] += val;
        pushdown(p, L, R);
        return;
    }
    upd(p << 1, l, r, L, L + R >> 1, val);
    upd(p << 1 | 1, l, r, (L + R >> 1) + 1, R, val);
    st[p] = minx(st[p << 1], st[p << 1 | 1]);
}

struct SegTree {
    static const int maxn = 1e5 + 5;
    set<int> st[maxn << 2];
    void add(int p, int l, int r, int L, int R, int val) {
        if (l > R || r < L) return;
        if (l <= L && r >= R) {
            st[p].insert(val);
            return;
        }
        add(p << 1, l, r, L, L + R >> 1, val);
        add(p << 1 | 1, l, r, (L + R >> 1) + 1, R, val);
    }
    void rem(int p, int l, int r, int L, int R, int val) {
        if (l > R || r < L) return;
        if (l <= L && r >= R) {
            st[p].erase(val);
            return;
        }
        rem(p << 1, l, r, L, L + R >> 1, val);
        rem(p << 1 | 1, l, r, (L + R >> 1) + 1, R, val);
    }
    int query(int p, int i, int L, int R) {
        if (i < L || i > R) return -1;
        if (sz(st[p])) return *st[p].begin();
        if (L == R) return -1;
        return max(query(p << 1, i, L, L + R >> 1), query(p << 1 | 1, i, (L + R >> 1) + 1, R));
    }
} seg;

void dfs1(int u, int dad = -1) {
    size[u] = 1;
    for (int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if (v != dad) {
            p[v] = u, lev[v] = lev[u] + 1;
            dfs1(v, u);
            size[u] += size[v];
        }
    }
}
void dfs2(int u, int h = 0, int dad = -1) {
    num[u] = cnt++, head[u] = h;
    pair<int, int> best = make_pair(-1, -1);
    for (int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if (v != dad) {
            best = max(best, make_pair(size[v], v));
        }
    }
    if (~best.second) {
        dfs2(best.second, h, u);
    }
    for (int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if (v != dad && v != best.second) {
            dfs2(v, v, u);
        }
    }
}
void upd(int u, int v, int val, int ix) {
    int hu = head[u], hv = head[v];
    while (hu != hv) {
        if (lev[hu] < lev[hv]) swap(u, v), swap(hu, hv);
        upd(1, num[hu], num[u], 0, n - 1, val);
        if (val == 1) {
            seg.add(1, num[hu], num[u], 0, n - 1, ix);
        }
        else {
            seg.rem(1, num[hu], num[u], 0, n - 1, ix);
        }
        u = p[hu], hu = head[u];
    }
    if (lev[u] > lev[v]) swap(u, v);
    upd(1, num[u] + 1, num[v], 0, n - 1, val);
    if (val == 1) {
        seg.add(1, num[u] + 1, num[v], 0, n - 1, ix);
    }
    else {
        seg.rem(1, num[u] + 1, num[v], 0, n - 1, ix);
    }
}

