template<int um> class UF {
	public:
	vector<int> par,rank;
	UF() {rank=vector<int>(um,0); for(int i=0;i<um;i++) par.push_back(i);}
	int operator[](int x) {return (par[x]==x)?(x):(par[x] = operator[](par[x]));}
	int operator()(int x,int y) {
		if((x=operator[](x))==(y=operator[](y))) return x;
		if(rank[x]>rank[y]) return par[x]=y;
		rank[x]+=rank[x]==rank[y]; return par[y]=x;
	}
};
UF<500000> uf;

int N;
set<int> E[101010];
queue<pair<int,int>> Q;

void merge(int a,int b) {
	int a2=uf[a];
	int b2=uf[b];

	uf(a,b);
	int x=uf[a];
	int y=a2+b2-x;
	if(E[x].size()<E[y].size()) swap(E[x],E[y]);
	FORR(e,E[y]) {
		int g=uf[e];
		if(E[x].count(g)) {
			Q.push({x,g});
			E[x].erase(g);
		}
		else {
			E[x].insert(g);
		}
	}
	E[y].clear();
}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;

	int id=-1;
	FOR(i,2*(N-1)) {
		cin>>x>>y;
		x--,y--;

		if(E[x].count(y)) {
			E[x].erase(y);
			Q.push({x,y});
		}
		else {
			E[x].insert(y);
		}
		if(E[y].count(x)) {
			E[y].erase(x);
			Q.push({x,y});
		}
		else {
			E[y].insert(x);
		}
	}

	FOR(i,N-1) {
		while(Q.size()) {
			auto a=Q.front();
			if(uf[a.first]!=uf[a.second]) break;
			Q.pop();
		}

		if(Q.empty()) return _P("NO\n");

		merge(Q.front().first,Q.front().second);
		Q.pop();
	}
	return _P("YES\n");
}


