	void pull(int i)
	{
		int l = L(i), r = R(i);
		if(num[l].X == 0) num[i] = num[r];
		else if(num[r].X == 0) num[i] = num[l];
		else num[i] = min(num[l], num[r]);
		return;
	}
	void push(int i)
	{
		if(tag[i])
		{
			int l = L(i), r = R(i);
			tag[l] += tag[i]; tag[r] += tag[i];
			num[l].X += tag[i]; num[r].X += tag[i];
			tag[i] = 0;
		}
		return;
	}

	void M(int a, int b, int x, int l = 1, int r = n, int k = 1)
	{
