const int N=100010;
const int M=4*N;
struct Seg {
    int add[M],mix[M];
    array<int,3> mi[M];
    void init( int id, int l, int r ) {
        if ( l==r ) {
            add[id]=0;
            mix[id]=0;
            mi[id]={{0,0,l}};
            return;
        }
        int m=(l+r)/2;
        init(id*2,l,m);
        init(id*2+1,m+1,r);
    }
    array<int,3> get_mi( int id ) {
        return {{mi[id][0]+add[id],mi[id][1]^mix[id],mi[id][2]}};
    }
    void pull( int id ) {
        mi[id]=min(get_mi(id*2),get_mi(id*2+1));
    }
    void ins( int id, int l, int r, int ql, int qr, int qa, int qs ) {
        if ( ql<=l && r<=qr ) {
            // dump(id,l,r,ql,qr,qa,qs);
            add[id]+=qa;
            mix[id]^=qs;
            return;
        }
        int m=(l+r)/2;
        if ( ql<=m ) ins(id*2,l,m,ql,qr,qa,qs);
        if ( qr>m ) ins(id*2+1,m+1,r,ql,qr,qa,qs);
        pull(id);
        // dump(id,l,r,get_mi(id));
    }
} seg;

int n;
VI e[N];

int sz[N];
int get_sz( int p, int f ) {
    sz[p]=1;
    FOR(it,e[p]) if ( *it!=f ) sz[p]+=get_sz(*it,p);
    return sz[p];
}

int st[N],ed[N],pid,fa[N],dep[N],root[N];
void dfs( int p, int f, int lv ) {
    st[p]=++pid;
    fa[p]=f;
    dep[p]=lv;
    int w=0;
    FOR(it,e[p]) if ( *it!=f && (!w || sz[*it]>sz[w]) ) w=*it;
    if ( w ) {
        root[w]=root[p];
        dfs(w,p,lv+1);
        FOR(it,e[p]) if ( *it!=f && *it!=w ) {
            root[*it]=*it;
            dfs(*it,p,lv+1);
        }
    }
    ed[p]=pid;
}

void build() {
    get_sz(1,0);
    root[1]=1;
    pid=0;
    dfs(1,0,1);
    REP1(i,1,n) dump(i,st[i]);
    seg.init(1,1,n);
}

vector<PII> get_path( int a, int b ) {
   vector<PII> v;
   while ( root[a]!=root[b] ) {
       if ( dep[root[a]]>dep[root[b]] ) swap(a,b);
       v.PB(MP(st[root[b]],st[b]));
       b=fa[root[b]];
   }
   if ( dep[a]>dep[b] ) swap(a,b);
   if ( a!=b ) v.PB(MP(st[a]+1,st[b]));
   return v;
}

int main() {
    R(n);
    REP(i,n-1) {
        int a,b;
        R(a,b);
        e[a].PB(b);
