    REP(i,n-1) R(e2[i].first,e2[i].second);
    REP(i,n-1) {
        auto p=get_path(e2[i].first,e2[i].second);
        dump(e2[i],p);
        for ( auto j:p ) {
            seg.ins(1,1,n,j.first,j.second,+1,i);
        }
    }
    seg.ins(1,1,n,1,1,N,0);
    REP(i,n-1) {
        auto x=seg.get_mi(1);
        dump(i,x);
        if ( x[0]!=1 ) {
            W("NO");
            return 0;
        }
        int id=x[1];
        assert(0<=id && id<n-1);
        auto p=get_path(e2[id].first,e2[id].second);
        for ( auto j:p ) {
            seg.ins(1,1,n,j.first,j.second,-1,id);
        }
        seg.ins(1,1,n,x[2],x[2],N,0);
    }
    W("YES");
    return 0;
}

