class E {
public:
    void solve(istream& cin, ostream& cout) {
        int N; cin >> N;
        vector<unordered_set<int>> E(N);
        vector<vector<int>> W(N);
        vector<pii> M;
        for (int i = 0; i < 2*N-2; ++i) {
            int u, v;
            cin >> u >> v;
            --u;
            --v;
            if (E[u].count(v) == 1) {
                E[u].erase(v);
                E[v].erase(u);
                W[v].push_back(M.size());
                W[u].push_back(M.size());
                M.emplace_back(u,v);
            } else {
                E[u].insert(v);
                E[v].insert(u);
            }
        }

        for (int m = 0; m < M.size(); ++m) {
            int u = M[m].x;
            int v = M[m].y;
            if (E[u].size() < E[v].size()) swap(u,v);

            for (int w: E[v]) {
                E[w].erase(v);
                if (E[u].count(w) == 1) {
                    E[u].erase(w);
                    E[w].erase(u);
                    W[v].push_back(M.size());
                    W[u].push_back(M.size());
                    M.emplace_back(u,w);
                } else {
                    E[u].insert(w);
                    E[w].insert(u);
                }
            }

            for (int ch: W[v]) {
                W[u].push_back(ch);
                if (M[ch].x == v) {
                    M[ch].x = u;
                } else if (M[ch].y == v) {
                    M[ch].y = u;
                }
            }

            E[v].clear();
        }

        cout << (M.size() == N-1 ? "YES" : "NO") << endl;
    }
};


