void solve(){
    for(int u = 0; u < n; u++){
        if(B_deg[u] == 1){
            if(leafed[u])
                elim.push(u);
            else
                leafed[u] = !leafed[u];
        }
        if(R_deg[u] == 1){
            if(!leafed[u])
                elim.push(u);
            else
