		int b = que.front().second;
		que.pop();
		if(inst.findSet(a,b)) continue;
		inst.unionSet(a,b);
		if(G[a].size() < G[b].size()) swap(a,b);
		for(auto x:G[b]) G[a].insert(x);
		G[b].clear();
		for(auto x:G[a]) que.push(make_pair(a,x));
	}

	int r = inst.root(1);
	if(G[r].size() == N) cout << "YES" << endl;
	else cout << "NO" << endl;

	return 0;
}

