void initLCA() {
    FOR(t,1,19) {
        FOR(i,1,n) {
            father[t][i] = father[t-1][father[t-1][i]];
        }
    }
}

int lca(int u, int v) {
    if (u == v) return u;

    if (h[u] < h[v]) swap(u, v);
    if (h[u] > h[v]) {
        FORD(t,19,0) {
            int x = father[t][u];
            if (h[x] >= h[v]) u = x;
        }
    }

    if (u == v) return u;

    FORD(t,19,0) if (father[t][u] != father[t][v]) {
        u = father[t][u];
        v = father[t][v];
    }
    assert(father[0][u] == father[0][v]);
    return father[0][u];
}

struct Query {
