#include <bits/stdc++.h>
using namespace std;

typedef pair<int, int> pii;
const int N = 1e5 + 100;
const pii BAD = pii(-1, -1);

int n;
struct tree {
	int par[N];
	bool dead[N];
	queue<pii> q;
	vector<int> nei[N], comp[N];
	map<pii, vector<pii>> edges;
	tree() {
		for (int i = 0; i < N; i++)
			comp[par[i] = i].push_back(i);
	}
	pii ask() {
		if (q.empty())
			return BAD;
		pii p = q.front();
		q.pop();
		return p;
	}
	pii f(pii p, pii q) {
		for (pii x: {p, q})
			if (edges[x].size())
				return edges[x].back();
		return BAD;
	}
	void normalize(pii p) {
		int U = p.first, V = p.second;
		if (dead[U] || dead[V] || U == V)
			edges[p].clear();
		while (edges[p].size()) {
			pii e = edges[p].back();
			int u = par[e.first], v = par[e.second];
			if ((U == u && V == v) || (U == v && V == u))
				break;
			//cerr << U << ' ' << V << ' ' << e.first << ' ' << e.second << ' ' << u << ' ' << v << '\n';
			edges[p].pop_back();
		}
	}
	void read() {
		for (int i = 0; i < n - 1; i++) {
			int u, v;
			cin >> u >> v;
			nei[--u].push_back(--v);
			nei[v].push_back(u);
			edges[pii(u, v)].push_back(pii(u, v));
			q.push(pii(u, v));
		}
	}
	void merge(int u, int v) {
		//abort();
		if (comp[u].size() >= comp[v].size())
			swap(u, v);
		//cerr << "merge " << u << ' ' << v << '\n';
		edges[pii(u, v)].clear();
		edges[pii(v, u)].clear();
		while (comp[u].size()) {
			int me = comp[u].back();
			comp[u].pop_back();
			comp[par[me] = v].push_back(me);

			for (int she: nei[u]) {
				int a = u, b = par[she];
				if (a != b) {
					pii A = pii(v, b);
					q.push(A);
					for (pii B: {pii(u, b), pii(b, u)}) {
						while (edges[B].size()) {
							edges[A].push_back(edges[B].back());
							edges[B].pop_back();
						}
					}
				}
			}
		}
		dead[u] = true;
	}
} blue, red;

void input() {
	cin >> n;
	blue.read();
	red.read();
}

bool can(pii p) {
	//cerr << "try " << p.first + 1 << ' ' << p.second + 1 << '\n';
	pii q = pii(p.second, p.first);
	for (pii x: {p, q}) {
		blue.normalize(x);
		red.normalize(x);
	}
	pii A = blue.f(p, q), B = red.f(p, q);
	if (min(A.first, B.first) == -1)
		return false;
	int u = blue.par[A.first], v = blue.par[A.second];
	blue.merge(u, v);
	red.merge(u, v);
	return true;
}

bool ok() {
	int want = n - 1;
	while (want) {
		pii p = blue.ask();
		if (p == BAD)
			p = red.ask();
		if (p == BAD)
			return false;
		if (can(p))
			want--;
	}
	return true;
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	input();
	cout << (ok()? "YES\n": "NO\n");
}

