int dep[maxn];
void init_dfs(int x, int prev)
{
	fo(i,1,logn) f[x][i] = f[f[x][i-1]][i-1];
	for(vet *i = root[x]; i; i = i->next) {
		if(i->v == prev) continue;
		f[i->v][0] = x; dep[i->v] = dep[x]+1;
		init_dfs(i->v, x);
	}
}
int lca(int a, int b)
{
	if(dep[a] < dep[b]) swap(a,b);
	fr(i,logn,0) if(dep[f[a][i]] >= dep[b]) a = f[a][i];
	if(a == b) return a;
	fr(i,logn,0) if(f[a][i] != f[b][i]) {
		a = f[a][i]; b = f[b][i];
	}
	return f[a][0];
}
