	cnt++;
	e[cnt].k=y;
	e[cnt].next=home[x];
	home[x]=cnt;
}
int fa[N],dep[N],son[N],siz[N],id[N],id1[N],cc,top[N];
void dfs1(int k,int F){
	fa[k]=F;dep[k]=dep[F]+1;
	siz[k]=1;
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F){
		dfs1(e[i].k,k);
		siz[k]+=siz[e[i].k];
		if(siz[e[i].k]>siz[son[k]]) son[k]=e[i].k;
	}
}
void dfs2(int k,int tp){
	top[k]=tp;id[k]=++cc;id1[cc]=k;
	if(son[k]) dfs2(son[k],tp);
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=fa[k]&&e[i].k!=son[k]){
		dfs2(e[i].k,e[i].k);
	}
}
