int main() {
	int n;

	cin >> n;
	for (int i = 1; i < n; ++i) {
		int a, b;
		cin >> a >> b;
		blue[a].insert(b);
		blue[b].insert(a);
	}

	for (int i = 1; i < n; ++i) {
		int a, b;
		cin >> a >> b;
		red[a].insert(b);
		red[b].insert(a);
		if (blue[a].find(b) != blue[a].end())
			q.emplace(a, b);
	}

	iota(parent + 1, parent + n + 1, 1);

	int cnt = 0;
	while (!q.empty()) {
		++cnt;

		auto p = q.front();
		q.pop();

		int x = getRoot(p.first), y = getRoot(p.second);

		if (blue[x].size() + red[x].size() < blue[y].size() + red[y].size()) swap(x, y);
		parent[y] = x;

		blue[x].erase(y);
		blue[y].erase(x);
		red[x].erase(y);
		red[y].erase(x);

		for (auto &&dest: blue[y]) {
			if (red[x].find(dest) != red[x].end()) q.emplace(x, dest);
		}

		for (auto &&dest: red[y]) {
			if (blue[x].find(dest) != blue[x].end()) q.emplace(x, dest);
			red[x].insert(dest);
			red[dest].erase(y);
			red[dest].insert(x);
		}
		red[y].clear();

		for (auto &&dest: blue[y]) {
			blue[x].insert(dest);
			blue[dest].erase(y);
			blue[dest].insert(x);
		}
		blue[y].clear();
	}

	if (cnt == n - 1) cout << "YES" << endl; else cout << "NO" << endl;

	return 0;
}

