	for(int i = 0; i < n - 1; i++)
	{
		int u, v;
		cin >> u >> v;
		G[u].push_back(v);
		G[v].push_back(u);
	}
}

segment_tree t;

void pre_dfs(int u, int pr)
{
	tr_sz[u] = 1;
	for(int v: G[u])
		if(v != pr)
		{
			pre_dfs(v, u);
			tr_sz[u] += tr_sz[v];
		}
}

void decompose(int u, int head, int pr, int dep = 0)
{
	par[u][0] = pr;
	for(int l = 1; l <= lgn; l++)
		par[u][l] = par[par[u][l - 1]][l - 1];

    de[u] = dep;
	st[u] = ++dfs_time;
	vert[dfs_time] = u;
	::head[u] = head;

	pair<int, int> mx = {-1, -1};
	for(int v: G[u])
		if(v != pr)
			mx = max(mx, {tr_sz[v], v});

	if(mx.second != -1)
		decompose(mx.second, head, u, dep + 1);

	for(int v: G[u])
		if(v != pr && v != mx.second)
			decompose(v, v, u, dep + 1);

	en[u] = dfs_time;
}

inline bool upper(int u, int v) { return st[u] <= st[v] && en[v] <= en[u]; }

int lca(int u, int v)
{
	if(upper(u, v)) return u;
	if(upper(v, u)) return v;

	for(int l = lgn; l >= 0; l--)
		if(!upper(par[u][l], v))
			u = par[u][l];

	return par[u][0];
}

void hld_precompute(int _root)
{
	root = _root;
	lgn = 0; while((1 << lgn) < n) lgn++;
	dfs_time = 0;

	pre_dfs(root, root);
	decompose(root, root, root);
}

node get_path(int u, int anc)
{
	node ret = broken;
	while(st[anc] < st[u])
	{
		ret = merge(ret, t.query(max(st[anc] + 1, st[head[u]]), st[u], 1, dfs_time, 0));
		u = par[head[u]][0];
	}

	return ret;
}

void add_path(int u, int anc, int val)
{
	while(st[anc] < st[u])
	{
		t.add(max(st[anc] + 1, st[head[u]]), st[u], val, 1, dfs_time, 0);
		u = par[head[u]][0];
	}
}

node query(int u, int v)
{
    int anc = lca(u, v);
    node ret = merge(get_path(u, anc), get_path(v, anc));
    return ret;
}

void add(int u, int v, int val)
{
    int anc = lca(u, v);
    add_path(u, anc, val);
    add_path(v, anc, val);
}

int dist(int u, int v) { return de[u] + de[v] - 2 * de[lca(u, v)]; }

set<pair<int, int> > stt;

void gen_path(int u, int anc, int idx)
{
	while(st[anc] < st[u])
	{
		stt.insert({st[u], idx});
		u = par[head[u]][0];
	}
}

void rem_path(int u, int anc, int idx)
{
	while(st[anc] < st[u])
	{
		stt.erase({st[u], idx});
		u = par[head[u]][0];
	}
}

void gen(int u, int v, int val)
{
    int anc = lca(u, v);
    gen_path(u, anc, val);
    gen_path(v, anc, val);
}

void rem(int u, int v, int val)
{
    int anc = lca(u, v);
    rem_path(u, anc, val);
    rem_path(v, anc, val);
}

void solve()
{
	hld_precompute(1);
	t.init(1, dfs_time, 0);

	vector<pair<int, int> > e;

    for(int i = 0; i < n - 1; i++)
    {
        int u, v;
        cin >> u >> v;
        add(u, v, 1);
        gen(u, v, i);
        e.push_back({u, v});
    }

    for(int ii = 0; ii < n - 1; ii++)
    {
        pair<int, int> mx = t.query(2, dfs_time, 1, dfs_time, 0).mn;
        if(mx.first != 1)
        {
            cout << "NO" << endl;
            return;
        }

        int i = stt.lower_bound({mx.second, -inf})->second, u = e[i].first, v = e[i].second;
        mx = query(u, v).mx;

        if(mx.first != 1)
        {
            cout << "NO" << endl;
            return;
        }

        add(u, v, -1);
        t.del(mx.second, 1, dfs_time, 0);
        rem(u, v, i);
    }

    cout << "YES" << endl;
}

