	node2(pair<int, int> val)
	{
		mx = val;
	}
};

node2 temp2, broken2;

node2 merge(node2 l, node2 r)
{
	temp2.mx = max(l.mx, r.mx);
	return temp2;
}

struct segment_tree2
{
    multiset<pair<int, int> > st[4 * MAXN];
	node2 tr[4 * MAXN];

	void init(int l, int r, int idx)
	{
		if(l == r)
		{
			tr[idx] = node2();
			return;
		}

		int mid = (l + r) >> 1;
		init(l, mid, 2 * idx + 1);
		init(mid + 1, r, 2 * idx + 2);

		tr[idx] = merge(tr[2 * idx + 1], tr[2 * idx + 2]);
	}

	void erase(int pos, pair<int, int> val, int l, int r, int idx)
	{
		if(l > pos || r < pos)
			return;

		if(l == r && l == pos)
		{
            st[idx].erase(st[idx].find(val));
			if(st[idx].empty()) tr[idx].mx = {-1e9, -1e9};
			else tr[idx].mx = *prev(st[idx].end());
			return;
		}

		int mid = (l + r) >> 1;
		erase(pos, val, l, mid, 2 * idx + 1);
		erase(pos, val, mid + 1, r, 2 * idx + 2);

		tr[idx] = merge(tr[2 * idx + 1], tr[2 * idx + 2]);
	}


	void update(int pos, pair<int, int> val, int l, int r, int idx)
	{
		if(l > pos || r < pos)
			return;

		if(l == r && l == pos)
		{
            st[idx].insert(val);
			if(st[idx].empty()) tr[idx].mx = {-1e9, -1e9};
			else tr[idx].mx = *prev(st[idx].end());
			return;
		}

		int mid = (l + r) >> 1;
		update(pos, val, l, mid, 2 * idx + 1);
		update(pos, val, mid + 1, r, 2 * idx + 2);

		tr[idx] = merge(tr[2 * idx + 1], tr[2 * idx + 2]);
	}

	node2 query(int qL, int qR, int l, int r, int idx)
	{
		if(l > qR || r < qL)
			return broken2;

		if(qL <= l && r <= qR)
			return tr[idx];

		int mid = (l + r) >> 1;
		return merge(query(qL, qR, l, mid, 2 * idx + 1), query(qL, qR, mid + 1, r, 2 * idx + 2));
	}
};

