    	int m = D.front();
    	D.pop();
    	x++;
    	set<int> f;
    	for (auto it : G[m]) {
    		G[it].erase(m);
    		f.insert(it);
    	}
    	for (auto it : T[m]) {
    		T[it].erase(m);
    		f.insert(it);
    	}
    	G[m].clear();
    	T[m].clear();
    	for (auto it : f) {
    		if (G[it].size() <= 1 && T[it].size() <= 1 && E.find(it) == E.end()) {
    			D.push(it);
    			E.insert(it);
    		}
    	}
    }
    if (E.size() == N) cout << "YES" << endl;
    else cout << "NO" << endl;
    return 0;
}

