int is_p(int a, int b) {
    return tin[a] <= tin[b] && tin[b] < tout[a];
}

int lca(int a, int b) {
    if (is_p(a, b))
        return a;
    for (int i = LOG - 1; i >= 0; --i) {
        if (!is_p(up[i][a], b))
            a = up[i][a];
    }
    return up[0][a];
}

void build(int v, int tl, int tr) {
    if (tl + 1 == tr) {
        int a = gg[vv[tl].first];
        int b = gg[vv[tl].second];
        int x = lca(a, b);
        rmq[v] = make_pair(h[a] + h[b] - 2 * h[x], tl);
        return;
    }
    int m = (tl + tr) >> 1;
    build(v * 2 + 1, tl, m);
    build(v * 2 + 2, m, tr);
    rmq[v] = min(rmq[v * 2 + 1], rmq[v * 2 + 2]);
}

void del(int v, int tl, int tr, int l, int r, int x) {
    if (r <= tl || tr <= l)
        return;
    if (l <= tl && tr <= r) {
        dd[v] += x;
        rmq[v].first += x;
        return;
    }
    int m = (tl + tr) >> 1;
    del(v * 2 + 1, tl, m, l, r, x);
    del(v * 2 + 2, m, tr, l, r, x);
    rmq[v] = min(rmq[v * 2 + 1], rmq[v * 2 + 2]);
    rmq[v].first += dd[v];
}

int tm;
vector<int> eds[MAXN];

void dfs1(int v) {
    was[v] = 1;
    tin[v] = tm++;
    gg.push_back(v);
    for (int u: eds[v]) {
        if (!was[u]) {
            pp[u] = v;
            h[u] = h[v] + 1;
            dfs1(u);
        }
    }
    tout[v] = tm;
}

int n;

bool cmp2(pair<int, int> a, pair<int, int> b) {
    return a.second < b.second;
}

int get(int a) {
    if (a == p[a])
        return a;
    return p[a] = get(p[a]);
}

int fnd(int tl, int tr, int x) {
    int l = tl - 1;
    int r = tr;
    while (r - l > 1) {
        int mid = (l + r) >> 1;
        if (vv[mid].second >= x)
            r = mid;
        else
            l = mid;
    }
    return r;
}

int main() {
