    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        scanf("%d%d", &a, &b);
        --a, --b;
        eds[a].push_back(b);
        eds[b].push_back(a);
    }
    for (int i = 0; i < n; ++i)
        p[i] = i;
    dfs1(0);
    for (int i = 0; i < n; ++i)
        up[0][i] = pp[i];
    for (int i = 1; i < LOG; ++i) {
        for (int j = 0; j < n; ++j)
            up[i][j] = up[i - 1][up[i - 1][j]];
    }
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        scanf("%d%d", &a, &b);
        --a, --b;
        if (tin[a] > tin[b])
            swap(a, b);
        vv.push_back(make_pair(tin[a], tin[b]));
    }
    sort(vv.begin(), vv.end());
    for (int i = 0; i < vv.size(); i += SQ) {
        int r = min((int)vv.size(), i + SQ);
        mn[i / SQ] = vv[i].first;
        mx[i / SQ] = vv[r - 1].first;
        sort(vv.begin() + i, vv.begin() + r, cmp2);
    }
    build(0, 0, vv.size());
    for (int i = 0; i < n - 1; ++i) {
        if (rmq[0].first != 1) {
            cout << "NO\n";
            return 0;
        }
        int x = rmq[0].second;
        int a = gg[vv[x].first];
        int b = gg[vv[x].second];
        int l = lca(a, b);
        int x1 = get(a);
        int x2 = get(b);
        if (h[x1] <= h[l] && h[x2] <= h[l]) {
            cout << "NO\n";
            return 0;
        }
        if (h[x1] < h[x2])
            swap(x1, x2);
        p[x1] = pp[x1];
        a = tin[x1];
        b = tout[x1];
        for (int k = 0; k * SQ < vv.size(); ++k) {
            if (mn[k] >= b || mx[k] < a)
                continue;
            int l = k * SQ;
            int r = min((k + 1) * SQ, (int)vv.size());
            if (a <= mn[k] && mx[k] < b) {
                int xx = fnd(l, r, b);
                if (xx != r)
                    del(0, 0, vv.size(), xx, r, -1);
            }
            else {
                for (int i = l; i < r; ++i)
                    if (a <= vv[i].first && vv[i].first < b && vv[i].second >= b)
                        del(0, 0, vv.size(), i, i + 1, -1);
            }
        }
        for (int k = 0; k * SQ < vv.size(); ++k) {
            if (mn[k] >= a)
                continue;
            int l = k * SQ;
            int r = min((k + 1) * SQ, (int)vv.size());
            if (mx[k] < a) {
                int xl = fnd(l, r, a);
                int xr = fnd(l, r, b);
                if (xl != xr)
                    del(0, 0, vv.size(), xl, xr, -1);
            }
            else {
                for (int i = l; i < r; ++i)
                    if (a <= vv[i].second && vv[i].second < b && vv[i].first < a)
                        del(0, 0, vv.size(), i, i + 1, -1);
            }
        }
        del(0, 0, vv.size(), x, x + 1, MAXN * 5);
