void dfs1(int t, int f = 0, int d = 1)
{
    siz[t] = 1; dep[t] = d; fa[t] = f;
    for (int i = 0; i < bi[t].size(); ++ i)
        if (bi[t][i] != f)
        {
            dfs1(bi[t][i], t, d + 1);
            siz[t] += siz[bi[t][i]];
            if (siz[bi[t][i]] > siz[mxc[t]]) mxc[t] = bi[t][i];
        }
}
void dfs2(int t, int p = 1)
{
    lst[++ tot] = t; inl[tot] = t; fp[t] = p;
    if (mxc[t]) dfs2(mxc[t], p);
    for (int i = 0; i < bi[t].size(); ++ i)
        if (bi[t][i] != fa[t] && bi[t][i] != mxc[t])
            dfs2(bi[t][i], bi[t][i]);
}
int lb[N], rb[N], lc[N], rc[N], na[N], nb[N], ta[N];
int build(int l, int r)
{
    int t = ++ tot;
    lb[t] = l; rb[t] = r;
    if (l != r)
    {
        lc[t] = build(l, (l + r) / 2);
        rc[t] = build((l + r) / 2 + 1, r);
    }
    return t;
}
void psdw(int t)
{
    na[lc[t]] += ta[t]; ta[lc[t]] += ta[t];
    na[rc[t]] += ta[t]; ta[rc[t]] += ta[t];
    ta[t] = 0;
    nb[lc[t]] += nb[t]; nb[rc[t]] += nb[t];
    nb[t] = 0;
}
void upd(int t)
{
    na[t] = min(na[lc[t]], na[rc[t]]);
}
void cg(int t, int l, int r, int a, int b)
{
    if (l <= lb[t] && rb[t] <= r)
    {
        ta[t] += a;
        na[t] += a;
        nb[t] += b;
        return;
    }
    psdw(t);
    if (l <= rb[lc[t]]) cg(lc[t], l, r, a, b);
    if (r >= lb[rc[t]]) cg(rc[t], l, r, a, b);
    upd(t);
}
int ask(int t)
{
    int w;
    if (lb[t] == rb[t])
    {
        na[t] += 1000000;
        return nb[t];
    }
    psdw(t);
    if (na[lc[t]] < na[rc[t]]) w = ask(lc[t]);
    else w = ask(rc[t]);
    upd(t);
    return w;
}
void put(int u, int v, int a, int b)
{
    // cerr << u << " " << v << endl;
    while (u != v)
    {
        if (fp[u] == fp[v])
        {
            if (dep[u] > dep[v]) swap(u, v);
            cg(1, inl[u] + 1, inl[v], a, b);
            return;
        }
        if (dep[fp[u]] < dep[fp[v]]) swap(u, v);
        cg(1, inl[fp[u]], inl[u], a, b);
        u = fa[fp[u]];
    }
}
