bool cmp(int a, int b) {
	return sz[a] > sz[b];
}

void relax(int id) {
	int x = lazy[id];
	lazy[id] = 0;
	mn[2 * id + 0] += x;
	lazy[2 * id + 0] += x;
	mn[2 * id + 1] += x;
	lazy[2 * id + 1] += x;
}

void build(int id, int L, int R) {
	seg[id] = L;
	if (R == L + 1)
		return;
	int mid = (L + R) / 2;
	build(2 * id + 0, L, mid);
	build(2 * id + 1, mid, R);
}

void add(int id, int L, int R, int l, int r, int x) {
	if (R <= l || r <= L)
		return;
	if (L >= l && R <= r) {
		mn[id] += x;
		lazy[id] += x;
		return;
	}
	relax(id);
	int mid = (L + R) / 2;
	add(2 * id + 0, L, mid, l, r, x);
	add(2 * id + 1, mid, R, l, r, x);
	mn[id] = min(mn[2 * id], mn[2 * id + 1]);
	if (mn[id] == mn[2 * id + 0])
		seg[id] = seg[2 * id + 0];
	else
		seg[id] = seg[2 * id + 1];
}

void push(int id, int L, int R, int l, int r, int x) {
	if (R <= l || r <= L)
		return;
	if (L >= l && R <= r) {
		vec[id].push_back(x);
		return;
	}
	int mid = (L + R) / 2;
	push(2 * id + 0, L, mid, l, r, x);
	push(2 * id + 1, mid, R, l, r, x);
}

int back(int id, int L, int R, int idx) {
	if (idx < L || idx >= R) {
		return 0;
	}
	while (vec[id].size() && mark[vec[id].back()])
		vec[id].pop_back();
	if (vec[id].size())
		return vec[id].back();
	int mid = (L + R) / 2;
	return max(back(2 * id + 0, L, mid, idx), back(2 * id + 1, mid, R, idx));
}

void getsz(int v, int p = -1) {
	sz[v] = 1;
	for (int u: adj[v]) {
		if (u != p) {
			par[u] = v;
			h[u] = h[v] + 1;
			ch[v].push_back(u);
			getsz(u, v);
			sz[v] += sz[u];
		}
	}
}

void dfs(int v) {
	st[v] = T++;
	bool heavy = 0;
	sort(ch[v].begin(), ch[v].end(), cmp);
	for (auto u: ch[v]) {
		if (heavy) {
			heavy = 0;
			up[u] = up[v];
		}
		else
			up[u] = u;
		dfs(u);
	}
}

void add(int v, int u, int i) {
	while (up[v] != up[u]) {
		if (h[up[v]] < h[up[u]]) {
			swap(v, u);
		}
		add(1, 0, n, st[up[v]], st[v] + 1, +1);
		push(1, 0, n, st[up[v]], st[v] + 1, i);
		v = par[up[v]];
	}
	if (v == u)
		return;
	if (h[v] < h[u])
		swap(v, u);
	add(1, 0, n, st[u] + 1, st[v] + 1, +1);
	push(1, 0, n, st[u] + 1, st[v] + 1, i);
}

void rem(int v, int u, int i) {
	mark[i] = 1;
	while (up[v] != up[u]) {
		if (h[up[v]] < h[up[u]]) {
			swap(v, u);
		}
		add(1, 0, n, st[up[v]], st[v] + 1, -1);
		v = par[up[v]];
	}
	if (v == u)
		return;
	if (h[v] < h[u])
		swap(v, u);
	add(1, 0, n, st[u] + 1, st[v] + 1, -1);
}

