typedef long long ll;

const int N = 1e5 + 7;
const int K = 20;

int dp[N];
int cnt[N];
int tin[N], tout[N];
int st[N][K];
int sz;
vector <int> g[N];

void dfs(int v, int pr)
{
    tin[v] = sz++;
    st[v][0] = pr;
    for (int i = 1; i < K; i++)
    {
        st[v][i] = st[st[v][i - 1]][i - 1];
    }
    for (auto to : g[v])
    {
        if (to != pr)
        {
            dfs(to, v);
        }
    }
    tout[v] = sz++;
}

bool pr(int a, int b)
{
    return tin[a] <= tin[b] && tout[a] >= tout[b];
}

int lca(int a, int b)
{
    if (pr(a, b))
    {
        return a;
    }
    for (int i = K - 1; i >= 0; i--)
    {
        if (!pr(st[a][i], b))
        {
            a = st[a][i];
        }
    }
    return st[a][0];
}

void de(int v, int pr)
{
    dp[v] = cnt[v];
    for (auto to : g[v])
    {
        if (to != pr)
        {
            de(to, v);
        }
        dp[v] += dp[to];
    }
}

