	lt[now].lz=0;
}
void upd(int now)
{
	int lc=lt[now].lc,rc=lt[now].rc;
	if(lt[lc].lz) down(lc);
	if(lt[rc].lz) down(rc);
	if(lt[lc].mi<lt[rc].mi) lt[now].mi=lt[lc].mi,lt[now].p=lt[lc].p;
	else lt[now].mi=lt[rc].mi,lt[now].p=lt[rc].p;
}
void bt(int l,int r)
{
	int now=++tl;
	lt[now].l=l;lt[now].r=r;
	if(l<r)
	{
		int mid=(l+r)/2;
		lt[now].lc=tl+1;bt(l,mid);
		lt[now].rc=tl+1;bt(mid+1,r);
		upd(now);
	}
	else {lt[now].p=l;if(l==1) lt[now].mi=inf;}
}
void change(int now,int l,int r,int k,int d)
{
	int lc=lt[now].lc,rc=lt[now].rc,mid=(lt[now].l+lt[now].r)/2;
	if(lt[now].lz) down(now);
	if(lt[now].l==l && lt[now].r==r)
