	if(mid>=r) change(lc,l,r,k,d);
	else if(l>mid) change(rc,l,r,k,d);
	else change(lc,l,mid,k,d),change(rc,mid+1,r,k,d);
	upd(now);
}
void modify(int x,int y,int k,int d)
{
	int fx=t[x].tp,fy=t[y].tp;
	while(fx!=fy)
	{
		if(t[fx].dep<t[fy].dep) swap(fx,fy),swap(x,y);
		change(1,dfn[fx],dfn[x],k,d);
		x=t[fx].fa;fx=t[x].tp;
	}
	if(x==y) return;
	if(dfn[x]>dfn[y]) swap(x,y);
	change(1,dfn[x]+1,dfn[y],k,d);
}
