const int maxn = 1E5 + 10;
typedef pair <int,int> pr;

int n,cnt,du[maxn];
bool vis[maxn];

queue <pr> Q;
map <pr,int> E;

vector <int> v[maxn];

inline void Add(int x,int y)
{
	if (x > y) swap(x,y);
	pr now = mp(x,y); ++E[now];
	if (E[now] > 1) Q.push(now);
	++du[x]; v[x].push_back(y);
	++du[y]; v[y].push_back(x);
}

int main()
{
	#ifdef DMC
		freopen("DMC.txt","r",stdin);
	#endif

	cin >> n;
	for (int i = 1; i < n; i++)
	{
		int x,y; scanf("%d%d",&x,&y);
		if (x > y) swap(x,y); ++du[x]; ++du[y];
		++E[mp(x,y)]; v[x].push_back(y); v[y].push_back(x);
	}
	for (int i = 1; i < n; i++)
	{
		int x,y; scanf("%d%d",&x,&y);
		if (x > y) swap(x,y); ++du[x]; ++du[y];
		++E[mp(x,y)]; v[x].push_back(y); v[y].push_back(x);
	}
	for (int i = 1; i <= n; i++)
		for (int j = 0; j < v[i].size(); j++)
		{
			pr now = mp(i,v[i][j]);
			if (E[now] > 1) Q.push(now);
		}
	while (!Q.empty())
	{
		pr k = Q.front(); Q.pop();
		if (vis[k.fr] || vis[k.sc]) continue;
		int x = k.fr,y = k.sc; ++cnt;
		if (du[x] < du[y]) swap(x,y); vis[y] = 1;
		for (int i = 0; i < v[y].size(); i++)
			if (v[y][i] != x && !vis[v[y][i]]) Add(x,v[y][i]);
	}
	puts(cnt == n - 1 ? "YES" : "NO");
	return 0;
}

