    return 1ll*n*y+x;
}
void addEdge(int u,int v){
    s[u].insert(v);
    s[v].insert(u);
    ll eid=getID(u,v);
    int t=g[eid]+1;
    g[eid]++;
    if(t==2)
        q.push(mp(u,v));
}
void removeEdge(int u,int v){
    s[u].erase(v);
    s[v].erase(u);
    g.erase(getID(u,v));
}
