            return false;
        u=q.front().first;
        v=q.front().second;
        q.pop();
        u=find(u); 
        v=find(v);
        if(s[u].size()>s[v].size())
            swap(u,v);
        bl[u]=v;
        removeEdge(u,v);
        for(sit i=s[u].begin(),j;i!=s[u].end();i=j){
            j=i;
            j++;
            int x=*i;
            x=find(x);
            removeEdge(u,x);
            addEdge(v,x);
        }
    }
