      return;
    }
    push(i,a,b);
    int c = (a+b)/2;
    kill_(2*i  , a  , c, l, r);
    kill_(2*i+1, c+1, b, l, r);
    update(i);
  }

  void kill(int l, int r){
    kill_(1, 0, n-1, l, r);
  }

  void add__(int i, int, int, pii v){
    A[i].data.insert(v);
    A[i].minVal.x() += 1;
    A[i].minVal.z() = v;
  }

  void add_(int i, int a, int b, int l, int r, pii v) {
    if(l > b) return;
    if(r < a) return;
    if(l <= a && b <= r){
      add__(i, a, b, v);
      return;
    }
    push(i,a,b);
    int c = (a+b)/2;
    add_(2*i  , a  , c, l, r, v);
    add_(2*i+1, c+1, b, l, r, v);
    update(i);
  }

  void add(int l, int r, pii v){
    add_(1, 0, n-1, l, r, v);
  }

  void rem__(int i, int, int, pii v){
    A[i].data.erase(v);
    A[i].minVal.x()--;
    if(!A[i].data.empty()) {
      A[i].minVal.z() = *A[i].data.begin();
    }
    update(i);
  }

  void rem_(int i, int a, int b, int l, int r, pii v) {
    if(l > b) return;
    if(r < a) return;
    if(l <= a && b <= r){
      rem__(i, a, b, v);
      return;
    }
    push(i,a,b);
    int c = (a+b)/2;
    rem_(2*i  , a  , c, l, r, v);
    rem_(2*i+1, c+1, b, l, r, v);
    update(i);
  }

  void rem(int l, int r, pii v){
    rem_(1, 0, n-1, l, r, v);
  }

  node get_(int i, int a, int b, int l, int r) {
    if(l > b) return node();
    if(r < a) return node();
    if(l <= a && b <= r){
      return A[i];
    }
    push(i,a,b);
    int c = (a+b)/2;
    node ar = get_(2*i  , a  , c, l, r);
    node br = get_(2*i+1, c+1, b, l, r);
    node res;
    res.combine(ar,br);
    return res;
  }

  auto get(int l, int r){
    node a = get_(1, 0, n-1, l, r);
    return a.minVal;
  }
};

struct treechain {
  lli root = -1;
  lli size = 0;
  vi  nodes;

  treechain() { }

#ifdef WITH_HLD
  using segment = segment_tree; // segment tree / bit / other
  segment A;
  void build(){ A = segment(size); /* make segment tree */ }
#else
  void build(){ }
#endif
};

struct tree {
  lli n;
  vvi G;

  vi parent;
  vi depth;
  vi size;
  vi order, rorder;
  vii eorder;

  vector<treechain> chains;
  vector<lli>       chain;
  vector<lli>       chainIx;

  tree(lli n_) : n(n_), G(n) { }

  void read_graph(istream& input = cin) {
    FOR(i, n-1) {
      lli u, v; input >> u >> v;
      u -= 1; v -= 1;
      G[u].pb(v); G[v].pb(u);
    }
  }

  void calcparent() {
    if(parent.empty()) {
      parent.assign(n, -1);
      order.clear();
      vi E(n, 0);
      vector<lli> Q; Q.pb(0);
      while(!Q.empty()) {
        lli i = Q.back(); Q.pop_back();
        order.pb(i);
        E[i] = 1;
        for(auto j : G[i]) if(!E[j]) {
            parent[j] = i;
            Q.pb(j);
          }
      }
      rorder = order;
      reverse(all(rorder));
    }
  }

  template<typename T>
  inline vector<vector<T> > makeEVec(T const& def = T()) {
    vector<vector<T> > v(n); FOR(i, n) v[i].assign(G[i].size(), def);
    return v;
  }

  void calceorder() {
    if(eorder.empty()) {
      eorder.reserve(2*n);
      vi E1(n); vi R(n,0);
      auto E = makeEVec(false);
      FOR(i, n) FOR(j_, G[i].size()) if(!E[i][j_]) {
        vii Q; Q.pb(mt(i,j_));
        vii tmp;
        while(!Q.empty()) {
          DESTRUCT2(Q.back(), i, j_); Q.pop_back();
          tmp.pb(mt(i, j_)); E[i][j_] = 1;
          lli j = G[i][j_];
          if(!E1[j]) {
            E1[j]=1;
            FOR(k_, G[j].size()) {
              if(G[j][k_] == i) R[j]=k_;
              if(G[j][k_] != i && !E[j][k_]) Q.pb(mt(j, k_));
            }
          }else{
            if(G[j][R[j]]!=i && !E[j][R[j]]) Q.pb(mt(j,R[j]));
          }
        }
        reverse(all(tmp));
        eorder.insert(end(eorder), all(tmp));
      }
    }
  }

  void calcsize() {
    calcparent();
    if(size.empty()) {
      size.assign(n, 1);
      for(auto i : rorder) if(parent[i]!=-1) size[parent[i]] += size[i];
    }
  }

  void calcdepth() {
    calcparent();
    if(depth.empty()) {
      depth.assign(n, 0);
      for(auto i : order) if(parent[i] != -1) depth[i] = depth[parent[i]] + 1;
    }
  }

  void calchld() {
    if(chains.empty()){
      calcsize();
      calcdepth();

      chain.assign(n, -1);
      for(auto i : rorder) {
        lli best = -1;
        for(auto j : G[i]) if(j != parent[i]) {
            if(best == -1 || size[j] > size[best]) best = j;
          }
        if(best == -1) {
          chain[i] = chains.size();
          chains.eb();
        }else{
          chain[i] = chain[best];
        }
        chains[chain[i]].size += 1;
      }

      chainIx.assign(n, -1);
      for(auto i : order) {
        if(parent[i]==-1 || chain[i] != chain[parent[i]]) chains[chain[i]].root = i;
        chainIx[i] = chains[chain[i]].nodes.size();
        chains[chain[i]].nodes.pb(i);
      };

      for(auto& c : chains) c.build();
    }
  }

  // O(log n) lca
  lli lca(lli a, lli b) {
    calchld();
    while(chain[a] != chain[b]) {
      if(depth[chains[chain[a]].root]>depth[chains[chain[b]].root]) {
        a = parent[chains[chain[a]].root];
      }else{
        b = parent[chains[chain[b]].root];
      }
    }
    if(depth[a]<depth[b]) return a; else return b;
  }

  lli dist(lli a, lli b) {
    calchld();
    return depth[a]+depth[b]-2*depth[lca(a, b)];
  }

#ifdef WITH_HLD
  // arguments to f :
  // segment, segment range, range in path from a to b (a = 0, b = dist(a, b))
  // the segment range is increasing
  // the range in path can be decreasing
  // O (log² n)
  void hld_query(lli a, lli b, function<void(treechain::segment&, lli, lli, lli, lli)> f) {
    calchld();
    lli from = 0, to = dist(a, b);
    while(chain[a] != chain[b]) {
      if(depth[chains[chain[a]].root]>depth[chains[chain[b]].root]) {
        lli a_ = parent[chains[chain[a]].root];
        lli d = depth[a]-depth[a_];
        f(chains[chain[a]].A, 0, chainIx[a], from+d, from);
        from += d;
        a = a_;
      }else{
        lli b_ = parent[chains[chain[b]].root];
        lli d = depth[b]-depth[b_];
        f(chains[chain[b]].A, 0, chainIx[b], to-d, to);
        to -= d;
        b = b_;
      }
    }
    if(depth[a]<depth[b]) {
      f(chains[chain[a]].A, chainIx[a]+1, chainIx[b], from, to);
    }else{
      f(chains[chain[a]].A, chainIx[b]+1, chainIx[a], from, to);
    }
  }
#endif
};

