void dofail() {
  cout << "NO" << endl;
  exit(0);
}

int main(){
  ios::sync_with_stdio(0); cin.tie(0);
  int n; cin>>n;
  tree tr(n); tr.read_graph();
  tr.calchld();
  for(auto& ch:tr.chains) {
    auto &A=ch.A;
    FOR(i,ch.size-1) {
      A.A[A.n+i+1] = segment_tree::node(mt(ch.nodes[i],ch.nodes[i+1]));
    }
    if(ch.root != -1) {
      A.A[A.n] = segment_tree::node(mt(ch.root,ch.nodes[0]));
    }
    A.build();
  }
  vii G;
  vector<tpl<treechain::segment*,int,int>> Q;
  FOR(i,n-1) {
    int a,b; cin>>a>>b; --a; --b;
    tr.hld_query(a,b,[&](treechain::segment& ch, lli l, lli r, lli, lli) {
        ch.add(l,r,mt(a,b));
        auto p = ch.get(l,r);
        if(p.x() == 1) Q.pb(mt(&ch,l,r));
      });
    G.pb(mt(a,b));
  }
  set<pii> seen;
  int ndone=0;
  while(!Q.empty()) {
    auto p = Q.back(); Q.pop_back();
    treechain::segment &ch = *p.x();
    int l=p.y(), r = p.z();
    while(1) {
      auto p = ch.get(l,r);
      if(p.x() != 1) break;
      if(seen.count(p.y())) dofail();
      seen.insert(p.y());
      ndone++;
      int a=p.z().x(), b=p.z().y();
      tr.hld_query(p.y().x(),p.y().y(),[&](treechain::segment& ch, lli l, lli r, lli, lli) {
          ch.kill(l,r);
        });
      tr.hld_query(a,b,[&](treechain::segment& ch, lli l, lli r, lli, lli) {
          ch.rem(l,r,mt(a,b));
          auto p = ch.get(l,r);
          if(p.x() == 1) Q.pb(mt(&ch,l,r));
        });
    }
  }
  if(ndone != n-1) dofail();
  cout << "YES" << endl;
  return 0;
}

