int n,tot;

void addedge(int x,int y)
{
	if (x>y) swap(x,y);
	if (++cnt[x][y]==2) q.push(mkp(x,y));
	edge[x].insert(y),edge[y].insert(x);
}

bool judge()
{
	for (int i=1,x,y;i<n;++i)
	{
		if (q.empty()) return 0;
		P e=q.front();q.pop();
		x=e.ft,y=e.sd;
		if (edge[x].size()<edge[y].size()) swap(x,y);
		edge[x].erase(y),edge[y].erase(x);
		for (multiset<int>::iterator it=edge[y].begin();it!=edge[y].end();++it) addedge(x,*it);
		edge[y].clear();
	}
	return 1;
}

