#include <bits/stdc++.h>
#define N 100005

using namespace std;

int n, totBlock;
int size[N];
set<int> g[N];
queue<pair<int, int> > que;

namespace UFS {

int fa[N];
inline void init() { for(int i = 1; i <= n; ++i) fa[i] = i; }
inline int find(int u) { return fa[u] == u ? u : fa[u] = find(fa[u]); }

}

inline void read(int &x) {
	x = 0; char ch = getchar();
	while(!isdigit(ch)) ch = getchar();
	while(isdigit(ch)) x = x * 10 + ch - '0', ch = getchar();
}

void work() {
	int u, v;
	pair<int, int> o;
	while(!que.empty()) {
		o = que.front(), que.pop();
		u = UFS :: find(o.first), v = UFS :: find(o.second);
		if(u != v) {
			--totBlock;
			if(size[u] > size[v]) swap(u, v);
			// merge
			UFS :: fa[u] = v;
			for(set<int> :: iterator it = g[u].begin(); it != g[u].end(); ++it) {
				int to = UFS :: find(*it);
				if(to == v) continue;
				if(g[to].find(v) != g[to].end()) {
					g[to].erase(u), --size[to];
					//g[v].erase(to), --size[v];
					que.push(make_pair(u, to));
				} else {
					g[to].erase(u), g[to].insert(v);
					g[v].insert(to), ++size[v];
				}
			}
		}
	}
}

int main() {
	read(n);
	UFS :: init();
	for(int i = 1, u, v; i <= 2 * n - 2; ++i) {
		read(u), read(v);
		if(g[u].find(v) != g[u].end()) {
			g[u].erase(v), --size[u];
			g[v].erase(u), --size[v];
			que.push(make_pair(u, v));
		} else {
			g[u].insert(v), ++size[u];
			g[v].insert(u), ++size[v];
		}
	}

	totBlock = n;
	work();

	puts(totBlock == 1 ? "YES" : "NO");
	return 0;
}

