const int MAX=1e5+5;

map<pair<int,int>,int> mpbl; 
map<pair<int,int>,int> mprd;
set<int> degbl[MAX];
set<int> degrd[MAX];
set<pair<int,int> > dg;
vector<int> te;

void addbl(int a,int b)
{
	if(a>b)
	{
		swap(a,b);
	}
	degbl[a].insert(b);
	degbl[b].insert(a);
	mpbl[make_pair(a,b)]++;
	if(mprd[make_pair(a,b)]>0)
	{
		dg.insert(make_pair(a,b));
	}
}


void addrd(int a,int b)
{
	if(a>b)
	{
		swap(a,b);
	}
	degrd[a].insert(b);
	degrd[b].insert(a);
	mprd[make_pair(a,b)]++;
	if(mpbl[make_pair(a,b)]>0)
	{
		dg.insert(make_pair(a,b));
	}
}

void erasebl(int a,int b)
{
	if(a>b)
	{
		swap(a,b);
	}
	degbl[a].erase(degbl[a].find(b));
	degbl[b].erase(degbl[b].find(a));
	mpbl[make_pair(a,b)]--;
}


void eraserd(int a,int b)
{
	if(a>b)
	{
		swap(a,b);
	}
	degrd[a].erase(degrd[a].find(b));
	degrd[b].erase(degrd[b].find(a));
	mprd[make_pair(a,b)]--;
}



