void lin(int x,int y){
    e[++cnt].nxt=hd[x];
    e[cnt].to=y;
    hd[x]=cnt;
}
int dfn[N],df;
int son[N],sz[N],top[N],fa[N],dep[N];
bool del[N];
void dfs(int x){
    sz[x]=1;dep[x]=dep[fa[x]]+1;
    for(reg i=hd[x];i;i=e[i].nxt){
        int y=e[i].to;
        if(y==fa[x]) continue;
        fa[y]=x;
        dfs(y);
        sz[x]+=sz[y];
        if(sz[y]>sz[son[x]]) son[x]=y;
    }
}
void dfs2(int x){
    dfn[x]=++df;
    if(!top[x]) top[x]=x;
    if(son[x]) top[son[x]]=top[x],dfs2(son[x]);
    for(reg i=hd[x];i;i=e[i].nxt){
        int y=e[i].to;
        if(y==son[x]||y==fa[x]) continue;
        dfs2(y);
    }
}
int b[N][2];
struct tr{
    int mi,id;
    int tag;
    vector<int>mem;
}t[4*N];
#define mid ((l+r)>>1)
#define ls (x<<1)
#define rs (x<<1|1)
void pushup(int x){
    t[x].mi=min(t[ls].mi,t[rs].mi);
    if(t[ls].mi==t[x].mi) t[x].id=t[ls].id;
    else t[x].id=t[rs].id;
}
void add(int x,int c){
    t[x].mi+=c;t[x].tag+=c;
}
void pushdown(int x){
    if(!t[x].tag) return;
    add(ls,t[x].tag);add(rs,t[x].tag);
    t[x].tag=0;
}
void build(int x,int l,int r){
    if(l==r){
        if(l==1) t[x].mi=inf,t[x].id=l;
        else t[x].mi=0;t[x].id=l;
        return;
    }
    build(ls,l,mid);
    build(rs,mid+1,r);
    pushup(x);
}
void push(int x,int l,int r,int L,int R,int id){
    if(L<=l&&r<=R){
        t[x].mem.pb(id);return ;
    }
    if(L<=mid) push(ls,l,mid,L,R,id);
    if(mid<R) push(rs,mid+1,r,L,R,id);
}
int cur;
void fin(int x,int l,int r,int p){
    while(!t[x].mem.empty()&&del[t[x].mem.back()]) t[x].mem.pop_back();
    if(t[x].mem.size()){
        cur=t[x].mem.back();
    }
    if(l==r){
        t[x].mi=inf;return;
    }
    pushdown(x);
    if(p<=mid) fin(ls,l,mid,p);
    else fin(rs,mid+1,r,p);
    pushup(x);
}
void upda(int x,int l,int r,int L,int R,int c){
    if(L<=l&&r<=R){
        add(x,c);return;
    }
    pushdown(x);
    if(L<=mid) upda(ls,l,mid,L,R,c);
    if(mid<R) upda(rs,mid+1,r,L,R,c);
    pushup(x);
}
void chan(int x,int y,int c){
    while(top[x]!=top[y]){
        if(dep[top[x]]<dep[top[y]]) swap(x,y);
        upda(1,1,n,dfn[top[x]],dfn[x],c);
        x=fa[top[x]];
    }
    if(dep[x]<dep[y]) swap(x,y);
    if(dfn[y]+1<=dfn[x]) upda(1,1,n,dfn[y]+1,dfn[x],c);
}
void put(int x,int y,int id){
    while(top[x]!=top[y]){
        if(dep[top[x]]<dep[top[y]]) swap(x,y);
        push(1,1,n,dfn[top[x]],dfn[x],id);
        x=fa[top[x]];
    }
    if(dep[x]<dep[y]) swap(x,y);
    if(dfn[y]+1<=dfn[x]) push(1,1,n,dfn[y]+1,dfn[x],id);
}
