#include <iostream>
#include <vector>
#include <set>

using namespace std;

const int MAX_N = 1e5 + 5;

pair<int, int> edge (int u, int v) {
  return make_pair(min(u, v), max(u, v));
}

int root [MAX_N];
vector<int> adj_blue [MAX_N];
vector<int> adj_red [MAX_N];
set<pair<int, int>> edges_blue;
set<pair<int, int>> edges_red;

vector<pair<int, int>> todo;

int find (int u) {
  if (root[u] != u) {
    root[u] = find(root[u]);
  }
  return root[u];
}

int cc;
void merge (int u, int v) {
  u = find(u);
  v = find(v);

  if (u == v) return;
  int szu = adj_blue[u].size() + adj_red[u].size();
  int szv = adj_blue[v].size() + adj_red[v].size();
  if (szu < szv) swap(u, v);

  edges_blue.erase(edge(u, v));
  edges_red.erase(edge(u, v));
  root[v] = u;
  cc--;
  for (int w : adj_blue[v]) {
    if (find(w) != u) {
      edges_blue.erase(edge(v, find(w)));
      adj_blue[u].push_back(find(w));
      edges_blue.insert(edge(u, find(w)));
      if (edges_red.count(edge(u, find(w)))) {
        todo.push_back(make_pair(u, find(w)));
      }
    }
  }

  for (int w : adj_red[v]) {
    if (find(w) != u) {
      edges_red.erase(edge(v, find(w)));
      adj_red[u].push_back(find(w));
      edges_red.insert(edge(u, find(w)));
      if (edges_blue.count(edge(u, find(w)))) {
        todo.push_back(make_pair(u, find(w)));
      }
    }
  }
}

int main () {
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  for (int i = 0; i < n - 1; i++) {
    int u, v;
    cin >> u >> v;

    adj_blue[u].push_back(v);
    adj_blue[v].push_back(u);
    edges_blue.insert(edge(u, v));
  }

  for (int i = 0; i < n - 1; i++) {
    int u, v;
    cin >> u >> v;

    adj_red[u].push_back(v);
    adj_red[v].push_back(u);
    edges_red.insert(edge(u, v));
    if (edges_blue.count(edge(u, v))) {
      todo.push_back(make_pair(u, v));
    }
  }

  cc = n;
  for (int i = 1; i <= n; i++) {
    root[i] = i;
  }

  while (!todo.empty()) {
    auto pr = todo.back();
    todo.pop_back();
    merge(pr.first, pr.second);    
  }

  if (cc == 1) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
}

