// Quick find
struct qf {
  vi g;
  vvi d;
  v(set<int>) e;
  qf(){}
  qf(int mx):g(mx),d(mx,vi(1)),e(mx) {
    rep(i,mx) g[i] = i, d[i][0] = i;
  }
  void add(int a, int b) {
    if (e[a].count(b)) {
      e[a].erase(b);
      e[b].erase(a);
      q.emplace(a,b);
    } else {
      e[a].insert(b);
      e[b].insert(a);
    }
  }
  bool unite(int a, int b) {
    a = g[a]; b = g[b];
    if (a == b) return false;
    if (sz(d[a]) < sz(d[b])) swap(a,b);
    d[a].insert(d[a].end(), rng(d[b]));
    for (int i : d[b]) g[i] = a;    
    d[b] = vi();
    for (int v : e[b]) {
      e[v].erase(b);
      if (e[a].count(v)) {
        e[a].erase(v);
        e[v].erase(a);
        q.emplace(a,v);
        continue;  
      }
      e[a].insert(v);
      e[v].insert(a);
    }
    return true;
  }
  bool same(int a, int b) const { return g[a] == g[b];}
  int size(int v) const { return sz(d[g[v]]);}
  int operator[](int v) const { return g[v];}
};
