int n;
multiset<int> e[MAXN];
queue<pii> q;

inline void AddEdge(int u, int v) {
	if (u == v) return;
	if (u > v) swap(u, v);
	if (e[u].find(v) != e[u].end()) {
		q.push(MP(u, v));
	}
	e[u].insert(v);
	e[v].insert(u);
}

void init() {
	read(n);
	for (int i = 1, m = n * 2 - 2, u, v; i <= m; ++i) {
		read(u); read(v);
		AddEdge(u, v);
	}
}

void solve() {
	for (int i = 1; i < n; ++i) {
		while (871) {
			if (q.empty()) out(0);
			int u = q.front().fi, v = q.front().se;
			q.pop();
			if (e[u].find(v) == e[u].end()) continue;
			if (e[u].size() < e[v].size()) swap(u, v);
			for (auto p : e[v]) {
				e[p].erase(e[p].find(v));
				AddEdge(u, p);
			}
			e[v].clear();
			break;
		}
	}
	out(1);
}

int main() {
	init();
	solve();
	return 0;
}

