pair<int, int> gid(int x, int y) {
	if(x > y) swap(x, y);
	return make_pair(x, y);
}
map<pair<int, int>, int> cnt;

int n;
queue<pair<int, int> > q;

void lk(int u, int v) {
	if(u > v) swap(u, v);
	g[u].emplace(v);
	g[v].emplace(u);
	if(++ cnt[gid(u, v)] == 2) {
		q.emplace(u, v);
	}
}

