PII Work(int x,int y)
{
	if(x>y)
		swap(x,y);
	return PII(x,y);
}
void AddEdge(int u,int v)
{
	st[u].insert(v);
	st[v].insert(u);
	mp[Work(u,v)]++;
	if(mp[Work(u,v)]==2)
		que.push(Work(u,v));
}
void Init()
{
	for(int i=0;i<=MAXN;i++)
		setfa[i]=i;
}
int Findfa(int x)
{
	if(x==setfa[x])
		return x;
	return setfa[x]=Findfa(setfa[x]);
}
void Union(int x,int y)
{
	int fx=Findfa(x),fy=Findfa(y);
	if(fx==fy)
		return;
	setfa[fx]=fy;
}
int main()
{
