		while(true)
		{
			if(que.empty()==true)
			{
				printf("NO\n");
				exit(0);
			}
			u=Findfa(que.front().first);
			v=Findfa(que.front().second);
			que.pop();
			if(Findfa(u)==Findfa(v))
				continue;
			spu=u,spv=v;
			break;
		}
		if(st[spu].size()>st[spv].size())
			swap(spu,spv);
		Union(spu,spv);
		mp.erase(Work(spu,spv));
		st[spv].erase(spu);
		vec.clear();
		for(it=st[spu].begin();it!=st[spu].end();it++)
			vec.push_back(*it);
		for(int i=0;i<vec.size();i++)
		{
			int poi=vec[i];
			poi=Findfa(poi);
			if(poi==spv)
				continue;
			mp.erase(Work(spu,poi));
			st[poi].erase(spu);
			st[spu].erase(poi);
			AddEdge(poi,spv);
		}
	}
	printf("YES\n");
	return 0;
}

