	for (int i = 0; i < N - 1; i++)
	{
		int a, b; scanf("%d%d", &a, &b);
		adj[a].insert(b); adj[b].insert(a);
		if (a > b) swap(a, b);
		edgeCount[ii(a, b)]++;
	}
	for (int i = 0; i < N - 1; i++)
	{
		int c, d; scanf("%d%d", &c, &d);
		adj[c].insert(d); adj[d].insert(c);
		if (c > d) swap(c, d);
		edgeCount[ii(c, d)]++;
		if (edgeCount[ii(c, d)] == 2) bfs.emplace(c, d);
	}
	while (!bfs.empty())
	{
		times++;
		int a, b; tie(a, b) = bfs.front(); bfs.pop();
		if (adj[a].size() > adj[b].size()) swap(a, b);
		for (int v : adj[a])
		{
			if (v == b) continue;
			adj[b].insert(v);
			adj[v].insert(b);
			if (b < v)
			{
				edgeCount[ii(b, v)]++;
				if (edgeCount[ii(b, v)] == 2) bfs.emplace(b, v);
			}
			else
			{
				edgeCount[ii(v, b)]++;
				if (edgeCount[ii(v, b)] == 2) bfs.emplace(v, b);
			}
		}
		for (int v : adj[a])
		{
