  }
  add(1, n, 1, 1, 1000000, root);
  int ct = 0;
  while (ct < n - 1) {
    if (mn[root] != 1) {
//      printf("mn[%d] = %d\n", root, mn[root]);
      puts("NO");
      return 0;
    }
    int p = mnpos[root];
    int id = query(1, n, p, root);
    add(1, n, p, p, 1000000, root);
//    printf("  id = %d!\n", id);
    ++ct;
    Add(U[id], V[id], id, -1);
  }
  puts("YES");
  return 0;
}

