const int maxn = 200010;
int N,M,dfn[maxn],father[maxn],side[maxn],nxt[maxn],top[maxn];
int size[maxn],toit[maxn],tree[maxn*4],tag[maxn*4],d[maxn],cnt,DFN;

inline void add(int a,int b) { nxt[++cnt] = side[a]; side[a] = cnt; toit[cnt] = b; }
inline void ins(int a,int b) { add(a,b); add(b,a); }

inline int gi()
{
	int ret = 0,f = 1; char ch;
	do ch = getchar(); while (!(ch >= '0'&&ch <= '9')&&ch != '-');
	if (ch == '-') f = -1,ch = getchar();
	do ret = ret*10+ch-'0',ch = getchar(); while (ch >= '0'&&ch <= '9');
	return ret*f;
}

inline void Div(int now,int Top)
{
	dfn[now] = ++DFN; top[now] = Top; int heavy = 0;
	for (int i = side[now];i;i = nxt[i])
		if (toit[i] != father[now]&&size[toit[i]] > size[heavy]) heavy = toit[i];
	if (!heavy) return; Div(heavy,Top);
	for (int i = side[now];i;i = nxt[i])
		if (toit[i] != father[now]&&toit[i] != heavy) Div(toit[i],toit[i]);
}

inline void dfs(int now)
{
	size[now] = 1;
	for (int i = side[now];i;i = nxt[i])
		if (toit[i] != father[now])
			father[toit[i]] = now,d[toit[i]] = d[now]+1,dfs(toit[i]);
}

inline int lca(int a,int b)
{
	while (top[a] != top[b])
	{
		if (d[top[a]] < d[top[b]]) swap(a,b);
		a = father[top[a]];
	}
	if (d[a] < d[b]) swap(a,b); return b;
}

inline void pushdown(int now,int l,int r)
{
	if (tag[now])
	{
		if (l != r)
		{
			tree[now<<1] += tag[now]; tag[now<<1] += tag[now];
			tree[now<<1|1] += tag[now]; tag[now<<1|1] += tag[now];
		}
		tag[now] = 0;
	}
}

inline int ask(int now,int l,int r,int ql,int qr)
{
	pushdown(now,l,r);
	if (l == ql&&r == qr) return tree[now];
	int mid = (l+r) >> 1;
	if (qr <= mid) return ask(now<<1,l,mid,ql,qr);
	else if (ql > mid) return ask(now<<1|1,mid+1,r,ql,qr);
	else return min(ask(now<<1,l,mid,ql,mid),ask(now<<1|1,mid+1,r,mid+1,qr));
}

inline void modify(int now,int l,int r,int ql,int qr,int inc)
{
	pushdown(now,l,r);
	if (l == ql&&r == qr) { tree[now] += inc; tag[now] += inc; return; }
	int mid = (l+r) >> 1;
	if (qr <= mid) modify(now<<1,l,mid,ql,qr,inc);
	else if (ql > mid) modify(now<<1|1,mid+1,r,ql,qr,inc);
	else
	{
		modify(now<<1,l,mid,ql,mid,inc);
		modify(now<<1|1,mid+1,r,mid+1,qr,inc);
	}
	tree[now] = min(tree[now<<1],tree[now<<1|1]);
}

inline void insert(int a,int b,int inc)
{
	while (top[a] != top[b])
	{
		if (d[top[a]] < d[top[b]]) swap(a,b);
		modify(1,1,N,dfn[top[a]],dfn[a],inc); a = father[top[a]];
	}
	if (d[a] < d[b]) swap(a,b);
	modify(1,1,N,dfn[b],dfn[a],inc);
}

inline int Query(int a,int b)
{
	int ret = 1<<30;
	while (top[a] != top[b])
	{
		if (d[top[a]] < d[top[b]]) swap(a,b);
		ret = min(ret,ask(1,1,N,dfn[top[a]],dfn[a]));
		a = father[top[a]];
	}
	if (d[a] < d[b]) swap(a,b);
	ret = min(ret,ask(1,1,N,dfn[b],dfn[a]));
	return ret;
}

struct node
{
	int a,b,c;
	inline void read()
	{
		a = gi(),b = gi(); insert(a,b,1);
		c = d[a]+d[b]-2*d[lca(a,b)];
	}
	inline int query() { return Query(a,b); }
	inline void modify() { insert(a,b,-1); }
	inline node(int _a = 0,int _b = 0,int _c = 0):a(_a),b(_b),c(_c){}
	friend inline bool operator <(const node &x,const node &y) { return x.c < y.c; }
}Q[maxn];

inline bool check()
{
	for (int i = M;i;--i)
	{
		if (Q[i].query() == 1) Q[i].modify();
		else return false;
	}
	return true;
}

