{
	//freopen("K.in","r",stdin);
	//freopen("K.out","w",stdout);
	N = gi(),M = N-1;
	for (int i = 1;i < N;++i) ins(gi(),gi());
	dfs(1); Div(1,1);
	for (int i = 1;i <= M;++i) Q[i].read();
	sort(Q+1,Q+M+1);
	if (check()) puts("YES");
