bool merge(int x, int y) {
	// printf("%d %d\n", x, y);
	x = find(x), y = find(y);
	if(x == y) return false;
	if(st[x].size() < st[y].size()) swap(x, y);
	f[y] = x;
	for(set<int>::iterator it = st[y].begin(); 
		it != st[y].end(); ++it) {
		int t = find(*it);
		if(x == t) continue;
		if(st[x].count(t)) q.push(pii(x, t));
		else {
			st[x].insert(t), st[t].insert(x);
			st[t].erase(y);
		}
	}
	st[y].clear(), st[x].erase(y);
	return true;
}
