void ekle(int x, int y, int z){
	if(x > y)
		swap(x, y);
	int kac = h[x][y];
	if(s.count(mp(kac, mp(x, y))))
		s.erase(mp(kac, mp(x, y)));
	kac += z;
	h[x][y] = kac;
	// cout << x << " " << y << " -> " << kac << endl;
	s.insert(mp(kac, mp(x, y)));
}

