  priority_queue<P,vector<P>,greater<P> > pq;

  for(Int i=0;i<n;i++) pq.emplace(H[i].size(),i);
  while(!pq.empty()){
    Int v=pq.top().second;pq.pop();
    if(v!=uf.find(v)) continue;
    //v=uf.find(v);
    for(auto z:H[v]){
      if(uf.same(z,v)||!G[v].count(z)) continue;
      Int u=uf.find(z);
      queue<Int> mg;
      mg.emplace(u);
      while(!mg.empty()){
	u=mg.front();mg.pop();
	u=uf.find(u);
	if(uf.same(u,v)) continue;

	if(H[v].size()<H[u].size()) swap(H[v],H[u]);
	if(G[v].size()<G[u].size()) swap(G[v],G[u]);
	for(auto x:G[u]){
	  if(H[u].count(x)||H[v].count(x)) mg.emplace(x);
	  G[v].emplace(x);
	}
