	  H[v].emplace(x);
	}
	H[u].clear();G[u].clear();

	uf.unite(u,v);        
	Int r=uf.find(v);
	if(r!=v){
	  swap(H[u],H[v]);
	  swap(G[u],G[v]);
	}
	v=r;
      }
      assert(v==uf.find(v));
      pq.emplace(H[v].size(),v);
      break;
    }
  }

