void merge(int x,int y) {

	if(x==y) return ;

	if(sz(s[x])<sz(s[y])) swap(x,y);

	ata[y]=x;

	for(auto go:s[y]) {

		s[go].erase(s[go].find(y));

		if(x!=go) {

			s[x].insert(go);
			s[go].insert(x);

		}

		int val=--cnt[min(y,go)][max(y,go)];

		if(!val) cnt[min(y,go)].erase(cnt[min(y,go)].find(max(y,go)));

		if(x!=go) {

			val=++cnt[min(x,go)][max(x,go)];

			if(val==2) q.push({x,go});

		}

	}

	s[y].clear();

}

