class Seg {
public:
  vector<pair<int, pair<int, int>>> d, a;
  int n;

  void init(int nw) {
    n = 1;
    while(n <= nw) {
      n *= 2;
    }
    d.resize(n * 2);
    a.resize(n * 2);
    rep(i, nw) {
      d[n - 1 + i] = make_pair(0LL, make_pair(0LL, i));
      a[n - 1 + i] = make_pair(0LL, make_pair(0LL, 0LL));
    }
    mfor(i, nw, n) {
      d[n - 1 + i] = make_pair(inf, make_pair(0LL, 0LL));
      a[n - 1 + i] = make_pair(0LL, make_pair(0LL, 0LL));
    }
    rrep(i, n - 1) {
      d[i] = min(d[i * 2 + 1], d[i * 2 + 2]);
      a[i] = make_pair(0LL, make_pair(0LL, 0LL));
    }
  }
  void add_(int b, int e, int k, int x, int p, int nb, int ne) {
    if(b <= nb && ne <= e) {
      a[p] = a[p] + make_pair(k, make_pair(x, 0));
    }
    else if(ne <= b || e <= nb) {}
    else {
      a[p * 2 + 1] = a[p * 2 + 1] + a[p];
      a[p * 2 + 2] = a[p * 2 + 2] + a[p];
      int m = (nb + ne) / 2;
      add_(b, e, k, x, p * 2 + 1, nb, m);
      add_(b, e, k, x, p * 2 + 2, m, ne);
      d[p] = min(a[p * 2 + 1] + d[p * 2 + 1], a[p * 2 + 2] + d[p * 2 + 2]);
      a[p] = make_pair(0, make_pair(0, 0));
    }
  }
  void add(int b, int e, int k, int x) {
    add_(b, e, k, x, 0, 0, n);
  }
  pair<int, pair<int, int>> solve() {
    return a[0] + d[0];
  }
};

