        data = vector<Val> (n<<1);
        copy(v.begin(),v.end(),data.begin()+n);
        for(int i=n+(int)v.size(); i<2*n;i++)data[i]=calc.id();
        for(int i=n-1; i>0; --i){data[i]=calc(data[i*2],data[i*2+1]);}
    }
    void update(int i,Val v){
        int k = i + n;
        data[k] = v;
        for(k>>=1; k>=1; k>>=1)data[k] = calc(data[k*2],data[k*2+1]);
    }
    Val query(int l,int r){ //get[a,b)
        Val resl=calc.id(),resr=calc.id();
        for(l += n, r += n; l<r; l>>=1, r>>=1){
            if(l&1)resl=calc(resl, data[l++]);
            if(r&1)resr=calc(data[r-1],resr);
        }
        return calc(resl,resr);
    }
};

struct Problem{
    int n;
    SegmentTree<RangeSum> seg;
    HeavyLightDecomposition start,goal;
    map<pair<int,int>,int> mp;
    vector<pair<int,int>> edges;
    vector<int> vis;
    Problem(LL n):n(n),seg(n),start(n),goal(n),vis(n){};
    void push_edge(int from, int to, queue<int> &Q){
        vector<pair<int,int>> q;
        start.decompose_vertex_query(from,to,q);
        int dist=start.dist(from,to);
        DBG(from,to,dist)
        for(auto &e :q){
            if(e.first>e.second)swap(e.first,e.second);
            int head= start.htop[start.idtov[e.first]];
            dist-=seg.query(head,e.second+1)-seg.query(head,e.first);
        }
        DBG(from,to,dist)
        if(dist==1){
            Q.push(mp[{from,to}]);
        }
    }
    void refill(queue<int> &Q){
        for(int i=0; i<n-1; ++i){
            if(vis[i]==0){
                int from=edges[i].first,to=edges[i].second;
                push_edge(from,to,Q);
            }
        }
    }
    void solve(){
        for(int i=0; i<n-1; ++i){
            int a,b;
            cin >> a >> b;
            --a;--b;
            start.T[a].push_back(Edge(a,b));
            start.T[b].push_back(Edge(b,a));
        }
        for(int i=0; i<n-1; ++i){
            int a,b;
            cin >> a >> b;
            --a;--b;
            if(a>b) swap(a,b);
            goal.T[a].push_back(Edge(a,b));
            goal.T[b].push_back(Edge(b,a));
            mp[{a,b}]=i;
            edges.emplace_back(a,b);
        }
        int cnt=0;
        start.calc(0);
        queue<int> Q;
        for(int i=0; i<n-1; ++i){
            if(start.dist(edges[i].first,edges[i].second)==1){
                Q.push(i);
                DBG(edges[i])
                vis[i]=1;
            }
        }
        while(!Q.empty()){
            while(!Q.empty()){
                int a=edges[Q.front()].first;
                int b=edges[Q.front()].second;
                vis[Q.front()]=1;
                Q.pop();
                DBG(a,b)
                ++cnt;
                int tmp=max(start.index[a],start.index[b]);
                seg.update(tmp,seg.query(tmp,tmp+1)+1);
                for(auto x: goal.T[a]){
                    int to=x.to,from=a;
                    if(from>to) swap(from,to);
                    if(vis[mp[{from,to}]]==0){
                        push_edge(from,to,Q);
                    }
                }
                DBG('A')
                for(auto x: goal.T[b]){
                    int to=x.to,from=b;
                    if(from>to) swap(from,to);
                    if(vis[mp[{from,to}]]==0){
                        push_edge(from,to,Q);
                    }
                }
            DBG(cnt)
            }
            refill(Q);
        }

        if(cnt==n-1)cout << "YES" <<"\n";
        else cout <<"NO" <<"\n";
    }
};

int main(){
    cin.tie(0);
    ios_base::sync_with_stdio(false);
    long long n=0;
    cin >> n;
    Problem p(n);
    p.solve();
    return 0;
}

