using namespace std;

const int MAXN = 100000;

map<pair<int, int>, int> edges;
queue<pair<int, int> > q;
int dad[1 + MAXN], components;
vector<int> g[1 + MAXN];

int findDad(int node) {
    if (dad[node] == node)
        return node;
    return dad[node] = findDad(dad[node]);
}

void addEdge(int a, int b) {
    a = findDad(a);
    b = findDad(b);
    if (a > b)
        swap(a, b);
    edges[make_pair(a, b)]++;
    if (edges[make_pair(a, b)] == 2)
        q.push(make_pair(a, b));
}

void join(int a, int b) {
    components--;
    if (g[a].size() > g[b].size())
        swap(a, b);
    dad[a] = b;
    for (auto it : g[a]) {
        int c = findDad(it);
        if (c != b)
            addEdge(b, c);
    }
}

int main(){
    //ifstream cin("input.in");
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++)
        dad[i] = i;
    for (int i = 1; i <= 2 * (n - 1); i++) {
        int a, b;
        cin >> a >> b;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
        addEdge(a, b);
    }
    components = n;
    while (!q.empty()) {
        int a = q.front().first, b = q.front().second;
        q.pop();
        a = findDad(a);
        b = findDad(b);
        if (a != b)
            join(a, b);
    }
    if (components == 1)
        cout << "YES\n";
    else
        cout << "NO\n";
    return 0;
}

