	for (int i = 1; i < n; ++i) {
		int u, v; cin >> u >> v; --u; --v;
// 		if (u > v) swap(u, v);
		graph[u][v] |= 2;
		graph[v][u] |= 2;
		if (graph[u][v] == 3) q.emplace(u, v);
