using namespace std;

typedef pair<int,int> pr;

set <int> e1[100005],e2[100005];
int size[100005];
queue <pr> q;

int fa[100005];

void init(int n) {
  for(int i=1;i<=n;i++) fa[i]=i;
}

int find_father(int x) {
  return (fa[x]==x)?x:fa[x]=find_father(fa[x]);
}

bool merge(int x,int y) {
  x=find_father(x);y=find_father(y);
  if (x==y) return 0;
  if (size[x]<size[y]) swap(x,y);
  size[x]+=size[y];fa[y]=x;
  for(set<int>::iterator it=e1[y].begin();it!=e1[y].end();it++)
    if ((*it)!=x&&e2[x].count(*it)) q.push(pr(x,*it));
  for(set<int>::iterator it=e2[y].begin();it!=e2[y].end();it++)
    if ((*it)!=x&&e1[x].count(*it)) q.push(pr(x,*it));
  for(set<int>::iterator it=e1[y].begin();it!=e1[y].end();it++)
    if ((*it)!=x) e1[x].insert(*it);
  for(set<int>::iterator it=e2[y].begin();it!=e2[y].end();it++)
    if ((*it)!=x) e2[x].insert(*it);
  return 1;
}

