inline pii Query(int x, int l, int r, int p)
{
	if (S[x].size())
		return *S[x].begin();
	int mid = l + r >> 1;
	if (p <= mid)
		return Query(x << 1, l, mid, p);
	return Query(x << 1 | 1, mid + 1, r, p);
