inline void Modify(int x, int l, int r, int p)
{
	if (l == r)
		return (void)(mn[x].xx = INF);
	int mid = l + r >> 1;
	if (p <= mid)
		Modify(x << 1, l, mid, p);
	else
		Modify(x << 1 | 1, mid + 1, r, p);
	Pushup(x);
}

