const int N = 1e5 + 100;

int n;
vi g[N];
set<int> has[N];
int dep[N], par[N];

void dfs(int u = 1, int fa = 0)
{
	dep[u] = dep[fa] + 1; par[u] = fa;
	for(int v: g[u]) if(v != fa)
	{
		dfs(v, u);
	}
	return;
}

void add(int u, int v, int i)
{
#ifdef DEBUG
	printf("add(%d, %d, %d)\n", u, v, i);
#endif
	while(u != v)
	{
		if(dep[u] < dep[v]) swap(u, v);
		has[u].insert(i);
		u = par[u];
	}
	return;
}

int a[N], b[N];

void TZL()
{
	scf(n);
	rep(i, n - 1)
	{
		int u, v; scf(u, v);
		g[u].pb(v); g[v].pb(u);
	}

	dfs();
	rep(i, n - 1)
	{
		int u, v; scf(u, v);
		add(u, v, i);
		a[i] = u; b[i] = v;
	}
	return;
}

void del(int u, int v, int i)
{
#ifdef DEBUG
	printf("del(%d, %d, %d)\n", u, v, i);
#endif
	while(u != v)
	{
		if(dep[u] < dep[v]) swap(u, v);
		has[u].erase(i);
		u = par[u];
	}
	return;
}

void RANK1()
{
	rep(i, n - 1)
	{
		int fuck = -1;
		forn(i, 2, n) if(SZ(has[i]) == 1)
		{
			fuck = i;
			break;
		}

		if(!~fuck)
		{
			puts("NO");
			return;
		}

		int x = *has[fuck].begin();
		del(a[x], b[x], x);
	}
	puts("YES");
	return;
}

