int const N = 1e5 + 41;
int const M = 17;
int const INF = 1e9 + 41;

int n, f[N], s[N];
int par[N][M], tin[N], tout[N], cnt, se[N], h[N];
int ver[N];
vector<int> e[N];
vector<int> st;
int dc[N];
int ea[N], eb[N];

int getTo(int id, int f){
	return (::f[id] == f ? s[id] : ::f[id]);
}

int dfs0(int u, int p){
	dc[u] = 1;
	st.pb(u);
	rep(i, 0, sz(e[u])){
		int to = getTo(e[u][i], u);
		if(to == p) continue;
		dc[u] += dfs0(to, u);
	}
	int n = sz(st) - 1;
	rep(i, 0, M){
		par[u][i] = -1;
		if((1<<i) <= n){
			par[u][i] = st[n - (1<<i)];
		}
	}
	st.pop_back();
	return dc[u];
}

void dfs1(int u, int p, int s){
	tin[u] = cnt;
	ver[cnt] = u;
	se[u] = s;
	ea[cnt] = p;
	eb[cnt] = u;
	++cnt;
	h[u] = -1;
	rep(i, 0, sz(e[u])){
		int to = getTo(e[u][i], u);
		if(to == p) continue;
		if(dc[to] * 2 >= dc[u]) h[u] = to;
	}
	if(h[u] != -1){
		dfs1(h[u], u, s);
	}
	rep(i, 0, sz(e[u])){
		int to = getTo(e[u][i], u);
		if(to == p || to == h[u]) continue;
		dfs1(to, u, to);
	}

	tout[u] = cnt-1;	
}

bool isA(int a, int b){
	return (tin[a] <= tin[b] && tout[a] >= tout[b]);
}

int getLca(int a, int b){
	if(isA(a, b)) return a;
	if(isA(b, a)) return b;
	for(int i=M-1;i>=0;--i){
		if(par[a][i] == -1 || isA(par[a][i], b)) continue;
		a = par[a][i];
	}
	return par[a][0];
}

pii te[N * 8];
int adde[N * 8];

void push(int v){
	adde[v * 2 + 1] += adde[v];
	adde[v * 2 + 2] += adde[v];
	te[v].first += adde[v];
	adde[v] = 0;
}

pii getMin(int v1, int v2){
	pii f = mp(te[v1].first + adde[v1], te[v1].second);
	pii s = mp(te[v2].first + adde[v2], te[v2].second);
	return min(f, s);
}

void upd(int v, int tl, int tr, int l, int r, int val){
	if(tl > r || tr < l) return;
	if(l <= tl && tr <= r){
		adde[v] += val;
		return;
	}
	push(v);
	int tm = (tl+tr)/2;
	upd(v*2+1, tl, tm, l, r, val);
	upd(v*2+2, tm+1, tr, l, r, val);
	te[v] = getMin(v*2+1, v*2+2);
}

void updLine(int v, int lca, int val){
	while(v != lca){
		int nxt = se[v];
		if(isA(nxt, lca)) nxt = lca;
		if(nxt == lca){
			upd(0, 0, n-1, tin[nxt] + 1, tin[v], val);
			v = nxt;
		}else{
			upd(0, 0, n-1, tin[nxt], tin[v], val);
			v = par[nxt][0];
		}
	}
}

void updWay(int a, int b, int val){
	int lca = getLca(a, b);
	updLine(a, lca, val);
	updLine(b, lca, val);
}

int sf[N], ss[N];
int posInTree[N];

struct Q{
	int from, to, val;
	Q(){};
	Q(int from, int to, int val) : from(from), to(to), val(val) {};
	bool operator<(const Q &a) const{
		if(val == a.val){
			if(from == a.from){
				return to < a.to;
			}else return from < a.from;
		}else return val < a.val;
	};
};

set<Q> t[N * 4];
vector<int> fe[N];
Q EMP = Q(-1, -1, INF);

void build(int v, int tl, int tr){
	if(tl != tr){
		int tm = (tl+tr)/2;
		build(v*2+1, tl, tm);
		build(v*2+2, tm+1, tr);
	}else{
		posInTree[tl] = v;
	}
	rep(i, tl, tr+1){
		rep(j, 0, sz(fe[i])){
			int to = sf[fe[i][j]];
			if(to == i) to = ss[fe[i][j]];
			t[v].insert(Q(i, to, tin[to]));
		}
	}
}

Q getLower(int v, int tl, int tr, int l, int r, int val){
	if(tl > r || tr < l) return EMP;
	if(l <= tl && tr <= r){
		auto it = t[v].lower_bound(Q(-1, -1, val));
		if(it == t[v].end()) return EMP;
		else return (*it);
	}
	int tm = (tl+tr)/2;
	Q lr = getLower(v*2+1, tl, tm, l, r, val);
	Q rr = getLower(v*2+2, tm+1, tr, l, r, val);
	return min(lr, rr);
}

void clear(int v, Q val){
	while(true){
		t[v].erase(val);
		if(v == 0) break;
		v = (v-1) / 2;
	}
}

void buildE(int v, int tl, int tr){
	if(tl == tr){
		if(tl == 0){
			te[v] = mp(INF, 0);
		}else{
			te[v] = mp(0, tl);
		}
	}else{
		int tm = (tl+tr)/2;
		buildE(v*2+1, tl, tm);
		buildE(v*2+2, tm+1, tr);
		te[v] = min(te[v*2+1], te[v*2+2]);
	}
}

void solve(){
	cin >> n;
	rep(i, 0, n-1){
		cin >> f[i] >> s[i];
		--f[i];--s[i];
		e[f[i]].pb(i);
		e[s[i]].pb(i);
	}
	rep(i, 0, n-1){
		cin >> sf[i] >> ss[i];
		--sf[i];
		--ss[i];
		fe[sf[i]].pb(i);
		fe[ss[i]].pb(i);
	}
	dfs0(0, -1);
	dfs1(0, -1, 0);
	build(0, 0, n-1);
	buildE(0, 0, n-1);
	rep(i, 0, n-1){
		updWay(sf[i], ss[i], 1);
	}
	bool ok = true;

	rep(i, 0, n-1){
		pii curMinEdge = mp(te[0].first + adde[0], te[0].second);
		if(curMinEdge.first != 1){
			ok = false;
			break;
		}else{
			int a = ea[curMinEdge.second];
			int b = eb[curMinEdge.second];
			Q curMin = getLower(0, 0, n-1, 0, tin[b] - 1, tin[b]);
			curMin = min(curMin, getLower(0, 0, n-1, tin[b] + dc[b], n-1, tin[b]));
			updWay(curMin.from, curMin.to, -1);
			clear(posInTree[curMin.from], curMin);
			clear(posInTree[curMin.to], Q(curMin.to, curMin.from, tin[curMin.from]));
			updWay(a, b, INF);
		}
	}

	if(ok) cout << "YES" << endl;
	else cout << "NO" << endl;
}


int main(){
#ifdef _DEBUG
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif

	solve();

	return 0;
}

