int ecnt,n,fa[N],dep[N],top[N],son[N],size[N],indx,tu,tv,c[N],d[N];
void add(int x,int y){
	e[++ecnt].u=x,e[ecnt].v=y;
	e[ecnt].next=v[x].head,v[x].head=ecnt;
	e[++ecnt].u=y,e[ecnt].v=x;
	e[ecnt].next=v[y].head,v[y].head=ecnt;
}
void dfs1(int x,int f){
	fa[x]=f,dep[x]=dep[f]+1,size[x]=1;
	for(int i=v[x].head;i;i=e[i].next){
		int y=e[i].v;
		if(y==f)continue;
		dfs1(y,x);
		size[x]+=size[y];
		if(size[y]>size[son[x]])son[x]=y;
	}
}
void dfs2(int x,int tp){
	top[x]=tp,v[x].t=++indx;
	if(son[x])dfs2(son[x],tp);
	for(int i=v[x].head;i;i=e[i].next){
		int y=e[i].v;
		if(y==fa[x]||y==son[x])continue;
		dfs2(y,y);
	}
}
void pushup(int pos){t[pos].mx=max(t[pos<<1].mx,t[pos<<1|1].mx);}
void pushdown(int pos){
	if(t[pos].tag){
		t[pos<<1].mx+=t[pos].tag;
		t[pos<<1].tag+=t[pos].tag;
		t[pos<<1|1].mx+=t[pos].tag;
		t[pos<<1|1].tag+=t[pos].tag;
		t[pos].tag=0;
	}
}
void build(int pos,int l,int r){
	t[pos].l=l,t[pos].r=r;
	if(l==r)return ;
	int mid=(l+r)>>1;
	build(pos<<1,l,mid),build(pos<<1|1,mid+1,r);
}
void add(int pos,int l,int r,int del){
	if(t[pos].l>r||t[pos].r<l)return ;
	if(l<=t[pos].l&&t[pos].r<=r){
		t[pos].tag+=del;
		t[pos].mx+=del;
		return ;
	}
	pushdown(pos);
	add(pos<<1,l,r,del),add(pos<<1|1,l,r,del);
	pushup(pos);
}
int query(int pos,int l,int r){
	if(t[pos].l>r||t[pos].r<l)return oo;
	if(l<=t[pos].l&&t[pos].r<=r)return t[pos].mx;
	pushdown(pos);
	return min(query(pos<<1,l,r),query(pos<<1|1,l,r));
}
void change(int x,int y,int del){
	while(top[x]!=top[y]){
		if(dep[top[x]]<dep[top[y]])swap(x,y);
		add(1,v[top[x]].t,v[x].t,del);
		x=fa[top[x]];
	}
	if(dep[x]<dep[y])swap(x,y);
	add(1,v[son[y]].t,v[x].t,del);
}
int get(int x,int y){
	int res=oo;
	while(top[x]!=top[y]){
		if(dep[top[x]]<dep[top[y]])swap(x,y);
		res=min(res,query(1,v[top[x]].t,v[x].t));
		x=fa[top[x]];
	}
	if(dep[x]<dep[y])swap(x,y);
	res=min(res,query(1,v[son[y]].t,v[x].t));
	return res;
}
