    int u,v; //u->v merging
    while (!del.empty()){
        curr=del.back(),del.pop_back();

        u=dsu.parent(f(curr)),v=dsu.parent(s(curr));
        if (al[u].size()>al[v].size()) swap(u,v);

        for (auto &it:al[u]){
            DEL(it,u);
