inline void pushup(int rt){
	sum[rt]=min(sum[rt<<1],sum[rt<<1|1]);
}
int tag[606060];
inline void pushdown(int rt){
	if (tag[rt]){
		sum[rt<<1]+=tag[rt],sum[rt<<1|1]+=tag[rt];
		tag[rt<<1]+=tag[rt],tag[rt<<1|1]+=tag[rt];
		tag[rt]=0;
	}
}
