void ins(pi x) {
    if (x.f > x.s) swap(x.f,x.s);
    if (adj[x.f].count(x.s)) posi.insert(x);
    adj[x.f].insert(x.s), adj[x.s].insert(x.f);
}

void del(pi x) {
    if (x.f > x.s) swap(x.f,x.s);
    if (posi.count(x)) posi.erase(x);
    adj[x.f].erase(adj[x.f].find(x.s)), adj[x.s].erase(adj[x.s].find(x.f));
}

