const int maxn=100005;
struct segtree{
	int n;
	int mn[maxn*4],tag[maxn*4];
	int lst[maxn*100],nxt[maxn*100];
	void qwq(int o){
		nxt[lst[o]]=nxt[o];
		lst[nxt[o]]=lst[o];
	}
	int tot;
	int ul,ur;
	void pu(int o){
		mn[o]=min(mn[o*2],mn[o*2+1])+tag[o];
	}
	void add(int o,int l,int r){
		if (ul<=l && ur>=r){
			mn[o]++;
			tag[o]++;
			tot++;
			nxt[tot]=nxt[o];
			lst[nxt[o]]=tot;
			nxt[o]=tot;
			lst[tot]=o;
			return;
		}
		int mid=(l+r)/2;
		if (ul<=mid)
			add(o*2,l,mid);
		if (ur>mid)
			add(o*2+1,mid+1,r);
		pu(o);
	}
	void add(int l,int r){
		// printf("add %d %d\n",l,r);
		ul=l,ur=r;
		add(1,1,n);
	}
	void del(int o,int l,int r){
		if (ul<=l && ur>=r){
			mn[o]--;
			tag[o]--;
			return;
		}
		int mid=(l+r)/2;
		if (ul<=mid)
			del(o*2,l,mid);
		if (ur>mid)
			del(o*2+1,mid+1,r);
		pu(o);
	}
	void del(int l,int r){
		// printf("del %d %d\n",l,r);
		ul=l,ur=r;
		del(1,1,n);
	}
	int pop(int o,int l,int r){
		if (l==r){
			mn[o]=maxn;
			tag[o]=0;
			return nxt[o];
		}
		int mid=(l+r)/2;
		int ans=nxt[o];
		if (mn[o*2]<=mn[o*2+1])
			ans|=pop(o*2,l,mid);	
		else ans|=pop(o*2+1,mid+1,r);
		pu(o);
		return ans;
	}
	int pop(){
		return pop(1,1,n);
	}
}t;
struct graph{
	int n,m;
	struct edge{
		int to,next;
	}e[maxn*2];
	int first[maxn];
	void addedge(int from,int to){
		e[++m]=(edge){to,first[from]};
		first[from]=m;
	}
	int fa[maxn],top[maxn],dep[maxn],sz[maxn],id[maxn],son[maxn],cl;
	void dfs(int u){
		sz[u]=1;
		for(int i=first[u];i;i=e[i].next){
			int v=e[i].to;
			if (fa[u]==v)
				continue;
			fa[v]=u;
			dep[v]=dep[u]+1;
			dfs(v);
			sz[u]+=sz[v];
			if (sz[v]>sz[son[u]])
				son[u]=v;
		}
	}
	void dfs2(int u,int tp){
		top[u]=tp;
		id[u]=cl++;
		if (son[u])
			dfs2(son[u],tp);
		for(int i=first[u];i;i=e[i].next){
			int v=e[i].to;
			if (!top[v])
				dfs2(v,v);
		}
	}
	void prepare(){
		dfs(1);
		dfs2(1,1);
		t.n=n-1;
		t.tot=n*4;
	}
	int fst[maxn];
	pair<int,int> w[maxn];
	void add(int u,int v,int p){
		fst[p]=t.tot+1;
		w[p]=make_pair(u,v);
		for(;top[u]!=top[v];u=fa[top[u]]){
			if (dep[top[u]]<dep[top[v]])
				swap(u,v);
			t.add(id[top[u]],id[u]);
		}
		if (dep[u]>dep[v])
			swap(u,v);
		if (u!=v)
			t.add(id[u]+1,id[v]);
	}
	void del(int u,int v){
		for(;top[u]!=top[v];u=fa[top[u]]){
			if (dep[top[u]]<dep[top[v]])
				swap(u,v);
			t.del(id[top[u]],id[u]);
		}
		if (dep[u]>dep[v])
			swap(u,v);
		if (u!=v)
			t.del(id[u]+1,id[v]);
	}
	bool work(){
		fst[n]=t.tot+1;
		int T=n-1;
		// puts("WTF");
		while(T--){
			if (t.mn[1]!=1){
				// printf("mn=%d on %d\n",t.mn[1],T);
				return false;
			}
			// printf("%d\n",T);
			int o=t.pop(),p=upper_bound(fst+1,fst+n,o)-fst-1;
			for(int i=fst[p];i<fst[p+1];i++)
				t.qwq(i);
			// printf("p=%d\n",p);
			del(w[p].first,w[p].second);
		}
		return true;
	}
