using namespace std;

const int MAXN = 1000001;
const int LOGMAXN = 20;

int val[MAXN];
int vis[MAXN];
int suma[MAXN];
int loga[MAXN];
int level[MAXN];
int P[LOGMAXN][MAXN];
vector<int> lista[MAXN];
vector<int> grafo[MAXN];

void pre(int n) {
	for(int j=1;(1<<j)<=n;j++)
		forn(i, n)
			P[j][i] = P[j - 1][ P[j - 1][i] ];
}

int LCA(int u,int v,int n) {
	if(level[u] < level[v]) swap(u, v);

	int l = loga[n];
	for(int i=l;i>=0;i--)
		if( level[ P[i][u] ] >= level[v] )
			u = P[i][u];

	if(u == v) return u;
	for(int i=l;i>=0;i--)
		if(P[i][u] != P[i][v]) {
			u = P[i][u];
			v = P[i][v];
		}

	return P[0][u];
}

int dfs(int u,int p,int l = 0) {
	P[0][u] = p;
	level[u] = l;
	int ans = suma[u];
	forn(i, lista[u].size()) {
		int v = lista[u][i];
		if(v != p) {
			int aux = dfs(v, u, l + 1);
			if(aux) {
				grafo[u].pb(v);
				grafo[v].pb(u);
			}
			ans += aux;
		}
	}
	return val[u] = ans;
}

int Check(int u,int prev,int f) {
	int ans = 1, cont = 0;
	vis[u] = 1;
	forn(i, grafo[u].size()) {
		int v = grafo[u][i];
		if(!vis[v]) {
			if(val[u] == prev)
				ans = min(ans, Check(v, val[u], f));
			else if(val[u] > prev && !f)
				ans = min(ans, Check(v, val[u], f));
			else if(val[u] < prev && !f)
				ans = min(ans, Check(v, val[u], 1));
			else if(val[u] < prev && f)
				ans = min(ans, Check(v, val[u], f));
			else ans = 0;
			cont++;
		}
	}
	if(cont > 1) ans = 0;
	return ans;
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	for(int i=2;i<MAXN;i++)
		loga[i] = loga[i >> 1] + 1;
	int n,a,b;
	cin>>n;

	forn(i, n - 1) {
		cin>>a>>b;
		a--,b--;
		lista[a].pb(b);
		lista[b].pb(a);
	}
	dfs(0, 0);
	pre(n);

	forn(i, n - 1) {
		cin>>a>>b;
		a--,b--;
		int r = LCA(a, b, n);

		suma[a]++;
		suma[b]++;
		suma[r] -= 2;
	}
	forn(i, n) grafo[i].clear();

	dfs(0, 0);

	int f = 1;
	forn(i, n)
		if(!vis[i] && grafo[i].size() == 1)
			f = min(f, Check(i, 0, 0));

	if(f) cout<<"YES"<<endl;
	else cout<<"NO"<<endl;
	return 0;
}

