  vector<vector<Int> > H(n);
  for(Int i=1;i<n;i++){
    Int x,y;
    cin>>x>>y;
    x--;y--;
    G[x].emplace(y);
    G[y].emplace(x);
  }
  for(Int i=1;i<n;i++){
    Int x,y;
    cin>>x>>y;
    x--;y--;
    H[x].emplace_back(y);
    H[y].emplace_back(x);
  }

  UnionFind uf(n);
  using P = pair<Int, Int>;
  priority_queue<P,vector<P>,greater<P> > pq;
  for(Int i=0;i<n;i++) pq.emplace(H[i].size(),i);

  while(!pq.empty()){
    Int v=pq.top().second;pq.pop();
    v=uf.find(v);
    Int flg=0;
    for(Int i=0;i<(Int)H[v].size();i++){
      Int u=uf.find(H[v][i]);
      if(uf.same(v,u)){
	swap(H[v][i],H[v].back());
	H[v].pop_back();
	continue;
      }
      if(G[v].count(u)){
	swap(H[v][i],H[v].back());
	H[v].pop_back();
	if(H[v].size()<H[u].size()) swap(H[v],H[u]);
	if(G[v].size()<G[u].size()) swap(H[v],H[u]);
	for(auto x:H[u]) H[v].emplace_back(x);
	for(auto x:G[u]) G[v].emplace(x);
	H[u].clear();G[u].clear();
	uf.unite(u,v);
	Int r=uf.find(v);
	if(r!=v){
	  swap(H[r],H[v]);
	  swap(G[r],G[v]);
	}
	flg=1;
	break;
      }
    }
    if(flg){
      pq.emplace(H[v].size(),v);
    }
  }

  cout<<(uf.r[uf.find(0)]==n?"YES":"NO")<<endl;
  return 0;
}

