const int MAXN = 1e5 + 5;

int N;
vector<int> G0[MAXN], G1[MAXN];
std::set<Pii> E0, E1;
std::queue<Pii> q;

void input()
{
    read(N);
    for (int i = 1; i < N; ++i) {
        int u, v;
        read(u); read(v);
        if (u > v) std::swap(u, v);
        G0[u].push_back(v);
        G0[v].push_back(u);
        E0.insert(MP(u, v));
    }
    for (int i = 1; i < N; ++i) {
        int u, v;
        read(u); read(v);
        if (u > v) std::swap(u, v);
        G1[u].push_back(v);
        G1[v].push_back(u);
        E1.insert(MP(u, v));
    }
}

int fa[MAXN];

int getFather(int u)
{
    return fa[u] == u ? u : fa[u] = getFather(fa[u]);
}

void solve()
{
    for (std::set<Pii>::iterator it = E1.begin(); it != E1.end(); ++it) {
        if (E0.find(*it) != E0.end())
            q.push(*it);
    }

    int tot = 0;
    for (int i = 1; i <= N; ++i) {
        fa[i] = i;
    }
    while (!q.empty()) {
        Pii e = q.front(); q.pop();
        if (getFather(e.x) != e.x || getFather(e.y) != e.y)
            continue;
        assert(E0.find(e) != E0.end());
        assert(E1.find(e) != E1.end());
        ++tot;
        E0.erase(e);
        E1.erase(e);
        if (SZ(G0[e.x]) + SZ(G1[e.x]) > SZ(G0[e.y]) + SZ(G1[e.y]))
            std::swap(e.x, e.y);
        for (int i = 0; i < SZ(G0[e.x]); ++i) {
            int v = getFather(G0[e.x][i]);
            Pii e0(e.x, v), e1(e.y, v);
            if (e0.x > e0.y) std::swap(e0.x, e0.y);
            if (e1.x > e1.y) std::swap(e1.x, e1.y);
            if (E0.find(e0) != E0.end()) {
                E0.erase(e0);
                E0.insert(e1);
                G0[e.y].push_back(v);
                if (E1.find(e1) != E1.end())
                    q.push(e1);
            }
        }
        for (int i = 0; i < SZ(G1[e.x]); ++i) {
            int v = getFather(G1[e.x][i]);
            Pii e0(e.x, v), e1(e.y, v);
            if (e0.x > e0.y) std::swap(e0.x, e0.y);
            if (e1.x > e1.y) std::swap(e1.x, e1.y);
            if (E1.find(e0) != E1.end()) {
                E1.erase(e0);
                E1.insert(e1);
                G1[e.y].push_back(v);
                if (E0.find(e1) != E0.end())
                    q.push(e1);
            }
        }
        fa[e.x] = e.y;
    }

    puts(tot == N - 1 ? "YES" : "NO");
}

int main()
{
#ifdef __DEBUG
    freopen("E.in", "r", stdin);
    freopen("E.out", "w", stdout);
#endif

    input();
    solve();

    return 0;
}

