	memset(a, 0, sizeof(a));
	for (int i = 1; i < n; i++) {
		int a, b;
		cin >> a >> b;
		e[a].push_back(b);
		e[b].push_back(a);
	}
	curt = n;
	dfs(1, 1);
	for (int i = 1; i < n; i++) {
		int c, d;
		cin >> c >> d;
		if (ps[c][0] == d) {
			a[i] = ps[c].id(0);
			possible[pose++] = i;
		} else if (ps[d][0] == c) {
			a[i] = ps[d].id(0);
			possible[pose++] = i;
		} else {
			for (int j = LG - 1; j >= 0; j--) {
				if (h[c] >= h[d] + (1 << j)) {
					advance(i, c, j);
				}
				if (h[d] >= h[c] + (1 << j)) {
					advance(i, d, j);
				}
			}
			if (c != d) {
				for (int j = LG - 1; j >= 0; j--) {
					if (ps[d][j] >= ps[c][j]) {
						advance(i, d, j);
						advance(i, c, j);
					}
				}
				advance(i, c, 0);
				advance(i, d, 0);
			}
		}
	}
	for (int posb = 0; posb < pose; posb++) {
		int v = possible[posb];
		a[a[v]] = -1;
		go(a[v]);
	}
	assert(pose <= n - 1);
	if (pose == n - 1) cout << "YES" << endl;
	else cout << "NO" << endl;
	return 0;
}

