int get_lca(int x, int y) {
	map<int, int> w;
	while (x) {	
		w[x] = 1;
		x = par[x].f; 
	}
	while (y) {
		if (w[y]) return y;
		y = par[y].f; 
	}
	assert(0);
}

vec get_path(int x, int y) {
	if (lvl[x] > lvl[y]) 
		swap(x, y);
	vec g;
	int lca = get_lca(x, y);
	while (y != lca) {
		g.pb(par[y].s);
		y = par[y].f;
	}
	while (x != lca) {
		g.pb(par[x].s);
		x = par[x].f;
	}
	return g;
}

void add(int id, int c) {
	for (auto it : g[id]) {
		val[it] += c;
	}
}

bool on_path(int x, int id) {
	return binary_search(all(g[x]), id);
}

