#define REP(i, n) for(int i = 1; i <= n; i ++)
#define REP0(i, n) for(int i = 0; i < n; i ++)
#define rep(i, a, b) for(int i = a; i <= b; i ++)
#define dow(i, a, b) for(int i = a; i >= b; i --)
#define REPG(i, u) for(int i = head[u]; ~i; i = e[i].next)
#define zx puts("!!!");
#define mp(x, y) make_pair(x, y)
#define pii pair<int, int>

using namespace std;
const int N = 3e5 + 5;
int asdf = 0, head[N], fa[N], f[N * 3], deg[N];
struct edge{ int to, next; } e[N * 5]; void add(int u, int v) { e[++asdf] = (edge){ v, head[u] }; head[u] = asdf; }
map<int, int>g[N];
queue<pii>q;
int find(int x) { return x == fa[x] ? x : fa[x] = find(fa[x]); }

int main()
{
	mem(head, -1);
	int n; scanf("%d", &n); REP(i, n) fa[i] = i;
	int u, v;
	REP(i, 2 * n - 2) { 
		scanf("%d%d", &u, &v), add(u, v), add(v, u), g[u][v] ++, g[v][u] ++;
		deg[u] ++; deg[v] ++;
		if(g[u][v] == 2) q.push(mp(u, v));
	}
	REP(x, n - 1) { bool fl = 0; pii nw; int fx, fy;
		while(!q.empty()) {
			nw = q.front(); q.pop();
			fx = find(nw.first), fy = find(nw.second);
			if(fx != fy) { fl = 1; break; }
		} if(!fl) { puts("NO"); return 0; }
		if(deg[fx] > deg[fy]) swap(fx, fy);
		fa[fx] = fy; g[fx][fy] = g[fy][fx] = 0;
		deg[fy] --; deg[fx] --; REPG(i, fx) {
			int v = find(e[i].to); if(v == fy || !g[fx][v]) continue;
			g[fx][v] = g[v][fx] = 0; deg[fx] --;
			g[v][fy] ++; g[fy][v] ++; deg[fy] ++; if(g[v][fy] == 1) add(v, fy), add(fy, v);
			if(g[v][fy] == 2) q.push(mp(v, fy));
		}
	} puts("YES");
 	return 0;
}

