struct SEG{
	int siz;
	vector<set<int>> s;
	vector<P> t;
	vector<int> u;
	void init(int n){
		siz = 1;
		while(siz < n)siz <<= 1;
		rep(i,siz*2-1){
			s.push_back(nullsi);
			t.push_back(P(0,0));
			u.push_back(0);
		}
		rep(i,siz){
			t[i+siz-1] = P(0,i);
		}
		rrep(i,siz-1){
			t[i] = min( t[2*i+1] , t[2*i+2] );
		}
	}
	void add(int a,int b,int x,int k,int l,int r){
		if(b <= l || r <= a)return;
		if(a <= l && r <= b){
			s[k].insert(x);
			u[k] ++;
			t[k].fr += 1;
			return;
		}
		add(a,b,x,2*k+1,l,(l+r)/2);
		add(a,b,x,2*k+2,(l+r)/2,r);
		t[k] = min( t[2*k+1] , t[2*k+2] );
		t[k].fr += u[k];
	}
	void erase(int a,int b,int x,int k,int l,int r){
		if(b <= l || r <= a)return;
		if(a <= l && r <= b){
			s[k].erase(x);
			u[k] --;
			t[k].fr -= 1;
			return;
		}
		erase(a,b,x,2*k+1,l,(l+r)/2);
		erase(a,b,x,2*k+2,(l+r)/2,r);
		t[k] = min( t[2*k+1] , t[2*k+2] );
		t[k].fr += u[k];
	}
	void query(int a,int b,int cnt,int k,int l,int r){
		if(b <= l || r <= a)return;
		if(t[k].fr+cnt >= 2)return;
		if(s[k].size() == 1){
			que.push(*s[k].begin());
			cnt ++;
		}
		if(r-l == 1){
			u[k] += INF;
			t[k].fr += INF;
			return;
		}
		query(a,b,cnt,2*k+1,l,(l+r)/2);
		query(a,b,cnt,2*k+2,(l+r)/2,r);
		t[k] = min( t[2*k+1] , t[2*k+2] );
		t[k].fr += u[k];
	}
};

