		return find(x) == find(y);
	}
	void unit(int x,int y){
		if(same(x,y))return;
		x = find(x);
		y = find(y);
		if(r[x] < r[y]){
			par[x] = y;
		}
		else {
			par[y] = x;
			if(r[x] == r[y]){
				r[x] ++;
			}
		}
	}
};

struct HL{
	int V;
	vector<vector<int>> G;
	int x,y;
	vector<int> d[2];
	int D;
	vector<int> id;
	vector<P> loc;
	UF uf;
	vector<HL*> ch;
	vector<vector<int>> ch_ids;
	vector<int> root;
	void init(int _V){
		V = _V;
		rep(i,V+1){
			G.push_back(nullvi);
			d[0].push_back(-1);
			d[1].push_back(-1);
			loc.push_back(P(-1,-1));
		}
	}
	void add_edge(int a,int b){
		G[a].pb(b); G[b].pb(a);
	}
	void dfs(int v,int p,int t){
		d[t][v] = d[t][p]+1;
		for(int u: G[v]){
			if(u == p)continue;
			dfs(u,v,t);
		}
	}
	void dia(){
		x = 1;
		d[0][0] = -1;
		dfs(x,0,0);
		rep1(i,V)if(d[0][i]>d[0][x])x=i;
		d[1][0] = -1;
		dfs(x,0,0);
		y = 1;
		rep1(i,V)if(d[0][i]>d[0][y])y=i;
		dfs(y,0,1);
	}
	void run_HL(){
		dia();
		D = d[0][y];
		rep(i,D+1){
			id.push_back(-1);
		}
		rep1(i,V){
			if(d[0][i]+d[1][i] == D){
				id[d[0][i]] = i;
				loc[i] = P(-1,d[0][i]);
			}
			else loc[i] = P(-2,0);
		}
		uf.init(V);
		rep1(i,V){
			if(loc[i].fr != -2)continue;
			for(int j: G[i]){
				if(loc[j].fr == -2)uf.unit(i,j);
			}
		}
		rep1(i,V){
			if(loc[i].fr == -1)continue;
			if(loc[uf.find(i)].fr == -2){
				loc[uf.find(i)].fr = ch_ids.size();
				ch.push_back(new HL);
				ch_ids.push_back(nullvi);
				root.push_back(0);
				ch_ids[loc[uf.find(i)].fr].push_back(uf.find(i));
				loc[uf.find(i)].sc = 1;
			}
			if(uf.find(i) != i){
				loc[i].fr = loc[uf.find(i)].fr;
				ch_ids[loc[i].fr].push_back(i);
				loc[i].sc = ch_ids[loc[i].fr].size();
			}
		}
		rep(i,ch_ids.size()){
			ch[i]->init(ch_ids[i].size()+1);
			int _v = ch_ids[i][0];
			root[i] = id[d[0][_v]-(d[0][_v]+d[1][_v]-D)/2];
			for(int v: ch_ids[i]){
				for(int u: G[v]){
					if(u == root[i])ch[i]->add_edge(loc[v].sc,ch_ids[i].size()+1);
					else if(loc[v].sc < loc[u].sc)ch[i]->add_edge(loc[v].sc,loc[u].sc);
				}
			}
			ch_ids[i].pb(root[i]);
			ch[i]->run_HL();
		}
		init_adhoc();
	}
	SEG seg;
	void init_adhoc(){
		seg.init(id.size());
	}
	void add(int a,int b,int c){
		if(loc[a] > loc[b])swap(a,b);
		if(loc[b].fr == -1){
			seg.add(loc[a].sc,loc[b].sc,c,0,0,seg.siz);
		}
		else if(loc[a].fr == -1){
			if(loc[a].sc <= loc[root[loc[b].fr]].sc)seg.add(loc[a].sc,loc[root[loc[b].fr]].sc,c,0,0,seg.siz);
			else seg.add(loc[root[loc[b].fr]].sc,loc[a].sc,c,0,0,seg.siz);
			ch[loc[b].fr]->add(loc[b].sc,ch_ids[loc[b].fr].size(),c);
		}
		else if(loc[a].fr == loc[b].fr){
			ch[loc[a].fr]->add(loc[a].sc,loc[b].sc,c);
		}
		else {
			if(loc[root[loc[a].fr]].sc>loc[root[loc[b].fr]].sc)swap(a,b);
			seg.add(loc[root[loc[a].fr]].sc,loc[root[loc[b].fr]].sc,c,0,0,seg.siz);
			ch[loc[a].fr]->add(loc[a].sc,ch_ids[loc[a].fr].size(),c);
			ch[loc[b].fr]->add(loc[b].sc,ch_ids[loc[b].fr].size(),c);
		}
	}
	void erase(int a,int b,int c){
		if(loc[a] > loc[b])swap(a,b);
		if(loc[b].fr == -1){
			seg.erase(loc[a].sc,loc[b].sc,c,0,0,seg.siz);
		}
		else if(loc[a].fr == -1){
			if(loc[a].sc <= loc[root[loc[b].fr]].sc)seg.erase(loc[a].sc,loc[root[loc[b].fr]].sc,c,0,0,seg.siz);
			else seg.erase(loc[root[loc[b].fr]].sc,loc[a].sc,c,0,0,seg.siz);
			ch[loc[b].fr]->erase(loc[b].sc,ch_ids[loc[b].fr].size(),c);
		}
		else if(loc[a].fr == loc[b].fr){
			ch[loc[a].fr]->erase(loc[a].sc,loc[b].sc,c);
		}
		else {
			if(loc[root[loc[a].fr]].sc>loc[root[loc[b].fr]].sc)swap(a,b);
			seg.erase(loc[root[loc[a].fr]].sc,loc[root[loc[b].fr]].sc,c,0,0,seg.siz);
			ch[loc[a].fr]->erase(loc[a].sc,ch_ids[loc[a].fr].size(),c);
			ch[loc[b].fr]->erase(loc[b].sc,ch_ids[loc[b].fr].size(),c);
		}
	}
	void query(int a,int b){
		if(loc[a] > loc[b])swap(a,b);
		if(loc[b].fr == -1){
			seg.query(loc[a].sc,loc[b].sc,0,0,0,seg.siz);
		}
		else if(loc[a].fr == -1){
			if(loc[a].sc <= loc[root[loc[b].fr]].sc)seg.query(loc[a].sc,loc[root[loc[b].fr]].sc,0,0,0,seg.siz);
			else seg.query(loc[root[loc[b].fr]].sc,loc[a].sc,0,0,0,seg.siz);
			ch[loc[b].fr]->query(loc[b].sc,ch_ids[loc[b].fr].size());
		}
		else if(loc[a].fr == loc[b].fr){
			ch[loc[a].fr]->query(loc[a].sc,loc[b].sc);
		}
		else {
			if(loc[root[loc[a].fr]].sc>loc[root[loc[b].fr]].sc)swap(a,b);
			seg.query(loc[root[loc[a].fr]].sc,loc[root[loc[b].fr]].sc,0,0,0,seg.siz);
			ch[loc[a].fr]->query(loc[a].sc,ch_ids[loc[a].fr].size());
			ch[loc[b].fr]->query(loc[b].sc,ch_ids[loc[b].fr].size());
		}
	}
	void out(){
		cerr << "diameter:";
		for(int v: id)cerr << v << " ";
		cerr << endl;
		rep1(i,V){
			cerr << i << ":" << loc[i].fr << " " << loc[i].sc << endl;
		}
		rep(i,ch.size()){
			cerr << "=========ch[" << i << "]==========" << endl;
			cerr << "root=" << root[i] << endl;
			ch[i]->out();
		}
	}
};

