	int kac = h[x][y];
	if(s.count(mp(kac, mp(x, y))))
		s.erase(s.find(mp(kac, mp(x, y))));
	kac += z;
	h[x][y] = kac;
	if(kac > 0)
		s.insert(mp(kac, mp(x, y)));
}

