using namespace std;
const int maxn = 100100;
unordered_set<int> to[maxn];
int uf[maxn];
int find(int x){
	if(x == uf[x]) return x;
	return uf[x] = find(uf[x]);
}
using ii = pair<int,int>;
map<ii, int> c_edges;
queue<ii> q;
void upd_edge(int u, int v, int d){
	if(u == v) return;
	if(u > v) swap(u, v);
	ii e = {u, v};
	int cur_c = c_edges[e];
	cur_c += d;
	c_edges[e] = cur_c;
	if(cur_c == 2) q.push(e);
}
int join(int u, int v){
	u = find(u);
	v = find(v);
	if(u == v) return false;
	if(to[u].size() < to[v].size()) swap(u, v);
	to[u].erase(v);
	to[v].erase(u);
	for(int s : to[v]){
		upd_edge(v, s, -1);
		to[u].insert(s);
		to[s].erase(v);
		to[s].insert(u);
		upd_edge(u, s, 1);
	}
	to[v].clear();
	uf[v] = u;
	return true;
}
int main(){
	int n; cin >> n;
	iota(uf, uf + maxn, 0);
	for(int rot = 0; rot < 2; rot++){
		for(int i = 0; i < n - 1; i++){
			int u, v; cin >> u >> v;
			upd_edge(u, v, 1);
			to[u].insert(v);
			to[v].insert(u);
		}
	}
	for(int i = 0; i < n - 1; i++){
		if(q.empty()){
			cout << "NO" << endl;
			return 0;
		}
		int u, v;
		tie(u, v) = q.front(); q.pop();
		upd_edge(u, v, -1);
		upd_edge(u, v, -1);
		join(u, v);
	}
	cout << "YES" << endl;
	return 0;
}

