    stack<pair<int, int> > st;
    f(i, 1, n + 1)for (map<int, int>::iterator it = tr[i].lower_bound(i); it != tr[i].end(); ++it)if (it->second >= 2)st.push(make_pair(i, it->first));
    while (!st.empty()){
        int a = P(st.top().first), b = P(st.top().second);
        st.pop();
        if (tr[a].size() > tr[b].size())swap(a, b);
        for (map<int, int>::iterator it = tr[a].begin(); it != tr[a].end(); ++it){
            if (it->first == b){
                tr[b].erase(a);
                continue;
            }
            map<int, int>::iterator it0 = tr[b].insert(make_pair(it->first, 0)).first;
            int t = it0->second;
            it0->second += it->second;
            tr[it->first][b] += it->second;
            if (t < 2 && it0->second >= 2)st.push(make_pair(it->first, b));
            tr[it->first].erase(a);
        }
        tr[a].clear();
        pa[a] = b;
        --n;
    }
    if (n == 1)printf("YES\n");
    else printf("NO\n");
}

