    rep(i, 0, N - 1) {
        int a, b; scanf("%d%d", &a, &b);
        addEdge(a, b);
    }
    rep(i, 0, N - 1) {
        int a, b; scanf("%d%d", &a, &b);
        addEdge(a, b);
    }

    set<int> u;
    rep(i, 1, N + 1) u.insert(uf[i]);

    if (u.size() == 1) printf("YES\n");
    else printf("NO\n");
}

#include <set>
#include <queue>
#include <cstdio>
#include <algorithm>

using namespace std;

const int N=1e5+10;

int n,f[N];
set<int>B[N],R[N];
queue< pair<int,int> >Q;

void Init()
{
	scanf("%d",&n);
	int a,b;
	for (int i=1;i<n;++i)
	{
		scanf("%d%d",&a,&b);
		B[a].insert(b); B[b].insert(a);
	}
	for (int i=1;i<n;++i)
	{
		scanf("%d%d",&a,&b);
		R[a].insert(b); R[b].insert(a); 
		if (B[a].count(b)) Q.push(make_pair(a,b));
	}
}

int find(int a) { return a==f[a]?a:f[a]=find(f[a]); }

void Union(int x,int y)
{
	if (R[x].size()>R[y].size()) swap(x,y);
	f[x]=y;
	for (auto a:R[x]) if (B[a].count(y)) Q.push(make_pair(a,y));
	for (auto a:B[x]) if (R[a].count(y)) Q.push(make_pair(a,y));
	for (auto a:R[x]) { R[a].erase(x); R[a].insert(y); R[y].insert(a); }
	for (auto a:B[x]) { B[a].erase(x); B[a].insert(y); B[y].insert(a); }
}

void Solve()
{
	for (int i=1;i<=n;++i) f[i]=i;
	int cnt=0;
	while (!Q.empty())
	{
		int x=Q.front().first,y=Q.front().second; Q.pop();
		x=find(x); y=find(y);
		if (x==y)  continue;
		++cnt;
		R[x].erase(y); R[y].erase(x); B[x].erase(y); B[y].erase(x);
		Union(x,y);
	}
	if (cnt==n-1) printf("Yes\n");
	else printf("No\n");
}

int main()
{
	Init();
	Solve();
	return 0;
}

#include <bits/stdc++.h>

using namespace std;
using ll = long long;
using ull = unsigned long long;
constexpr ll TEN(int n) { return (n==0) ? 1 : 10*TEN(n-1); }
template<class T> using V = vector<T>;
template<class T> using VV = V<V<T>>;

struct HL {
    V<int> _ord, _rord, big, small; //primitive
    V<int> pid, psz; int pc = 0; //path id, size, count(optional)
    V<int> out; // [id, out[id]) is subtree(optional)
    HL(int n = 0) : _ord(n), _rord(n), big(n), small(n), pid(n), out(n) {}
    int ord(int i) const { return i == -1 ? -1 : _ord[i]; }
    int rord(int i) const { return i == -1 ? -1 : _rord[i]; }
    int par(int a) const {
        a = ord(a);
        return rord(small[a] == a ? big[a] : a-1);
    }
    int lca(int a, int b) const {
        a = ord(a); b = ord(b);
        while (a != b) {
            if (a > b) swap(a, b);
            if (small[b] <= a) break;
            else b = big[b];
        }
        return rord(a);
    }
    template<class F>
    void get_path(int a, int b, F f) const { // aの直前までbから登る、fの引数は両閉区間
        a = ord(a); b = ord(b);
        while (a < b) {
            if (small[b] <= a) f(a+1, b);
            else f(small[b], b);
            b = big[b];
        }
    }
    int to(int a, int b) { // aからbの方向へ1移動する
        a = ord(a); b = ord(b);
        assert(a < b);
        while (true) {
            if (small[b] <= a) return rord(a+1);
            else if (big[b] == a) return rord(small[b]);
            b = big[b];
        }
        assert(false);
    }
};

template<class E> struct HL_EXEC : HL {
    const VV<E>& g;
    V<int> tch;
    int id = 0;
    HL_EXEC(const VV<E>& _g, int r) : HL(_g.size()), g(_g), tch(g.size(), -1) {
        assert(dfs_sz(r, -1) == int(g.size()));
        dfs(r, -1);
        init_extra();
    }
    void init_extra() {
        // ord, rord, big, small以外を使わないなら不要
        int n = int(g.size());

        // pid, psz, pc
        int l = 0;
        while (l < n) {
            int r = l+1;
            while (r < n && small[r] == l) r++;
            psz.push_back(r-l);
            for (int i = l; i < r; i++) {
                pid[i] = pc;
            }
            l = r;
            pc++;
        }

        // out
        for (int i = n-1; i >= 0; i--) {
            out[i] = max(out[i], i+1);
            int p = ord(par(rord(i)));
            if (p != -1) out[p] = max(out[p], out[i]);
        }
    }
    int dfs_sz(int p, int b) {
        int sz = 1, msz = -1;
        for (auto e: g[p]) {
            if (e.to == b) continue;
            int u = dfs_sz(e.to, p);
            sz += u;
            if (msz < u) tie(tch[p], msz) = make_pair(e.to, u);
        }
        return sz;
    }
    void dfs(int p, int b) {
        int q = id++, bq = ord(b);
        _ord[p] = q; _rord[q] = p;
        if (b == -1 || bq != q-1) {
            small[q] = q; big[q] = bq;
        } else {
            small[q] = small[bq]; big[q] = big[bq];
        }
        if (tch[p] == -1) return;
        dfs(tch[p], p);
        for (auto e: g[p]) {
            if (e.to == b || e.to == tch[p]) continue;
            dfs(e.to, p);
        }
    }
};

template<class E> HL get_hl(const VV<E>& g, int r) { return HL_EXEC<E>(g, r); }

using P = pair<ll, int>;
struct Node {
    using NP = Node*;
    NP l, r;
    int sz;
    P mi; ll lz = 0;
    Node(int sz, int off = 0) : sz(sz) {
        if (sz == 1) {
            mi = P(0, off);
            return;
        }
        l = new Node(sz/2, off);
        r = new Node(sz-sz/2, off+sz/2);
        mi = min(l->mi, r->mi);
    }
    void lzdata(ll x) {
        mi.first += x;
        lz += x;
    }
    void push() {
        l->lzdata(lz);
        r->lzdata(lz);
        lz = 0;
    }
    P get(int a, int b) {
        if (b <= 0 || sz <= a) return P(TEN(18), -1);
        if (a <= 0 && sz <= b) return mi;
        push();
        return min(l->get(a, b), r->get(a-sz/2, b-sz/2));
    }
    void add(int a, int b, ll x) {
        if (b <= 0 || sz <= a) return;
        if (a <= 0 && sz <= b) {
            lzdata(x);
            return;
        }
        push();
        l->add(a, b, x);
        r->add(a-sz/2, b-sz/2, x);
        mi = min(l->mi, r->mi);
    }
};


