    int pc = 0;
    while (true) {
        P p = tr->get(0, n);
        if (p.first == 0) {
            tr->add(p.second, p.second + 1, TEN(18));
            continue;
        }
        if (p.first >= 2*TEN(6)) {
            cout << "NO" << endl;
            return 0;
        }
        int idx = p.first - TEN(6);
        add(c[idx], d[idx], -TEN(6) - idx);
        pc++;
        if (pc == n-1) break;
    }
    cout << "YES" << endl;
    return 0;
}

