const int N=100005;
const int E=N<<1;

struct tree
{
	int last[N],deg[N];
	int tov[E],nxt[E];
	int tot;

	void insert(int x,int y){++deg[tov[++tot]=y],nxt[tot]=last[x],last[x]=tot;}
}t[2];

bool exist[N];
int n;

queue<int> q;

bool judge()
{
	for (int i=1;i<=n;++i)
	{
		exist[i]=1;
		if (t[0].deg[i]<=1&&t[1].deg[i]<=1) q.push(i);
	}
	for (int tr=1,x;tr<=n;++tr)
	{
		if (q.empty()) return 0;
		exist[x=q.front()]=0,q.pop();
		for (int b=0;b<2;++b)
			for (int i=t[b].last[x],y;i;i=t[b].nxt[i])
				if (exist[y=t[b].tov[i]])
					if (--t[b].deg[y]==1&&t[b^1].deg[y]<=1)
						q.push(y);
	}
	return 1;
}

