struct UF {
	vector<int> par;
	void init(int n) {
		par.resize(n); 
		for(int i = 0; i < n; i++) {
			par[i] = i;
		}
	}
	UF(int mx = 0) { init(mx); }

	int find(int x) {
		if(par[x] == x) return x;
		else return par[x] = find(par[x]);
	}
	void unite(int x, int y) { //x: par y: child
		x = find(x);
		y = find(y);
		if(x == y) return;
		par[y] = x;
	}
	bool same(int x, int y) { return find(x) == find(y); }
};

UF U;
int N;

vector<pi> L[MAX_N];
pi E[2][MAX_N];
set<pi> S[MAX_N];

void solve() {
	cin >> N;
	U.init(N);
	rep(k, 0, 2) {
		rep(i, 0, N - 1) {
			int a, b;
			cin >> a >> b; a--; b--;
			if(a > b) swap(a, b);
			E[k][i] = pi(a, b);
			S[k].insert(pi(a, b));
			L[a].push_back(pi(i, k));
			L[b].push_back(pi(i, k));
		}
	}

	queue<pi> que;
	for(auto w: S[0]) {
		if(S[1].count(w)) que.push(w);
	}

	while(!que.empty()) {
		pi p = que.front(); que.pop();
		int a = U.find(p.fst), b = U.find(p.sec);
		if(a == b) continue;
		if((int)L[a].size() > (int)L[b].size()) swap(a, b);
		U.unite(b, a);
		for(auto w: L[a]) {
			int id = w.fst, k = w.sec;
			S[k].erase(E[k][id]);
			E[k][id].fst = U.find(E[k][id].fst);
			E[k][id].sec = U.find(E[k][id].sec);
			if(E[k][id].fst > E[k][id].sec) swap(E[k][id].fst, E[k][id].sec);
			S[k].insert(E[k][id]);
			if(S[1 - k].count(E[k][id])) que.push(E[k][id]);
			L[b].push_back(w);
		}
		L[a].clear();
	}

	bool ok = true;
	for(int i = 0; i < N; i++) {
		if(U.find(0) != U.find(i)) ok = false;
	}
	cout << (ok ? "YES" : "NO") << "\n"; 
}

