			if(s[v[x][i]]<=1) continue;
			s[v[x][i]]-=1; k+=1;
			if(s[v[x][i]]<=1 && S[v[x][i]]<=1 && !d[v[x][i]]) q.push(v[x][i]), m-=1,d[v[x][i]]=1; 
		}
		if(k>1) return 1/0; k=0;
		for(int i=0;i<V[x].size();i++)
		{
			if(S[V[x][i]]<=1) continue;
			S[V[x][i]]-=1; k+=1;
			if(S[V[x][i]]<=1 && s[V[x][i]]<=1 && !d[V[x][i]]) q.push(V[x][i]), m-=1, d[V[x][i]]=1;
		}
		if(k>1) return 1/0;
	}
	for(int i=1;i<=n;i++)
	{
		if(S[i]<=1 && s[i]<=1 && !d[i]) return 1/0;
	}
	if(m) printf("NO\n");
	else printf("YES\n");
	}
}

#include <bits/stdc++.h>
#define reg register

using namespace std;

typedef long long ll;
typedef pair < int, int > pii;
const int maxn = 100005;

inline int read() {
    reg int s = 0, ch;
    while (!isdigit(ch = getchar())) ;
    while (isdigit(ch)) s = (s << 1) + (s << 3) + (ch ^ 48), ch = getchar();
    return s;
}

int n, fa[maxn];
map < pii, int > Map;
set < int > s[maxn];
queue < pii > q;

inline int find(reg int x) { return (fa[x] == x) ? x : (fa[x] = find(fa[x])); }

inline void init(reg int x, reg int y) {
    s[x].insert(y), s[y].insert(x);
    Map[pii(x, y)]++, Map[pii(y, x)]++;
    if (Map[pii(x, y)] == 2) q.push(pii(x, y));
}

inline void solve() {
    while (!q.empty()) {
        reg int x = q.front().first, y = q.front().second; q.pop();
        x = find(x), y = find(y), s[x].erase(y), s[y].erase(x);
        if (s[x].size() < s[y].size()) swap(x, y);
        for (auto it : s[y]) {
            Map[pii(it, y)] = Map[pii(y, it)] = 0,
            s[it].erase(y), s[it].insert(x), s[x].insert(it),
            Map[pii(it, x)]++, Map[pii(x, it)]++;
            if (Map[pii(it, x)] == 2) q.push(pii(it, x));
        }
        fa[y] = x, s[y].clear();
    }
}

int main() {
    ios::sync_with_stdio(false);
    n = read(); reg int u, v;
    for (reg int i = 1; i <= 2 * n - 2; i++) u = read(), v = read(), init(u, v);
    for (reg int i = 1; i <= n; i++) fa[i] = i;
    solve(); reg int ans = 0;
    for (reg int i = 1; i <= n; i++) ans += fa[i] == i;
    if (ans == 1) puts("YES");
    else puts("NO");
    return 0;
}

