const int MAX_V = 1e5;
vector<int> es[MAX_V];
int root[MAX_V];
vector<int> chil[MAX_V];
map<pii, int> mp;
queue<pii> que;

void add_edge(int u, int v){
    if(u == v) return;
    mp[pii(u, v)]++, mp[pii(v, u)]++;
    if(mp[pii(u, v)] >= 2) que.push(pii(u, v));
}

void merge(int u, int v){
    u = root[u], v = root[v];
    if(u == v) return;
    if(sz(chil[u]) > sz(chil[v])) swap(u, v);
    for(auto &e: chil[u]){
        root[e] = v;
        chil[v].pb(e);
    }
    chil[u].clear();
    for(auto &e: es[u]){
        es[v].pb(root[e]);
        add_edge(v, root[e]);
    }
}

int main(){
    int N;
    cin >> N;
    rep(i, N){
        root[i] = i;
        chil[i].pb(i);
    }
    rep(i, 2*(N-1)){
        int u, v; cin >> u >> v; u--, v--;
        es[u].pb(v), es[v].pb(u);
        add_edge(u, v);
    }
    while(!que.empty()){
        merge(que.front().first, que.front().second);
        que.pop();
    }
    bool ans = true;
    rep(i, N){
        if(root[i] != root[0]) ans = false;
    }
    if(ans) cout << "YES" << endl;
    else cout << "NO" << endl;
}

