void add(int a, int b) {
	mp[make_pair(a, b)]++;
	mp[make_pair(b, a)]++;
	ad[a].insert(b);
	ad[b].insert(a);
	if(mp[make_pair(a, b)] == 2) q.push_back(make_pair(a, b));
	return;
}

int getpar(int a) {
	if(par[a] == -1) return a;
	par[a] = getpar(par[a]);
	return par[a];
}

