void updr (int i, int x, int y) {
        mr.erase(mr.find(ar[i]));
        //printf("update %d %d, as %d changes to %d\n", ar[i].first, ar[i].second, x, y);
        if (ar[i].first == x) {
                ar[i].first = y;
        } else {
                assert(ar[i].second == x);
                ar[i].second = y;
        }
        fix(ar[i]);

        insert(mr, mb, ar[i]);
}

void updb (int i, int x, int y) {
        mb.erase(mb.find(ab[i]));
        if (ab[i].first == x) {
                ab[i].first = y;
        } else {
                assert(ab[i].second == x);
                ab[i].second = y;
        }
        fix(ab[i]);

        insert(mb, mr, ab[i]);
}

void merge (int a, int b) {
