		cout<<"YES\n";
		exit(0);
	}
}

void rempath(int u, int v)
{
	ii tmp = mp(min(u,v),max(u,v));
	int lc=T.lca(u,v);
	while(u!=lc)
	{
		if(par[u].empty())
		{
			cout<<"NO\n";
			exit(0);
		}
		par[u].erase(tmp);
		if(par[u].size()==1) leaves.pb(u);
		u=T.st[0][u].p;
	}
	while(v!=lc)
	{
		if(par[v].empty())
		{
			cout<<"NO\n";
			exit(0);
		}
		par[v].erase(tmp);
		if(par[v].size()==1) leaves.pb(v);
		v=T.st[0][v].p;
	}
	if(tim()>5850000)
	{
		cout<<"YES\n";
		exit(0);
	}
}

