int lca(int x,int y) {

	if(der[x]<der[y]) swap(x,y);

	for(int i=LOG-1;i>=0;i--) {

		if(der[x]-pw(i)>=der[y]) {

			x=baba[i][x];

		}

	}

	if(x==y) return x;

	for(int i=LOG-1;i>=0;i--) {

		if(baba[i][x]!=baba[i][y]) {

			x=baba[i][x];
			y=baba[i][y];

		}

	}

	return baba[0][x];

}

