set<int>w[MAXN];
long long getid(int x,int y)
{
	if(x<y)
		swap(x,y);
	return 1ll*x*n+y;
}
void link(int x,int y)
{
	w[x].insert(y);
	w[y].insert(x);
	a[getid(x,y)]++;
	if(a[getid(x,y)]>=3)
	{
		printf("NO\n");
		exit(0);
	}
	if(a[getid(x,y)]==2)
		Q.push(node(x,y));
}
int main()
{
	//freopen("bluered.in","r",stdin);
	//freopen("bluered.out","w",stdout);
	scanf("%d",&n);
