		{
			if(Q.empty())
			{
				printf("NO\n");
				return 0;
			}
			x=find(Q.front().x);
			y=find(Q.front().y);
			Q.pop();
			if(x!=y)
				break;
		}
		if(w[x].size()>w[y].size())
			swap(x,y);
		fa[x]=y;
		a.erase(getid(x,y));
