    pre(root, root);
    forn (d, maxd - 1)
        forn (u, n)
            p[u][d + 1] = p[p[u][d]][d];
    forn (i, n) {
        if (i == root)
            continue;
        put(in[i], 1);
        put(out[i], -1);
    }

    forn (i, n - 1) {
        //cerr << "Que " << i << '\n';
        int u, v;
        cin >> u >> v;
        --u, --v;
        qu[i] = u;
        qv[i] = v;
        qw[i] = lca(u, v);
        int len = rem(i);
        if (len == 1) {
            q.push_back(i);
        }
        if (len <= buben) {
            extractEdges(i);
        } else {
            upd[i + len - 2].push_back(i);
        }
    }
    forn (ii, sz(q)) {
        int id = q[ii];
