	else{t[i].mn=t[t[i].r].mn; t[i].mnp=t[t[i].r].mnp;}
}
inline void maketree(int L, int R){
	t[l].l=t[l].r=t[l].f=t[l].mn=0; t[l].mnp=L; t[l].a.clear();
	if(L<R){
		int mid=(L+R)>>1, l1=l;
		l++; t[l1].l=l; maketree(L, mid);
		l++; t[l1].r=l; maketree(mid+1, R);
		update(l1);
	}else if(L==1){t[l].mn=inf;}
}

inline void updatef(int i, int x){t[i].f+=x; t[i].mn+=x;}
inline void pushdown(int i){
	if(t[i].f){updatef(t[i].l, t[i].f); updatef(t[i].r, t[i].f); t[i].f=0;}
}

inline void ins(int i, int a, int b, int id, int c, int L, int R){
	if(a<=L&&R<=b){updatef(i, c); if(c==1)t[i].a.push_back(id); return;}
	pushdown(i);
	int mid=(L+R)>>1;
	if(a<=mid)ins(t[i].l, a, b, id, c, L, mid);
	if(mid<b)ins(t[i].r, a, b, id, c, mid+1, R);
	update(i);
}
inline void ins1(int i, int x, int y, int z){
	int xx, yy;
	while(led[x]!=led[y]){
		xx=led[x]; yy=led[y];
		if(def[xx]>=def[yy]){ins(1, pos[xx], pos[x], i, z, 1, n); x=fa[xx];}
		if(def[xx]<=def[yy]){ins(1, pos[yy], pos[y], i, z, 1, n); y=fa[yy];}
	}
	if(def[x]>def[y])ins(1, pos[y]+1, pos[x], i, z, 1, n);
	if(def[x]<def[y])ins(1, pos[x]+1, pos[y], i, z, 1, n);
}

inline void check(int i, int x, int L, int R){
	while(t[i].a.size()&&flag[t[i].a[t[i].a.size()-1]])t[i].a.pop_back();
	if(t[i].a.size())y=t[i].a[t[i].a.size()-1];
	if(L==R){t[i].mn=inf; return;}
	pushdown(i);
	int mid=(L+R)>>1;
	if(x<=mid)check(t[i].l, x, L, mid);
	else check(t[i].r, x, mid+1, R);
	update(i);
}

