    int mid=(l+r)>>1,cur;
    cur=getmn(lson); if (cur!=-1) { if (cur) return cur; if (ret) return ret; }
    cur=getmn(rson); if (cur!=-1) { if (cur) return cur; if (ret) return ret; }
