#include <bits/stdc++.h>
using namespace std;

typedef pair<int, int> P;

int N;
P AB[200000];
vector<int> edges[100000];
bitset<200000> done;
map<P, int> mp;
queue<P> que;

struct UnionFind {
    int par[100000];

    UnionFind(int n=0){
        if(n>0) initialize(n);
    }

    void initialize(int n){
        for(int i=0; i<n; i++){
            par[i] = i;
        }
    }

    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(edges[x].size() > edges[y].size()) swap(x, y);

        par[x] = y;
        for(int i : edges[x]){
            if(done[i]) continue;
            auto p = AB[i];
            mp.erase(p);
            add(find(p.first), find(p.second), i);
            edges[y].push_back(i);
        }
        edges[x].clear();
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    void add(int a, int b, int i){
        if(a > b) swap(a, b);
        P p = {a, b};
        AB[i] = p;
        if(mp.count(p)){
            int j = mp[p];
            done[i] = done[j] = 1;
            que.push(p);
            mp.erase(p);
        }else{
            mp[p] = i;
        }
    }

    void solve(){
        for(int i=0; i<2*N-2; i++){
            int a, b;
            cin >> a >> b;
            a--; b--;
            edges[a].push_back(i);
            edges[b].push_back(i);
            add(a, b, i);
        }

        while(que.size()){
            auto p = que.front(); que.pop();
            unite(p.first, p.second);
        }

        for(int i=0; i<2*N-2; i++){
            if(!done[i]){
                cout << "NO" << endl;
                exit(0);
            }
        }
        cout << "YES" << endl;
        exit(0);
    }
};

int main(){
    cin >> N;
    UnionFind uf(N);
    uf.solve();
    return 0;
}

