struct node{
	int l,r;
	set < pii > vs;
	node(){
		vs.clear();
	}
};
struct segT_edge{
	node arr[800005];
	void init(int p,int l,int r){
		arr[p].l=l;
		arr[p].r=r;
		if(l<r){
			int M=((l+r)>>1);
			init((p<<1),l,M);
			init(((p<<1)|1),M+1,r);
		}
	}
	void insert(int p,int d,pii v){
		arr[p].vs.insert(v);
		if(arr[p].l<arr[p].r){
			int M=((arr[p].l+arr[p].r)>>1);
			if(d<=M) insert((p<<1),d,v);
			else 	 insert(((p<<1)|1),d,v);
		}
	}
	void erase(int p,int d,pii v){
		arr[p].vs.erase(arr[p].vs.find(v));
		if(arr[p].l<arr[p].r){
			int M=((arr[p].l+arr[p].r)>>1);
			if(d<=M) erase((p<<1),d,v);
			else 	 erase(((p<<1)|1),d,v);
		}
	}
	pii query(int p,int L,int R){
		if(arr[p].l>=L && arr[p].r<=R){
			if(arr[p].vs.empty()) return mpr(-1,-1);
			if(arr[p].vs.begin()->first<L) return *arr[p].vs.begin();
			if(arr[p].vs.rbegin()->first>R) return *arr[p].vs.rbegin();
			return mpr(-1,-1);
		}
		int M=((arr[p].l+arr[p].r)>>1);
		pii ret=mpr(-1,-1);
		if(L<=M) ret=query((p<<1),L,R);
		if(R>M) UMAX(ret,query(((p<<1)|1),L,R));
		return ret;
	}
}segt_edge;
struct segT_ver{
	int l[800005],r[800005],v[800005],d[800005];
	void init(int p,int L,int R){
		l[p]=L;
		r[p]=R;
		v[p]=d[p]=0;
		if(L<R){
			int M=((L+R)>>1);
			init((p<<1),L,M);
			init(((p<<1)|1),M+1,R);
		}
	}
	void push(int p){
		v[p]+=d[p];
		if(l[p]<r[p]){
			v[p<<1]+=d[p];
			v[(p<<1)|1]+=d[p];
		}
		d[p]=0;
	}
	void add(int p,int L,int R,int V){
		if(l[p]>=L && r[p]<=R){
			d[p]+=V;
			push(p);
			return;
		}
		push(p);
		int M=((l[p]+r[p])>>1);
		if(L<=M) add((p<<1),L,R,V);
		if(R>M) add(((p<<1)|1),L,R,V);
		v[p]=MIN(v[p<<1],v[(p<<1)|1]);
	}
	pii query(int p,int L,int R){
		push(p);
		if(l[p]==r[p])
			return mpr(v[p],l[p]);
		int M=((l[p]+r[p])>>1);
		pii ret=mpr(iinf,-1);
		if(L<=M) ret=query((p<<1),L,R);
		if(R>M) UMIN(ret,query(((p<<1)|1),L,R));
		return ret;
	}
}segt_ver;
