queue < int > Q;
void dfs(int ver,int f){
	int i;
	fa[0][ver]=f;
	sz[ver]=1;
	rk[ver]=(f==-1?0:(rk[f]+1));
	mxson[ver]=-1;
	for(i=0;i<(int)adj[ver].size();++i){
		if(adj[ver][i]!=f) {
			dfs(adj[ver][i],ver);
			sz[ver]+=sz[adj[ver][i]];
			if(mxson[ver]==-1 || sz[adj[ver][i]]>sz[mxson[ver]])
				mxson[ver]=adj[ver][i];
		}
	}
}
void rdfs(int ver,int tpv){
	tpver[ver]=tpv;
	id[ver]=tick;
	rid[tick++]=ver;
	int i;
	if(mxson[ver]!=-1) rdfs(mxson[ver],tpv);
	for(i=0;i<(int)adj[ver].size();++i){
		if(adj[ver][i]!=fa[0][ver] && adj[ver][i]!=mxson[ver]){
			rdfs(adj[ver][i],adj[ver][i]);
		}
	}
	lv[ver]=tick;
}
void build(){
	int i,j;
	for(i=1;i<20;++i){
		for(j=0;j<n;++j){
			if(fa[i-1][j]==-1)
				fa[i][j]=-1;
			else
				fa[i][j]=fa[i-1][fa[i-1][j]];
		}
	}
}
int lca(int u,int v){
	if(rk[u]<rk[v]) swap(u,v);
	int i;
	for(i=19;i>=0;--i) 
		if(fa[i][u]!=-1 && rk[fa[i][u]]>=rk[v]) u=fa[i][u];
	if(u==v) return u;
	for(i=19;i>=0;--i){
		if(fa[i][u]!=fa[i][v]){
			u=fa[i][u];
			v=fa[i][v];
		}
	}
	return fa[0][u];
}
int queryt(int u,int v){// [u,v)
	pii ret=mpr(iinf,-1);
	while(tpver[u]!=tpver[v]){
		int tp=tpver[u];
		UMIN(ret,segt_ver.query(1,id[tp],id[u]));
		u=fa[0][tp];
	}
	if(rk[u]>rk[v]) UMIN(ret,segt_ver.query(1,id[v]+1,id[u]));
	if(ret.first==1) return rid[ret.second];
	//assert(ret.first!=0);
	return -1;
}
void modifyt(int u,int v,int d){// [u,v)
	while(tpver[u]!=tpver[v]){
		int tp=tpver[u];
		segt_ver.add(1,id[tp],id[u],d);
		u=fa[0][tp];
	}
	if(rk[u]>rk[v]) segt_ver.add(1,id[v]+1,id[u],d);
}
