		adj[j].push_back(k);
		adj[k].push_back(j);
	}
    #ifdef LOCAL
        TStart();
    #endif
    // calculation start
    // 数据结构记得初始化！ n，m别写反！
	segt_ver.init(1,0,n+1);
	segt_edge.init(1,0,n+1);
    dfs(0,-1);
	rdfs(0,0);
	build();
	for(i=0;i<n-1;++i){
		scanf("%d%d",c+i,d+i);
		--c[i];--d[i];
		modifyt(c[i],lca(c[i],d[i]),1);
		modifyt(d[i],lca(c[i],d[i]),1);
		mp[mpr(c[i],d[i])]=mp[mpr(d[i],c[i])]=i;
		segt_edge.insert(1,id[c[i]],mpr(id[d[i]],id[c[i]]));
		segt_edge.insert(1,id[d[i]],mpr(id[c[i]],id[d[i]]));
	}
	//for(i=1;i<n;++i) printf("%d\n",queryt(i,fa[0][i]));
	for(i=0;i<n-1;++i){
		int v=MAX(queryt(c[i],lca(c[i],d[i])),queryt(d[i],lca(c[i],d[i])));
		if(v!=-1){
			Q.push(i);
			while(v!=-1){
			//	printf("%d\n",v);
				modifyt(v,fa[0][v],iinf);
				v=MAX(queryt(c[i],lca(c[i],d[i])),queryt(d[i],lca(c[i],d[i])));
			}
		}
	}
	while(!Q.empty()){
		int C=c[Q.front()],D=d[Q.front()],f=Q.front(),LCA;
