		segt_edge.erase(1,id[C],mpr(id[D],id[C]));
		segt_edge.erase(1,id[D],mpr(id[C],id[D]));
		LCA=lca(C,D);
		modifyt(C,LCA,-1);
		modifyt(D,LCA,-1);
		int la=queryt(C,LCA);
		while(la!=-1){
			modifyt(la,fa[0][la],iinf);
			pii nv=segt_edge.query(1,id[la],lv[la]-1);
			nv.first=rid[nv.first];
			nv.second=rid[nv.second];
			if(nv.second!=-1) Q.push(mp[nv]);
			la=queryt(C,LCA);
		}
		la=queryt(D,LCA);
		while(la!=-1){
			modifyt(la,fa[0][la],iinf);
			pii nv=segt_edge.query(1,id[la],lv[la]-1);
			nv.first=rid[nv.first];
			nv.second=rid[nv.second];
			if(nv.second!=-1) Q.push(mp[nv]);
			la=queryt(D,LCA);
		}
	}
	for(i=0;i<n-1;++i){
		if(!vis[i]){
			printf("NO");
			return 0;
		}
	}
