int gl(int i) {
    return i == rp[i] ? i : rp[i] = gl(rp[i]);
}

int main() {
    scanf("%d", &n);
    FO(i,0,n-1) {
        int x, y;
        scanf("%d %d", &x, &y);
        u[x].insert(y);
        u[y].insert(x);
    }
    FO(i,0,n-1) {
        int x, y;
        scanf("%d %d", &x, &y);
        v[x].insert(y);
        v[y].insert(x);
    }
    FO(i,1,n+1) rp[i] = i;
    queue<pair<int,int> > q;
    FO(i,0,n) {
        for (int j : u[i]) if (v[i].count(j)) q.emplace(i,j);
    }
    int nm = 0;
    while (sz(q)) {
        int i, j; tie(i,j) = q.front(); q.pop();
        i = gl(i); j = gl(j);
        if (i == j) continue;
        if (sz(u[i])+sz(v[i]) > sz(u[j])+sz(v[j])) swap(i,j);
        for (int k : u[i]) {
            if (k == i || k == j) continue;
            u[k].erase(i);
            u[k].insert(j);
            if (v[j].count(k)) q.emplace(j,k);
            u[j].insert(k);
        }
        for (int k : v[i]) {
            if (k == i || k == j) continue;
            v[k].erase(i);
            v[k].insert(j);
            if (u[j].count(k)) q.emplace(j,k);
            v[j].insert(k);
        }
        u[i].clear(); v[i].clear();
        rp[i] = j;
        nm++;
    }
    if (nm == n-1) puts("YES");
    else puts("NO");
}

