int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << setprecision(20);
    int n;
    cin >> n;
    VV<Edge> g(n);
    queue<P> ev;
    for (int i = 0; i < n-1; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(Edge{b});
        g[b].push_back(Edge{a});
        ev.push(P{a, b});
    }   

    V<int> c(n-1), d(n-1);
    for (int i = 0; i < n-1; i++) {
        cin >> c[i] >> d[i]; c[i]--; d[i]--;
    }

    HLDecomp<Edge> hl(g, 0);

    for (int i = 0; i < n; i++) {
        hl.id_set(i, i);
    }
    for (int i = 0; i < n-1; i++) {
//        cout << "set " << c[i] << " " << d[i] << " " << i << endl;
        hl.set(c[i], d[i], i, false);
    }

    int ec = 0;
    while (ev.size()) {
        P p = ev.front(); ev.pop();
        P buf = hl.get_mi(p[0], p[1]);
//        cout << "check " << p[0] << " " << p[1] << " " << buf[0] << " " << buf[1] << endl;
        if (buf[0] == 0) {
            hl.add(buf[1]);
            ev.push(p);
            continue;
        }
        if (buf[0] != 1) continue;
        ec++;
        int id = hl.get(buf[1]);
//        cout << "era "  << c[id] << " " << d[id] << " " << id << endl;
        hl.set(c[id], d[id], id, true);
        ev.push(p);
        ev.push(P{c[id], d[id]});
    }

    if (ec == n-1) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
    return 0;
}

