import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();

        graph = new Set[2][n];
        for (int i = 0; i < 2 ; i++) {
            for (int j = 0; j < n ; j++) {
                graph[i][j] = new HashSet<>();
            }
        }
        que = new int[2000000];

        int[][] blueEdges = in.nextIntTable(n-1, 2);
        int[][] redEdges = in.nextIntTable(n-1, 2);
        for (int i = 0; i < n-1 ; i++) {
            addEge(0, blueEdges[i][0]-1, blueEdges[i][1]-1);
            addEge(1, redEdges[i][0]-1, redEdges[i][1]-1);
        }

        int groupCnt = n;
        while (qt < qh) {
            int l = que[qt++];
            int r = que[qt++];
            if (mergeVertex(l, r)) {
                groupCnt--;
            }
        }

        out.println(groupCnt == 1 ? "YES" : "NO");
        out.flush();
    }

    static void addEge(int color, int l, int r) {
        if (l == r || graph[color][l].contains(r) || graph[color][r].contains(l)) {
            return;
        }
        graph[color][l].add(r);
        graph[color][r].add(l);
        if (graph[1-color][l].contains(r)) {
            que[qh++] = l;
            que[qh++] = r;
        }
    }

    static boolean mergeVertex(int l, int r) {
        if (l == r) {
            return false;
        }
        int el = countEdge(l);
        int er = countEdge(r);
        if (el == 0 || er == 0) {
            return false;
        }
        if (el > er) {
            return mergeVertex(r, l);
        }

        // merge l into r
        for (int k = 0 ; k <= 1 ; k++) {
            for (int to : graph[k][l]) {
                graph[k][to].remove(l);
                addEge(k, to, r);
            }
