  static class TaskE {

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      DisjointSets dsu = new DisjointSets(n);
      TaskE.State[] states = new TaskE.State[n];
      for (int i = 0; i < n; ++i) {
        states[i] = new TaskE.State();
      }
      for (int i = 0; i < n - 1; ++i) {
        int x = in.nextInt() - 1;
        int y = in.nextInt() - 1;
        states[x].outRed.add(y);
        states[y].outRed.add(x);
      }
      for (int i = 0; i < n - 1; ++i) {
        int x = in.nextInt() - 1;
        int y = in.nextInt() - 1;
        states[x].outBlack.add(y);
        states[y].outBlack.add(x);
      }
      Queue<Integer> q = new ArrayDeque<>();
      for (int i = 0; i < n; ++i) {
        q.add(i);
      }
      while (!q.isEmpty()) {
        int x = q.poll();
        if (dsu.root(x) != x) {
          continue;
        }
        states[x].normalize(dsu, x);
        ArrayList<Integer> neigh = states[x].evict();
        for (int y : neigh) {
          int r1 = dsu.root(y);
          int r2 = dsu.root(x);
          if (r1 == r2) {
            continue;
          }
          dsu.unite(r1, r2);
          int r = dsu.root(r1);
          if (r == r1) {
            states[r1].merge(states[r2]);
            states[r2] = null;
          } else {
            states[r2].merge(states[r1]);
            states[r1] = null;
          }
        }
        if (!neigh.isEmpty()) {
          q.add(dsu.root(x));
        }
      }
      HashSet<Integer> roots = new HashSet<>();
      for (int i = 0; i < n; ++i) {
        roots.add(dsu.root(i));
      }
      if (roots.size() == 1) {
        out.printLine("YES");
      } else {
        out.printLine("NO");
      }

    }

    static class State {

      HashSet<Integer> outRed = new HashSet<>();
      HashSet<Integer> outBlack = new HashSet<>();

      ArrayList<Integer> evict() {
        ArrayList<Integer> res = new ArrayList<>();
        for (int x : outRed) {
          if (outBlack.contains(x)) {
            res.add(x);
          }
        }
        for (int x : res) {
          outBlack.remove(x);
          outRed.remove(x);
        }
        return res;
      }

      void normalize(DisjointSets dsu, int us) {
        HashSet<Integer> tmp = new HashSet<>();
        for (int x : outBlack) {
          int y = dsu.root(x);
          if (y == us) {
            continue;
          }
          tmp.add(y);
        }
        outBlack = tmp;
        tmp = new HashSet<>();
        for (int x : outRed) {
          int y = dsu.root(x);
          if (y == us) {
            continue;
          }
          tmp.add(y);
        }
        outRed = tmp;
      }

      void merge(TaskE.State other) {
        if (outRed.size() >= other.outRed.size()) {
          outRed.addAll(other.outRed);
        } else {
          other.outRed.addAll(outRed);
          outRed = other.outRed;
        }
        if (outBlack.size() >= other.outBlack.size()) {
          outBlack.addAll(other.outBlack);
        } else {
          other.outBlack.addAll(outBlack);
          outBlack = other.outBlack;
        }
//            outRed.addAll(other.outRed);
//            outBlack.addAll(other.outBlack);
      }

    }

