        for (int i = 0; i < n; ++i) {
            edge[i] = new ArrayList<>();
        }
        Map<Long, Integer> edges = new HashMap<>();
        Queue<Long> pair = new ArrayDeque<>();
        for (int i = 0; i < (n - 1) * 2; ++i) {
            int a = ni() - 1;
            int b = ni() - 1;
            edge[a].add(b);
            edge[b].add(a);
            long key = getKey(a, b);
            int c = inc(edges, key);
            if (c == 2) {
                pair.add(key);
            }
        }
        boolean used[] = new boolean[n];
        for (int m = 1; m < n; ++m) {
            Integer x = -1, y = -1;
            while (!pair.isEmpty()) {
                long key = pair.poll();
                int a = (int) (key >>> 32);
                int b = (int) (key & ((1L << 32) - 1L));
                if (!used[a] && !used[b]) {
                    x = a;
                    y = b;
                    break;
                }
            }
            if (x.equals(-1)) {
                out.println("NO");
                return;
            }
            for (Integer t : edge[y]) {
                edge[t].remove(y);
                if (!t.equals(x)) {
                    edge[t].add(x);
                    edge[x].add(t);
                    long key = getKey(t, x);
                    int c = inc(edges, key);
                    if (c == 2) {
                        pair.add(key);
                    }
                }
            }
            used[y] = true;
            ++m;
        }
