		if (g[0][a].size() + g[1][a].size() < g[0][b].size() + g[1][b].size()) {
			int t = a; a = b; b = t;
		}
		for (int i = 0; i < 2; i++) {
			for (int t : g[i][b]) {
				remove(i, b, t);
				add(i, a, t);
			}
			g[i][b].clear();
		}
	}

	void add(int t, int a, int b) {
		if (a == b) return;
		if (a > b) { int tmp = a; a = b; b = tmp; }
		Long key1 = (long)a<<32|b;
		Long key2 = (long)b<<32|a;
		if (!set[t].contains(key1)) {
			g[t][b].add(a);
			g[t][a].add(b);
			set[t].add(key1);
			set[t].add(key2);
			if (set[1^t].contains(key1)) {
				que.add(key1);
			}
		}
	}

	void remove(int t, int a, int b) {
		Long key1 = (long)a<<32|b;
		Long key2 = (long)b<<32|a;
		set[t].remove(key1);
		set[t].remove(key2);
	}

