	/// MAIN CODE
	public void run() throws IOException {
//		int TEST_CASE = Integer.parseInt(new String(io.nextLine()).trim());
		int TEST_CASE = 1;
		while(TEST_CASE-- != 0) {
			int n = io.nextInt();
			g = new List[2][n];
			for (int i = 0; i < n; i++) {
				g[0][i] = new ArrayList<>();
				g[1][i] = new ArrayList<>();
			}
			for (int i = 0; i < n - 1; i++) {
				int a = io.nextInt() - 1;
				int b = io.nextInt() - 1;
				add(0, a, b);
			}
			for (int i = 0; i < n - 1; i++) {
				int a = io.nextInt() - 1;
				int b = io.nextInt() - 1;
				add(1, a, b);
			}

			while (!que.isEmpty()) {
				long key = que.poll();
				int a = (int)(key>>>32);
				int b = (int)(key&0xFFFFFFFFL);
				merge(a, b);
			}

			io.out.println(merged == n - 1 ? "YES" : "NO");
		}
	}

	Counter<Long>[] counter = new Counter[]{
		new Counter<>(),
		new Counter<>(),
	};

	List<Integer>[][] g;
	ArrayDeque<Long> que = new ArrayDeque<>();
	int merged;

	void merge(int a, int b) {
		if (g[0][a].isEmpty() || g[0][b].isEmpty()) return;
		merged++;
		if (g[0][a].size() + g[1][a].size() < g[0][b].size() + g[1][b].size()) {
			int t = a; a = b; b = t;
		}
		for (int i = 0; i < 2; i++) {
			for (int t : g[i][b]) {
//				dump(b, a, t);
				remove(i, b, t);
				add(i, a, t);
			}
		}
	}

	void add(int t, int a, int b) {
		if (a == b) return;
		if (a > b) { int tmp = a; a = b; b = tmp; }
		Long key = (long)a<<32|b;
		if (counter[t].get(key) == 0) {
			g[t][b].add(a);
			g[t][a].add(b);
			counter[t].add(key, 1);
			if (counter[1^t].get(key) > 0) {
				que.add(key);
			}
		}
	}

	void remove(int t, int a, int b) {
		if (a > b) { int tmp = a; a = b; b = tmp; }
