		for (int i = 0; i < 2 * (N - 1); ++i) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			--a;
			--b;
			if (g[a].contains(b)) {
				pend.add(new Pair(a, b));
			}
			g[a].add(b);
			g[b].add(a);
		}
		int cnt = 0;
		while (!pend.isEmpty()) {
			++cnt;
			Pair p = pend.poll();
			if (g[p.a].size() < g[p.b].size()) {
