            long hash = getHash(c[i], d[i]);
            if(dic.ContainsKey(hash))
            {
                fc.Add(i);
                fa.Add(dic[hash]);
                da[dic[hash]] = i;
                dc[i] = dic[hash];
            }
        }

        state = new int[N];
