        {
            es[i] = new List<int>();
            es2[i] = new List<int>();
            conne[i] = new List<int>();
        }


        for (int i = 0; i < M; i++)
        {
            if (da.ContainsKey(i)) continue;
            es[a[i]].Add(i);
            es[b[i]].Add(i);
        }
        for (int i = 0; i < M; i++)
        {
            if (dc.ContainsKey(i)) continue;
            es2[c[i]].Add(i);
            es2[d[i]].Add(i);
        }

        if (fa.Count == 0)
        {
            Console.WriteLine("NO");
            return;
        }

        addQ = new Queue<int>();
        bool first = true;

        int memo = -1;
        foreach (var item in fa)
        {
            if (first)
            {
                memo = item;
                first = false;
            }
            else
            {
                Estate[da[item]] = 4;
                conne[a[item]].Add(b[item]);
                conne[b[item]].Add(a[item]);
            }
        }

        update(a[memo]);
        update(a[memo]);
        update(b[memo]);
        update(b[memo]);
        Estate[da[memo]] = 4;


        while (addQ.Count > 0)
        {
            int now = addQ.Dequeue();
            if (state[c[now]] == 1) update(c[now]);
