    int[] Estate;
    Queue<int> addQ;

    void update(int now)
    {
        state[now]++;

        foreach (var item in conne[now])
        {
            if (state[item] < state[now])
            {
                update(item);
            }
        }

        foreach (var item in es2[now])
        {
            Estate[item]++;
            if(Estate[item] == 3)
            {
                addQ.Enqueue(item);
            }
        }

        if (state[now] == 2)
        {
            foreach (var item in es[now])
            {
                int next = a[item] + b[item] - now;
                if(state[next] == 0) update(next);
            }
        }


    }


    //swap
    void swap<T>(ref T a, ref T b)
    {
        T c = a;
        a = b;
        b = c;
    }


    long getHash(long a, long b)
    {
        long hash = 0;
        hash += a * 19786316311312L;
        hash += b * 535871674169487L;
        return hash;
    }
}

